select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/aesthetics-and-decorations","synthetic":false,"version":{"version":"26.1","title":"Armors and Weapons Aesthetics and Decoration 26.2 - Google€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1eTch7jpn5rapbeYvzmIZ48g49bcIKF4O/view?usp=drive_link","source_sha256":"cd98ad0a074984a2ec84d4b8bf85cd4104b02ca916d57563e35d6f58eae2e089","retrieved_at":"2026-10-06T00:00:00Z","page_count":17,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 16 page(s) without a text layer","content_sha256":"24fcbeeea7409fcbff666c1e8a7aed60a02f4b6e38aa2f174bb2de141432944f","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":17,"source_lines":265,"assigned_lines":339,"furniture_lines":57,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99638,"provisions":37,"numbered":36,"needs_review":0,"verified":1,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":265,"picture_text_lines":3,"ocr_corrections":3}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"aesthetics-and-decorations:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"aesthetics-and-decorations:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Armors and weapons aesthetics are very important for the fighters' appearance and sports representation.\n\nThe development of our sport will be easier with well-maintained and properly finished armor and weapons.\n\nCrafting armor and its parts is a process mostly made by hand with the help of different hand tools such as hammers and files, even during the surfacing process and polishing. Thus, it is not rare to find such traces on artifacts, even in the corners of a highly polished armor.","page_from":3,"page_to":3,"stable_key":"aesthetics-and-decorations:2","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2ada4d9d7f482c48734c79f80dbf20b80c71b07b362b5345a8fb4e45b61decc6","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"The following aesthetics are allowed:\n\n● Matte polish (see Section 4 below),\n● Satin Polish (see Section 5 below),\n● Mirror Polish (see Section 6 below),\n● Blackening and Bluing (see Section 7 below).\n\nAll types of aesthetics must:\n\n● be based on historical sources,\n\n● be homogenous regarding the whole set of armor: it is not allowed to mix different aesthetics in the same armor set unless specifically written in the specific requirements,\n\n● have a steel surface that does not present strong forging remains, big filing traces, and modern grinding marks,\n\n● be properly polished, any highly unpolished armor part is Denied,\n\n● be free of rust.\n\nDecoration\n\nAn armor can be decorated with different methods, such as:\n● etching,\n● engraving,\n● plating and gilding.\nHelmets can be decorated with the medieval spirit, with crest, torse, burlets or orle for example.\n\nExample of burlet:\n\n\\ Picture from Age of Craft ©\n\nAs the topic of painted armors is very controversial among armor experts, historical sources can’t stand a clear position about painted armor.\n\nWe have historical sources for the late 15th century helmets (mainly Sallets) but nothing relevant for the 14th century nor for armor parts.\n\nTherefore, any painted armor metal part, metal buckler or weapon is Denied.\n\nPainted armor","page_from":3,"page_to":4,"stable_key":"aesthetics-and-decorations:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["4","5","6","7"],"content_sha256":"25c9af5577f5a05a1bc00913f3abd076f62e92578200ca9b380312e7ac9a330c","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Matte Polish","body":"","page_from":5,"page_to":5,"stable_key":"aesthetics-and-decorations:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"89b9f6215c503f511340b49d91f9014b11bfefcc80b7d3a3782d03eef5a5ad93","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"4.1","title":"Definition and Sources","body":"A basic polishing method, widely used during the Middle Ages. Its appearance is flat and gray, and subtle marks from the polishing process are still visible. A utilitarian finish that hides scratches and holds a protective oil film well.\n\nThe basic and most common finish is the matte polish. It is recommended for all types of 14th and 15th century armor and weapons.\n\nIt is Approved for 14th century, Transitional and 15th century armors.\n\nArmet, on display at the Metropolitan Museum of Arts (MET) - 1440 - New York (USA)","page_from":5,"page_to":5,"stable_key":"aesthetics-and-decorations:4.1","parent_key":"aesthetics-and-decorations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8bf2ccb4dc555e9c5c2dad6714f29a4b8710099906c42d9f8200e7a7503ab51","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"The whole armor or weapon must be matte polished.\nIt is Denied to have an armor set mixing matte polish with other aesthetics.\nMatte polish can be used with other decoration techniques, such as etching, engraving, gilding or plating.","page_from":5,"page_to":5,"stable_key":"aesthetics-and-decorations:4.2","parent_key":"aesthetics-and-decorations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4cdf47ff9cee56311cad8050e643c0bd9af38b3b96c410b7cfc7381ec8ab67e4","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Finishes","body":"Picture from Medieval Extreme © Picture from Master Uley ©\n\nAcceptable grinder marks\n\nExamples of Denied Finishes\n\nExcessive rust\n\nUnpolished weapons\n\nPictures from The Medieval Things ©","page_from":6,"page_to":7,"stable_key":"aesthetics-and-decorations:4.3","parent_key":"aesthetics-and-decorations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d35ae7c0bfd98ca7bc05e5623f0252adb1178165e86c92062c64232c2568184b","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":0,"kind":"section","number":"5","title":"Satin Polish","body":"","page_from":8,"page_to":8,"stable_key":"aesthetics-and-decorations:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f4706b29f4a82c4c4df746a537a9d569ad378bf243935001c8409248c85e7443","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"5.1","title":"Definition and Sources","body":"Satin polish has a semi-reflective surface with a subdued sheen, the polishing marks are small and only visible upon close inspection. A practical polishing method that balances functionality with a refined appearance. Armors are polished with multiple grinding grits to obtain an intermediary reflective finish. It is not as shiny as mirror polishing.\n\nIt is Approved for 14th century, Transitional and 15th century armors.\n\nMontefeltro Altarpiece by Piero della Francesca - 1472 - Italy Note: the helmet in this art is mirror polished","page_from":8,"page_to":8,"stable_key":"aesthetics-and-decorations:5.1","parent_key":"aesthetics-and-decorations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7848095fae1f69ce49fff48803867a102bb12eba59ae204b9710f3fac9e7b5e5","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"The whole armor must be satin polished or a mix of satin and mirror polished.\n\nIt is Denied to have an armor set mixing matte polishing parts with satin polishing parts.\n\nIt is Denied to have an armor set mixing black/blued polishing parts with satin polishing parts.\n\nSatin polish can be used with other decoration techniques, such as etching, engraving, gilding or plating.","page_from":8,"page_to":8,"stable_key":"aesthetics-and-decorations:5.2","parent_key":"aesthetics-and-decorations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"20b89028ae477157b9b605abb200421ec8c260b8ae73626509dafe7607f375ac","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Finishes","body":"Pictures from Master Uley © Picture from Black Dog Armoury ©","page_from":8,"page_to":8,"stable_key":"aesthetics-and-decorations:5.3","parent_key":"aesthetics-and-decorations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eed3cc78b2c17404908fcfc6862a2a28d041481e7274e9ee4d5048491c5c5069","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"section","number":"6","title":"Mirror Polish","body":"","page_from":9,"page_to":9,"stable_key":"aesthetics-and-decorations:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6d98a76fe5fc4d3c57933bbeac161f1dde06674b644baed38df5a5805df953ee","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"6.1","title":"Definition and Sources","body":"A late-period polishing technique that gained popularity in the 15th century. Metal plates are polished with progressively finer grit until polishing marks are not visible, resulting in a reflective sheen. This finish requires high maintenance to keep it looking its best. Armors are polished with multiple grinding grits reaching into the 1000 grid to obtain a beautiful reflective finish.\n\nIt is Approved for 14th century, Transitional and 15th century armors.\n\nArmor of Sigismund von Tirol, Kunsthistorisches Museum Wien - 1484 - Austria","page_from":9,"page_to":9,"stable_key":"aesthetics-and-decorations:6.1","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4fa3bf7379a5265c34f6368166d6bec09f21098ee418c291bb983dfd236aef5c","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"The whole armor must be satin polished or a mix of satin and mirror polished.\nIt is Denied to have an armor set mixing black/blued polishing parts with mirror polishing parts.\n\nMirror polish can be used with other decoration techniques, such as etching, engraving, gilding or plating.","page_from":9,"page_to":9,"stable_key":"aesthetics-and-decorations:6.2","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"80d3a1cf1427dcec29fcb47c7cea47fed0d08aaa4f07c84e6883290b5d81b552","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Finishes","body":"Pictures from Master Uley © Pictures from J. Amiot ©","page_from":9,"page_to":9,"stable_key":"aesthetics-and-decorations:6.3","parent_key":"aesthetics-and-decorations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"089c496034f49675e136aa229bb40081973658b45cdd8438e51c4c8035bbf16c","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":0,"kind":"section","number":"7","title":"Blackening and Bluing","body":"","page_from":10,"page_to":10,"stable_key":"aesthetics-and-decorations:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04a104503bcbc15764aefe0d202a6723969190b3c0152db86e761ed2f340525b","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"7.1","title":"Definition and Sources","body":"This finishing method appeared in the mid-15th century sources, the metal plates are carefully heated to high temperatures to obtain a black or blue finish by treating the steel with oils\n\nWe lack historical sources for the 14th century to allow those finishes for armors of this period.\nBlackening and blueing are Approved for 15th century armors.\nBlackening and blueing are Denied for 14th century and Transitional armors.\n\nNote: We want to gather data on blackened armor. Which different technique and material armorers can use and which is the result in terms of aesthetics, maintenance, prevention of corrosion, sustainability etc. If you want to submit your work, please send us an email to: authenticity@buhurtinternational.com\n\nAcceptable methods of blackening/bluing are as followed:\n● Temperature bluing\n\nThe metal plates are carefully heated to adequate temperatures to obtain a blue oxide finish on the surface of the steel.\n\n● Oil blackening\n\nThis technique involves applying oils, such as linseed oil, to steel, which is then baked in an oven or applied to heated steel at relatively low temperatures. The process results in a deep black, protective finish. However, it requires regular touch-ups to maintain its appearance and protective qualities.\n\n● Chemical blackening/bluing Modern chemicals normally intended for use on firearms are permitted for armor. Hot-blue treatment is preferred, as it results in a deeper and more durable finish, but be mindful of how this\n\ncould affect heat-treated steel. Cold-blue can be repeatedly applied to darken the surface of the steel and also to touch up hot-blued steel.\n\nGreenwich Armour replica (1595) Plates formed by Robert MacPherson & Jeff Wasson, decoration and finishing by Chris Gilman\n\nGeorgsaltar' (Meister der Georgslegende) Armet, German - 1550 - Foot combat armor, Royal Armouries - Köln, Wallraf-Richartz-Museum - Metropolitan Museum of Arts 1591 - England 1460-1465 - Germany","page_from":10,"page_to":11,"stable_key":"aesthetics-and-decorations:7.1","parent_key":"aesthetics-and-decorations:7","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c81679af10dfcff0a842e0f87a2ac4cec0c5609cc194fd57b43957f26731d08b","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements","body":"The whole armor must be of the same method of blackening/bluing.\nIt is Denied to have an armor set mixing black/blued polishing parts with other aesthetics.\n\nBlackening/bluing finish can be used with other decoration techniques, such as etching, engraving, gilding, or plating.\nIt is Denied to use paint to reproduce a black/blued finish.","page_from":11,"page_to":11,"stable_key":"aesthetics-and-decorations:7.2","parent_key":"aesthetics-and-decorations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c328a254ec32e8660798852c38b34ae2f1374664614f7f9c5926898271a580ca","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"7.3","title":"Examples of Approved Finishes","body":"Pictures from Master Uley ©","page_from":11,"page_to":11,"stable_key":"aesthetics-and-decorations:7.3","parent_key":"aesthetics-and-decorations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"107954f9f1d964b1ef6c6ce78e4f0e672cdd4bce625f5d1311f6c25cc93f6622","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"7.4","title":"Examples of Denied Finishes","body":"Unpolished helmet, trying to imitate proper blackening\n\nPicture from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"aesthetics-and-decorations:7.4","parent_key":"aesthetics-and-decorations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e5fb993c3ca8230f32cf9af3bf0b620be80fa8c6f24923acf90816cb4604d4b1","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":0,"kind":"section","number":"8","title":"Decorations","body":"","page_from":12,"page_to":12,"stable_key":"aesthetics-and-decorations:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"14800e74a759316af6b08df6c201eaa3ffaacde110b08fa12beb8e399b9b5e30","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":1,"kind":"rule","number":"8.1","title":"Definition and Sources","body":"Armors were often decorated with different methods to display the owner’s status. The following decoration methods are documented by historical sources: etching, engraving, plating and gilding.\n\nHelmets were decorated with fabric or metal elements such as crest, burlet, torse and orle.\nIt is Approved for 14th century, Transitional and 15th century armors.\n\nBL Royal 20 C VII Chroniques de France ou de St Denis - 1380/1400 - France\n\nLate 14th century, MET Museum","page_from":12,"page_to":12,"stable_key":"aesthetics-and-decorations:8.1","parent_key":"aesthetics-and-decorations:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04c061d072f8de4532ed880d868eac2f683b385b4c3d73daace78ec08f557548","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":1,"kind":"rule","number":"8.2","title":"Specific Requirements","body":"All decorations must be based on historical sources. It is permissible to combine different decorative elements as long as they form a cohesive and visually consistent design across the entire armor set. No offensive symbols, words, or political messages of any kind may be used. If a logo is included, it must be stylized to align with medieval aesthetics and designs.","page_from":12,"page_to":12,"stable_key":"aesthetics-and-decorations:8.2","parent_key":"aesthetics-and-decorations:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2dde61e555e9ef169e50723a96731d3dfebbbae351b7f764d8fb503c7959ead7","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"8.3","title":"Allowed Decoration Techniques","body":"","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:8.3","parent_key":"aesthetics-and-decorations:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f32441e0e9c1df1bda61a04b8bc9d0552ae241178cce5d3b0b62031145b498b1","has_figures":false,"extraction":"ocr"},{"ordinal":26,"depth":2,"kind":"rule","number":"8.3.1","title":"Etching","body":"It is allowed to etch symbols, inscriptions, and motifs inspired by medieval artwork. The etching may be carried out by traditional or modern techniques, but the resulting designs should be in keeping with the aesthetics of the period. Exact historical reproductions are not required; however, modern logos, offensive imagery, and contemporary text or symbolism must be avoided.","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:8.3.1","parent_key":"aesthetics-and-decorations:8.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"932122a9a03c6c279b3e374ff89ace3ba7013e9e0742ab1946b4f8dabeb044a6","has_figures":false,"extraction":"ocr"},{"ordinal":27,"depth":2,"kind":"rule","number":"8.3.2","title":"Engraving","body":"It is allowed to engrave symbols, lettering, and decorative motifs consistent with medieval sources.\nEngravings may be done by hand or with mechanical tools, so long as the overall appearance remains historically inspired. As with etching, the use of modern, offensive, or overtly contemporary themes is\n\nprohibited.","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:8.3.2","parent_key":"aesthetics-and-decorations:8.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d02366efeb1f1211b8b5332d1e9c206cd7c16e487399e87e31c5b7e423c5f47b","has_figures":false,"extraction":"ocr"},{"ordinal":28,"depth":2,"kind":"rule","number":"8.3.3","title":"Plating","body":"It is Allowed to decorate the edges of an armor part with metal plates. The following materials can be used:\n\n● Copper,\n\n● Brass,\n\n● Gold,\n\n● Silver,\n\n● any other metal that can be documented by historical sources.","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:8.3.3","parent_key":"aesthetics-and-decorations:8.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a8b477e434808947db197e3faf564aa3a638e96bd846e2e934ded5212b44116d","has_figures":false,"extraction":"ocr"},{"ordinal":29,"depth":2,"kind":"rule","number":"8.3.4","title":"Gilding","body":"It is Allowed to use gilding as a decoration on armor and weapons. The following materials can be used:\n\n● Copper,\n● Brass,\n● Gold,\n\n● Silver,\n\n● any other metal that can be documented by historical sources.","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:8.3.4","parent_key":"aesthetics-and-decorations:8.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"91f093ce6da61361eefec460c2a15f48630233cdd72882070eb21c6d45609c6c","has_figures":false,"extraction":"ocr"},{"ordinal":30,"depth":2,"kind":"rule","number":"8.3.5","title":"Helmet decorations","body":"It is Allowed to decorate a helmet in the medieval spirit. It must be based on historical sources. Any textile or leather part must conform with the “Textiles and Leather’ document.","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:8.3.5","parent_key":"aesthetics-and-decorations:8.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c771b3786b1b4655ff9f3ea8304ed34d9536776773ae83a07754cb3bafdf8bb7","has_figures":false,"extraction":"ocr"},{"ordinal":31,"depth":2,"kind":"rule","number":"8.3.6","title":"Shield Decorations","body":"It is Allowed to decorate shields with paint and other embellishments in the spirit of medieval artwork.\nWhile exact historical reproductions are not required, the overall design must closely approximate medieval styles and avoid any modern logos, symbols, or contemporary imagery.","page_from":13,"page_to":13,"stable_key":"aesthetics-and-decorations:8.3.6","parent_key":"aesthetics-and-decorations:8.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"80d4a3c68e536225649570f6b3348d6000c0576a15e6d8308fb332afe729df9e","has_figures":false,"extraction":"ocr"},{"ordinal":32,"depth":1,"kind":"rule","number":"8.4","title":"Examples of Approved Decorations","body":"Pictures from The Medieval Things ©\n\nPictures from R. Desgranges ©","page_from":14,"page_to":14,"stable_key":"aesthetics-and-decorations:8.4","parent_key":"aesthetics-and-decorations:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"48449dad50bad41aa3608761bd5ee8d99ec43dfd5e726eda99d02ad1fe570f51","has_figures":true,"extraction":"ocr"},{"ordinal":33,"depth":1,"kind":"rule","number":"8.5","title":"Examples of Denied Decorations","body":"Painted helmets\n\nPictures from The Medieval Things ©","page_from":15,"page_to":15,"stable_key":"aesthetics-and-decorations:8.5","parent_key":"aesthetics-and-decorations:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"63fe4c47a45d16cfdeea46cd264a429b14f98792df91037f85260fc839b7b9f3","has_figures":true,"extraction":"ocr"},{"ordinal":34,"depth":0,"kind":"section","number":"9","title":"Repairs","body":"","page_from":16,"page_to":16,"stable_key":"aesthetics-and-decorations:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3215b4faa784c6485a21414381e3759aaea86439e4cadb998d8f40a466d88d7f","has_figures":true,"extraction":"ocr"},{"ordinal":35,"depth":1,"kind":"rule","number":"9.1","title":"Definition and Sources","body":"Armors were sometimes repaired to increase its durability. In the Middle Ages, the most common way to repair an armor was to rivet a metal plate from beneath. From a buhurt point of view, it will be important to respect period techniques for visible repairs.\n\nIt is Approved for 14th century, Transitional, and 15th century armors.","page_from":16,"page_to":16,"stable_key":"aesthetics-and-decorations:9.1","parent_key":"aesthetics-and-decorations:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7fce277b733802e93f6c29b154c582f98751428d3f40ea307f70457f1455ba43","has_figures":true,"extraction":"ocr"},{"ordinal":36,"depth":1,"kind":"rule","number":"9.2","title":"Specific Requirements","body":"Visible repairs must be executed with period techniques, for example with a riveted patch installed on the inside of the armor part and riveted.\n\nRepairs must be clean and not dangerous for other equipment elements.\n\nAny modern reparation is allowed if properly concealed. Any type of welding must be grinded/filed and polished on the outside.","page_from":16,"page_to":16,"stable_key":"aesthetics-and-decorations:9.2","parent_key":"aesthetics-and-decorations:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"87af2ad9c5f49ebbc9e8c6414da28c316e53e9b0bf38441f6965a4aa1a2dbccd","has_figures":true,"extraction":"ocr"},{"ordinal":37,"depth":0,"kind":"note","number":"10","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n- Split of “2. Definition” and “3. General Requirements” and subsequent title-numbers modifications)\n\nFebruary-2025 (V2025.02)\n\n- rephrased 6.2\n- formatting: grammar and formatting improvements\n\n11-Nov-2024 -Add Document has been created","page_from":17,"page_to":17,"stable_key":"aesthetics-and-decorations:10","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"fdfa0fa434edc44ea5f3d1faf53366fa36e0f833e4a63b23e38992f0cca8c0bf","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/armor-requirements","synthetic":false,"version":{"version":"26.1","title":"Armor requirement 26.2","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1yQDGSiXkM2pjHS9yj5e-HLJklWIeRKZE/view?usp=drive_link","source_sha256":"e6bfc37709315cac775255ef91c9f0b91a389f724e44bedc8340d9c9ed939477","retrieved_at":"2026-10-06T00:00:00Z","page_count":10,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"27778dc37e6bcaf52201b56fbd5cba2f9dcb209853c4aec24fb3d0e1c2d66de2","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":10,"source_lines":229,"assigned_lines":309,"furniture_lines":47,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99573,"provisions":37,"numbered":36,"needs_review":0,"verified":1,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"armor-requirements:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Introduction and Definitions","body":"This document will display all requirements for armors, shields, and weapons used in any category.\nEvery competitor is solely responsible for the quality of his/her equipment. Marshals and Authenticity Officers are responsible for the correct application of this document.","page_from":3,"page_to":3,"stable_key":"armor-requirements:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3761488bab5c354bcc56c87b04f76572198d87df3f9e484e6dd72c5ee13bd67b","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Equipment","body":"Armors, clothes, shields and weapons used by a competitor.","page_from":3,"page_to":3,"stable_key":"armor-requirements:1.1","parent_key":"armor-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6c96adf0a55ff453ceea64ccb6abcc1324f6a8564ae82dd2814ba2ba5d0a1d3e","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"List","body":"Place where the fights occur.","page_from":3,"page_to":3,"stable_key":"armor-requirements:1.2","parent_key":"armor-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6a3b9108fce5da206e5d3123df37f9d4eee2ae2e945c9ea5d30402531a976946","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Categories","body":"● Duel 1v1 sword and shield, sword and buckler, longsword, polearm.\n● Buhurt Group fight, 5v5, 12v12, 30v30.\n● Outrance","page_from":3,"page_to":3,"stable_key":"armor-requirements:1.3","parent_key":"armor-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"279154f5accbbec2e941fee91e25b9a8322d8f2edc12ae3e00e9ea5d57ea9337","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.4","title":"Historical Sources","body":"It is the result of research to conclude the plausibility of the item had existed. Historical sources can be primary (artifacts, museum originals…) or secondary (images, paintings, statues, description, writings…).\nAny historical source must be analyzed through criticism and logic.","page_from":3,"page_to":3,"stable_key":"armor-requirements:1.4","parent_key":"armor-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d857eac231ed0f8bc669feb273e6eb865934187673a7d9f875c7ca7196cbd548","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"2","title":"Historical Consistency Requirements","body":"","page_from":4,"page_to":4,"stable_key":"armor-requirements:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d31c28382ccb21c1059e6d4305309e504fac888cd55f5f7d19f8b6c065042fda","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.1","title":"Equipment from Historical Sources","body":"Only armors derived from historical sources are permitted for use.\nArmors must align with Authenticity Rules documents.","page_from":4,"page_to":4,"stable_key":"armor-requirements:2.1","parent_key":"armor-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4bc2bf7568c1473fa8df0960e774eebcf241a40ce0e5300c7b94c9a1734d8098","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.2","title":"Dates of Sources","body":"Armors must align with sources dating between the 14th (1300) and 17th (1600) centuries.\nFor safety considerations, reproductions of armors predating the 13th century are prohibited.","page_from":4,"page_to":4,"stable_key":"armor-requirements:2.2","parent_key":"armor-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a28049b6d8a8e6f33195151b9c10cb953d6496615802ee55ee5db86dbbbe10af","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.3","title":"Prohibited Features","body":"Prohibited features encompass evident indications of modern materials or manufacturing techniques including: neon colors, obvious nylon cords, plastic ties, visible welded seams, heat-induced discoloration, modern footwear and other visible modern equipment.","page_from":4,"page_to":4,"stable_key":"armor-requirements:2.3","parent_key":"armor-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4db415997ea3088a33d14b1f83f28284c217c52c228cdbe671bb8efe5a810d53","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.4","title":"Consistency in Equipment","body":"Armors, shields and weapons must consist of pieces from the same style. Distinct styles are defined in modern-day terms as:","page_from":4,"page_to":4,"stable_key":"armor-requirements:2.4","parent_key":"armor-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0f662844d238df526088106c1e1306d184021655dfb499de798deac2e390f03b","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":2,"kind":"rule","number":"2.4.1","title":"Western Europe Style","body":"● 14th century: from 1300 to 1380\n● Transitional: from 1380 to 1420\n● 15th century: from 1420 to 1500. 15th century style armor must be approved by the Authenticity Committee. We recommended seeking approval before buying such armor.\nWestern Europe includes the following modern countries: Great Britain, Ireland, France, Portugal, Spain, Germany, Italy, Norway, Denmark, Sweden, Finland, Austria, Switzerland, Belgium, and the Netherlands","page_from":4,"page_to":4,"stable_key":"armor-requirements:2.4.1","parent_key":"armor-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2643ae32478ba316b8395ccda4fd3a67af5df6fda578b8efa3b413b72f73bb18","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":2,"kind":"rule","number":"2.4.2","title":"Slavic Influence","body":"● Central Europe 14th: from 1300 to 1400\n● Russian late armors: from 1500 to 1700 Slavic Influence includes the following modern countries: Czech Republic, Romania, Hungary, Poland, Slovakia, Slovenia, Croatia, Latvia, Estonia, Moldova, Serbia, Ukraine, Russia, and Belarus.","page_from":4,"page_to":4,"stable_key":"armor-requirements:2.4.2","parent_key":"armor-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8845a4bd9ab94d64bd8b444efbd8d5dc0044784fc55d9199cf3e2c8ac48a89f4","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.4.3","title":"Eastern Influence","body":"● Chinese style: from 1300 to 1600\n● Japanese samurai style: from 1400 to 1700\n● Middle-East style: from 1300 to 1700 Eastern influence includes the following modern countries: China, Japan, India, Korea, Iran, Iraq, Turkey, Egypt.","page_from":4,"page_to":4,"stable_key":"armor-requirements:2.4.3","parent_key":"armor-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a897136c756e31df00c966016acb120b39ee88b366d812f5404c7b73bacc590c","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"2.4.4","title":"Authorized Deviations","body":"Competitors may deviate from these specified styles if they provide sources supporting their equipment choices.\n\nCompetitors who deviate from these specified styles must send an email to authenticity@buhurtinternational.com to obtain validation of their armor.","page_from":5,"page_to":5,"stable_key":"armor-requirements:2.4.4","parent_key":"armor-requirements:2.4","review_status":"verified","review_note":"Not a table: justified prose (wide word spacing). Checked against the official page.","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"22027dd3a2bbd5f18b1c6f280c274987188f9bcdbb075ebd0e7b099d35da600c","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"","page_from":5,"page_to":5,"stable_key":"armor-requirements:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8295fe2bc4208d485f0e4d62f112a839e3bfc08e2b952098f2a20793db34314","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"3.1","title":"Competitor Responsibility","body":"Every competitor is responsible for the quality and the safety of his/her equipment.","page_from":5,"page_to":5,"stable_key":"armor-requirements:3.1","parent_key":"armor-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ecb1e84d661b9eff26c4d7d798592eb5051f07a5cb22c97ebf08110d719841de","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"3.2","title":"Quality Equipment","body":"All armor parts must be made of strong metal plates able to endure full contact fights.\nPoor quality equipment is not allowed in any category.\nPoor quality armor examples: highly damaged, almost broken or cracked, barely attached to the other armor pieces etc.","page_from":5,"page_to":5,"stable_key":"armor-requirements:3.2","parent_key":"armor-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b5fd3293f82140a18c5bf45441c3c09d3f3631a55f5bf0ae9b371c958d2377bd","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"3.3","title":"Safe Equipment","body":"The whole armor must protect the following body parts:\n● Head: open-face helmets are not allowed in any category,\n● Neck: throat and all sides of the neck,\n● Chest: torso and back,\n● Pelvis: Ball joint of Hip, Groin, tailbone,\n● Arms: shoulders, biceps, elbows and forearms,\n● Legs: thighs and shins,\n● Feet: toes included,\n● Hands: wrist and fingers.\n\nMandatory-protected body parts:","page_from":5,"page_to":5,"stable_key":"armor-requirements:3.3","parent_key":"armor-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bb6a849bc8f522886cfbb227689004c8e7310e777e4dd58e409f668ae62aea55","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"3.4","title":"Access to the List","body":"Marshals are allowed to deny any competitor with clearly poor quality equipment to enter the list.","page_from":5,"page_to":5,"stable_key":"armor-requirements:3.4","parent_key":"armor-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dfb2df0970d7a106f60178a55300638291c259e1bda95af6a2d8a263c3199131","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":0,"kind":"section","number":"4","title":"Helmets Requirements","body":"","page_from":6,"page_to":6,"stable_key":"armor-requirements:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bea6a84daa12e89c16bc3b1cdcc5cd5dce3a9efac0fed32cb407042fa885b003","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"4.1","title":"Protection","body":"A helmet is the head protection. It must protect the entire head and neck from all sides.\n\nA helmet is composed by the following parts:\n\nA helmet must protect the whole head. Open-face helmets are not allowed in any category.\nHelmet must conform to the corresponding Authenticity Rules documents.\nIf the helmet includes a removable or pivoting visor, it should be secured to prevent any opening during a fight.\nLocking systems, if visible, must be based on historical sources and use authentic materials (leather, rope, etc.).\nApproved locking systems are displayed in corresponding Authenticity Rules documents.","page_from":6,"page_to":6,"stable_key":"armor-requirements:4.1","parent_key":"armor-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f324c2824befaf19bf7460874e04c877a70f43757f3d652c5afc08e84e0f6198","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"4.2","title":"Thickness and Composition","body":"Dome and visor must be made of metal.\nIt is recommended to use steel (mild, tempered, hardened or stainless).\nAny other material (I.e titanium) is not permitted.\nVisors may be made of titanium.\nA helmet can be made of steel of varying thicknesses.\nRecommend minimum thicknesses:\n● 2.5mm mild steel / spring steel.\n● 2.5mm stainless steel.\n● 2.0mm tempered steel / hardened steel.","page_from":6,"page_to":6,"stable_key":"armor-requirements:4.2","parent_key":"armor-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"675d5eb9b2fd74409b7b0ec5e6345f2999cfc58e6e386cd1486277e793781492","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"4.3","title":"Coif","body":"A helmet must have a quilted, or padded, coif inside, or a leather suspension system with a quilted coif.\nThe recommended minimum thickness of the coif is 5 mm.","page_from":7,"page_to":7,"stable_key":"armor-requirements:4.3","parent_key":"armor-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f0a528960cb4d616b19877657a0b59aa00a355bcf64f7538f4eb2fe4aaf1d315","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"4.4","title":"Chin Strap","body":"A chin strap must secure the helmet to the head, preventing any loss of it during a fight.\nIf the construction of the helmet excludes the use of the chinstrap, the helmet must be secured on the head by other means.\nIt is recommended to use additional straps to secure the helmet to the torso and/or back protection. The straps must be made of strong leather with metal buckles(plastic buckles are not permitted).","page_from":7,"page_to":7,"stable_key":"armor-requirements:4.4","parent_key":"armor-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"92bc9a8bcd9bd1136eb9e4a38f1e84cf7b1333bf3ace92a4b3efb6274098765a","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"4.5","title":"Neck Protection","body":"A neck protection is mandatory and must cover the neck in any position.\nThis protection can be made of metal plates sewn to the pellerine and hidden by an aventail.\nIt is recommended to wear a neck protection attached to the gambeson.\nNeck protection must conform to the “Neck Protection” document.","page_from":7,"page_to":7,"stable_key":"armor-requirements:4.5","parent_key":"armor-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"56f53e6412228b7c918d50591aa95337b6e6c01fd0a6c8d0c2b303896853d16d","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":0,"kind":"section","number":"5","title":"Armor Requirements","body":"","page_from":8,"page_to":8,"stable_key":"armor-requirements:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d1b1d414bc46f60230899a21dedd1aeaa6b66f23e882f8e774ab180f4bcf199f","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"5.1","title":"Metal Thickness Recommendations","body":"The minimum recommended thickness for steel plates of an armor is 1.5 mm (mild steel) or 0.8 mm (tempered steel, hardened steel, stainless steel).\n\nThe minimum recommended thickness for titanium plates of an armor is 0.8 mm.","page_from":8,"page_to":8,"stable_key":"armor-requirements:5.1","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aeda0d86dc979efeef71d0d0fe303733e0166a145abfb617377af05e98c981ce","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"5.2","title":"Chest","body":"The torso and the back must be protected with metal plates.\n\nChainmail elements can be used as an additional protection or as an articulation of plate elements.\n\nAn under-armor layer protecting the torso and the back is mandatory, commonly called gambeson. It should consist of at least a layer of felted fabric quilted with fabric.\n\nIt is allowed and recommended to wear concealed modern protection for the back.\n\nHips protection is mandatory. If the torso protection is not long enough to cover the hips in standing position, competitors can use a metal scale skirt, hidden metal plates attached to gambeson, or other permitted protection displayed in Authenticity Rule documents.","page_from":8,"page_to":8,"stable_key":"armor-requirements:5.2","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f21aaf745979a8105ff4ad6f03c0e3bcc0e3b4f6b3e65d14a7257d961ea6b49e","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"5.3","title":"Groin","body":"Groin must be protected with armor or modern groin protection.\n\nModern groin protection must be concealed.","page_from":8,"page_to":8,"stable_key":"armor-requirements:5.3","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b28d4b2fc1b5b80e71561b6486d2741c2045921d0e3f17c30d245f0ce6bc7ec9","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"5.4","title":"Hands","body":"Both hands must be protected with gauntlets or plate mittens.\n\nGauntlets and mittens must conform to the “Gauntlets” document.\n\nChainmail can be used only as an additional element or as an articulation of plate elements.\n\nGauntlets with separate fingers are not allowed in any category.\n\nIt is allowed to lock the gauntlet in closed-position with a leather strap or any locking system based on historical source.\n\nIt is not allowed to use gauntlets that can’t be opened in any way. Such gauntlets can be found under many names, including “torpedo”, “hoof”, “fist” etc. Except for the Longsword Duels Category.","page_from":8,"page_to":8,"stable_key":"armor-requirements:5.4","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f2585879319087d4ed2ff59e13501f104b440d594dbe7bb2123383463c0f0b28","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"5.5","title":"Arms","body":"Arms must be protected with metal plate armor.\n\nUnder-shield forearms can be left unprotected if the shield covers the entire forearm.\n\nIt is recommended to wear full arms protection in the Buhurt category, even if the shield covers the forearm.","page_from":8,"page_to":8,"stable_key":"armor-requirements:5.5","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cf4adfa9a7dff903c7de79da843547ba1be1c8fde0309fb831096f263b699706","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"5.6","title":"Joints","body":"All joints (shoulders, elbows, hips, knees, wrists) must be sufficiently protected with metal plate armor.","page_from":9,"page_to":9,"stable_key":"armor-requirements:5.6","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d97afd92a36eeb81ddb2f0c5f49656a59b45851f48a25a23069b4aab5576fde1","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"5.7","title":"Legs","body":"Legs must be protected with metal plate armor.\n\nLeg armor can leave the back of the leg unprotected.\n\nIt is recommended to wear leg armor with full cover of the back of the leg in Buhurt categories.\n\nIt is recommended to wear padded chausses to cover the open areas.\n\nIt is allowed to wear only a pair of pants. Such a pair of pants must conform to the “Textiles and Leather” document .\n\nKnee pads or knee braces must be concealed.","page_from":9,"page_to":9,"stable_key":"armor-requirements:5.7","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eff327709240d3a0937673481ed624fab5b8d92682ecb42ba365dde0a0ddf337","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":1,"kind":"rule","number":"5.8","title":"Feet","body":"Feet must be protected with metal plates, commonly called sabatons.\n\nSabatons must conform to the “Sabatons” document.\n\nSabatons must cover the top part of the foot (including tarsal and metatarsals) and toes.\n\nSabatons must be well attached to the shoes by leather laces or any other authentical material (rope, linen thread for example).","page_from":9,"page_to":9,"stable_key":"armor-requirements:5.8","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8422505c949b6531d1b44b112c53e5f8c0620c4703521bdd0d18e17bd85c9288","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":1,"kind":"rule","number":"5.9","title":"Shoes","body":"Modern shoes are not permitted.\n\nOnly replicas of medieval shoes are allowed.\n\nFlat rubber soles with low profile texture are permitted to replace historical soles.\n\nShoes must conform to the “Textiles and Leather” document.","page_from":9,"page_to":9,"stable_key":"armor-requirements:5.9","parent_key":"armor-requirements:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7635a043f899a7890b5b65402ba345ec45fb05c99528a6428720d9b1938030f7","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":0,"kind":"note","number":"6","title":"Changelog","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\nReplace:\n- In 4.5. Neck Protection: “Neck protection must conform to the Authenticity Rules document.” by “Neck protection must conform to the “Neck Protection” document.”\n- In 5.8. Feet: “Sabatons must conform to the Authenticity Rules document.” by “Sabatons must conform to the “Sabatons” document.”\n\nDate update: February 2025 (V2025.02)\n- add: 3.3: Pelvis: Ball joint of Hip, Groin, tailbone\n- add: 5.6: All joints (shoulders, elbows,hips, knees, wrists) must be sufficiently protected with metal plate armor.\n\nDate update: December 2024\n- add: Document created","page_from":10,"page_to":10,"stable_key":"armor-requirements:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["4.5","5.8"],"content_sha256":"40106c3a50e8c0ded2912909465568767625a3b56e9ac6b448bcefae44e6bb3a","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/aventails","synthetic":false,"version":{"version":"26.1","title":"Aventails - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1nKUSTq1LoUk3-OTymAJa4Pa_SWcJQA0h/view?usp=sharing","source_sha256":"32b032c3f8e9e7a80a22d8c755514f7bc1f2fe91a5b65fc877361eafe297655d","retrieved_at":"2026-10-06T00:00:00Z","page_count":15,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 15 page(s) without a text layer","content_sha256":"7259c38b09b338c45b719fea81df7a8a6f64cce5d838b822bc7341561306c9e2","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":15,"source_lines":191,"assigned_lines":247,"furniture_lines":44,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.996,"provisions":28,"numbered":27,"needs_review":0,"verified":1,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":191,"picture_text_lines":2,"ocr_corrections":2}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"aventails:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"aventails:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"","page_from":3,"page_to":3,"stable_key":"aventails:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b0e430dd84d11db7bcfb85c5ebd769c0cd101fa4738a4ef4209b2146c3a2dc00","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Definition","body":"An Aventail, also called a camail, is a flexible neck defense attached to a helmet, typically made from chainmail. Scales Aventails also appear in period art. The purpose of the Aventail is to protect the neck, throat, and shoulders of the wearer by draping over the shoulders and upper chest. It typically hangs from the lower edge of the helmet and was popular from the 13th to 15th centuries, providing flexible but effective protection.\n\nBy the turn of the 15th century, Aventails were commonly sewn onto a leather band that ran around the base of the helmet. This was secured with cords to studs known as vervelles. Beneath the Aventail, a padded liner called a pelerine extended from the helmet liner to cushion and distribute the impact of strikes. The outer edge of the Aventail's ring was stitched to the pelerine for stability and to prevent shifting during combat.\n\nAventails were primarily seen on bascinet-style helmets but could be adapted for other helmets like Great helms or kettle hats. Many aventails were elaborately decorated, featuring quilted covers with heraldic designs as well as decorative chainmail rings and latten vervelle covers.","page_from":3,"page_to":3,"stable_key":"aventails:2.1","parent_key":"aventails:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ab9f3cb6caa1c44f0353868bac92f30bfa11c8a6db36b1a2be5b1e04b557f592","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Description","body":"Types of Aventails:\n\n● Chainmail Aventail Aventails made from chainmail elements, attached to the helmet with a suspension system.\n\n● Scales Aventail Aventails made of metal scales riveted to the pelerine.\n\n● Fabric Aventail Aventails made from fabric, used to display heraldry and must be decorated.","page_from":3,"page_to":3,"stable_key":"aventails:2.2","parent_key":"aventails:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2dd07697f302cc8d82463c4c1e17d4304e5efedf5ef8fedd2e8b3bae9258a121","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"All types of Aventails must respect the following requirements:\n\n● Must be based on historical sources.\n\n● Must be firmly attached to the helmet with a vervelle and leather system.\n\n● Must be appropriately sized for the wearer, as depicted in historical sources.\n\n● It is not allowed to combine two or more different types of Aventails (e.g., chainmail and fabric) unless documented by historical sources.\n\nEach helmet-related document will explain what types of Aventails are allowed and denied.","page_from":3,"page_to":3,"stable_key":"aventails:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cbcf580855a1be75333d0690161fa72b624883685f9df7fb60bb769b23af0628","has_figures":false,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"4","title":"Chainmail Aventail","body":"","page_from":4,"page_to":4,"stable_key":"aventails:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"45ee5a98483f77a171764c18473d6ec1ebfdb1f4dad4afeefb66a48bc11e2ed0","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"Chainmail Aventails have been part of armor since the earliest helmets. By the 14th and 15th centuries, it was almost impossible to have a helmet without a chainmail Aventail.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nBook of the Queen - 1410/1414 - France Wallace Collection - 1390/1410 - UK","page_from":4,"page_to":4,"stable_key":"aventails:4.1","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"54101fa597e92db2edd87f7acdd7fb80a5e18ef516bebbdcdb31b23024105d04","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"Chainmail Aventails must follow the General Requirements (see Section 3 above).\n\nThe outer edge of the chainmail Aventail must be securely stitched to a padded pelerine to prevent displacement.\n\nThe aventail must cover the shoulders, throat, and neck at all times without gaps.\n\nChainmail Aventail must be properly maintained: damaged rings must be replaced, rust must be removed, etc.","page_from":4,"page_to":4,"stable_key":"aventails:4.2","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"cad4daa429816e848f5011556de7566b88360cf121e33541f37565d9836abca7","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Reproductions","body":"Picture from Master Uley© Picture from The Medieval Things\n\nPicture from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"aventails:4.3","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ef33132a3028f0fef98af9a35dc0f9577f1098bc75ecae59ca98a0eabf90006b","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.4","title":"Examples of Reproductions","body":"Incomplete Aventails\n\nPoorly made Aventails\n\nPictures from The Medieval Things ©","page_from":6,"page_to":6,"stable_key":"aventails:4.4","parent_key":"aventails:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7960650ac1d7f3c1b05df5319c4329bce3e845080c25f043917b5e1dc14c0d36","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"section","number":"5","title":"Scales Aventail","body":"","page_from":7,"page_to":7,"stable_key":"aventails:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7909753546e8a62aaa13eba8e66cffc320e3036428fc70987439e21dff8a301a","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"Scales Aventail consist of metal scales riveted to a leather or fabric base. Though no artifacts remain, they can be documented in manuscripts.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nBook of Hours - 1425/1435 - France Concerning the Fates of Illustrious Men and Women - 1415 - France\n\nSint-Martinusbasiliek - 1409 - Belgium","page_from":7,"page_to":7,"stable_key":"aventails:5.1","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7633fdea410b98350b1003cbeb6ee539e3e113fb236ef32ac67170410308e65c","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"Scales Aventails must follow the General Requirements (see Section 3 above).\n\nScales must be contoured (not flat) and securely riveted to the pelerine for a proper fit and protection.\nAllowed shapes include square, triangular, and semicircular designs.\n\nScales must lay evenly and overlap slightly to ensure full protection with no gaps.\n\nScales Aventail must conform to the “Armors and Weapons Aesthetics and Decorations” document.","page_from":7,"page_to":7,"stable_key":"aventails:5.2","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"33bf77dd082f87d72310bdefd0a4a3d286b3cc0f180aab85818b056518be8080","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Reproductions","body":"Picture from Forge of Svan ©","page_from":8,"page_to":8,"stable_key":"aventails:5.3","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e30eaf13c6e349f3123cfc56f8e5a9d2bc51ea47d3c2b9b35522309757ff186e","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Denied Reproductions","body":"Poorly made scales Aventail\n\nPicture from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"aventails:5.4","parent_key":"aventails:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e96d8a00459c80000d3adb9100d55eec74ba57ba10a89a9260ede3a42822614e","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":0,"kind":"section","number":"6","title":"Fabric Aventails","body":"","page_from":9,"page_to":9,"stable_key":"aventails:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d673d414db1b2d348fb1593ef1edd5e408506d106e36a90824dc20dafb4d0389","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"Fabric Aventail, often displayed over chainmail Aventail, serves decorative purposes. They may feature multi-colored designs, decorative stitching, embroidery, and coats of arms. While this type of Aventail is documented by sources from the 14th century, there is no evidence of fabric Aventail later on. The mail elements present with other 15th-century helmets like Barbutes and Sallets are not Aventails but mail standards/collars.\n\nThey are Approved for 14th century and Transitional armors.\nThey are for 15th century armors.\n\nChurch of St Georges, Schenna - 1380/1400 - Italy Runkelstein Castle, Ritten- 1395/1405 - Italy","page_from":9,"page_to":9,"stable_key":"aventails:6.1","parent_key":"aventails:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dbfa65d20b2e097277710aa69a8df9a19f88869b6202dc42eddb2169c9318fd0","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Fabric Aventail must:\n\n● follow the General Requirements (see Section 3 above),\n● consist of at least one layer of fabric, attached to the helmet using the same suspension method as other aventails (see Section 7 below),\n● conform to the “Textiles and Leather” document,\n● include at least one of the approved decoration methods, such as:\n○ Multi-color base (at least 2 distinct colors), ○ Embroidery, ○ Stitching, ○ Stamp-printing.\nDecorations must be inspired by medieval images and not be offensive.\nAny additional plates must be concealed when standing.\n\nIt is recommended to sew the fabric aventail to the pelerine.","page_from":10,"page_to":10,"stable_key":"aventails:6.2","parent_key":"aventails:6","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":["3","7"],"content_sha256":"7d983a82d75db80ea1c68c95d6482a0276d941c419ac41308b4f3aa1b14d1835","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"aventails:6.3","parent_key":"aventails:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f1cd9b5432108c0555278d395c5d5f4631b90033f061a2d1771b9e116698028","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Denied Reproductions","body":"Only 1 color with no decoration Mix of chainmail and fabric Aventail\n\nOnly 1 color, and floppy Aventail\n\nPictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"aventails:6.4","parent_key":"aventails:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1864b70740e4c94c19b949bb8ada2c462b4f49189f9b2f860e07d625a8c30e0e","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":0,"kind":"section","number":"7","title":"Suspension System","body":"","page_from":12,"page_to":12,"stable_key":"aventails:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5b787ec151fc07a5c3bd034a09ecda28bad7c5adb80f3f8d56e49c76a048c8e4","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"From the first bascinets of the 14th century until the late armets, Aventails were attached to helmets using a suspension system made of vervelles and leather. This system was used from the 14th to the 16th centuries.\n\nIt is Approved for 14th century, Transitional and 15th century armors.\n\nBascinet Royal Armouries, Leeds - 1380/1400 - Italy","page_from":12,"page_to":12,"stable_key":"aventails:7.1","parent_key":"aventails:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"39d67f27a54abf6ae7440c96031075cd0e520ea6c84c7a18074da34831f217c2","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":1,"kind":"rule","number":"7.2","title":"Examples of suspension systems","body":"Vervelles\n\nPiece of leather\n\nThread\n\nExamples of vervelles","page_from":13,"page_to":13,"stable_key":"aventails:7.2","parent_key":"aventails:7","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"822a22f69f71bc0ad49f2870da7ddd2800c0e3a7b3f571dff75abb63c7af9a64","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"7.3","title":"Specific Requirements","body":"The suspension system consists of vervelles, a piece of leather, and thread.\n\n● Vervelles These are metal components with a hole, allowing threads (metal or leather) to pass through.\n\n● Leather Piece The aventail (chainmail neck guard) is attached to a leather piece, which can be riveted or sewn.\n\n● Thread\n\n● The thread, made of either metal or leather (or materials that replicate their look), passes through the vervelles to secure the leather piece to the helmet.\n\nAlternative method for fabric Aventail: the Aventail can be sewn directly to the helmet’s edge.","page_from":13,"page_to":13,"stable_key":"aventails:7.3","parent_key":"aventails:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d48893ab885978b393f2f902d871751a75e8d1ad1d3b90d018b5370ef715f0fb","has_figures":true,"extraction":"ocr"},{"ordinal":26,"depth":1,"kind":"rule","number":"7.4","title":"Materials Requirements","body":"All materials used in the suspension system must comfort with the following documents:\n● Metal parts: “Armors and weapons aesthetics and decoration” document.\n● Fabric and Leather parts: “Textiles and Leather’ document.","page_from":14,"page_to":14,"stable_key":"aventails:7.4","parent_key":"aventails:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eae67feaab614bd138093e3111199f27063f9f31b811ee0f14615e700bc71cb7","has_figures":true,"extraction":"ocr"},{"ordinal":27,"depth":1,"kind":"rule","number":"7.5","title":"Examples of Approved Reproductions","body":"Leather and vervelle system\n\nPictures from The Medieval Things©","page_from":14,"page_to":14,"stable_key":"aventails:7.5","parent_key":"aventails:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"20c54c3797b749af8089e264b3d014cb21cc1bb6db413a5471e408105b1df30c","has_figures":true,"extraction":"ocr"},{"ordinal":28,"depth":0,"kind":"note","number":"8","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “41. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition” and “3. General Requirements”.\nThis split doesn’t have an impact on the content of the rules.\n\nFebruary-2025 (V2025.03) Clarification: 4.1 Format: Grammar and Formatting\n\nDecember-2024: -Add Document has been created","page_from":15,"page_to":15,"stable_key":"aventails:8","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"26c264576ef66c392cbba4a6e0a4e829124424f61823fb80783760110d988b32","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/barbutes","synthetic":false,"version":{"version":"26.1","title":"Barbutes - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1zllcOqunbMXrrV1K1PPtahGEjncrol3V/view?usp=drive_link","source_sha256":"6a3d140a13e1180d57a5209374a1c98856a8603a19c45391ba7d22f282650a56","retrieved_at":"2026-10-06T00:00:00Z","page_count":11,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 10 page(s) without a text layer","content_sha256":"6f7e3e8d993a0bdd9784951f06b1dc1b531eddfd1d13e65b848e5c5ce4fd92f7","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":11,"source_lines":115,"assigned_lines":138,"furniture_lines":37,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99618,"provisions":15,"numbered":14,"needs_review":0,"verified":1,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":115,"picture_text_lines":12,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"barbutes:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 29.11.2025.\nThe document and its rules will be implemented from the 2029 season (01/01/2029).\nCompetitors will have 3 seasons to align their equipment with this document and its rules.","page_from":3,"page_to":3,"stable_key":"barbutes:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e215a7d2edf407991399a96ef4f69da15cc1358d2842fc3bb9fc959292569ef","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Barbutes are a design of helmet growing extremely popular during the 15th century. They see an extensive use and evolution between approximately 1430 to 1500.\n\nBarbutes tend to be locally used in Italy.\nBarbutes are worn alone or with an addition of a gorget of plate or mail.\n\nBarbutes can be of different designs: T shape or Y shape. The term “shape” refers to the opening for the eyes and mouth.\n\nBarbutes type helmets are Approved for 15th century armors of matching design.\n\nBarbutes type helmets are Denied for 14th century and Transitional armors.\n\nT-shaped Barbute\n\nY-shaped Barbute","page_from":3,"page_to":4,"stable_key":"barbutes:2","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3abd8fbe56b369a57a9214176fab91be1a2fb63b3cb3421e2513be3f6d390716","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"","page_from":5,"page_to":5,"stable_key":"barbutes:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04e42d373a22b64d239d42d339423dfe562a290d68219f938a8fe993f807be48","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"T-shaped Barbutes","body":"Metropolitan Museum of Art - 1460 - Italy\n\nCastello Sforzesco, Milano - 1460/1470 - Italy\n\nCastello Sforzesco, Milano - 1475/1500 - Italy","page_from":5,"page_to":5,"stable_key":"barbutes:3.1","parent_key":"barbutes:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"467e3b6afe5645cc8aba2693bf2d56e52a121045a47f99606a864924297ba2d3","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Y-shaped Barbutes","body":"The Wallace Collection - 1470 - Italy\n\nMaster Christoforo, Detroit institute of art - 1450/1460 - Italy Philadelphia Museum of Art -1450/1470 - Italy\n\nBrescia, Metropolitan Museum of Art - 1470/80- Italy Bernardino da Carnago, Metropolitan Museum of Art - 1475 - Italy","page_from":6,"page_to":6,"stable_key":"barbutes:3.2","parent_key":"barbutes:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a3cf640b411e87a8e03f66397794a7cc055c2dda0a579c53bac7058186e45233","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":7,"page_to":7,"stable_key":"barbutes:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of historical sources.\n\nA particular attention must be paid to the crest on top of the Barbute, often forgotten by modern armorers.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":7,"page_to":7,"stable_key":"barbutes:4.1","parent_key":"barbutes:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"25e425ee27fb09506da52e4418cdd4a5fdbc5be8e35ae9414deec9953b7520bc","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"Visors must not be too long or too short, it must respect the proportions of historical sources.\n\nIt is allowed to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the aventail.","page_from":7,"page_to":7,"stable_key":"barbutes:4.2","parent_key":"barbutes:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b196653870d315abb8b88eb05ac8a8e567815b48d44d66f86df8e70dd8af8f57","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.3","title":"Eyes and Mouth slot","body":"Eyes and Mouth slots must resemble sources for the visor (T shape or Y shape).\nEyes and Mouth slots should not exceed 25 mm tall to prevent any injury, as a safety recommendation.\nIt is Allowed to add:\n\n● Up to five (5) safety Eye bars: one (1) in the middle and two (2) on each side of the Eye slots,\n● Up to five (5) safety Eye bars on the mouth slot, It is allowed to use a T shaped-Eye bar at the junction of the Eye slots and the Mouth slot.\n\nIt is allowed to use slanted safety Eye bars for barbute with Y shape only.\nEye bars must be welded internally or riveted internally.\nEye bars must conform to the “Eye bars” document.","page_from":7,"page_to":7,"stable_key":"barbutes:4.3","parent_key":"barbutes:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1751327b8d14c9ef8d69cb9a3cfbfae1883254fef53cd63694c58ea573343273","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.4","title":"Gorget","body":"Barbutes are not designed to be worn with an aventail, unlike bascinets. Barbutes are worn with a gorget.\n\nBarbutes must be worn with a plate gorget, or a safe construction simulating a mail gorget as best as possible.\n\nGorget must be constructed in such a way as to protect its wearer. Mail gorget must integrate a grill of protection or additional plates.\n\nChainmail gorget must conform to Chainmail Aventails requirements listed in the “Aventails” document.\nAdditional neck protection can be worn according to historical sources.\nAdditional neck protection not based on historical sources can be worn if concealed.","page_from":7,"page_to":7,"stable_key":"barbutes:4.4","parent_key":"barbutes:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3f6d51a24a8f4dbb7131d74336c9e0384598ba86df33b64a237ad7c2f12b3c1e","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"4.5","title":"Others","body":"Barbutes may be decorated in the spirit of medieval styles, such as orle, torse, decorated collar, coat of arms badges etc.\n\nSuch decoration must be made in coherence with historical sources.\n\nBarbutes can be covered with silk or velvet, as per historical sources. These decorations require a lot of maintenance to maintain a high level of aesthetic. Any Barbute with silk or velvet cover that is too much damaged can be denied during Authenticity Check.\n\nUsing modern and/or offensive imagery and slogans is prohibited.","page_from":8,"page_to":8,"stable_key":"barbutes:4.5","parent_key":"barbutes:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cb79d0170155860b62510e879b388addec669f8e87b5d8787fa277b7652a90d8","has_figures":false,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"We recommend the addition of safety bars\n\nPictures from The Medieval Things ©\n\nWe recommend a smaller opening for safety\n\nPicture from Medieval Extreme ©\n\nPicture from Zoom en lice ©","page_from":9,"page_to":9,"stable_key":"barbutes:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e34b6028b45face42ba6806f47af7c324db39de02f0984041802aa24219c75e","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":0,"kind":"section","number":"6","title":"Examples of Denied Reproductions","body":"Fabric aventail\n\nPicture from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"barbutes:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"51a993dee0717d86a8b7bb35a56e00d0393efdfdd3193f51119ec29b4fcc276d","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Document has been created","page_from":11,"page_to":11,"stable_key":"barbutes:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"fc2fa3307e16c0384a9b98ebb44a708756a26d706adfaee6c3daf9247418b1a1","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/belt-flag-s","synthetic":false,"version":{"version":"26.1","title":"Belt Flag - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1ATswdLydtmGmWQeiTmF7GmyAod7GSQci/view?usp=sharing","source_sha256":"857bb42b4d04ee8c5bc582aaa6e65651ca3f175d7afc37ccea32a7dcd4729c33","retrieved_at":"2026-10-06T00:00:00Z","page_count":6,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 6 page(s) without a text layer","content_sha256":"ab37dfa6037aae3c461da7624878d29c90c2cbb6e0e9c1599768b254c02e0ef6","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":6,"source_lines":71,"assigned_lines":92,"furniture_lines":13,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99792,"provisions":6,"numbered":5,"needs_review":0,"verified":1,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":71,"picture_text_lines":2,"ocr_corrections":2}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"belt-flag-s:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"belt-flag-s:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition and Rules","body":"A Belt flag is an element hung on a belt designed to show your belt number in the list.\nA Belt flag must be made of fabric or leather.\nA Belt flag must conform with the “Textiles and Leather’ document.\n\nAs a competitor, it is required to wear a Belt flag with your belt number during buhurt fights.t is not required for duel and outrance fights.\n\nA competitor may have a second Belt flag that is decorative. No more than two Belt flags may be worn by a competitor.","page_from":3,"page_to":3,"stable_key":"belt-flag-s:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8a374497f49af71bb9fa8145b1aa2878ac82fd1e4782ee84db6a2263351ec938","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"Belts flags consist of a base and a number.\n\nBase must:\n● have a shape that can be square, rectangular or triangular,\n● have atrim to be worn with a belt,\n● be made of one main color.\n\nSome decoration can be added on the edges of the base.\nSuch decoration must not interfere with the readability of the Belt flag.\n\nNumbers must:\n● have individual figures from 0 to 9,\n● be from 01 to 99,\n● be written in Arabic numerals,\n● be 13 cm tall as a minimum.\n\nNumbers can be of any color, contrasting with the base main color.\nAll Belt flags must respect the following dimensions:\n\n● Length: from 26 cm to 36 cm.\n● Width: from 14 cm to 18 cm.\n\nSymbols and decorations used for belt flags must be based on historical sources. Any clearly modern symbol or decoration is denied.\n\nExamples: Warhammer logos, movies or TV show imagery, modern slogans, etc...\nException: It is allowed to wear a belt flag with the global medical imagery stating you are hearing impaired or deaf:","page_from":3,"page_to":4,"stable_key":"belt-flag-s:3","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly; \"13 cm\" corrected from \"13cm\"","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fae8b5bc1a4c36c4060ecdc138cd5393668df6366d0f93996ba886d5944ec36f","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Examples of Approved Reproductions","body":"Picture by Zoom en Lice\n\nPictures by The Medieval Things","page_from":5,"page_to":5,"stable_key":"belt-flag-s:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"01d007b4e4a972c4604b66b06ca0f398a5807e641a3a744c5a89023791853aa8","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"note","number":"5","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd? “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition and Rules” and “3. General Requirements”. This split doesn’t have an impact on the content of the rules.\n\n- “Examples of Approved Reproductions” is now “4.” instead of “1.2”\n\nAdd:\n\n- In 3. General Requirements: “Exception: it is allowed to wear a belt flag with the global medical imagery stating you are hearing impaired or deaf’ + picture\n\n- In 4. Examples of Approved Reproductions: New picture to illustrate a belt flag for hearing-impaired people\n\nReplace:\n\n- In “2. Definition and rules”: “As a competitor, you must have a belt flag with your number [...]” by “As a competitor, it is required to wear a belt flag with your belt number [...]”\n\n11-Nov-2024: -add Document has been created","page_from":6,"page_to":6,"stable_key":"belt-flag-s:5","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":["3","4"],"content_sha256":"5d34e5e712b4e5e652ea4bf1bbe18c95a08970d3615804234777c7308b11477c","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/eyebars","synthetic":false,"version":{"version":"26.1","title":"Eyebars - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1skAksQXo5-RNNdEP1Tje8dGw_uiJ_ucb/view?usp=sharing","source_sha256":"2c34b05ad8173bfa08dd964246946174d4039b3c08dcb9fd4e7543b13d474e74","retrieved_at":"2026-10-06T00:00:00Z","page_count":9,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 8 page(s) without a text layer","content_sha256":"bed132b6f3b09f57b7b0a19bcd8c2674f2afbb5d092b0c77beac51ac785dbdf4","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","1 line(s) looked like a numbered heading but did not fit the sequence"],"pages":9,"source_lines":129,"assigned_lines":163,"furniture_lines":28,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99576,"provisions":20,"numbered":19,"needs_review":0,"verified":4,"empty_pages":[1],"rejected_numbers":1,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":129,"picture_text_lines":0,"ocr_corrections":2}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"eyebars:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"eyebars:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition and Description","body":"","page_from":3,"page_to":3,"stable_key":"eyebars:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6cbfee393877c9e22587dc5be99d5858f07bd00b9726562bdcd10d1fcf53a39d","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Definition","body":"“Eye bars” are the term used to describe additional protection for the eye slots of a helmet.\nRare historical sources display some additional eye protection, mainly for great helms.\n\nHowever, it is permitted to add Eye bars that do not rely on historical sources to increase the safety of helmets. The number and type of permitted Eye bars are displayed in each helmet rules document.","page_from":3,"page_to":3,"stable_key":"eyebars:2.1","parent_key":"eyebars:2","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5b127f22d4683792d131ec02db0d1a3d52181df442713092a574f8a3f1a2dd19","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Eye bars Description","body":"Eye bars can be:\n\n● Externally Riveted Eye bars This type of Eye bars is documented by historical sources for specific helmets. Therefore, they are only allowed on helmet models that can be historically referenced to have externally riveted Eye bars. If there is no supporting evidence for a particular helmet style, externally riveted Eye bars are not permitted on that helmet.\n\n● Integrated Eye bars This type of Eye bars is documented by historical sources for certain helmets as part of the visor or faceplate itself. They are only permitted on helmet models that can be shown to have used integrated Eye bars historically. If no suitable source exists, integrated Eye bars are not allowed.\nThey must closely replicate the shape, placement, and size seen in surviving artifacts or credible period art.\n\n● Safety Eye bars This type of Eye bar is not documented by historical sources. These concealed Eye bars are allowed solely to increase safety in modern buhurt combat. They typically consist of metal bars riveted or welded to the inside of a helmet, thus remaining concealed from the outside.\n\nNumber and Placement of Safety Eye bars:\n\n○ For helmets with two separate Eye slots, you may install up to two (2) vertical Eye bars per Eye slot.\n\n○ For helmets with one continuous Eye slot, you may install up to five (5) Eye bars across the slot.","page_from":3,"page_to":3,"stable_key":"eyebars:2.2","parent_key":"eyebars:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"77c2ca6c769380fbcfafb7af96e8603fee9b07f90b30e234987a2be715fffa53","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"All types of Eye bars must respect the following requirements:\n● Be firmly attached to prevent any breakage and maintain a high level of protection in any situation.\n\n● Protect the whole Eye slot from top to bottom.\n\nRecommended: Eye slots should not exceed an opening of 25 mm\n\n<< 25mm tall maximum |","page_from":4,"page_to":4,"stable_key":"eyebars:3","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d67dba79e2bfaf601879789d2d4ab158e3d6df23daa58e02017cd63e96b9c7d7","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"4","title":"Externally Riveted Eye bars","body":"","page_from":4,"page_to":4,"stable_key":"eyebars:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fa6c0a12d57025d02752fd4062b6b0c900483c29278e15e80405f62ca04842c9","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"A few historical sources display this type of Eye bar.\nThe main source is the Great Helm from Nuremberg (1350).\n\nDespite its rarity, it is Approved for 14th century, Transitional and 15th century armors.","page_from":4,"page_to":4,"stable_key":"eyebars:4.1","parent_key":"eyebars:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9b39e3ea674ffa1889be87ca5e20f31590eba6bf87a21151a72c25080b9e663e","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"Externally riveted Eye bars must:\n● conform with the General Requirements (see Section 3 above),\n● be firmly riveted to the outside of the Eye slot,\n● resemble the historical sources and not exceed a width of 30mm,\n● be made of metal.","page_from":5,"page_to":5,"stable_key":"eyebars:4.2","parent_key":"eyebars:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"cfb85293b1e47384071772ebdbac43c213967b1fb79971494fd1a391aa285ba3","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Reproductions","body":"Picture by Zoom en Lice ©","page_from":5,"page_to":5,"stable_key":"eyebars:4.3","parent_key":"eyebars:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eb3088b7223a1941a3bfd62b8c150534a64e5eb6cf3d2e52d1f619345c3bf5da","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":0,"kind":"section","number":"5","title":"Integrated Eye bars","body":"","page_from":6,"page_to":6,"stable_key":"eyebars:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bae04bf551c5a837dc43322ec93faba016bd597de140cc55f930a1fdcc482713","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"A few historical sources display this type of Eye bar. One artifact from the Churburg castle shows a nice example. .\n\n1380 BNF Nouvelle acquisition frangaise Paris France Integrated eyebar for side-pivoting visored bascinet\n\n1390-1410 - Churburg - Italy","page_from":6,"page_to":6,"stable_key":"eyebars:5.1","parent_key":"eyebars:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e688ba5f1f56238c6d25e4dec1e96e8a2a32904d2b7e53a2dbcad975835fd98b","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"Integrated Eye bars must:\n● conform with the general requirements (see Section 3 above),\n● be sturdy made and able to endure full-contact fights,\n● resemble the historical sources and not exceed a width of 20mm.","page_from":7,"page_to":7,"stable_key":"eyebars:5.2","parent_key":"eyebars:5","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"4e55eb2274614bf292bb2373f7304d239e6acd05502c68cfae1d551a75007f1a","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Reproductions","body":"Picture from Master Uley ©","page_from":7,"page_to":7,"stable_key":"eyebars:5.3","parent_key":"eyebars:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"880d93f8cce8438e568f5b64713b553facad3829b392c40bc9b66b8874020d5c","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":0,"kind":"section","number":"6","title":"Safety Eye bars","body":"","page_from":8,"page_to":8,"stable_key":"eyebars:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"96066988de01064546e4616288b83d8335a83f2b5346086dffeb223e5de47482","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"There are no historical sources for Eye bars welded onto Eye slots.\n\nNevertheless, for safety reasons, they are Approved for 14th century, Transitional and 15th century armors.","page_from":8,"page_to":8,"stable_key":"eyebars:6.1","parent_key":"eyebars:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b2912f610ebc70c959ed93cd37a6b7b5ee173571fa004ea08e6d412b407f4d9d","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Safety Eye bars must:\n\n● conform with the General Requirements (see Section 3 above),\n● be welded or riveted from the inside of the helm,\n\n● be sturdy made and able to endure full-contact fights,\n\n● be painted black.","page_from":8,"page_to":8,"stable_key":"eyebars:6.2","parent_key":"eyebars:6","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"1e4bf716de59f493182aec8776dddde10a14cc392c411615322b5852cc535dba","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"eyebars:6.3","parent_key":"eyebars:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f1cd9b5432108c0555278d395c5d5f4631b90033f061a2d1771b9e116698028","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Denied Reproductions","body":"Too many eyebars\n\nPicture from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"eyebars:6.4","parent_key":"eyebars:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae0f58edf81d2fe69f41b18b522476eed649421a0b2c7f646b2cfd108a0fb94d","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and legibility. Except points listed below, no content changes.\n\nReplace:\nThroughout the document “Buhurt “Optimized” Eye bars” by “Safety Eye bars”\n\nAdd? “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition and description” and “3. General Requirements”. This split doesn’t have an impact on the content of the rules.\n\nAdd:\n\n- 2.2 Eye bars description: whole paragraph on Integrated Eye bars and multiple precisions on Externally riveted Eye bars and Safety Eye bars\n\nAdd: “5. Integrated Eye bars” (and subsequent modification of all Title numbers in the document) Replace:\n\n- In 5.1 Historical Sources and Datation: “The main source is the Great Helm from Nuremberg (1350).” by “One artifact from the Churburg castle shows a nice example.”\n\n- In 6.4 Examples of Denied Reproductions: “Too much eyebars” by “too many Eye bars”\n\nDecember-2024: -add Document has been created","page_from":9,"page_to":9,"stable_key":"eyebars:7","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":["5.1","6.4"],"content_sha256":"c75f4f272f05dd88a635b0d5d319fd7af4fd5a8da8028b954a4366e3e820db65","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/falchions","synthetic":false,"version":{"version":"26.1","title":"Falchions 26.2","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1blWdDUbcSepUW9dy1C4x-MCzGFymFki6/view?usp=drive_link","source_sha256":"a8c2b137d637edc2fa238e2cd37535d790230677983448ef1ab59855c49a206f","retrieved_at":"2026-10-06T00:00:00Z","page_count":26,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 2 page(s) without a text layer","content_sha256":"ab12b3c3a3892f127d4eb14d29829052e18265a8d5a8ed7e2d7a494ebd6152f6","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 4","1 line(s) looked like a numbered heading but did not fit the sequence"],"pages":26,"source_lines":237,"assigned_lines":432,"furniture_lines":65,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99584,"provisions":32,"numbered":30,"needs_review":0,"verified":1,"empty_pages":[4],"rejected_numbers":1,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":12,"picture_text_lines":8,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"falchions:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 29.11.2025.\nThe document and its rules will be implemented from the 2029 season (01/01/2029).\nCompetitors will have 3 seasons to align their equipment with this document and its rules.","page_from":3,"page_to":3,"stable_key":"falchions:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e215a7d2edf407991399a96ef4f69da15cc1358d2842fc3bb9fc959292569ef","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition and Description","body":"","page_from":3,"page_to":3,"stable_key":"falchions:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6cbfee393877c9e22587dc5be99d5858f07bd00b9726562bdcd10d1fcf53a39d","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Definition","body":"“Falchion” is the term used to describe a single-edged bladed weapon from the Middle Ages in Europe.\nThe falchion originated in the 12th century and evolved until the 15th century.\nFalchions can be one-handed or two-handed.\n“Messer” is the term used to describe a specific subtype of falchion.","page_from":3,"page_to":3,"stable_key":"falchions:2.1","parent_key":"falchions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"abeabd16624e8fcbca82ae198a5324a19cb6f839bfced369ce254b4b0a5eb53c","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Description","body":"Falchions existed in many forms throughout the Middle Ages.\nThey have been classified by James Elmslie in 2015, and we will stick to his typology for buhurt.\n\nType of Falchions:\n\n● Type 1 A straight blade with a wider part on the striking edge.\n\n● Type 2 “Reverse-edged” forward curve, the point must be rounded or removed.\n\n● Type 3 Variations in having scalloped or cutaway tips on the blades.\n\n● Type 4 Curved saber-like blades often associated with, but not exclusive to, Eastern Europe.\n\n● Type 5 Symmetrical single-edged profiles with little to no curvature.\n\n● 2-handed Not classified by James Elmslie , but depicted in manuscripts.\n\nFalchions that are not based on the James Elmslie typology can be accepted if documented by historical sources.","page_from":3,"page_to":3,"stable_key":"falchions:2.2","parent_key":"falchions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0144ef647649b95275ce3d2d1a2e6d7966f6187a050c42cce8aa4bb8cc344edb","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":4,"page_to":4,"stable_key":"falchions:page-4","parent_key":null,"review_status":"verified","review_note":"Picture page: the Elmslie single-edged blade type chart (types 1a to 5e, blade curvature). Its lettering is part of the picture; there is no text to transcribe.","topics":["pictures"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"Falchions of any types must:\n● be based on historical sources,\n● reproduce the proportions and curves based on historical sources,\n● match the style of the armor kit of the competitor,\n● be conform to the 9.0 section about pommels and guards,\n● be conform to the Technical Requirements document for weapons.\n\nAll decorations on the falchion must be stylized in accordance with the style of the armor kit of the competitor.\n\nIt is prohibited to decorate a falchion with images that are clearly modern and/or offensive. Any metal part of the falchion must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nAny textile or leather part of the falchion must conform to the “Textiles and Leather” document.","page_from":5,"page_to":5,"stable_key":"falchions:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8450031f8b2dc10b0298cb7639565c91e569acc7a38bdfb337b71732aca596ba","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"section","number":"4","title":"Falchions Type 1","body":"","page_from":6,"page_to":6,"stable_key":"falchions:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f5bb468491fedf6ede373cbbf6c16f379a9b2a4deee98394d16224900b50d425","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"Type 1 falchions are based on Elmslie typology. They are characterized by a flaring profile, and broad, abrupt tip.\nThere are 4 subtypes, from 1a to 1d.\nAll subtypes type 1 falchion have been used since the 13th century.\nThey are Approved for 14th century, Transitional and 15th century armors.\nType 1d falchion is Denied because its pointy edge is not safe.\n\nAPPROVED DENIED\n\nFalchion of Cluny - 1270/1280 - France\n\nFalchion of Conyers - 1260/1270 - England","page_from":6,"page_to":6,"stable_key":"falchions:4.1","parent_key":"falchions:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"52eef1a8cf6af2fd582c9686b9d39a14c727dad710630f07181de448a710076f","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.2","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"falchions:4.2","parent_key":"falchions:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e1a3cf6fa414e2525b3d175e026fb698b3455bff6c100a6c4b1cc83932b4aac3","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"5","title":"Falchions Type 2","body":"","page_from":8,"page_to":8,"stable_key":"falchions:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d1a21421703558483f9ccaada2f6b99773044b21cbb28c4f70a8e80854bbb217","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"Type 2 falchions are based on Elmslie typology. They are also called “reverse-edge falchions”. They are sharpened along the ‘short’ edge, which features a clipped portion, leading to the reinforced thrusting tip.\nThey are Approved for 14th century, Transitional and 15th century armors.\nA particular attention must be paid to the safety of the pointy edge, it must be made to be safe.\n\nBNF Français 246 Histoire Ancienne - C. 1360-1400 - France\n\nFlemish Falchion - C. 1400 - Musée de L’Armée - France\n\nCastello di Avio - 1350 - Italy","page_from":8,"page_to":9,"stable_key":"falchions:5.1","parent_key":"falchions:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"10cbf7046134d3675d543f95fd8bd573e809707a294c08e1f29091399a3c5b09","has_figures":true,"extraction":"mixed"},{"ordinal":13,"depth":1,"kind":"rule","number":"5.2","title":"Examples of Approved Reproductions","body":"Picture from Gohurt ©\n\nPicture from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"falchions:5.2","parent_key":"falchions:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3295b56e44a6a5c345eb0e481ed095b2479d6cdb11c2c3f701c24004eff9d7cb","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":0,"kind":"section","number":"6","title":"Falchions Type 3","body":"","page_from":11,"page_to":11,"stable_key":"falchions:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"abcaf33849dc876b9c47b4549a2631f9a28e9e1502caa36404097c2dfc333255","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"Type 3 falchions are based on Elmslie typology. They are characterized by having scalloped or cutaway tips on the blades of various shapes. The curvature of the blade can vary.\nThere are 5 subtypes, from 3a to 3e.\nAll type 3 falchions have been used since the 14th century.\nThey are Approved for 14th century, Transitional and 15th century armors.\nA particular attention must be paid to the safety of the pointy edge, it must be made to be safe.\n\nFalchion from Thorpe - 1350 - England\n\nBNF Français 167 Bible Moralisée - 1345/1355 - France\n\nMorgan M.394 Bible Historiale - 1415 - France","page_from":11,"page_to":13,"stable_key":"falchions:6.1","parent_key":"falchions:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"da0c3fb7a64558fba0e0b2fe656b63261ea26de8ea2edab99e0732b42aa52b80","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"6.2","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":14,"page_to":14,"stable_key":"falchions:6.2","parent_key":"falchions:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"034e82c6b3677d1fcc994784e78ae900a90eb0bfbde1c2fedaabe9861990de84","has_figures":true,"extraction":"text"},{"ordinal":17,"depth":0,"kind":"section","number":"7","title":"Falchions Type 4","body":"","page_from":15,"page_to":15,"stable_key":"falchions:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fac5021304a9db2421638cd8fad066fb4b08bd5027181d6e0c3cab59369a1395","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"Type 4 falchions are based on Elmslie typology. They are characterized by a curved blade that gives them a sabre look.\nThere are 4 subtypes, from 4a to 4d.\nAll type 4 falchions have been used since the 14th century.\nThey are Approved for 14th century, Transitional and 15th century armors.","page_from":15,"page_to":15,"stable_key":"falchions:7.1","parent_key":"falchions:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c214b388c77c57bc07305df1081064ca9de6cee455fcb627b18404ca3804baf2","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"7.2","title":"Examples of Approved Reproductions","body":"Picture from Gohurt ©","page_from":15,"page_to":15,"stable_key":"falchions:7.2","parent_key":"falchions:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c2e9c9ecebac4711aa1a5a2b832c980f6a02e28977695883bb24fad0839f25d5","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":0,"kind":"section","number":"8","title":"Falchions Type 5","body":"","page_from":16,"page_to":16,"stable_key":"falchions:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4e314807b291df56d2e7c9cdb55ca77e491c0d7b78d10237889d0d90d98d9384","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"8.1","title":"Historical Sources and Datation","body":"Type 5 falchions are based on Elmslie typology. They are characterized by relatively symmetrical profiles, typically featuring little to no curvature over their length.\nThere are 5 subtypes, from 4a to 4e.\nAll type 5 falchions have been used since the 14th century.\nSubtypes 5a, 5b, 5c falchions are Approved for 14th century, Transitional and 15th century armors.\nSubtypes 5d and 5e are Denied for safety reasons.\n\nAPPROVED\n\nDENIED\n\nMorgan M.394 Bible Historiale - 1415 - France","page_from":16,"page_to":17,"stable_key":"falchions:8.1","parent_key":"falchions:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ed963c60a158e33f66f50304f01d3c20811f03149d097f91e812a60f32cdbeee","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":0,"kind":"section","number":"9","title":"2-Handed Falchions","body":"","page_from":18,"page_to":18,"stable_key":"falchions:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a7e00b7919f7ba982e901c1ada7e8891fde209dd18b5238ee665d12d13b519c","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"9.1","title":"Historical Sources and Datation","body":"2-handed falchions are not based on Elmslie typology. They are depicted in manuscripts from the middle ages in Europe.\nThere are 3 subtypes of 2-handed that are suitable for buhurt:\n● Type 2 It has a similar shape to 1-handed falchion type 2, with a square guard.\n● Type 3c It has a similar shape to 1-handed falchion type 3c.\n● Type 3e It has a similar shape to 1-handed falchion type 3e.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\n2-handed Type 2\n\nRomance of Alexander - 1338/1344 - England\n\n2-handed Type 3c\n\nLyon BM PA 30 Cy commencent les grans croniques de la genealogie des roys de France - 1380 - France\n\n2-handed Type 3e\n\nMartyr of Saint Savinien - Bibliotheque Nationale de France - Department of Manuscripts 50 f. 324v. - second half of the 14th century - France","page_from":18,"page_to":19,"stable_key":"falchions:9.1","parent_key":"falchions:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"38458379aae0152ee68712d98e17ab0c42e4a17636eef81b206fde7f76ad000a","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"9.2","title":"Examples of Approved Reproductions","body":"2-Handed Type 2 2-Handed Type 3c\n\n2-Handed Type 3e\n\nPictures from Medieval Extreme ©","page_from":20,"page_to":20,"stable_key":"falchions:9.2","parent_key":"falchions:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cfa9bdefa909d739ebeac7c7060e0f30ed9b808a75ef325b4eec03c4c123964d","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":0,"kind":"section","number":"10","title":"Pommels and Guards","body":"","page_from":21,"page_to":21,"stable_key":"falchions:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f701ee8f8fffc7f779b35fba4604f93d474537c2ac76209ed4861115ba3258f3","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"10.1","title":"Pommels","body":"Pommels can be of many forms and designs, mainly of rounded or square shape.\nPommels shapes are sorted under the Oakeshott Typology.\nPommels can be decorated.\nAny metal part of the pommel must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nExample of historical shapes from OakeshottTypology:\n\nTypes A to E are all Denied as they are from centuries that predate the 14th century.\n\nTypes G1 and G2 originated from the 16th century.\nThey are:\n● Approved for 16th century armors and weapons.\n● Denied for 14th century, Transitional and 15th century armors and weapons.\n\nFor safety reason, it is Denied to reproduce a hook shape for the pommel, despite it is documented by historical sources, such as:","page_from":21,"page_to":22,"stable_key":"falchions:10.1","parent_key":"falchions:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"69c5dd929377c6cc57ef9262b284316841c65f8df5b83605c4dad4915f7756c6","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"10.2","title":"Guards","body":"Guards can be of many forms and designs, mainly of straight design for 14th and 15th century designs.\nIt is recommended to avoid exotic shapes of guards and stick to the classic shapes, widely supported by historical sources.\nGuards can be decorated.\nAny metal part of the pommel must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nExample of historical shapes from Oakeshott Typology:\n\n© Ewatt Oakeshott - The Sword in the Age of Chivalry\n\nNote: Oakeshott defined up to 12 different styles of guards, with variations.\nWe selected only the first 6 styles to keep the document simple, but other styles of guards from the Oakeshott typology are acceptable to use.","page_from":23,"page_to":23,"stable_key":"falchions:10.2","parent_key":"falchions:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"18cc342bad442de80ced9fc110baaaee93256c1b3369006abbc85157ba4946a7","has_figures":true,"extraction":"text"},{"ordinal":28,"depth":0,"kind":"section","number":"11","title":"Common Mistakes","body":"","page_from":24,"page_to":24,"stable_key":"falchions:11","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3f4c410d7e4a85130f354b67a48a8ce0cd86bd6db07eba5f8bfe2b7c9f747dc1","has_figures":true,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"11.1","title":"1-Handed Falchions with D-guards","body":"From the 16th century, mainly in Italy, falchions with “D Guard” started to be used for civil combats.\nThey represent a serious risk of injury and can not be used.\n\nAll 1-handed falchions reproducing the designs of a 1-handed falchion with a D-guard are Denied.\n\n1.1. Examples of Denied Reproductions\n\nPicture from Medieval Extreme ©","page_from":24,"page_to":24,"stable_key":"falchions:11.1","parent_key":"falchions:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c3640c2687fe066eaff1302ffa95a2028fc750a9c6c2045a78fde85ab33cd3a1","has_figures":true,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"11.2","title":"Beidanas","body":"Beidanas are a farming tool from the 17th century in Italy. Despite its falchion inspired design, it is not a weapon for combat and therefore not suitable for buhurt.\n\nAll falchions reproducing the designs of a Beidana are Denied.","page_from":25,"page_to":25,"stable_key":"falchions:11.2","parent_key":"falchions:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"39e1e66cafe19b18370f8255f75a535b62de7aeacc4ef9aec8f8f14b9cb8a709","has_figures":true,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"11.3","title":"Falchions from the Morgan Bible (or Maciejowski Bible)","body":"This manuscript is often used for falchions sources. But it originated from the middle of the 13th century, and its design is unsafe for our sport.\n\nAll falchions reproducing the designs from this manuscript are Denied.","page_from":25,"page_to":25,"stable_key":"falchions:11.3","parent_key":"falchions:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"68e47d657f9c04d64e41e8adb13fc37460341bdbd626f9aede5fd48693c87ac3","has_figures":true,"extraction":"text"},{"ordinal":32,"depth":0,"kind":"note","number":"12","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Add: Document has been created","page_from":26,"page_to":26,"stable_key":"falchions:12","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"54f799fdbff43d99ef59179c1314369afe8b3c78d9187fb918b06e7870ccc288","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/gauntlets","synthetic":false,"version":{"version":"26.1","title":"Gauntlets - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1u71LdLSm6zVKW7jhI5djRKiF7D5UtqRS/view?usp=drive_link","source_sha256":"013dcddd2f2fb0033cbab5f06ce06fca2d8cc3b1a56eb3a2e26cf1923f797b6f","retrieved_at":"2026-10-06T00:00:00Z","page_count":21,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 20 page(s) without a text layer","content_sha256":"4092d2ced6c244d8d987c8757a1c2c570e3c3a2f69720af01b72690e96b67275","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":21,"source_lines":335,"assigned_lines":482,"furniture_lines":43,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99604,"provisions":55,"numbered":54,"needs_review":0,"verified":1,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":335,"picture_text_lines":7,"ocr_corrections":2}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"gauntlets:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"gauntlets:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Gauntlets (a pair of)” is the term used to describe all hand protections.\nType of Gauntlets:\n\n● Scales gauntlets Gauntlets made of multiple metal scales.\n\n● Hourglass gauntlets Named after an hourglass due to its shape. They are the main Gauntlets used during the 14th to the 16th century. Historically they have separated fingers.\n\n● Segmented mittens Gauntlets that appeared in the late 14th century. They are made of articulated plates. Historical sources are quite few and controversial.\n\n● 3/4 gauntlets Gauntlets that appeared in the early 15th century. They combine strength and flexibility due to separated fingers.\n\n● Milaneses gauntlets Gauntlets that appeared in the middle of the 15th century. They are articulated and provide very good protection.\n\n● Late 15th century gauntlets Bifurcated mittens from the late 15th century. They follow the same shape as milanese or gothic-style mittens, but the fingers are separated in the middle.\n\n● Plate articulated mittens Gauntlets that appeared in the late 15th century. They are made of articulated plates.\n\n● Under-shield gauntlets Metal plates riveted to a fabric base. They are allowed as buhurt-optimization. They must be worn only with a shield.\n\n● Eastern gauntlets Due to very few historical sources, it is allowed to use eastern stylization of European Gauntlets.\nAllowed designs are displayed in the “Eastern Armors” document.","page_from":3,"page_to":3,"stable_key":"gauntlets:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d12e69895f39b7d20a88d300f80432f752a8c6e12207efce746a982b47343a17","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"","page_from":4,"page_to":4,"stable_key":"gauntlets:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8295fe2bc4208d485f0e4d62f112a839e3bfc08e2b952098f2a20793db34314","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"Historical Basis","body":"All Gauntlets must be based on historical sources.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.1","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"689b441e7c974bec5546ad78b243029361e1c1d4eecc1c6a95908b8929a39c5d","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Proportional Accuracy","body":"The proportions of the Gauntlets must replicate those found in historical sources.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.2","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fd9d7249620620f53aa8386c66ccaeee15eebff36b98f5ade803e3e5346545d0","has_figures":false,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"3.3","title":"Aesthetic Consistency","body":"The overall aesthetic of the Gauntlets must imitate that of historical sources.\nIt is allowed to adapt the historical designs to allow a better grip. Such adapted design must conform with the historical design and proportions.\n\nExample of approved adapted design for better grip:","page_from":4,"page_to":4,"stable_key":"gauntlets:3.3","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d9664dd31db9fdf02087627da9298e75c67c3a4536ec6c53cb357278b7b8db0a","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.4","title":"Component Proportions","body":"Components must not be out of proportion in terms of length, size, or curve.\nComponents must fit harmoniously with one another, and the gauntlet must function properly.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.4","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3cd059b94ac3c550483248a15ece1e2994dcfba7d19580e51027ad899cf0e887","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.5","title":"Comprehensive Protection","body":"Gauntlets must protect the entire hand, including the wrist, fingers, and nails.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.5","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"25c7d9b5f2d98f925765fdd888d874c7b139a365235838a1ccaaa8f861b54cac","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.6","title":"Metal Components","body":"Any metal parts of the Gauntlet must conform to the standards outlined in the “Armors and Weapons Aesthetics and Decorations” document.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.6","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"69a7e6f89223c2501aa827f06ea9ca0c7ce0d5f568ef5ed66820f1348de96c28","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.7","title":"Textile and Leather Components","body":"Any textile or leather parts of the Gauntlet must adhere to the standards outlined in the “Textiles and Leather” document.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.7","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b16849e46658334a448ab620de6c4d1da5d6112531a992940e749567277bf5c1","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.8","title":"Decorative Elements","body":"Gauntlets may be decorated in medieval styles, such as etching, engraving, plating, or gilding.\nDecoration must be consistent with historical sources and the overall armor style.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.8","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7c9ce06cfcbb910c639edbc33af8553fd1734395c3a73d0a712f7737eb6c4f2e","has_figures":false,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.9","title":"Prohibited Imagery","body":"The use of modern and/or offensive imagery and slogans is strictly prohibited.","page_from":4,"page_to":4,"stable_key":"gauntlets:3.9","parent_key":"gauntlets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7cd41ab1cf3405bdc5b7342bf70c61641c25d08578861437fbb1cb65fe7a18d8","has_figures":false,"extraction":"ocr"},{"ordinal":14,"depth":0,"kind":"section","number":"4","title":"Scales Gauntlets","body":"","page_from":5,"page_to":5,"stable_key":"gauntlets:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"53aacd5ae982e5c723852adb8b2b2bbfed1b9f3bc144a99b2b6f91190eb59509","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"Scales Gauntlets are made of several scales sewn or riveted to a base, made of fabric or leather.\nThey are based on historical sources of the first half of the 14th century.\n\nThey are Approved for 14th century and Transitional armors.\n\nThey are Denied for 15th century armors.\n\nBNF Frangais 2091 Vita et Passio Beati Dionysii - 1317 - France Bodley 264 Romance of Alexander - 1338/1344 - England","page_from":5,"page_to":5,"stable_key":"gauntlets:4.1","parent_key":"gauntlets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c760ec65c1dbdf7c61f3395bd128959a6ed0efcd41ec042086cee6c23ea93c96","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"Scales Gauntlets must:\n\n● conform to the General Requirements (see Section 3 above),\n● be made of square or rectangular metal plates,\n● be made of:\n○ 5 rows of scales to protect the hand and the fingers, ○ 3 rows of scales to protect the sleeve and the wrist,\n● have a pronounced curve at the wrist.","page_from":5,"page_to":5,"stable_key":"gauntlets:4.2","parent_key":"gauntlets:4","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"acca473126c416d8845c0c126ba7a32473967d3712ccadb1433edace7c5db7d3","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Reproductions","body":"Pictures from Ficelle ©","page_from":5,"page_to":5,"stable_key":"gauntlets:4.3","parent_key":"gauntlets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5b273ef1cbb094737569f6f156140a1398a91016394d4429c0327c0c5cbde8c0","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.4","title":"Examples of Denied Reproductions","body":"Not enough scales (1 row on the wrist)\n\nPictures from The Medieval Things ©","page_from":6,"page_to":6,"stable_key":"gauntlets:4.4","parent_key":"gauntlets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e394fb44fbf069e4c34cffee94ac4758985050bc22cdf9535bbaa5ecce14f273","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":0,"kind":"section","number":"5","title":"Hourglass Gauntlets","body":"","page_from":7,"page_to":7,"stable_key":"gauntlets:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b5b21e7304fc02c7a03166c229441090bbbbc53dda79bd0eea7e6a6c78671395","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"Hourglass Gauntlets appeared around the middle of the 14th century. They were still in use during the 15th century under different designs. They are made of a solid cuff, designed as an hourglass, and separated finger plates.\n\nFor safety reasons, it is allowed to use a buhurt-optimization version of hourglass Gauntlets, with non-separated finger plates (also called “Hourglass mittens”). This type of Gauntlet must respect the style of historical hourglass gauntlets and be properly articulated.\n\nThe historical Gauntlets with separated fingers lack safety. They are no longer allowed in Buhurt International.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nGauntlets of Ripon Cathedral - 1380/1410 - England","page_from":7,"page_to":7,"stable_key":"gauntlets:5.1","parent_key":"gauntlets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ceaf0b1518849a3cc27047b3f473512c6d8a969ac3e723ccb8d50c4e3e02c3d0","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"Hourglass Gauntlets must conform to the General Requirements (see Section 3 above).\nThe design of the cuff must clearly present the correct hourglass shape.\nThumb protection must:\n\n● have anatomical shape,\n● be articulated with at least 2 segments, or\n● imitate the appearance of 2 segments-articulated thumb.\n\nDespite being 100% historical, separated-fingers Gauntlets are not allowed due to lack of safety.","page_from":7,"page_to":7,"stable_key":"gauntlets:5.2","parent_key":"gauntlets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"2d18a6bb09e2b12587b4013e099f86a4586c53ec1cb15b7a3c3a421d82e2a687","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Reproductions","body":"Picture from Medieval Extreme © Picture from Master Uley ©","page_from":8,"page_to":8,"stable_key":"gauntlets:5.3","parent_key":"gauntlets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"204b1ad1cf1bbbfd6cc46a9208db24fa0d008d375451ceabcd90e1868512bdf6","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Denied Reproductions","body":"Fully articulated fingers\n\nPicture from Age of Craft ©\n\nPlate Gauntlets with brigandine cuffs Historical sources do not support this construction. Brigandine gauntlets were built with small plates of metal riveted to a leather base, which makes them not safe enough for our sport.\n\nPicture from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"gauntlets:5.4","parent_key":"gauntlets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"034e1ec3da210e13f8d0c5688a7112ae483ed447625dcbd633372cda5cb43b64","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":0,"kind":"section","number":"6","title":"Segmented Mittens","body":"","page_from":9,"page_to":9,"stable_key":"gauntlets:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2c2c5bad3375e943956a5c1f981cfaffac10be2f48931f83e245ffaa915d7755","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"Segmented mittens are based on controversial historical sources. One of them in a wooden statue decorating a fountain in Nuremberg (Germany). The actual statue is a reproduction of the original one.\nOne of its hands is incomplete so it’s not possible to evaluate the accuracy of this source.\n\nFor safety reasons, it is allowed to use buhurt-optimized segmented mittens with alternative design. This type of Gauntlets must respect the style of historical segmented mittens and be properly articulated.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nFountain of Nuremberg (Germany), the original is from the 14th century (left) and the reproduction is from the 20th century (right).","page_from":9,"page_to":9,"stable_key":"gauntlets:6.1","parent_key":"gauntlets:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b58b58a851f5988b2e804b24f18eaecc7eb180bdc2a4f66fe751d8cf1d39fe44","has_figures":true,"extraction":"ocr"},{"ordinal":26,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Segmented mittens must conform to the General Requirements (see Section 3 above).\nThe design of the cuff must clearly present the correct hourglass shape.\nThumb protection must:\n\n● have anatomical shape,\n● be articulated with at least 2 segments, or\n● imitate the appearance of 2 segments-articulated thumb.","page_from":9,"page_to":9,"stable_key":"gauntlets:6.2","parent_key":"gauntlets:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"61d8595a1cf2358e497f59c87dfc5403252723e5328da5a4d03986e16a807853","has_figures":true,"extraction":"ocr"},{"ordinal":27,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Picture from Age of Craft ©","page_from":10,"page_to":10,"stable_key":"gauntlets:6.3","parent_key":"gauntlets:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5941e2b8cd2d85f525ddf78b582cbfec677f90331aaf52a1321b7517ad4d695c","has_figures":true,"extraction":"ocr"},{"ordinal":28,"depth":0,"kind":"section","number":"7","title":"3/4 Gauntlets","body":"","page_from":11,"page_to":11,"stable_key":"gauntlets:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8673462b26d8d9f240b96e8b2d17c7d1c37874e2201d8827d5b7a4d09828332b","has_figures":true,"extraction":"ocr"},{"ordinal":29,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"3/4 gauntlets tend to appear in the early 15th century. They are made of a solid cuff with a metacarpal plate. This plate can be riveted or articulated. Fingers are protected by separated plates or chainmail.\n\nThey are Approved for Transitional and 15th century armors.\nThey are Denied for 14th century armors.\n\nFor safety reasons, 3/4 gauntlets must use faux-finger mittens rather than individual finger plates. In other words, separate, fully articulated finger gauntlets are not permitted. These mitten-style 3/4 gauntlets must still respect the overall historical shape and proper articulation of 15th-century examples.\n\nChurchburg- 1410/1430 - Italy Sion Castle Museum - 1420/1440 - Switzerland","page_from":11,"page_to":11,"stable_key":"gauntlets:7.1","parent_key":"gauntlets:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"93d370e6e06ce33e550174c4e7f703521d8f3d0b6dc06113b71547db270cb2f8","has_figures":true,"extraction":"ocr"},{"ordinal":30,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements","body":"3/4 Gauntlets must conform to the General Requirements(see Section 3 above).\nThe design of the cuff must clearly present the correct hourglass shape.\nMetacarpal plate can be either riveted or historically accurate articulation Thumb protection must:\n\n● have anatomical shape,\n● be articulated with at least 2 segments, or\n● imitate the appearance of 2 segments-articulated thumb.","page_from":11,"page_to":11,"stable_key":"gauntlets:7.2","parent_key":"gauntlets:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"2eb1ad3398d656f1dd1fd8fee7526146b901deeab7c84e4dda7c8e44b42f15a6","has_figures":true,"extraction":"ocr"},{"ordinal":31,"depth":1,"kind":"rule","number":"7.3","title":"Examples of Denied Reproductions","body":"Fully articulated fingers\n\nPicture from Age of Craft ©","page_from":11,"page_to":11,"stable_key":"gauntlets:7.3","parent_key":"gauntlets:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e68d1f22ccc9f17028bf6026da28230acff8e11924a09473df3f68299af5c89d","has_figures":true,"extraction":"ocr"},{"ordinal":32,"depth":0,"kind":"section","number":"8","title":"Milanese Gauntlets","body":"","page_from":12,"page_to":12,"stable_key":"gauntlets:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a7482ddcfde90154fc5508d596d60f54d15973f1c4e2653fc1e8130def96209d","has_figures":true,"extraction":"ocr"},{"ordinal":33,"depth":1,"kind":"rule","number":"8.1","title":"Historical Sources and Datation","body":"“Milanese gauntlets” term regroups several 15th century mitten shapes, with different designs. Common features are articulated plates (including metacarpal plate, such as 3/4 gauntlets), profiled wrist plate and a full protection of the fingers.\n\nThey are Approved for 15th century armors.\n\nThey are for 14th century and Transitional armors.\n\nGlasgow - 1438/1440 - Scotland Metropolitan Museum of Art - 1450/1470","page_from":12,"page_to":12,"stable_key":"gauntlets:8.1","parent_key":"gauntlets:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a422757417a29417c19fd9f2fa6107a92dfef39094df25d4d16674f98efa85e6","has_figures":true,"extraction":"ocr"},{"ordinal":34,"depth":1,"kind":"rule","number":"8.2","title":"Specific Requirements","body":"Milanese Gauntlets must conform to the General Requirements (see Section 3 above).\nThe design of the cuff must clearly present the correct profiled shape.\n\nThe cuff must match the historical proportion in matter of length and width.\n\nCuff and metacarpal plate can be either riveted or historically accurate articulation Thumb protection must:\n\n● have anatomical shape,\n● be articulated with at least 2 segments, or\n● imitate the appearance of 2 segments-articulated thumb.","page_from":12,"page_to":12,"stable_key":"gauntlets:8.2","parent_key":"gauntlets:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"83738dcdb3a6a5ef279370c332ac2a14365bc9aa6cd2d2bc964f5d7bbfc90ca3","has_figures":true,"extraction":"ocr"},{"ordinal":35,"depth":1,"kind":"rule","number":"8.3","title":"Examples of Approved Reproductions","body":"Pictures from Black Dog Armoury ©","page_from":12,"page_to":12,"stable_key":"gauntlets:8.3","parent_key":"gauntlets:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17ba77fc90d58666665f98000619ea873033deaabb050437c9268bb034b02a40","has_figures":true,"extraction":"ocr"},{"ordinal":36,"depth":0,"kind":"section","number":"9","title":"Late 15th century Gauntlets","body":"","page_from":13,"page_to":13,"stable_key":"gauntlets:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"65f288331c617259f6d9433fe6274f2a00b67f4c452f7633c60fe0dbcaa2674b","has_figures":true,"extraction":"ocr"},{"ordinal":37,"depth":1,"kind":"rule","number":"9.1","title":"Historical Sources and Datation","body":"The term “Late 15th century Gauntlets” regroups 2 different types of Gauntlets: bifurcated mittens and locked Gauntlets.\n\nThey are Approved for 15th century armors.\nThey are Denied for 14th century and Transitional armors.","page_from":13,"page_to":13,"stable_key":"gauntlets:9.1","parent_key":"gauntlets:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"44c859c36a2e610a741da13716249b5666b6e8fef17f11db1b57c53d266d985a","has_figures":true,"extraction":"ocr"},{"ordinal":38,"depth":1,"kind":"rule","number":"9.2","title":"Bifurcated Mittens","body":"They follow the same shape as milanese mittens, but the fingers are protected by 2 plates instead of 1, increasing the handling of the weapon. They appeared in the late 15th century.","page_from":13,"page_to":13,"stable_key":"gauntlets:9.2","parent_key":"gauntlets:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"22bb7ffa36a088413916696bd43cb672cf068a09cd7aa1aedf3733b37cec4087","has_figures":true,"extraction":"ocr"},{"ordinal":39,"depth":1,"kind":"rule","number":"9.3","title":"Locked Gauntlets","body":"They follow the same shape as milanese mittens, but the whole Gauntlet can be locked to prevent any weapon loss.","page_from":13,"page_to":13,"stable_key":"gauntlets:9.3","parent_key":"gauntlets:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"513caf8b7e56c35ea49c5be1ed786a557f556073b0e98d12e572ae88a459c583","has_figures":true,"extraction":"ocr"},{"ordinal":40,"depth":1,"kind":"rule","number":"9.4","title":"Specific Requirements","body":"Late 15th Century Gauntlets must conform to the General Requirements (see Section 3 above).\nThe design of the cuff must clearly present the correct profiled shape.\n\nThe cuff must match the historical proportion in matter of length and width.\n\nCuff and metacarpal plate can be either riveted or historically accurate articulation\n\nThumb protection must:\n\n● have anatomical shape,\n● be articulated with at least 2 segments, or\n● imitate the appearance of 2 segments-articulated thumb.","page_from":14,"page_to":14,"stable_key":"gauntlets:9.4","parent_key":"gauntlets:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"8f26d0a662c157035493e81aa5ed5e8ff04d73d0fd6d8d02607504f86cc3de25","has_figures":false,"extraction":"ocr"},{"ordinal":41,"depth":0,"kind":"section","number":"10","title":"Plate Articulated Mittens","body":"","page_from":15,"page_to":15,"stable_key":"gauntlets:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"46039b63e3cc70840978fc29d298d0bd8158b714e9062d594697e7116f30790f","has_figures":true,"extraction":"ocr"},{"ordinal":42,"depth":1,"kind":"rule","number":"10.1","title":"Historical Sources and Datation","body":"There are no historical sources for such Gauntlets. They are buhurt-optimization Gauntlets designed to provide sufficient protection for full contact fights.\n\nThe global design takes inspiration from the photo below (1510 gauntlet).\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nWallace Collection - Germany","page_from":15,"page_to":15,"stable_key":"gauntlets:10.1","parent_key":"gauntlets:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"51753d23c7540f46b8a3441a9513c2c97cbce757ca18bc18f6693863ee79a36a","has_figures":true,"extraction":"ocr"},{"ordinal":43,"depth":1,"kind":"rule","number":"10.2","title":"Specific Requirements","body":"Plate articulated mittens must conform to the General Requirements (see section 3 above).\nThe design of the cuff must clearly present the correct profiled shape.\n\nThe cuff must match the historical proportion in matter of length and width.\n\nCuff and metacarpal plate can be either riveted or historically accurate articulation\n\nThumb protection must:\n\n● have anatomical shape,\n● be articulated with at least 2 segments, or\n● imitate the appearance of 2 segments-articulated thumb.\n\nExamples of Approved Reproductions\n\nPictures from Medieval Extreme ©","page_from":15,"page_to":16,"stable_key":"gauntlets:10.2","parent_key":"gauntlets:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"b2ec4d02f07e50b3642387cd600a1c6ef8c237f84ca8917f54d18da8d1682a77","has_figures":true,"extraction":"ocr"},{"ordinal":44,"depth":0,"kind":"section","number":"11","title":"Under-shield Gauntlets","body":"","page_from":17,"page_to":17,"stable_key":"gauntlets:11","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"14725e40ea12de271aa221a11511b7cc73f495fa3154e1dbfda387c1c3954b14","has_figures":true,"extraction":"ocr"},{"ordinal":45,"depth":1,"kind":"rule","number":"11.1","title":"Historical sources and datation","body":"There are no historical sources for such Gauntlets. They are buhurt-optimized Gauntlets designed to provide sufficient protection for the shield-wearer, thus being lighter and cheaper. However, it is not recommended to use such under-shield Gauntlets for buhurt categories.\n\nThey are Approved for 14th century, Transitional and 15th century armors.","page_from":17,"page_to":17,"stable_key":"gauntlets:11.1","parent_key":"gauntlets:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae76741b0a56cc899c4ba0de3c1a1083f8f26cc894a3187ade8b7452d7e2706f","has_figures":true,"extraction":"ocr"},{"ordinal":46,"depth":1,"kind":"rule","number":"11.2","title":"Specific Requirements","body":"Under-shield Gauntlets must:\n● conform to the general requirements (see section 3 above),\n● be made of metal plates riveted or sewn to a fabric or leather base.\n\nThe plates:\n● Must cover at least the fingers, including the thumb and the exposed-part of the wrist.\n● Must be firmly-riveted to a fabric or leather base\n\nThe base must conform to the “Textiles and Leather” document.","page_from":17,"page_to":17,"stable_key":"gauntlets:11.2","parent_key":"gauntlets:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"02fbd0cecf27913e114d86789dadf8d16043f87a1a19a77284b02d376cc7f6ee","has_figures":true,"extraction":"ocr"},{"ordinal":47,"depth":1,"kind":"rule","number":"11.3","title":"Examples of Approved Reproductions","body":"Pictures from Medieval Extreme","page_from":17,"page_to":17,"stable_key":"gauntlets:11.3","parent_key":"gauntlets:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"637309dc1b3f3fba43b8e045f7be384c7b8840bfb4b778aa3a726aa8e262df00","has_figures":true,"extraction":"ocr"},{"ordinal":48,"depth":1,"kind":"rule","number":"11.4","title":"Examples of Denied Reproductions","body":"No metal plate to protect the fingers\n\nPictures from The Medieval Things ©","page_from":17,"page_to":17,"stable_key":"gauntlets:11.4","parent_key":"gauntlets:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ac5318f289fe11682fd38a4ad3859472422601738ad621eb5381f810ee566c4e","has_figures":true,"extraction":"ocr"},{"ordinal":49,"depth":0,"kind":"section","number":"12","title":"Buhurt-optimization locking systems","body":"","page_from":18,"page_to":18,"stable_key":"gauntlets:12","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d8a11aba6c81e850ea8aec74ed568744d8e1e5b602093298d5016e3fbdad258b","has_figures":false,"extraction":"ocr"},{"ordinal":50,"depth":1,"kind":"rule","number":"12.1","title":"Historical Sources and Datation","body":"There are no historical sources for locking systems. However, it is likely plausible that knights of the middle ages used different techniques to prevent any loss of weapon during the battle. One of them consists of chains attached to the coat of plate. If the weapon should slip from the hand, it will not touch the ground, and therefore can be grabbed back.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\nBuhurt-optimization system can be:\n\n● Asystem to attach the weapon to the Gauntlet, preventing any loss of weapon,\n● Asystem to lock the Gauntlet in “close” position, preventing any loss of weapon,\n● Asystem to attach the Gauntlet to the forearm, preventing the Gauntlet to be removed.","page_from":18,"page_to":18,"stable_key":"gauntlets:12.1","parent_key":"gauntlets:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0b18df2b209557beb3782f42e4b3509a25715a4859f72250d5fa466ca8a4a663","has_figures":false,"extraction":"ocr"},{"ordinal":51,"depth":1,"kind":"rule","number":"12.2","title":"Specific Requirements","body":"Buhurt-optimization locking system can be allowed under certain conditions.\n\n● Weapon lock It is allowed to lock a weapon to the Gauntlet with an additional leather thread, leather strap, or any discrete and historically plausible system.\n\nAdditional leather elements must conform to the “Textiles and Leather” document.\n\n● Locked gauntlets\n\nIt is allowed to lock a Gauntlet in “close” position with an additional leather strap, or any discrete and historically plausible system.\n\nAdditional leather elements must conform to the “Textiles and Leather” document.\n\n● Gauntlet’s safeguard\n\nIt is allowed to attach a Gauntlet to another armor element (I.E forearm, gambeson) with an additional leather thread, leather strap, or any discrete and historically plausible system.\n\nAdditional leather elements must conform to the “Textiles and Leather” document.","page_from":18,"page_to":18,"stable_key":"gauntlets:12.2","parent_key":"gauntlets:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f7091a4978996250e9df36a9d6f50552dede7ca4f135b5513a55ec3207fc761b","has_figures":false,"extraction":"ocr"},{"ordinal":52,"depth":1,"kind":"rule","number":"12.3","title":"Examples of Approved Reproductions","body":"Lace or strap to secure the Gauntlet in close position\n\nPicture from Medieval Extreme ©\n\nPicture from F. Guts ©","page_from":19,"page_to":19,"stable_key":"gauntlets:12.3","parent_key":"gauntlets:12","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3e58f28ce5d6bf27bea31614c8f7ebacd5233639d060087da5f25828f6c37737","has_figures":true,"extraction":"ocr"},{"ordinal":53,"depth":1,"kind":"rule","number":"12.4","title":"Examples of Denied Reproductions","body":"Strap is too visible","page_from":19,"page_to":19,"stable_key":"gauntlets:12.4","parent_key":"gauntlets:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3b7668a32bf50b217e9bf39e9d0fee21b9f3cb6ae25108ddbaa4880944c2850e","has_figures":true,"extraction":"ocr"},{"ordinal":54,"depth":0,"kind":"section","number":"13","title":"Other Denied Items","body":"Chainmail Gauntlet, not safe enough Brigant Gauntlets are not safe enough\n\nGauntlets not based on historical sources\n\nPictures from The Medieval Things ©","page_from":20,"page_to":20,"stable_key":"gauntlets:13","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"af0918185cbcc0de6eb68ee2f061f438ab3154d5c08f2d38fae3be83ba87f693","has_figures":true,"extraction":"ocr"},{"ordinal":55,"depth":0,"kind":"note","number":"14","title":"Changelog","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd? “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Modification of “1. Definition and general requirements” to “1. Definition”\n\nReplace:\n\n- “2.1 Definition” by “Type of gauntlets:”\n\nAdd:\n\n- In 3.3 Aesthetic Consistency: “It is allowed to adapt the historical designs to allow a better grip.\nSuch adapted design must conform with the historical design and proportions.” and a picture as an example\n\n- In 4.4 Examples of denied reproductions (scales gauntlets): “(1 row on the wrist)”\n\n- In 5.4 Examples of denied reproductions (hourglass gauntlets): “Fully articulated fingers” Replace:\n\n- In 5.4 Examples of denied reproductions (hourglass gauntlets): “The leather part is not based on historical sources.” by “Plate gauntlets with brigandine cuffs are not based on historical sources”\n\n- In 7. % gauntlets: paragraph “For safety reasons, [...]” entirely rewritten\n\nAdd:\n\n- In 7.4 Examples of denied reproductions (% gauntlets): “Fully articulated fingers”\n\nReplace:\n\n- In 8.1 Historical sources and datation (Milanese gauntlets):\n\n- “They are approved for Transitional and 15th century armors.” by “They are approved for 15th century armors.”\n\n- “They are denied for 14th century armors.” by “They are denied for 14th century and Transitional armors.”\n\nAdd:\n\n- In 13.4 Examples of approved reproductions (Buhurt-optimization locking systems): new picture from F. Guts ©\n\n05-Dec-2024: -add Document has been created (Version 2024.12)","page_from":21,"page_to":21,"stable_key":"gauntlets:14","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":["3.3","4.4","5.4","7","7.4","8.1","13.4"],"content_sha256":"b9d34d6b4c0f7176ce5305de7f4a39c5afda731f02396ae1089c343ada26422a","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/great-helms","synthetic":false,"version":{"version":"26.1","title":"Great Helms - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/12ImGYz_z95qyThLls4MI8j0IUDuRDkq8/view?usp=sharing","source_sha256":"87fd76fb602b2955dca88a47a4b7c968b4b5120a56ee946b28c8d01848309f52","retrieved_at":"2026-10-06T00:00:00Z","page_count":7,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 7 page(s) without a text layer","content_sha256":"911fe0fbd663986b74afff99dfd841a9222be5ef573fd274a5663e981d24dc7c","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":7,"source_lines":98,"assigned_lines":129,"furniture_lines":21,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99682,"provisions":13,"numbered":12,"needs_review":0,"verified":1,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":98,"picture_text_lines":2,"ocr_corrections":1}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"great-helms:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"great-helms:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Great helms are a popular head defense formerly known as “Chapel de fer” from the 12th to the 14th centuries. Characterized by its cylindrical design and large size, it provided maximum protection for the face and neck. Often used as a secondary defense, it was worn over a maille coif, cervelliere, or bascinet.\n\nDuring the 14th century, Great helms were used as a primary defense during battle. It was designed to be removed after the early engagements.\n\nIn the late 14th and during the 15th century, Great helms evolved to be suitable for tournaments only.\nTheir latest version is called “Frogmouth” and is designed for jousting.\n\nGreat helms are Approved for 14th century, Transitional and 15th century armors.","page_from":3,"page_to":3,"stable_key":"great-helms:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"58ebed0621c4a3a660053f68c511be05fc97ebda4c523943ddeafe44415a0ece","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"Schweizerisches Landesmuseum - Germanisches National Museum - Pembridge Helm, National Museum of Scotland - 1325/1350 - Switzerland 1350 - Germany 1350/1375 - Scotland\n\nGerhard von Rieneck, Ederbach - Sir Nicholas Hawkberk Helm - “Frogmouth” helmet, The Art Institute of Chicago - 1382 - Germany 1407 - England 1490","page_from":3,"page_to":3,"stable_key":"great-helms:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a64f156f84734fc46662a96db5a973de84640755fd5b90489cb41a926d0d0979","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":4,"page_to":4,"stable_key":"great-helms:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of the sources.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":4,"page_to":4,"stable_key":"great-helms:4.1","parent_key":"great-helms:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e1e092015a328ec3efba910873117f0c08f7e9245beafb85f6b06c69c84de56b","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"The visor must not be too long or too short, it must respect the proportions of historical sources.\nBreath holes should be round and consistently sized unless documented by an historical source.\n\nBreath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.","page_from":4,"page_to":4,"stable_key":"great-helms:4.2","parent_key":"great-helms:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eedbb9100baee1f034a44cce626fa4e69c3ace528cca3d2c3283f1a276a5a1e6","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.3","title":"Eye slots","body":"Eye slots should resemble sources for the visor.\nEye slots should not exceed 25mm tall to prevent any injury.\nExternally riveted Eye bars must be based on documented historical examples.\n\nGreat helms with two (2) Eye slots are permitted to add up to two (2) externally riveted Eye bars or safety Eye bars per Eye slot.\n\nGreat helms with a single Eye slot are allowed to add up to five (5) safety Eye bars: one (1) in the middle and two (2) on each side.\n\nIt is not possible to mix externally riveted Eye bars and safety Eye bars on the same helmet. Only one type of Eye bar is allowed. Integrated Eye bars are not allowed.\n\nEye bars must conform to the “Eye bars” document.","page_from":4,"page_to":4,"stable_key":"great-helms:4.3","parent_key":"great-helms:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"01040b22f833f92edca02a3a70b6e03f4002cbc6354983d7443d9a40d4f7a387","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.4","title":"Aventails","body":"Great helms must be worn with chainmail Aventail or scale Aventail. Fabric Aventails are not allowed.\nAventails must conform to the “Aventails” document.\n\nGreat helms can not have a suspension system made of vervelles and leather. Chainmail should be affixed to the interior of the helmet.\n\nAny additional protective plates covering the cervical spine must be hidden under the Aventail.","page_from":5,"page_to":5,"stable_key":"great-helms:4.4","parent_key":"great-helms:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f87cb0878ee26d0f13a673b6535fbb005d1249f321a6bba44071124c6c37411b","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.5","title":"Others","body":"Great helms may be decorated in the spirit of medieval styles, such as an orle, torse, decorated Aventails (with copper/brass chainmail rings) coat of arms badges, etc.\n\nSuch decoration must be made in coherence with historical sources.\nUsing modern and/or offensive imagery and slogans is prohibited.","page_from":5,"page_to":5,"stable_key":"great-helms:4.5","parent_key":"great-helms:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"82aebbb0fbe20a3994972b1897414c6c3471b17a85544c33abd60ccc2b03a90a","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"Picture from J. Gries © Picture from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"great-helms:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a986d798b3d95c6b4249415d95f5931e85e1a2a75fab852b4caf0bf755fdb576","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"section","number":"6","title":"Examples of Denied Reproductions","body":"Design of the bottom of the visor does not reproduce historical sources.\n\nDesign of the top of the helmet does not reproduce historical sources.\n\nPictures from The Medieval Things ©","page_from":6,"page_to":6,"stable_key":"great-helms:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f309df6af798678038c3490679678375b83b6cc258bc0a0ada099c6a018b3965","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “1. implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- In 4.2 Visor Requirements: “Breath holes should be round and consistently sized unless documented by an historical source.”\n\nAdd:\n\n- In 4.3 Eye slots:\n\n- “Externally riveted eye bars must be based on documented historical examples.”\n\n- “Integrated eye bars are not allowed.”\n\nReplace:\n\n- In 4.3 Eye slots: “buhurt-optimized internal Eye bars” and “buhurt-optimized internal” by “safety Eye bars”\n\nDecember-2024: -add Document has been created","page_from":7,"page_to":7,"stable_key":"great-helms:7","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":["changelog"],"keywords":[],"cross_refs":["4.2","4.3"],"content_sha256":"bbb85ffd4c85d8933c274e2bea3862d3e32d60860ffae2022c6142c68430b8ef","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/greaves","synthetic":false,"version":{"version":"26.1","title":"Greaves - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1f9RnYIO90XcFlZyoKKVo6HjoM_3WH8xE/view?usp=sharing","source_sha256":"2f663fe24c935172f731eb2f4d42a3ee8227dfbde0f710e3415e0bc5da9d0cb4","retrieved_at":"2026-10-06T00:00:00Z","page_count":17,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 16 page(s) without a text layer","content_sha256":"2c8284d2cbda54b94328904b7009fbf95b6e70199b12ab809e6e0765f60cae98","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1","2 line(s) looked like a numbered heading but did not fit the sequence"],"pages":17,"source_lines":224,"assigned_lines":287,"furniture_lines":60,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.9943,"provisions":40,"numbered":39,"needs_review":0,"verified":1,"empty_pages":[1],"rejected_numbers":2,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":223,"picture_text_lines":1,"ocr_corrections":2}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"greaves:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"greaves:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Greaves” is the term used to describe all lower leg protections.\nTypes of Greaves:\n\n● 1-Panel Greaves (Half-Greaves)\n\nMade of 1 plate of metal forged to the shape of the lower leg.\nAttached by a leather strap at the back of the calf.\n\n● 2-Panel Greaves (Cased Greaves)\n\nMade of 2 plates of metal built to protect the lower leg at 360°.\nThe plates are built with hinges and attached by a leather strap at the inner side of the lower leg.\n\n● 3-Panel Greaves Made of 3 plates of metal attached with leather.\n\n● 3/4 Greaves\n\nThe front side of the lower leg is protected by a metal plate.\nThe outside of the lower leg is protected by a half-plate of metal, leaving the inner side of the lower leg unprotected.\n\n● Splinted Greaves\n\nMetal plates riveted to a leather base.\nThe plates are alternately outside and inside the leather.\n\n● Brigand Greaves\n\nMetal plates riveted to a fabric base.\nThe plates are covered by the fabric.\n\n● Eastern Greaves\n\nDue to very few historical sources, it is allowed to use eastern stylization of European Greaves.\nAllowed designs are displayed in the document “Eastern Armors.”","page_from":3,"page_to":3,"stable_key":"greaves:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"21a7abbe85e60b49e2116e8a892ca1e3fd41c8100dfbb27b2112c41b04be68df","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"Historical Basis: Must be based on historical sources.\nAnatomical Shape: Must have the anatomical shape of the lower leg.\nProportions: Must reproduce the proportions based on historical sources.\n\nMalleolus Protection: Must protect the malleolus bone.","page_from":4,"page_to":4,"stable_key":"greaves:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"becaaad6f367baf87be50de7552f52e88f0a55a502ef7c2cf5fa0c1fdf542ea1","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"One Panel Greaves (Half-Greaves)","body":"","page_from":4,"page_to":4,"stable_key":"greaves:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"492841f2f135e817a61f985be10def5acdba41ffa9ff929438e1b4c3546055cf","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"The 1-panel greave is the earliest form of lower leg protection available for knights, originating in the early 14th century.\n\nThey are Approved for 14th century and Transitional armors.\n\nThey are Denied for 15th century armors.","page_from":4,"page_to":4,"stable_key":"greaves:4.1","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c831a8e35e51765aa0470ac9c95b47ec1efee7b3d14d538414e9506800ce4e35","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"4.2","title":"Historical References","body":"Crucifixion, Niederhaslach — 1360, France J. von Falkenstein — 1365, Germany","page_from":4,"page_to":4,"stable_key":"greaves:4.2","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"159a5a4af5b8bf286cf21eec750c804e85e6c7c487d5106b637853e1d34ba452","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.3","title":"Specific Requirements for One Panel Greaves (Half-Greaves)","body":"They must follow the General Requirements (see Section 3 above).\nThe entire front of the lower leg must be covered by the greaves.","page_from":4,"page_to":4,"stable_key":"greaves:4.3","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"2d862116cc5ad56d4a2eb1817d17696c47fbc409dcbd952e13988c37c5f6f15d","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.4","title":"Examples of Approved Reproductions","body":"Picture from Forge of Svan © Picture from Age of Craft ©","page_from":5,"page_to":5,"stable_key":"greaves:4.4","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"81ab3536c085228f2870a52dd6acfdc933556fe7d13d47e512b3e6f71095560b","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.5","title":"Examples of Denied Reproductions","body":"Non-anatomic shape\n\nPictures from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"greaves:4.5","parent_key":"greaves:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"48363f128240e49d75bbaecc7fe0ceb0b05513e651d3a05af95218cbe21b6efc","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":0,"kind":"section","number":"5","title":"Two Panels Greaves (cased greaves)","body":"","page_from":6,"page_to":6,"stable_key":"greaves:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"27d5d17a6559219d96eeb53ed27a7383499571e563e1b40b7fc9e5bd103e0ff4","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"2-panel greaves, also known as cased greaves, were the most common form of lower leg protection from 1370 to 1600 and later. They provided superior protection for competitors by covering the entire lower leg from all sides.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nMetropolitan Museum of Arts - 1450 Brescia - 1470/1480 - Italy","page_from":6,"page_to":6,"stable_key":"greaves:5.1","parent_key":"greaves:5","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c748b8d9cdd972b9c297e0427f334047efdf15284c6baea9533e469d3a886873","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"They must follow the General Requirements (see Section 3 above).\n2-panel greaves are Approved if worn with the adequate armor style from the 15th century.\n2-panel greaves at the bottom or top of the greaves are Denied for 15th century armor.","page_from":6,"page_to":6,"stable_key":"greaves:5.2","parent_key":"greaves:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"39da784801ddf3bb9861fb854a3089db6f6b9f411fd6eb004a76a15fcbca2472","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Articulation","body":"Fully enclosed Greaves (with heel-protection) appear in the late 15th century only.\n\nThey are Denied for 14th century and Transitional armors.\n\nExample of fully enclosed Greaves:","page_from":7,"page_to":7,"stable_key":"greaves:5.3","parent_key":"greaves:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cc34691884418457901742d2e5faf8b30050dd995c0a351b706e339116bc81bd","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Approved Reproductions","body":"","page_from":7,"page_to":7,"stable_key":"greaves:5.4","parent_key":"greaves:5","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ba7378d469ed770eb6c2c9d7b6064ebce60a0fce73a503738d01e0eab030fcdc","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"5.5","title":"Examples of Denied reproductions","body":"Non-anatomic design Greaves with riveted ankle part (not based on historical sources)\n\nPictures from The Medieval Things ©","page_from":7,"page_to":7,"stable_key":"greaves:5.5","parent_key":"greaves:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae8c013ae3deee42d317e3ac5290ae6070f33ca27ef126c441b8adb81bfd54f4","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":0,"kind":"section","number":"6","title":"Three Panels Greaves","body":"","page_from":8,"page_to":8,"stable_key":"greaves:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4b563c3f281d0ee44230d60cfead1cb919305caca3705d5767cd74bbaacf27d9","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"3-panel Greaves are mainly represented in Germany from 1360 to 1380. They consist of one front panel and two side panels, articulated by leather straps.\n\nThey are Approved for 14th century and Transitional armors.\n\nThey are Denied for 15th century armors.","page_from":8,"page_to":8,"stable_key":"greaves:6.1","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a9a48fbe423acccd83896a002524b3e87cd3241b69ebcb7f51812c0e724f56de","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"6.2","title":"Historical Example","body":"Sir Burchard von Steinberg — 1376, Germany","page_from":8,"page_to":8,"stable_key":"greaves:6.2","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04df5c050bad62c33affaa267e725fde43b2100fc97aae219e0e1092d17671dd","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"6.3","title":"Specific Requirements","body":"They must conform to the General Requirements (see Section 3 above).\nThe side panels must protect both sides of the lower leg, including the malleolus bone.\nThe panels can be articulated with leather straps or a piece of leather between each panel.\n\nIt is Allowed to extend the width of the side panels to cover the back of the calf, despite this not being based on historical proportions.\n\nIt is Allowed to use hinges instead of leather despite it not being documented by historical sources.","page_from":8,"page_to":8,"stable_key":"greaves:6.3","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"cc9efe8fe488aab220c4fcb67ff8453a23baa6ce3835e31c51da5b54f207d513","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Approved Reproductions","body":"Side panels that are based on historical proportion\n\nPictures from Age of Craft ©\n\nPicture from The Medieval Things ©\n\nWider size panels for safety\n\nPicture from Medieval Extreme ©","page_from":9,"page_to":9,"stable_key":"greaves:6.4","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9d93e314aa9fff031d8d3d2cb186c3a706aa31b2acceaba67c752a741ecae769","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":1,"kind":"rule","number":"6.5","title":"Examples of Denied Reproductions","body":"Side panels lack of shaping\n\nDoes not adequately protect the malleolus bone, rule 1.2.4\n\nPictures from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"greaves:6.5","parent_key":"greaves:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["1.2.4"],"content_sha256":"7a3a728f4380d021b4813da0fad8a479e8004dc01f31caf521c1ead7dfdf04d2","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":0,"kind":"section","number":"7","title":"Three Quarters Greaves","body":"","page_from":11,"page_to":11,"stable_key":"greaves:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a9251a3bca05600975416881345bfba6a01ca65d9830c322ef2a4d52a131d96","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"3/4 Greaves first appeared in the 15th century.\nThey are Approved for Transitional and 15th century armors.\n\nThey are Denied for 14th century armors.","page_from":11,"page_to":11,"stable_key":"greaves:7.1","parent_key":"greaves:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aa62bd7e48f043d8ba5fa9f599886f4e04c1c371b2256210f4858ab5bf5832ff","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"7.2","title":"Historical Example","body":"Metropolitan Museum of Art — 1550, Italy\n\n1.1. Specific Requirements\n\nThey must conform to the General Requirements (see Section 3 above).\nThe side panels must cover at least half of the back of the calf.\n\n1.2. Examples of Approved Reproductions\n\nPicture from Age of Craft © Picture from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"greaves:7.2","parent_key":"greaves:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"4ad6fb672e5330ea76e22508839ad134a898e04faf94812ddaa2063519cc5a22","has_figures":true,"extraction":"ocr"},{"ordinal":26,"depth":0,"kind":"section","number":"8","title":"Splinted Greaves","body":"","page_from":12,"page_to":12,"stable_key":"greaves:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e6fbcc74aba8362d7a043853cc767f92e42c4c966613dd12a8a24d66032a9303","has_figures":true,"extraction":"ocr"},{"ordinal":27,"depth":1,"kind":"rule","number":"8.1","title":"Historical Sources and Datation","body":"Splinted Greaves are represented in Europe from 1350 to 1380. They consist of metal plates riveted to a leather base.\n\nThey are Approved for 14th century and Transitional armor.\nThey are Denied for 15th century armor.","page_from":12,"page_to":12,"stable_key":"greaves:8.1","parent_key":"greaves:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c24e82263f65686143ce48ac4392cb13301d8d45dfed9cabe9d048c3dedb5af8","has_figures":true,"extraction":"ocr"},{"ordinal":28,"depth":1,"kind":"rule","number":"8.2","title":"Historical Examples","body":"Louis Thys — 1365, Belgium G. von Schwarzburg — 1349, Germany","page_from":12,"page_to":12,"stable_key":"greaves:8.2","parent_key":"greaves:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"164b36db47cf2cee2bdc7beb12f637be8f011590be7ed7717b9c881f29af1ff5","has_figures":true,"extraction":"ocr"},{"ordinal":29,"depth":1,"kind":"rule","number":"8.3","title":"Specific Requirements for Splinted Greaves","body":"They must conform to the General Requirements (see Section 3 above).\n\nThey must be made of metal plates with the following features:\n● rectangular shape,\n● firmly riveted to a leather base,\n● plates must be riveted alternatively inside and outside the leather base,\n● plates must conform to the anatomical shape of the lower leg.","page_from":12,"page_to":12,"stable_key":"greaves:8.3","parent_key":"greaves:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"064d1b435edd50f1fd33cce01ea4854d6e4b1db2e62b775ab8f2bd7de9c2c8e4","has_figures":true,"extraction":"ocr"},{"ordinal":30,"depth":1,"kind":"rule","number":"8.4","title":"Examples of Approved Reproductions","body":"Picture from Medieval Extreme ©","page_from":13,"page_to":13,"stable_key":"greaves:8.4","parent_key":"greaves:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5990fa8e41906355c78cf5fe6fa0edf6f9ded63c19d1fdb1517463c510802d99","has_figures":true,"extraction":"ocr"},{"ordinal":31,"depth":1,"kind":"rule","number":"8.5","title":"Examples of Denied Reproductions","body":"Fantasy designs and Non-anatomical shape","page_from":13,"page_to":13,"stable_key":"greaves:8.5","parent_key":"greaves:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd64acf2904a937fe58df4e61c7960b9f22faadad82ea112b2a97d7e8573c23b","has_figures":true,"extraction":"ocr"},{"ordinal":32,"depth":0,"kind":"section","number":"9","title":"Brigand Greaves","body":"","page_from":14,"page_to":14,"stable_key":"greaves:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c8f1186ddffae03a64efe665d5663818e02787bd7698aa836135bd3746057237","has_figures":true,"extraction":"ocr"},{"ordinal":33,"depth":1,"kind":"rule","number":"9.1","title":"Historical Sources and Datation","body":"Brigand Greaves are represented in Europe from 1350 to 1380. They consist of metal plates riveted to a fabric base.\n\nThey are Approved for 14th century and Transitional armors.\n\nThey are Denied for 15th century armors.","page_from":14,"page_to":14,"stable_key":"greaves:9.1","parent_key":"greaves:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8f2a45809235653160cf64e0fabb6c4190b0a251e1d42d1bfb264b7e4f6f528","has_figures":true,"extraction":"ocr"},{"ordinal":34,"depth":1,"kind":"rule","number":"9.2","title":"Specific Requirements for Brigand Greaves","body":"They must conform to the General Requirements (see Section 3 above).\nThey must be made of metal plates with the following features:\n\n● rectangular shape,\n\n● firmly riveted to a leather base,\n\n● plates must be riveted inside the fabric, not outside,\n\n● plates must conform to the anatomical shape of the lower leg.","page_from":14,"page_to":14,"stable_key":"greaves:9.2","parent_key":"greaves:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"82c2f81c64152d85003d76fa8265e667be3743091fb567f31f7ce3d2ffe07ae5","has_figures":true,"extraction":"ocr"},{"ordinal":35,"depth":1,"kind":"rule","number":"9.3","title":"Examples of Approved Reproductions","body":"Picture from Forge of Svan ©","page_from":14,"page_to":14,"stable_key":"greaves:9.3","parent_key":"greaves:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"522b2739ab8c4f7d35e84d85559bddb5ea55400afac03652fbeaa29eb5165847","has_figures":true,"extraction":"ocr"},{"ordinal":36,"depth":1,"kind":"rule","number":"9.4","title":"Examples of Denied reproductions","body":"Non-anatomical shape\n\nPicture from The Medieval Things ©","page_from":15,"page_to":15,"stable_key":"greaves:9.4","parent_key":"greaves:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"465e52b1cdb2df9818c2f5cdc9a1215ffa70f5b3df9d3b840e1db00997ff3dce","has_figures":true,"extraction":"ocr"},{"ordinal":37,"depth":0,"kind":"section","number":"10","title":"Other Denied Items","body":"","page_from":16,"page_to":16,"stable_key":"greaves:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c7117c77dfe54c279f1cb934977e8127ec3845d71e4886bc513349de2405ffa6","has_figures":true,"extraction":"ocr"},{"ordinal":38,"depth":1,"kind":"rule","number":"10.1","title":"Four or five Panels Greaves","body":"Those types of Greaves are not based on historical sources.\n\nTo get an approved piece, the 4th plate can be removed. The closest alternative would be the 3-panels greaves.","page_from":16,"page_to":16,"stable_key":"greaves:10.1","parent_key":"greaves:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6e367a63c67b26fb465f039135ef2a3f3f8c89402448ee4d20c5b2ca76d4eef7","has_figures":true,"extraction":"ocr"},{"ordinal":39,"depth":1,"kind":"rule","number":"10.2","title":"Examples of Denied Reproductions","body":"Picture from The Medieval Things ©","page_from":16,"page_to":16,"stable_key":"greaves:10.2","parent_key":"greaves:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2c6f857090f0431f2250a005612eb9df11326396a87a77d3a60996db9293b7bc","has_figures":true,"extraction":"ocr"},{"ordinal":40,"depth":0,"kind":"note","number":"11","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition” and “3. General Requirements”.\nThis split doesn’t have an impact on the content of the rules.\n\nMarch-2025 (V2025.03)\n\n- Formatting: Overall grammar and formatting\n\n- add: 8.1: the 4th plate can be removed\n\n- add: 4.5: Side panels lack shaping, Does not adequately protect the malleolus bone, rule 1.2.\n- add: 3.5: Greaves with riveted ankle part (not based on historical sources)\n\nDecember-2024: -add Document has been created","page_from":17,"page_to":17,"stable_key":"greaves:11","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":["1.2"],"content_sha256":"448d909d67111ac66a9828d4d7d11b9dc1287e5fa51113196e9157e61115b8c4","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/infractions","synthetic":false,"version":{"version":"26.4","title":"Infraction classification and application 26.4","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.4\" and every page footer \"V. 26.4\"; changelog entry \"April - 2026 (V. 26.4)\".","source_url":"https://drive.google.com/file/d/1NQ5O-CT62qn-V6w3Zh4JqcCzKJVxEZS5/view?usp=drive_link","source_sha256":"313d5d3bf9264d8d3be7a32f88e2a046a933f50024676354ad732f43f6504565","retrieved_at":"2026-10-06T00:00:00Z","page_count":6,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"4e535567bfeeaf5e3756208a99182225df49f07efdb0e0862aea9bfb261c4298","detected":{"version":"26.4","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":6,"source_lines":87,"assigned_lines":131,"furniture_lines":11,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99712,"provisions":12,"numbered":11,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.4\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"infractions:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"08314837801c0561e4b5da4df28df075016d78fec8597b698744a7724df00b43","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Definition","body":"Authenticity rules are meant to be followed by all competitors attending Buhurt International tournaments, no matter the category. If a competitor shows up with an armor, shield or weapon that does not comply with the Authenticity rules, he/she risks a penalty.","page_from":3,"page_to":3,"stable_key":"infractions:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2d7b293b69b1334db19526e86381ac857d05a567da947a4ca235ab6eff1c619e","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Infraction Classification","body":"During Authenticity Check, Authenticity officers will evaluate the entire equipment of competitors before the start of the tournament. Any violation of the Authenticity rules will result in an infraction. Infractions can be classified under 3 different levels:","page_from":3,"page_to":3,"stable_key":"infractions:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"e08f51ed6a1a5538806971181c3c57e85637965f8dcb7310b51dd7d083232f95","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Minor infraction","body":"It is a small detail not easy to see, and it does not affect the coherence of the whole armor (small traces of rust, hammering marks, little datation difference between 2 parts etc.).","page_from":3,"page_to":3,"stable_key":"infractions:2.1","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"65621c4deccd4960002be4af4bc963b89be3f2bb98d05da3be1d54f85104f9f8","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Moderate Infraction","body":"It is something forbidden by the Authenticity rules (i.e badly designed helmet, over numerous eye bars etc.). Not respecting the rules can't be accepted, thus it is not severe enough to prevent the fighter from entering the list.","page_from":3,"page_to":3,"stable_key":"infractions:2.2","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b9a295548c8136aafd80a7b305933099ecf3e78bc1b5417813ad994d0dbf5e47","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.3","title":"Major infraction","body":"Fantasy armor or totally inaccurate equipment, that prevent the fighter from entering the list and damage the image of the sport, the teams and Buhurt International.","page_from":3,"page_to":3,"stable_key":"infractions:2.3","parent_key":"infractions:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6fc515e5b9ba0154bec59e4cacdc7cda92046be6e0474c88601c13063f239150","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"3","title":"Application of the Rules","body":"A violation of the authenticity rules will result in a green card. Depending on the rank of tournament, infraction will be applied differently.\n\nA green card combined with a yellow card will result in a red card and the competitor will be disqualified from the tournament.\n\nA competitor can receive only 1 green card per tournament, no matter how many infractions they have.\n\nIf a competitor fixes the issue(s) that warranted a green card, the green card can be removed after validation by the Authenticity Officer in charge of the event.\n\nGreen cards will be represented by a green ribbon worn at the competitor’s belt. It is mandatory to keep it during the whole competition. Any removal of the green card will be considered as an attempt to cheat.\n\nOnly the Authenticity Officer in charge of the event can allow a fighter to remove the green card from their belt.","page_from":4,"page_to":4,"stable_key":"infractions:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"67f89b5ea592e0c8ca0c776c8474ae775e6e4e742bf5c7d314049a338ae0f22c","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.1","title":"Source","body":"No authenticity check required.\nAuthenticity members on site will be able to give advice and guidance.","page_from":5,"page_to":5,"stable_key":"infractions:3.1","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a6e64701bb448476d1d46a9ea6a22106826049387e0d935aca5f04164401ab1","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.2","title":"Classic","body":"Authenticity check is mandatory prior to the start of the tournament.\nA competitor is allowed to enter the list if they respect the following cumulative criterias:\n\n● Have no more than 3 minors infraction (if they have 4 or more, they will receive a green card).\n● Have no more than 1 moderate infraction (if they have 2 or more, they will receive a green card.\n● Have no major infraction.","page_from":5,"page_to":5,"stable_key":"infractions:3.2","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"61ba2b621db23b295f260c50cfe5f3720280f06b1413f34d68eee1c4a9a32a1d","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"3.3","title":"Regional","body":"Authenticity check is mandatory prior to the start of the tournament.\nA competitor is allowed to enter the list if they respect the following cumulative criterias.\n● Have no more than 2 minors infraction, if you have 3 or more, then they will receive a green card.\n● Have no moderate infraction. If they have 1 or more, they will receive a green card.\n● Have no major infraction.","page_from":5,"page_to":5,"stable_key":"infractions:3.3","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eb368973ae8174062320726f02421f6eb7025397502387fad96975461da5c5d0","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"3.4","title":"Conference","body":"Authenticity check is mandatory prior to the start of the tournament.\nA competitor is allowed to enter the list if they respect the following cumulative criterias.\n● Have no more than 1 minor infraction, if you have 2 or more, then they will receive a green card.\n● Have no moderate infraction.\n● Have no major infraction.\n\nNote: as an exceptional measure, for season 2025, tournaments of Conference level will be considered as Regional regarding Authenticity rules. It means a competitor with 1 moderate infraction will be allowed to fight, but will receive a green card.","page_from":5,"page_to":5,"stable_key":"infractions:3.4","parent_key":"infractions:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ca064b7cd947130aa18a5c6b762cc4c1a82563b40b8f5e5a72cf0f9dc29690f7","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"note","number":"4","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nApril - 2026 (V. 26.4) Add:\n- 3. Application of the rules: Addition of the Green Ribbon.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\nSuppression:\n- 2 first paragraphs of “2. Definition” as they were outdated.\n\nFebruary - 2025:\n- Replaced: 1. (After vote) introducing the green card rule\n- Replaced: 2. Members | Officers || Fighters | Competitors\n- Add: 2. Any violation of the Authenticity rules will result in an infraction\n- Replaced: 3. violation breach of | greenYellow card remains the sanction for Aany” with “A violation of\n- Rephrased: 3. (After vote) to clarify the green card rule.\n- Add: 3.3 If they have 1 or more, they will receive a green card.\n- Add: 3.4: Note\n\nDecember 2024:\n-add Document has been created","page_from":6,"page_to":6,"stable_key":"infractions:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"6f6bd7dfbd1b84967352acc378beea8045fb1997e24b62b2545e9b88117e5b08","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/klappvisors","synthetic":false,"version":{"version":"26.1","title":"Klappvisors - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1nGbacRRmwzdVNeJg2OrkxRItcKL_Bu9a/view?usp=sharing","source_sha256":"e47d380dc11050342382e9fce90485b2f0f8a7c072c282f03afa4d716f406411","retrieved_at":"2026-10-06T00:00:00Z","page_count":13,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 13 page(s) without a text layer","content_sha256":"750f5ed545f378726c50a6534bc8ae7c2c3252a7bfb4ebe2326bf0ba8c370f25","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":13,"source_lines":134,"assigned_lines":174,"furniture_lines":36,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99507,"provisions":15,"numbered":14,"needs_review":0,"verified":1,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":134,"picture_text_lines":8,"ocr_corrections":1}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"klappvisors:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"klappvisors:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Klappvisor Bascinet is a medieval helmet that originated in the 14th century.\n\"Klappvisor\" is German and translates to \"folding visor.\" The single brow-mounted hinge is a distinctive feature of early bascinet visor designs.\n\nThese bascinet visors were often low profile to fit underneath a great helm, but would also serve as a primary defense on their own.\n\nKlappvisor uses a solid metal visor to protect the face, attached on the forehead by a piece of metal, the “spoon”.\nKlappvisor was used from 1340 to 1400, mainly in Germany and Italy.\n\nKlappvisor is Approved for 14th century and Transitional armors.\n\nKlappvisor is Denied for 15th century armors.\n\nSpoon","page_from":3,"page_to":3,"stable_key":"klappvisors:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4e5b48519702b3c55bca8130918382dd8b4f4a0bf4c381818fd4e2c8bec25487","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"","page_from":4,"page_to":4,"stable_key":"klappvisors:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04e42d373a22b64d239d42d339423dfe562a290d68219f938a8fe993f807be48","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"German-Style Klappvisors","body":"“Sitten Klappvisor” - 1390 - Switzerland “Bavarian Klappvisor” - unknown datation, probably late 14th cent.\nPicture from Musées cantonaux du Valais, - Bavarian Army Museum, Munich, Germany\n\nSion (Jean-Yves Glassey, Martigny) ©\n\nNuremberg Museum - 1370/1380 - Germany Coburg helmet - 1380/1390 - Germany\n\nBerlin Museum - 1350 - Germany","page_from":4,"page_to":5,"stable_key":"klappvisors:3.1","parent_key":"klappvisors:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"01b927d0ce24557282bc356536c2acdb0f06b5b53bef9ff91133497dc1abcf49","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Italian style Klappvisor","body":"14th century (datation unknown) - Italy 1350 - Italy\n\nMilan Klappvisor, Museo Stibbert, 1390/1400 - Italy\n\n● Other style Klappvisor\n\n1375 - Netherlands\n\nLeeds Armouries - 1350/1380 - England","page_from":6,"page_to":7,"stable_key":"klappvisors:3.2","parent_key":"klappvisors:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"74e5590e82f40d6c88d4a40a313c75540eea9f4621fcbe798a44ef374e261e3b","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":8,"page_to":8,"stable_key":"klappvisors:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of a Klappvisor source.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":8,"page_to":8,"stable_key":"klappvisors:4.1","parent_key":"klappvisors:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ea2fd20fd4ecb9b27834e58e1680b6add836d1c91f6f10913cd1679faf641504","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"Visors must not be too long or too short, it must respect the proportions of historical sources.\nThe hinge must be reproduced as per historical sources.\n\nIt is Allowed to weld the hinge. Welded hinges must resemble a functional hinge.\n\nIt is Allowed to weld the visor down. Welded visors must resemble a functional removable visor.\n\nIt is Allowed to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the Aventail.\n\nA leather strap can be used to secure the visor down.\n\nBreath holes should be round and must not exceed a diameter of 10mm. Breath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\n\nBreath holes of another shape must be documented by historical sources to be allowed.","page_from":8,"page_to":8,"stable_key":"klappvisors:4.2","parent_key":"klappvisors:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ec8a0dbb88f760415dbb299912e85172b482c2afdd10a47c100daf8244494b84","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.3","title":"Eye Slots","body":"Eye slots should resemble sources for the visor.\nEye slots should not exceed 25mm tall to prevent any injury.\nKlappvisor with 2 Eye slots are allowed to add up to two (2) safety Eye bars per Eye slot.\n\nKlappvisor may have integrated Eye bars. Such Eye bars must be made accordingly with historical sources, in terms of proportion, numbers and aesthetic.\n\nExternally riveted Eye bars are not allowed.\nEye bars must conform to the “Eye bars” document.","page_from":8,"page_to":8,"stable_key":"klappvisors:4.3","parent_key":"klappvisors:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8dec3d1dce2874cd05154dcf4fa1069da4632b3ce10e169de9c89e79375cbaa9","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.4","title":"Aventail","body":"Klappvisors must be worn with chainmail Aventails, fabric Aventails, or scales Aventails.\nAventails must conform to the “Aventails” document.\nAventails must be attached to the bascinet by a system of leather and vervelles.\n\nChainmail Aventail must be fastened down to the edge of a padded pelerine, attached to the helmet liner.\n\nScales and Fabric Aventails are recommended to be fastened down to the edge of a padded pelerine, attached to the helmet liner.\n\nAny additional protective plates covering the cervical spine must be hidden under the Aventail.","page_from":8,"page_to":8,"stable_key":"klappvisors:4.4","parent_key":"klappvisors:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ba8bf7eba04f867bade08337ea3089d60f608aa424837f8f5d18b9fdbd1c9a42","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"4.5","title":"Others","body":"Klappvisors may be decorated in the spirit of medieval styles, such as orle, torse, decorated Aventails (with copper/brass chainmail rings), vervelle covers and coat of arms badges etc.\n\nSuch decoration must be made in coherence with historical sources.\nUsing modern and/or offensive imagery and slogans is prohibited.","page_from":9,"page_to":9,"stable_key":"klappvisors:4.5","parent_key":"klappvisors:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b4134b5abaf4112f876a8de7d801840d94661fb0930a6875ca4ae20443cad2bc","has_figures":false,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©\n\nPictures from Medieval Extreme ©","page_from":10,"page_to":11,"stable_key":"klappvisors:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dca41949fd3f16d595c472a8f8ed6b1c281e24c94921a16bb84be6188b3de854","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":0,"kind":"section","number":"6","title":"Examples of Denied Reproductions","body":"Integrated Eye bars out of historical proportions\n\nPictures from The Medieval Things ©","page_from":12,"page_to":12,"stable_key":"klappvisors:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"81dc5f06e06ce5245f6adf40fea39d5696e01d5d99727a87f8e01ff49e7c3a1b","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document)\n- In 4.4 Aventails: “The aventail” by “Chainmail aventail”\n\nAdd:\n\n- In 4.3 Eye slots: “Externally riveted eye bars are not allowed.“\n\nReplace:\n\n- In 4.4 Aventails: “The aventail” by “Chainmail aventail”\n\nAdd:\n\n- In 4.4 Aventails: “Scales and Fabric aventails are recommended to be fastened down to the edge of a padded pelerine, attached to the helmet liner.”\n\nSuppression:\n\nIn 5. Denied reproductions: “+”\n\nMarch-2025:\nFormatting: Grammar and Formatting\n\nAdd: 3.3 Klappvisor may have integrated Eye bars. Such eye bars must be made accordingly with historical sources, in terms of proportion, numbers and aesthetic.\n\n11-Nov-2024: -Add Document has been created","page_from":13,"page_to":13,"stable_key":"klappvisors:7","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly (the closing quotation mark is printed as “)","topics":["changelog"],"keywords":[],"cross_refs":["4.4","4.3","5"],"content_sha256":"a6b4216cd56154a78371e1581c2df85729450298ecd31473d4e468dae6c776ef","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/nasals-and-breteches","synthetic":false,"version":{"version":"26.1","title":"Nasal and Breteche - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and page footers \"V. 26.1\" (two footers read \"26.7\" by OCR; the page image shows 26.1); changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1UhguW3phwP3DUHV1kiUcsu8pM1nQ0z7M/view?usp=sharing","source_sha256":"9d9fa618929079c3990d352e651b296bd363443f796b4d783e7c89a3e9e48b78","retrieved_at":"2026-10-06T00:00:00Z","page_count":10,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 10 page(s) without a text layer","content_sha256":"9812dae72209787217840b2b9f96fc1c029eadcd9757f4438dcbf991ac90f88b","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":10,"source_lines":123,"assigned_lines":162,"furniture_lines":31,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99652,"provisions":15,"numbered":14,"needs_review":0,"verified":1,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":123,"picture_text_lines":7,"ocr_corrections":3}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"nasals-and-breteches:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"nasals-and-breteches:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Nasal and Breteche bascinets are medieval helmets that originated in the early 14th century. They are an evolution of simple bascinets worn with chainmail. The chainmail aventail is attached to the front of the helmet to increase its face protection.\n\nNasal bascinet uses a solid metal nasal to protect the nose, attached on the forehead by a piece of metal, the “spoon”.\n\nBreteche bascinet uses chainmail to protect the nose, attached on the forehead by a piece of metal, the “cross”.\n\nBoth helmets were used from 1340 to the late 14th century in Western Europe.\nNasal and breteche bascinets are Approved for 14th century and Transitional armors.\n\nNasal and breteche bascinets are Denied for 15th century armors.\n\nSpoon Cross","page_from":3,"page_to":3,"stable_key":"nasals-and-breteches:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2af765ae2d419ce4577784446652fadf029718ea2612d01974dd1eddeecc7831","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"","page_from":4,"page_to":4,"stable_key":"nasals-and-breteches:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04e42d373a22b64d239d42d339423dfe562a290d68219f938a8fe993f807be48","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"Nasal Helmet","body":"Second half of the 14th century (datation unknown) - France Günther XXI. von Schwarzburg - 1349 - Germany\n\nBKE Cod. 339 Der Passionstraktat des Nikolaus Schulmeister - 1396 - Switzerland\n\nGaleotto Malaspina - 1367 - Italy","page_from":4,"page_to":4,"stable_key":"nasals-and-breteches:3.1","parent_key":"nasals-and-breteches:3","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"edf41077f79608f8f1414f8a5c6701a9ccd093427846eb6879122ecb4e8a70db","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Breteche Helmet","body":"Museo Stibbert, Florence - Second half of the 14th century (datation unknown) - Italy\n\nNote: This artifact may not be 100% original, as the founder of the museum commissioned some fiorentina armorers in 1881 to adapt and repair the skull, to create the cross and the chainmail (maybe original pieces of mail were patched up).\n\nDoge’s Palace, Venice - 1350/1370 - Italy Klosterneuburg Stiftsmuseum - 1335/1340 - Austria","page_from":5,"page_to":5,"stable_key":"nasals-and-breteches:3.2","parent_key":"nasals-and-breteches:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f35fa942ed4a9dfaf0891d462e6ece67009c789bf89683cee79200deacc0af58","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of a Nasal or a Breteche helmet source.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:4.1","parent_key":"nasals-and-breteches:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"310889b7114136d8ef086f15d8917e94a8af1eb36e5a9ca501017de0df44d610","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"Visors must be made of metal grill or plates, concealed under chainmail.\n\nChainmail must be properly attached to the visor with metal, leather or fabric thread.\n\nVisors must not be too long or too short and respect the proportions of historical sources.\n\nNasal helmet visor bottom line must end between nose and chin.\n\nThe fixation system must be reproduced as per historical sources (“spoon” or “cross”).\n\nIt is allowed to add a metal plate to protect the throat. Such a plate must be strong enough to endure\n\nfull contact fight and must be concealed under the Aventail.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:4.2","parent_key":"nasals-and-breteches:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d1b85b94a92f4909ef344f89b8671daae2bf83046186fbff7a9648c8af51019d","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.3","title":"Eye slots","body":"Eye slots should resemble sources for the visor.\nEye slots should not exceed 25mm tall to prevent any injury.\n\nIt is allowed to add up to two (2) safety Eye bars per Eye slot. Externally riveted Eye bars and integrated Eye bars are not allowed.\n\nEye bars must conform to the “Eye bars” rules document.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:4.3","parent_key":"nasals-and-breteches:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3afb2fe7c83bf4cfbeedf706e38ef9b665c7c5270acc22e89a8efb7c7fbfff4a","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.4","title":"Aventail","body":"Nasal and Breteche helmets must be worn with chainmail Aventails. Fabric or scales Aventails are not allowed.\n\nAventails must conform to the “Aventails” document.\n\nAventails must be attached to the bascinet by a suspension system made of vervelles and leather.\nThe Aventail must be fastened down to the edge of a padded pelerine attached to the helmet liner.\nAny additional protective plates covering the cervical spine must be hidden under the Aventail.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:4.4","parent_key":"nasals-and-breteches:4","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6e4ffe492081d242a630589665c2810f650ec0a755e61619184421b9dcc9b7fa","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"4.5","title":"Others","body":"Nasal and Breteche helmets may be decorated in the spirit of medieval styles, such as orle, torse, decorated Aventails (with copper/brass chainmail rings), vervelle covers and coat of arms badges, etc. Such decoration must be made in coherence with historical sources.\n\nUsing modern and/or offensive imagery and slogans is prohibited.","page_from":6,"page_to":6,"stable_key":"nasals-and-breteches:4.5","parent_key":"nasals-and-breteches:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"55d39b2d26c3ce0d59826dfba48fc5b4f2506bbb69e9b7aa9935fc730fd05311","has_figures":false,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"Example of approved welded spoon\n\nPictures from The Medieval Things ©\n\nPictures from The Medieval Things ©\n\nPicture from M. Leclere ©","page_from":7,"page_to":8,"stable_key":"nasals-and-breteches:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eb030cd2c9cd45663315c3cd781ece25fdff3819f94b67d2c27fde995d9d438a","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":0,"kind":"section","number":"6","title":"Examples of Denied Reproductions","body":"Eyebars not painted in black\n\nOverall design does not reproduce historical\n\nsources, including => improper chainmail\n\nfixation on the forehead\n\n(no cross)\n\n<= Aventail mixing fabric and chainmail\n\nPictures from The Medieval Things ©","page_from":9,"page_to":9,"stable_key":"nasals-and-breteches:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f040cb87841d67459a0e09b474fac72d783c6117637217e0b82738fa05fd7105","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1)\n\nFormatting redone for consistency and readability. Except points listed below, no content changes.\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document) Replace:\n\n- In 4.1 General Requirements: “Klappvisor” by “Nasal or a Breteche helmet”\n\n- In 4.3 Eye slots: ”Externally riveted and integrated eyebars are not allowed.”\n\nFebruary-2025 (2025.03) Formatting: grammar and formatting\n\nDecember-2024: -Add Document has been created","page_from":10,"page_to":10,"stable_key":"nasals-and-breteches:7","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":["4.1","4.3"],"content_sha256":"f1909787b474586ad5c309be735ec337f02a02c899f8870c4746b266b770bef6","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/neck-protection","synthetic":false,"version":{"version":"26.1","title":"Neck Protection - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1bo8-eNr_pTawNLNGod5mN64-d4EkkLS-/view?usp=sharing","source_sha256":"8da92f75d7fec05ca4001dba88012f4ec4fc5d1221ca18252247627261d17023","retrieved_at":"2026-10-06T00:00:00Z","page_count":13,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 13 page(s) without a text layer","content_sha256":"3218f7918dddc18e34418bfc4dfb9250b2af40ee7d83f6b1ff1183ca15b5bbe4","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":13,"source_lines":171,"assigned_lines":227,"furniture_lines":44,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99566,"provisions":25,"numbered":24,"needs_review":0,"verified":2,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":171,"picture_text_lines":7,"ocr_corrections":1}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"neck-protection:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"neck-protection:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Neck protection’ is the term to describe all historical and adapted protection for neck, shoulders and throat. Those protections are mandatory to ensure the safety of competitors.\n\nNeck protection can be worn upon the Aventail or not, depending on the type of protection.\n\nTypes of Neck protection:\n● Neck shield Metal plates that replicate the shape of a heater shield. It is allowed to be worn upon the Aventail.\n\n● Lobster tail Articulated metal plates designed as a lobster tail. It is allowed to be worn upon the Aventail.\n\n● Gorget\n\nA gorget is a plate protection that covers the neck, shoulders and throat. It is allowed to be visible and worn with the proper armor set.\n\n● Concealed neck plates Metal plates directly sewn to the gambeson or the Aventail. They must be hidden under the Aventail.","page_from":3,"page_to":3,"stable_key":"neck-protection:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"68fd6097f7453da574597fc3066eac3f285aa7fb2d5724b724c37c9434c4d088","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"All types of Neck protection must respect the following requirements:\n\n● be based on historical sources if they are visible,\n● be concealed if they are not based on historical sources,\n● be firmly attached to prevent any breakage and maintain a high level of protection in any case.\n\nAny metal part of the Neck protection must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nAny textile or leather part of the Neck protection must conform to the \"Textiles and Leather” document.","page_from":3,"page_to":3,"stable_key":"neck-protection:3","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a1e816a62c9903bea632a13e9ed1e0756109ab1cb369bfbdf9a0aeecbc37fd7d","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Recommendations","body":"It is recommended to wear a Neck protection sewn to your gambeson. This protection covers your neck no matter the position of your helmet (bent or twisted during wrestling).\n\nNeck protection relying on your Aventail can be damaged during fights and may be removed if not firmly attached to the Aventail. It is recommended to ensure those Neck protections are well attached and will not be removed easily.","page_from":4,"page_to":4,"stable_key":"neck-protection:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"42fc1acffef7d8785757c1d8f2dd820e108c37fee2db295b839a7361315746d3","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"section","number":"5","title":"Neck shield","body":"","page_from":5,"page_to":5,"stable_key":"neck-protection:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f8ef192e90dd5e78765c4f0d0e3af0c7452876e2346bb3027e77867492262212","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"Miniatures sometimes display a small shield attached to the Aventail, mainly during the 14th century.\nThose shields were supposed to show the heraldry of the wearer. Thus, as Neck protection is mandatory in our sport, such neck shields are allowed to be worn on the Aventail.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nBook of Hours - 1320 - The Netherlands","page_from":5,"page_to":5,"stable_key":"neck-protection:5.1","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"73d28f195dcdf17096b00ec874c1c8fbe64d0d8e59a5d7d403ada4296e513576","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"Neck shield:\n\n● must conform to the General Requirements (see Section 3 above),\n\n● can be worn upon the Aventail. It must be firmly attached to the Aventail,\n\n● must have a shape inspired by the heater shield,\n\n● cannot exceed 15x17 cm,\n\n● can be painted,\n\n● if painted, must conform to the “Armors and Weapons Aesthetics and Decorations” document.","page_from":5,"page_to":5,"stable_key":"neck-protection:5.2","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"7b363d68dced9a1d17103c9cc02b0714a775a91664dda48d5720c7a334551200","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Reproductions","body":"","page_from":6,"page_to":6,"stable_key":"neck-protection:5.3","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"13c10e0355b524b56aa6deae2b0ce7b2a84351c4c79a7370f4d680bce37d10b0","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Denied Reproductions","body":"Oversized neck shield, it risks being ripped off during wrestling.\n\nRound shape is not allowed, it must be concealed under the Aventail.\n\nPictures from The Medieval Things ©","page_from":6,"page_to":6,"stable_key":"neck-protection:5.4","parent_key":"neck-protection:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd2752a0717e476ed88711a0dff805dfbbaca80eb5cbb3dcef6926086a023d9a","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":0,"kind":"section","number":"6","title":"Lobster tail","body":"","page_from":7,"page_to":7,"stable_key":"neck-protection:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d690336556fca1b4224c8a6afdfd7cabd8c53c8f39ec7daaae3b245ea650fbcd","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"Lobster tail is a lobster-shape Neck protection made of articulated metal plates. It is depicted in manuscript and art from the late 14th century to the 15th century.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\n‘Le Livre et le vraye hystoire du bon roy Alixandre”\n- 1400/1420 - France\n\nAltar of St James, Pistoia - 1380/1400 - Italy\n\nPaduan Bible - 1400 - Italy","page_from":7,"page_to":7,"stable_key":"neck-protection:6.1","parent_key":"neck-protection:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e0853f340d90f2aea2cabf1084183bba26bd4856d6ad08902533f618ff723e84","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Lobster tail:\n\n● must conform to the General Requirements (see Section 3 above),\n\n● can be worn upon the Aventail. It must be firmly attached to the Aventail,\n● cannot be painted if they are worn upon the Aventail,\n\n● must be articulated and consist of at least 3 parts,\n\n● cannot exceed 15 x 25 cm.","page_from":7,"page_to":7,"stable_key":"neck-protection:6.2","parent_key":"neck-protection:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"6c765b3210808203ad45e7a797e51fce2f4c73ade3ad9798c07abacca87871e9","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Picture from Gohurt ©","page_from":8,"page_to":8,"stable_key":"neck-protection:6.3","parent_key":"neck-protection:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7b41e417b4f29f1057fe4b7bfa8518069dbf5f09fca9bd97a0bc5ba0042d7774","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Denied Reproductions","body":"Oversized\n\nPicture from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"neck-protection:6.4","parent_key":"neck-protection:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ee82cd2ebe8ee15dab908038e2dd7e823540018e45365d212cf02cf69269fe5d","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":0,"kind":"section","number":"7","title":"Gorget","body":"","page_from":9,"page_to":9,"stable_key":"neck-protection:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"72ecb9ee5d21132012b23e05cabfaf89e5880852b571b3a768de1b5158b3ff44","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"A gorget was a type of Neck protection worn over the neck, clavicles, and shoulders. It evolved from earlier forms of neck defenses, which often relied on chainmail or padded fabrics like the Aventail.\n\nBy the late 15th century, as plate armor became more refined, the gorget emerged as a key piece of protection for the throat and neck, made primarily from steel plates. Gorgets were most common in the 16th century but evidence exists of gorgets and plate collars.\n\nThey are Approved for 15th century armors.\n\nThey are Denied for 14th century and Transitional armors.\n\nWade Allen collection - 1510 - Italy","page_from":9,"page_to":9,"stable_key":"neck-protection:7.1","parent_key":"neck-protection:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6565599816ecfde649ee524035c170f389e6758b40d94f9bc96e8a4888b769cf","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements","body":"Gorget must:\n\n● conform to the General Requirements (see Section 3 above),\n\n● be constructed from plates,\n\n● cover the clavicles and back of the neck. The throat should have a low profile, be articulated or otherwise fitted in such a way that it doesn’t choke the wearer when their head is tilted forward.\n\n● be worn with appropriate armor styles and match historical sources in function and appearance.","page_from":9,"page_to":9,"stable_key":"neck-protection:7.2","parent_key":"neck-protection:7","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"f59fd96bbd66556162c0e2098b6d3249b4458af4a9910cf84e80084a7c821029","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"7.3","title":"Examples of Reproductions","body":"Picture from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"neck-protection:7.3","parent_key":"neck-protection:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1071ef109fe05ece40ac445672c054a613693b9ecca5509dd94740efbc9b2001","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":0,"kind":"section","number":"8","title":"Concealed neck plates","body":"","page_from":11,"page_to":11,"stable_key":"neck-protection:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1bbd917f51d6be8f11dd40684e8af8ab569e5b6a3f5236b9e390e2b530d9651d","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"8.1","title":"Historical Sources and Datation","body":"There are no historical sources nor datation for such armor elements.\n\nNevertheless, it is Approved to reinforce your neck armor with concealed plates.","page_from":11,"page_to":11,"stable_key":"neck-protection:8.1","parent_key":"neck-protection:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c73ba4067eca110fc1b8c5725f5755b169ed47f4e2b6d9f9b3644d9ffbbcd380","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":1,"kind":"rule","number":"8.2","title":"Specific Requirements","body":"Concealed neck plates must:\n\n● conform to the general requirements (see Section 3 above).\n● be made of metal.\n\n● be hidden under the Aventail.\n\n● be firmly attached.\n\n● be smooth with no sharp edges.\n\nIt is recommended to paint concealed neck plates with anti rust paint. Such paint must be a neutral color (grey, black) and do not interfere with the aesthetic of the armor.","page_from":11,"page_to":11,"stable_key":"neck-protection:8.2","parent_key":"neck-protection:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"3d6986c65937d19fe4dd413971733a4588e9b2ce03f902e5efaab54d087d0d7c","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":1,"kind":"rule","number":"8.3","title":"Examples of Approved Reproductions","body":"yr Pictures from Medieval Extreme ©","page_from":11,"page_to":11,"stable_key":"neck-protection:8.3","parent_key":"neck-protection:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c39be1b7bfd9e29a665ca96c54b05761b446826613c643fc7ea26bc5a633506f","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":1,"kind":"rule","number":"8.4","title":"Examples of Denied Reproductions","body":"Metal plates visible\n\nPictures from The Medieval Things ©","page_from":12,"page_to":12,"stable_key":"neck-protection:8.4","parent_key":"neck-protection:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ada990d5487a92d00b7a2f0b6b986f0c85584f7be8bd4b3e665ab05314c02f9f","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":0,"kind":"note","number":"9","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition and description” and “3. General Requirements”. This split doesn’t have an impact on the content of the rules.\n\nFebruary-2025 (V2025.02)\n- formatting: overall grammar and formatting\n- add: 4.1 They are denied for 14th century and Transitional armors\n\nDecember-2024: -Add Document has been created","page_from":13,"page_to":13,"stable_key":"neck-protection:9","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"33b178960fa5c781c878b4f8f298b26c137ef23f1419c5e372f89b51e1c4a10b","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/perforated-visor-bascinets","synthetic":false,"version":{"version":"26.4","title":"Perforated Visor Bascinets 26.4","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.4\" and every page footer \"V. 26.4\"; changelog entry \"April - 2026 (V. 26.4)\".","source_url":"https://drive.google.com/file/d/1hXeuPmztpXG9LdNrGV8j5dlr7ne7R93p/view?usp=drive_link","source_sha256":"e1962ebf619e9bb67660282eaf6e3815c05a3b5d0cafdf733d8d097f1b9397cf","retrieved_at":"2026-10-06T00:00:00Z","page_count":11,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"7ce0ecc81f08b5de6243b7c4d590858d70de990c54370ff47193c7cf7fc26c68","detected":{"version":"26.4","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":11,"source_lines":133,"assigned_lines":243,"furniture_lines":27,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99726,"provisions":16,"numbered":15,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.4\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"perforated-visor-bascinets:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"08314837801c0561e4b5da4df28df075016d78fec8597b698744a7724df00b43","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 29.11.2025.\nThe document and its rules will be implemented from the 2029 season (01/01/2029).\nCompetitors will have 3 seasons to align their equipment with this document and its rules.","page_from":3,"page_to":3,"stable_key":"perforated-visor-bascinets:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e215a7d2edf407991399a96ef4f69da15cc1358d2842fc3bb9fc959292569ef","has_figures":true,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Bascinets with perforated visors are helmets with movable perforated visors. Such visors do not include Eye slots.\nThis type of visor is depicted in some rare manuscripts in Western Europe from the late 14th century and early 15th century. A handful of later designs showing this kind of visor still survive through the 15th century.\nThere is no consensus among armor experts where such manuscripts depict actual perforated visors or badly drawn regular helmets (hundskulls for example).\nThose helmets use a solid metal visor to protect the face, attached by 2 different system:\n● Attached on the forehead by a movable piece of metal, similar to the “spoon” from Klappvisor,\n● Attached to the dome with hinges at the temples, similar to Pivoting visored Bascinets.","page_from":3,"page_to":3,"stable_key":"perforated-visor-bascinets:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0019092a5706e8abae0c05f9767d7ce7f0f4857b51895199bbac61f7a76d757f","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"","page_from":4,"page_to":4,"stable_key":"perforated-visor-bascinets:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04e42d373a22b64d239d42d339423dfe562a290d68219f938a8fe993f807be48","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"Bascinets with perforated and forehead attached visor","body":"The term “Bascinets with perforated and forehead attached visor” will be abbreviated to “Perforated Klappvisor Bascinets” for the remainder of the document.\n\nPerforated Klappvisor Bascinets can be seen in a couple of manuscripts, from 1389 to 1420/1430.\n\nPerforated Klappvisor Bascinets can have a visor with a rounded profile or a sharp profile. The shape of the profile does not change the approved and denied time periods.\n\nPerforated Klappvisor Bascinets are Approved for Transitional armors.\n\nPerforated Klappvisor Bascinets are Denied for 14th century armors.\n\nPerforated Klappvisor Bascinets can be Approved for 15th century armors with a coherent project.\nWe strongly recommend sending an email to authenticity@buhurtinternational.com before placing an order for such armor.\n\nVindobonensis 2762, Wenzel Bible - 1389 - Austria Pal.lat.1888 - 1430 - Germany\n\nGöttinger MS Philos. 63 Bellifortis - 1405 - Germany","page_from":4,"page_to":4,"stable_key":"perforated-visor-bascinets:3.1","parent_key":"perforated-visor-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f74690ada950ff6727a76f69a1552cdc15bded33d4bdd66fb0d45352fc200b6","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Bascinets with perforated side-pivoting attached visor","body":"The term “Bascinets with perforated side-pivoting attached visor” will be abbreviated to “Side-pivoting Perforated Bascinets” for the remainder of the document.\n\nSide-pivoring Perforated Bascinets must have a visor with a rounded profile.\n\nSide-pivoring Perforated Bascinets are Approved for Transitional armors.\n\nSide-pivoting Perforated Bascinets are Denied for 14th century and 15th century armors.\n\nVindobonensis 2762, Wenzel Bible - 1389 - Austria\n\nWenceslas Bible - 1390/1400 - Germany","page_from":5,"page_to":5,"stable_key":"perforated-visor-bascinets:3.2","parent_key":"perforated-visor-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2d06164cd0a428a755bd695dffd05cef60c9cddfb8c13f26fb3ce5941949f77a","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"3.3","title":"Great Bascinets with perforated visor","body":"Later during the 15th-century, a handful of contemporary designs show the use of perforated visors, despite a great lack of representation in art.\n\nGreat Bascinets with perforated visors must have a visor with a rounded profile.\n\nGreat Bascinets with perforated visors are Approved for 15th century armors.\n\nGreat Bascinets with perforated visors are Denied for 14th century and Transitional armors.\n\nGerman Great Bascinet, MET\n\nGrand Bacinet private collection - 1450/1475- southern Germany or Austria","page_from":6,"page_to":6,"stable_key":"perforated-visor-bascinets:3.3","parent_key":"perforated-visor-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e19f8f220edb69694cdee883b91dcf72ac80c74ae522207e8660098185daab17","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.4","title":"Bicoques with perforated visor","body":"Later during the 15th century, a handful of contemporary designs show the use of perforated visor, despite a great lack of representation in art.\n\nBicoques with perforated visors must have a visor with a rounded profile.\n\nBicoques with perforated visors Approved for 15th century armors.\n\nBicoques with perforated visors are Denied for 14th century and Transitional armors.\n\nBicoque ref_arm_1929_015 W1012 Goll - 1440-50","page_from":7,"page_to":7,"stable_key":"perforated-visor-bascinets:3.4","parent_key":"perforated-visor-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e618de6bc70914f4e48d5fcf7daeab2d66b28609041920a7858c7a40b9022e86","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of either bascinets, great bascinets or bicoque respective sources.\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations” document.\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.1","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5e06da447c11e37058bbb65a76ee5be64616928fa2d7ddb2c80c5dfff72bea8f","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"The visor must not be too long or too short, it must respect the proportions of historical sources.\nIt is allowed to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the aventail.\nA leather strap can be used to secure the visor down.\nIt is permitted to weld the visor down. Welded visors must resemble a functional removable visor.\nThe hinge must be reproduced as per historical sources.\nBreath holes should be round and must not exceed a diameter of 10mm. Breath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\nBreath holes of another shape must be documented by historical sources to be allowed.\n\nProfile of visors:\n● Sharp-profile visors Visors with a sharp profile must clearly present a pointy profile.\n\n● Rounded-profile visors Visors with a rounded profile must clearly present a globose profile.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.2","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c3ba1ad3192cfe0e1e59c982e90111000fcca35684e502ce8fce0656957459c2","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"4.3","title":"Aventails","body":"Bascinets with perforated visors must be worn with chainmail aventails, fabric aventails, or scales aventails.\nGreat Bascinets and Bicoques can not be worn with chainmail aventails, fabric aventails or scales aventails.\nAventails must conform to the “Aventails” document.\nAventails must be attached to the bascinet by a system of leather and vervelles.\nThe aventail must be fastened down to the edge of a padded pelerine attached to the helmet liner.\nAny additional protective plates covering the cervical spine must be hidden under the aventail.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.3","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b4c29c371ceaf41ef5ce0a6f29060805ee87275415a32c75025d14b3b342cf22","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"4.4","title":"Others","body":"All helmets with perforated visors may be decorated in the spirit of medieval styles, such as orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers and coat of arms badges etc.\nSuch decoration must be made in coherence with historical sources.\nUsing modern and/or offensive imagery and slogans is prohibited.","page_from":8,"page_to":8,"stable_key":"perforated-visor-bascinets:4.4","parent_key":"perforated-visor-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4a763495d63366c3f46fbcb9db642ced1d8cb4dec34a24aa16eb5784d9382b08","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":9,"page_to":9,"stable_key":"perforated-visor-bascinets:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1224f9c071bc04c751e872ce74a9712541a97269efe09bf62af4c75077148c22","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":0,"kind":"section","number":"6","title":"Examples of Denied Reproductions","body":"Visor lack of pointiness Visor lack of curvature and leaf instead of a spoon\n\nEyes holes do not match approved pattern\n\nPictures from The Medieval Things ©","page_from":10,"page_to":10,"stable_key":"perforated-visor-bascinets:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"09b66c7e69007ded86a499b2ebe22d0bd4296dfdf3c54dcc3705ddf1afdda3d4","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nApril - 2026 (V. 26.4) Change:\n- “Side-hinged” to “Side-pivoting” in all the document.\n\nJanuary - 2026 (V. 26.1) Add: Document has been created","page_from":11,"page_to":11,"stable_key":"perforated-visor-bascinets:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"4a6faf0ab7ddc221853be9f010b09d29ad47ff2458fbc3bf7adb7e29174ecc6a","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/sabatons","synthetic":false,"version":{"version":"26.1","title":"Sabatons - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1xeX4tDns1F0hnF1mGNhfDbtYTwPScrhv/view?usp=sharing","source_sha256":"d7d90d9c7e88aa3d3b60abf9307b99cc8944034e9c55626b7bd861bbbdc0de97","retrieved_at":"2026-10-06T00:00:00Z","page_count":10,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 9 page(s) without a text layer","content_sha256":"aac3b203a05e051dd7c68d11a0a07d0691173009c559e19fcf94f509af4c4530","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":10,"source_lines":149,"assigned_lines":189,"furniture_lines":41,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.9957,"provisions":21,"numbered":20,"needs_review":0,"verified":1,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":149,"picture_text_lines":11,"ocr_corrections":2}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"sabatons:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"sabatons:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Sabatons’ is the term used to describe all foot protections.\n\nTypes of Greaves:\n\n● Plate Sabatons Made of metal plates riveted together, it is the most effective and the most common foot protection over all Middle Ages.\n\n● Brigand Sabaton Made of metal plates riveted to a leather base. This protection is not commonly represented in historical sources. The plates are covered by the leather.\n\n● Scales Sabatons Made of small scales riveted upon a leather base. This protection is not commonly represented in historical sources.\n\n● Chainmail Sabatons The protection of the foot is ensured by chainmail. This is the earliest foot protection documented by historical sources.\n\n● Eastern Sabatons Due to very few historical sources, we allow eastern stylization of European Sabatons.\nAllowed designs are displayed in the “Eastern Armors” document.","page_from":3,"page_to":3,"stable_key":"sabatons:2","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"48069f2516e02127c625e9e327475e612a5a15cf99b6304c502733c2b2e51131","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"All types of Sabatons must:\n\n● be based on historical sources,\n● have an anatomical shape of the foot,\n● reproduce the proportions based on historical sources,\n\nAny metal part of the Sabatons must conform to the “Armors and Weapons Aesthetics and Decorations document.\n\nAny textile or leather part of the Sabatons must conform to the “Textiles and Leather” document.","page_from":3,"page_to":3,"stable_key":"sabatons:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9035077a5b82edfbe497c17f5acf26e9355ae5aee9adf2ddd7450a00407d6b83","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Plate sabatons","body":"","page_from":4,"page_to":4,"stable_key":"sabatons:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd831e569430bb5190fd0bee477beb4d7b405ff642a7d39607b1629dc54bc2a5","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"Plate Sabatons are mainly represented from the mid-14th century to very late armors of the 15th century.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nBL Sloane 2683 Book of Hours - 1390/1399 - Belgium\n\nKöln - 1375 - Germany E. of Woodstock - 1376 - England","page_from":4,"page_to":4,"stable_key":"sabatons:4.1","parent_key":"sabatons:4","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bd8438a853ecc751e87c548b699727001271a5c8ebf7dec0bafebe357545a11f","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"Plate Sabatons must conform to the General Requirements (see Section 3 above).\nPlate Sabatons must have at least 5 segments.\n\n=> Example:\n\nIt is allowed to add heel protection.\n\n=> Example:\n\nPlate Sabatons must have a pointed shape.\n\n> Example:\n\nMaximilian style armors of the 16th century can have square-shaped Sabatons.\n\n=> Example:","page_from":4,"page_to":5,"stable_key":"sabatons:4.2","parent_key":"sabatons:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"70211a1a3f862cb4c8c9c5b525c6bc22e75e12585b11ac47312679bbfb16aefe","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Reproductions","body":"Picture from Medieval Extreme ©\n\nPicture from Age of Craft ©","page_from":6,"page_to":6,"stable_key":"sabatons:4.3","parent_key":"sabatons:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2166635fc8ebafea086d6dccc2a1a0cad0e8680d584b9073c83c1f684d9a798e","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":0,"kind":"section","number":"5","title":"Brigand Sabatons","body":"","page_from":7,"page_to":7,"stable_key":"sabatons:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"63934a7210bde845c12d395913739f289d86a287db2e74611571e5085657df6f","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"Brigand Sabatons are not well represented in historical sources. They are displayed in sources from the middle of the 14th century.\n\nThey are Approved for 14th century armors.\n\nThey are Denied for Transitional and 15th century armors.\n\nG. von Schwarzburg - 1349 - Germany","page_from":7,"page_to":7,"stable_key":"sabatons:5.1","parent_key":"sabatons:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0386266a1d40424602affddecb28ba66c8d6db3f453c8b2443d92506969ac2d7","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"Brigand Sabatons must conform to the General Requirements (see Section 3 above).\nBrigand Sabatons must be made of metal plates.\n\nThe plates must be firmly-riveted to a leather base.\n\nThe plates must be riveted from the inside of the leather base.","page_from":7,"page_to":7,"stable_key":"sabatons:5.2","parent_key":"sabatons:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"df9b70e5a3239377e880259ab707adcada6d030e4d7bcc971b26d985dfc35575","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Reproductions","body":"Picture from Medieval Extreme ©","page_from":7,"page_to":7,"stable_key":"sabatons:5.3","parent_key":"sabatons:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d2ea4c5f1a569b7fcc8f40a87d84683e41cbd259ea0bcdd73de7b0a41014250c","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"section","number":"6","title":"Scale Sabatons","body":"","page_from":8,"page_to":8,"stable_key":"sabatons:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"26fcedd22ba71c8e06964fc0880725213e00b82f858b89159ad9e6c44f25b89f","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"Scales Sabatons are not well represented in historical sources. They are displayed in sources from 1350 to 1395.\n\nThey are Approved for 14th century and Transitional armors.\nThey are Denied for 15th century armor.\n\nTheir construction makes scale Sabatons less protective than plate Sabatons. Therefore, we do not recommend such Sabatons in any category.\n\nJ. von Falkenstein- 1365 - Germany Guda von Bellersheim - 1394 - Germany","page_from":8,"page_to":8,"stable_key":"sabatons:6.1","parent_key":"sabatons:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9863a978402dd15490dfc16aa71a5b3121839af5b1ed156c5a5c1e7e17925402","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Scales Sabatons must conform to the General Requirements (see Section 3 above).\nThe scales can have a rectangular shape or a rounded shape.\n\nThe scales must be firmly attached to the shoe with rivets or leather thread\n\nScale Sabatons must have a pointed shape.","page_from":8,"page_to":8,"stable_key":"sabatons:6.2","parent_key":"sabatons:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"3b54ce564d3f41b1533b290b481871a70566ffb5ab5be9923e7ea27d1997e183","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Picture from Medieval Extreme ©","page_from":8,"page_to":8,"stable_key":"sabatons:6.3","parent_key":"sabatons:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"88aff2fe4a494e022d0d298c8c8f69e1ab826e25e1bb88500c29be5df80c473a","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":0,"kind":"section","number":"7","title":"Chainmail Sabatons","body":"","page_from":9,"page_to":9,"stable_key":"sabatons:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"29f5aab9c88e4d278d3c94d6b1b0ed7d93afeb4a0af1c4460f1b71d7349af78c","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"Chainmail Sabatons are the earliest foot protection. They were popular in the 13th and early 14th century, and were replaced by more protective Sabatons around the middle of the 14th century. They are still in use in very rare cases during the 15th century.\n\nThey are Approved for 14th century armors and Transitional.\n\nThey are Approved for 15th century armors if documented by sources. We encourage you to send an email to the authenticity committee before purchasing such Sabatons and armors.\n\nTheir construction makes chainmail Sabatons less protective than plate Sabatons. Therefore, we do not recommend such Sabatons in any category.\n\nPfarr- und Klosterkirche Sankt Lampert, Seeon-Seebruck, Bavaria - 1395 - Germany","page_from":9,"page_to":9,"stable_key":"sabatons:7.1","parent_key":"sabatons:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dc2ead7cc8e7cdeb84d772b281d54fbf77d38ade4c298282a3274af75b4f563c","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements","body":"Chainmail Sabatons must conform to the General Requirements (see Section 3 above).\n\nIt is mandatory to use plate segments as the main protection, and use chainmail only for articulation purposes.\n\nIt is strongly recommended to use plate Sabatons as it is the best protection you can use for your foot.","page_from":9,"page_to":9,"stable_key":"sabatons:7.2","parent_key":"sabatons:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"b535630f2856aa815f948c19f4d929bb342ceaef471c7e1e083f83b3316ee80f","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"7.3","title":"Examples of Approved Reproductions","body":"Picture from Medieval Extreme ©","page_from":9,"page_to":9,"stable_key":"sabatons:7.3","parent_key":"sabatons:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e0425806256c6490d7111a395be93b676a7f0370e524f7ad2235e2bab5c67aef","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":0,"kind":"note","number":"8","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition and description ” and “3. General Requirements”. This split doesn’t have an impact on the content of the rules.\n\nDecember-2024: -Add Document has been created","page_from":10,"page_to":10,"stable_key":"sabatons:8","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"3f5bc07950991f2266211a8e7ffd12481f10f0fcdfc1f38d94d746843567eea9","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/sallets","synthetic":false,"version":{"version":"26.1","title":"Sallets - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1wQX1hGzV4fkjc8R5cmV_HsLYMDlmfEw6/view?usp=drive_link","source_sha256":"a4902a342148d9d03f8142d614a8f9119768635de3aa85996ab18389b7a84850","retrieved_at":"2026-10-06T00:00:00Z","page_count":13,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 11 page(s) without a text layer","content_sha256":"ef99d5356ddd08fe1b97d62a63fc9a117b9016a8c5a34c883546bab1913b8db4","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1, 4"],"pages":13,"source_lines":119,"assigned_lines":145,"furniture_lines":34,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99761,"provisions":13,"numbered":11,"needs_review":0,"verified":1,"empty_pages":[1,4],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":119,"picture_text_lines":2,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"sallets:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 29.11.2025.\nThe document and its rules will be implemented from the 2029 season (01/01/2029).\nCompetitors will have 3 seasons to align their equipment with this document and its rules.","page_from":3,"page_to":3,"stable_key":"sallets:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e215a7d2edf407991399a96ef4f69da15cc1358d2842fc3bb9fc959292569ef","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Sallets are the evolution of bascinets as the main combat helmet.\n\nEarliest examples are dated from 1430, and sallets were in use until 1540. The designs have widely evolved throughout the years.\n\nSallets are widely used in western Europe and can be made with integral face protection or open-faced helmets.\n\nSallets are worn alone or with an addition of a bevor, of plate or mail.\nBevor is a plate or chainmail element of armor designed to protect the neck and the mouth.\nSallets are Denied for 14th century and Transitional armors.\n\nDue to the extraordinary range of variety in 15th century armors, it is not possible to give a single approved status.\n\nSallets are Approved if matching the rest of armor for mid-15th century, Transitional 15-16th and first part of 16th century armor.\n\nChainmail bevor Plate bevor","page_from":3,"page_to":3,"stable_key":"sallets:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"496a2b0b887468d3d6ff8062d0d8a1105c54f1b2274474e8a82ae664747edb9d","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":4,"page_to":4,"stable_key":"sallets:page-4","parent_key":null,"review_status":"verified","review_note":"Picture page: drawings of sallets with aventails, no text.","topics":["pictures"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"DISCLAIMER\n\nWe do not intend to give a classification of Sallet per time period. We strongly recommend ordering a Sallet as a part of a whole set of armor, based on sufficient historical evidence. We strongly recommend sending an email to authenticity@buhurtinternational.com before placing an order for such armor.\n\nSallet and Bevor, Museum of Royal Armouries, Leeds. Sallet - Milan Workshop Missalia (Milan), Museum of Army in Paris - 1430/1440 - France 1480/1490 - Southern Germany Army in Paris - Around 1475 - Italy\n\nSallet with visor - Around 1475 - France or Flanders German sallet, Innsbruck - 1495 - Austria\n\nCombined salad with bevor, Historical Museum in Vienna - 1495 - Austria\n\nAugsburg Master: Lorenz Helmschmid Inv. A 205 Kunsthistorisches Museum Vienna - 1510 - Austria\n\nKept in St Michael's Church, Kerhais, England. (Stolen in the 1950s.) Dated by Capwell to 1480/90 - England\n\nHelmet of Philip the Handsome Flanders - 1496/1500 - Netherlands Stibbert Museum (Inv. 3599), Italy - 1490/1510 - Italy\n\nHalf-armor \"alla tedesca\", Milanese work, Inv. number G 9 Army Museum, Paris 1510/1515 - Italy\n\nBargello Museum (inv. 1635 C). Inv. 29.150.4a (sallet) Metropolitan Wallace Collection late sallet - 1500 Dating by Leiking 1500.Dating by Boccia 1500-1505. Museum of Art - 1500/1510 Museum dating 1515.\n\nPhiladelphia Museum of Art late sallet - 1500/1510\n\nThun sketchbook\n\nItalian sallet, Royal armouries, Leeds - 1440/1450 - England","page_from":5,"page_to":9,"stable_key":"sallets:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9f0900fcc779a57ff398f5bd0080def955767f094f5fa4851d4f524d6ab157a7","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":10,"page_to":10,"stable_key":"sallets:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":false,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of historical sources.\nA particular attention must be paid to the crest on top of the sallet, often forgotten by modern armorers.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":10,"page_to":10,"stable_key":"sallets:4.1","parent_key":"sallets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2d1cf89074b0892a3c1c3c7b9a0e223312ae54b78c17fac86828e46dfb26fb24","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"Visors must not be too long or too short, it must respect the proportions of historical sources.\n\nVisors locking systems must be reproduced as per historical sources. It must be hidden in helmet construction if it is not based on historical sources.\n\nIt is Allowed to weld the visor down. Welded visors must resemble a functional removable visor.\nBreath holes should be round, square or rectangular.\n\nRound breath holes must not exceed a diameter of 10 mm.\n\nSquare or rectangular breath holes must replicate historical sources.\n\nBreath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\n\nBreath holes of another shape must be documented by historical sources to be Allowed.","page_from":10,"page_to":10,"stable_key":"sallets:4.2","parent_key":"sallets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"529e6430ca9406749305a84caef4f761327b3b53aaf6d0d0ae99abd83e3f8a5c","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.3","title":"Eyes and Mouth slot","body":"Eye slots must resemble sources for the visor.\n\nEye slots should not exceed 25mm tall to prevent any injury.\nIt is Allowed to add up to five (5) safety eyebars.\n\nEye bars must be welded internally or riveted internally.\n\nEye bars must conform to the “Eye bars” document.","page_from":10,"page_to":10,"stable_key":"sallets:4.3","parent_key":"sallets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a3ffab67b5907529f5d8177ffafc905ebd332ea27cc1373ece2de1ce61d29bc","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.4","title":"Bevor","body":"Sallets are not designed to be worn with an aventail, unlike bascinets. Sallets are worn with bevor.\n\nSallet must be worn with a plate bevor, or a safe construction simulating a mail bevor as best as possible.\n\nBevor must be constructed in such a way as to protect its wearer. Mail bevor must integrate a grill of protection or additional plates.\n\nChainmail bevor must conform to Chainmail Aventails requirements listed in the “Aventails” document.\nAdditional neck protection can be worn according to historical sources.\nAdditional neck protection not based on historical sources can be worn if concealed.","page_from":10,"page_to":10,"stable_key":"sallets:4.4","parent_key":"sallets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"61afde4311abecd95e7f8030cd095e8f54f8f9d712de0146e0baefe26a61ccef","has_figures":false,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.5","title":"Others","body":"Sallets may be decorated in the spirit of medieval styles, such as orle, torse, vervelle covers and coat of arms badges etc.\n\nSuch decoration must be made in coherence with historical sources.\n\nSallets can be covered with silk or velvet, as per historical sources. These decorations require a lot of maintenance to maintain a high level of aesthetic. Any Sallet with silk or velvet cover that is too much damaged can be denied during Authenticity Check.\n\nUsing modern and/or offensive imagery and slogans is prohibited.","page_from":11,"page_to":11,"stable_key":"sallets:4.5","parent_key":"sallets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"07a8e5eb5fade37e38f11f993ad5d94ab1529e4dc8525769cd1e86a4da8600ec","has_figures":false,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":12,"page_to":12,"stable_key":"sallets:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1224f9c071bc04c751e872ce74a9712541a97269efe09bf62af4c75077148c22","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"note","number":"6","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Document has been created","page_from":13,"page_to":13,"stable_key":"sallets:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"ff29586f66c756612b879fe382552c6d47ab86c56e509100938b8443b89e4689","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/shields-and-bucklers","synthetic":false,"version":{"version":"26.4","title":"Shields and Bucklers 26.4","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.4\" and every page footer \"V. 26.4\".","source_url":"https://drive.google.com/file/d/1u3RCMI3PhELiRPootNoVZiLR9YbU5Nzt/view?usp=drive_link","source_sha256":"2cb34c31c11c52a4abdbf5c736a3cfbeec06673ee8dbe2e0104059638a3afe04","retrieved_at":"2026-10-06T00:00:00Z","page_count":20,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"118ecd5df3d5154329779f87acddd5aaae58a1a374efdde3d90851ec3ff31971","detected":{"version":"26.4","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":20,"source_lines":287,"assigned_lines":511,"furniture_lines":51,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99689,"provisions":31,"numbered":30,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.4\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"shields-and-bucklers:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"08314837801c0561e4b5da4df28df075016d78fec8597b698744a7724df00b43","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Shields and Bucklers” are the terms used to describe every protection made of wood or steel and designed to protect yourself.\n\nShields and Bucklers can be:\n● Heater Shields Shields made of triangular shape, the most common shape of Shields from the XIIIth century and beyond. They must be made of wood.\n● Punch Shields Punch Shields are primarily designed to hit the opponent. It includes a wide variety of shapes. They must be made of wood.\n● Round Shields Shields made of a round shape, very common throughout the middle ages. They can be made of wood or metal.\n● Bucklers Small round shape Shields with central handle, mainly used in duels and as a secondary equipment for close defense. They can be made of wood or metal.","page_from":3,"page_to":3,"stable_key":"shields-and-bucklers:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a27db45dd9bd7642ad23f5c138fd58d8f8f606e1332e70046ddc92827e48954","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"All types of Shields and Bucklers must respect the following requirements:\n● be based on historical sources,\n● must reproduce the proportions and curves based on historical sources,\n● must be made of wood or metal. Any other material must be approved by the Authenticity Committee to be allowed in Buhurt International events,\n● must match the style of the armor kit of the competitor.\nAll images, drawings, and paintings on Shields must be stylized in accordance with the style of the armor kit of the competitor.\nIt is prohibited to decorate Shields and Bucklers with images that are clearly modern and/or offensive.\nFor the Marshals’ safety, it is prohibited to decorate Shields and Bucklers with black and yellow combinations, which include stripes, chevrons and other marshals symbols. The weight of all Shields and Bucklers must not exceed 5 kg.\nIt is allowed to use bolts and nuts to fasten straps:\n● nuts must not protrude the screw,\n● bolts and nuts must be painted in black or concealed with leather or fabric.\nAll straps must be made of leather.\nAny metal part of the Shield or Buckler must conform to the “Armors and Weapons Aesthetics and Decorations” document.\nAny textile or leather part of the Shield or Buckler must conform to the “Textiles and Leather” document.","page_from":4,"page_to":4,"stable_key":"shields-and-bucklers:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6d196d8fbf24fc6b85b2b983fd1d2c6ecc10ae2fca001ab568df0dbce0d56926","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Wooden Shields Requirements","body":"The entire edge must be covered with either a band of strong leather, or with at least three or more layers of fabric.\nA leather band must be glued, sewn or riveted, to the Shield. Any rivets must be neatly finished, the edge of the rivet should not stick out.\nThe flat outside a wooden Shield must be covered with leather or fabric.\nThe handles must be made of leather.\nWooden Buckler and Heater Shield with a central handle must have a handle made of wood.\nShield boss (umbo) made of metal must conform to the “Armors and Weapons Aesthetics and Decorations” document.","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"85b0fd0c1787deed2b53c7f5353565c39bdc1cfbf042d82017267af5daf48a7f","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":0,"kind":"section","number":"5","title":"Metal Shields Requirements","body":"Must be of round shapes, based on historical sources, and repeat the form of the original in all three dimensions.\nThe entire edge of metal Shields must be rolled to the thickness of a minimum of 4 mm or more.\nThe handles must be made of metal and or wood Metal Shield and Shield boss (umbo) must conform to the “Armors and Weapons Aesthetics and Decorations” document.\nIt is allowed to blacken the back part of a metal Shield or metal Buckler.\nExample:\n\nPicture from O. Haguenstein ©","page_from":5,"page_to":5,"stable_key":"shields-and-bucklers:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae33866f2913a0328fecc2aa2555fe216ead12720344c628cac9b1f6358b80f4","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"6","title":"Heater Shields","body":"","page_from":6,"page_to":6,"stable_key":"shields-and-bucklers:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"19a588ef6abd5379334147570c2e633975db534de166b4fd52de2bac7449636d","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"The Heater Shield the main Shield shape for knights of the Middle Ages. Its triangular shape is typical of the 14th century. The shape goes thinner as the armors become more effective.\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nShield of Loew von Steinfurth - 1380 - Germany Grande Chroniques de France - 1400 - France\n\nPolitica & Economica - 1376 - France Ab Urbe Condita - 1390/1400 - France","page_from":6,"page_to":6,"stable_key":"shields-and-bucklers:6.1","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"64d7342cb29dafd3dc9a98d251731d4d4ea36c0159b85dfe00b4f8c58f8e9f7f","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Heater Shields must:\n● conform to the General Requirements and Wooden Shield requirements (see Sections 3 and 4 above),\n● be made of wood,\n● have a rectangular shape with a pointy shape at the bottom:\n\n● be curved, not flat:\n\n● have a length of 55 cm to 75 cm,\n● have a width of 30 cm to 65 cm,\n● have handles made of leather:\nExample:\n\nPicture from O. Haguenstein ©\n\nIt is allowed to add a Shield boss (umbo) on a Heater Shield with a central handle, as documented by historical sources.\nCentral handles must be made of wood.","page_from":7,"page_to":7,"stable_key":"shields-and-bucklers:6.2","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"29cc9df7a37fdf810d88bb2cf8afc837ccdbf44b6c354edfe077f19fb0f35be5","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"shields-and-bucklers:6.3","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f1cd9b5432108c0555278d395c5d5f4631b90033f061a2d1771b9e116698028","has_figures":true,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Denied Reproductions","body":"This shape (oval) is not based on historical sources for Shield with a central handle.\n\nPicture from The Medieval Things ©","page_from":8,"page_to":8,"stable_key":"shields-and-bucklers:6.4","parent_key":"shields-and-bucklers:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"319ff7d80cc4c64d3e3484e260e4906b6b0b95d0818d456d3efa789fe9f7b894","has_figures":true,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"section","number":"7","title":"Punch Shields","body":"","page_from":9,"page_to":9,"stable_key":"shields-and-bucklers:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"792203dbdde516f31e936f10edb96cbbcf6169d2a31d91e7644c7d4ea1eb638c","has_figures":true,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"7.1","title":"Historical Sources and Datation","body":"Punch Shields are designed to strike with the edge. The handles and straps allow you to wear them in a striking position. Their shape may vary depending on the time and place. Most common shapes are rectangular, trapezoid and oval.\nTheir ultimate evolution is the Pavese of the 15th century. This type of Shield has a rectangular shape and a gutter in the middle.\nAll shapes except the Pavese are Approved for 14th century, Transitional and 15th century armors.\nPavese shape is Approved for 15th century armors.\nPavese shape is Denied for 14th century and Transitional armors.\n\nCastello di Avio - 1350 - Italy\n\nShield of Order Teutonicus Great Master - 1320 - Germany\n\nDeutsches Historisches Museum (Berlin) - 1480 - Germany Wien Museum - 1480 - Austria\n\nPaduan Bible - 1400 - Italy","page_from":9,"page_to":10,"stable_key":"shields-and-bucklers:7.1","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6805a106d5223ee432431b9bc425442d421e272aeb095eed10fa86ad8022f1a2","has_figures":true,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"7.2","title":"Specific Requirements","body":"Punch Shield must:\n● conform to the General Requirements and Wooden Shield requirements (see Sections 3 and 4 above),\n● be made of wood,\n● have a shape rectangular, oval or pointed:\n\n● be curved, not flat:\n\n○ Except for Pavese shape, that can be flat if they conform to historical designs:\n\n● have a length of 55 cm to 75 cm,\n● have a width of 30 cm to 50 cm,\n● have handles made of leather (see example in 6.2. Punch Shield).\n\nThe striking area can be rounded or flat.\nThe rounded striking area must conform to a curve of 7 cm diameter.\nFlat striking area must be 7 cm wide as a minimum.\n\n7 cm wide\n\nIt is not allowed to add a Shield boss (umbo) on a Punch Shield.\nIt is allowed to add a metal sheet on the Shield to increase its resilience. In this case:\n● Additional metal sheets must be covered by leather or fabric as another part of the outside of the Shield.\n● Additional metal sheets must have no sharp edges nor pointy parts.\n● Additional metal sheets must be properly attached to the wooden core of the Shield, by rivets, nails or strong glue.","page_from":11,"page_to":12,"stable_key":"shields-and-bucklers:7.2","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3","6.2"],"content_sha256":"b099b58b027816ca1b46caa9725a2143eec37ce1508a5296e1d924543d7ba452","has_figures":true,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"7.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":12,"page_to":13,"stable_key":"shields-and-bucklers:7.3","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"517cefe2f22b30fd1ef599996381df272eeb5b23dcef2ea2bbe33af6090248b9","has_figures":true,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"7.4","title":"Examples of Denied Reproductions","body":"Flat Shield\n\nAbsence of leather or 3 layers of fabric on the edge\n\nPictures from The Medieval Things ©","page_from":14,"page_to":14,"stable_key":"shields-and-bucklers:7.4","parent_key":"shields-and-bucklers:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dd9f26a633aa8e96861618576aed40dfd4fc6c2fc10df1d671e78bf9cb48db86","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":0,"kind":"section","number":"8","title":"Round Shields","body":"","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a42d52ceba6fbf7f81727c933c40e18c0b0cc60fb9ce0516ebb1b9c262f42d9e","has_figures":true,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"8.1","title":"Historical Sources and Datation","body":"Round Shields were very common in the early 14th century, and became rare while other designs spread.\nThey are mainly made of wood. Some examples of metal round Shields exist but they are parade Shields and should be worn only with the proper set of armor of the late 15th century.\nRound Shields are worn with straps made of leather.\nThey are Approved for 14th century and Transitional armors.\nThey are Denied for 15th century armors unless historical sources are provided.\n\nRoman de la Rose - 1350 - France\n\nCathedral of Strasbourg - 1340 - France","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:8.1","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0e680ee12afdc8efe9258a5dea50602986e23ed427672b8dd5c0a65b4c3ebc93","has_figures":true,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"8.2","title":"Specific Requirements","body":"Round Shield must:\n● conform to the General Requirements and either the Wooden Shield Requirements or the Metal Shield Requirements (see Sections 3, 4 and 5 above),\n● be made of wood or metal, ○ Any metal Round Shields must be approved by the Authenticity Committee to be allowed in Buhurt International events.\n● have a diameter:\n○ for Sword and Buckler (Duel): from 25 cm to 35 cm, ○ for Buhurt and Sword and Shield (Duel): from 25 cm to 70 cm,\n● be flat or have a concave curve,\n● have handles made of leather (see example in 6.2. Punch Shield).\n\nIt is not allowed to add a Shield boss (umbo) on a Round Shield unless documented by historical sources.","page_from":15,"page_to":15,"stable_key":"shields-and-bucklers:8.2","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3","6.2"],"content_sha256":"42cdb3bdc6e1d17ca24fd46c00e871198f0eb7acd46799a4db5fb1bc7f1daeab","has_figures":true,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"8.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:8.3","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ddc2d3bcb465208219c2ed2be320328c0155cbeb5ad60af4701054a023ad723a","has_figures":true,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"8.4","title":"Examples of Denied Reproductions","body":"Round Shield with Shield boss (umbo)","page_from":16,"page_to":16,"stable_key":"shields-and-bucklers:8.4","parent_key":"shields-and-bucklers:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0c9ab73048d41cbd355f11a63309ba55fa78e02d1997058ff3542ec1e2c5d6f4","has_figures":true,"extraction":"text"},{"ordinal":22,"depth":0,"kind":"section","number":"9","title":"Bucklers","body":"","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1cde0147c799cce7f9727ae6ca36fd4aad1af1d643aef5f1615ad50e0f7eed9d","has_figures":true,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"9.1","title":"Historical Sources and Datation","body":"Bucklers are small round Shields made of wood or metal. They do not have straps but a rigid handle and a Shield boss (umbo).\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nWeltchronik in Versen - 1370 - Germany","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:9.1","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"70533f7c30e9bdf9b2a85215e05dc3e5c93cf7716766ed4cdf2d703cee22c9d7","has_figures":true,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"9.2","title":"Specific Requirements","body":"Bucklers must:\n● conform to the General Requirements and either the Wooden Shield Requirements or the Metal Shield Requirements (see Sections 3, 4 and 5 above),\n● be made of wood or metal,\n● have a Shield boss (umbo):\n○ Shield boss must be made of metal.\n○ Shield boss can be riveted or forged.\n● have a diameter:\n○ for Buhurt: from 20 cm to 40 cm, ○ for Duels: from 20 cm to 35 cm,\n● be flat or curved depending on historical sources.\n\nIf the Buckler is made of wood, the handle must be made of wood.\nIf the Buckler is made of metal, the handle must be made of metal.\nA strap can be added to secure the Buckler in punch position. This strap must be made of leather.","page_from":17,"page_to":17,"stable_key":"shields-and-bucklers:9.2","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"d4b2291f8a7006ade8b9dc75bedb232abcdc034902ea06db7e8d045859c8de42","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"9.3","title":"Examples of Approved Reproductions","body":"Picture from Black Dog Armoury ©\n\nWooden Buckler Picture from The Medieval Things © Additional leather strap Picture from Medieval Extreme ©","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:9.3","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4a1d9d835ef8fd2c6b6ff83d25a1be634ba85ef069ecfbef68bc6abf2430795b","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"9.4","title":"Examples of Denied Reproductions","body":"Black painting is not allowed as per “Armors and Weapons Aesthetics and Decoration” document.\n\nPicture from The Medieval Things ©","page_from":18,"page_to":18,"stable_key":"shields-and-bucklers:9.4","parent_key":"shields-and-bucklers:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fd22d23a7c1349b4f622f82d1d5f12f2cee406c21bd890701f8c73087b9de97d","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":0,"kind":"section","number":"10","title":"Fastening Systems","body":"","page_from":19,"page_to":19,"stable_key":"shields-and-bucklers:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ceefbd5d8215caa7f16c8685313424a3e8e149fb3970aca9844f09c4e971e7fe","has_figures":true,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"10.1","title":"Historical Sources and Datation","body":"Leather straps were fastened with nails or rivets.\nThe following methods are Approved for 14th century, Transitional and 15th century armors:\n● nails,\n● rivets,\n● modern nuts and bolts.\nExamples:\n\nNails Rivet with metal plate Pictures from Black Dog Armoury ©","page_from":19,"page_to":19,"stable_key":"shields-and-bucklers:10.1","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"78cedf2015f35bd2855b0ecafe58bcad5b6a3060a15f54e002b94f106a609112","has_figures":true,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"10.2","title":"Specific requirements","body":"Nails and rivets can be left visible.\nModern nuts and bolts must be concealed by one of the following methods:\n● Covered by a piece of leather nailed to the Shield.\n● Painted in black or any other color to make it concealed.\n● Hexagonal unpainted bolts must be ground to a rounded shape, replicating a rivet aesthetic.\nBolts must not protrude from the nuts.","page_from":19,"page_to":19,"stable_key":"shields-and-bucklers:10.2","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"851e803eeea6a27c57332d9224831a2dd4bae6af4a46bb98f3440aa89719b641","has_figures":true,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"10.3","title":"Examples of Approved Systems","body":"Rivets can be visible Modern nuts and bolts, painted black Pictures from Medieval Extreme ©","page_from":19,"page_to":19,"stable_key":"shields-and-bucklers:10.3","parent_key":"shields-and-bucklers:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"849be3c98ea25086315078942c1ada79026e2861c2f3facaa2a81b711f959c50","has_figures":true,"extraction":"text"},{"ordinal":31,"depth":0,"kind":"note","number":"11","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nApril - 2026 (V. 26.4) Add:\n- 3. General Requirements: “For the Marshals’ safety, it is prohibited to decorate Shields and Bucklers with black and yellow combinations, which include stripes, chevrons and other marshals symbols.”\n\nFebruary - 2026 (V. 26.2) Change:\n- 8.2 “Specific Requirements” of Round Shields: Maximum diameter changed from 35 to 70 cm for Sword and Shield (Duel).\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\nAdd:\n- “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n- Split of “1. Definition and general requirements” in “2. Definition” and “3. General Requirements”.\n- From 1.1. to “4. Wooden Shields requirements” and 1.2. to “5. Metal Shields Requirements”.\n- This doesn’t have an impact on the content of the rules.\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document)\n- Modification of diameters for Round shields and Bucklers depending on the type of fight.\n\nMarch-2025 (V2025.02)\n- clarification : 6.2\n- format: Grammar and Formatting\n\nDecember-2024: -Add Document has been created","page_from":20,"page_to":20,"stable_key":"shields-and-bucklers:11","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"5244af554a589eca1b6e2ad5429483ba8f177126c87179886aca60654f420b02","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/side-pivoting-visored-bascinets","synthetic":false,"version":{"version":"26.1","title":"Side-pivoting visored Bascinets - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\" (the footer names the document \"Side-hinged visored Bascinets\"); changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1v9GjZNB6xaTEkKWBgC-zo0tkiCin6VSc/view?usp=drive_link","source_sha256":"f63587c9dc71d4e2c642c6e3f85eeb0ce47e3b05e10342306c7ccd4aa22bdee1","retrieved_at":"2026-10-06T00:00:00Z","page_count":15,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 15 page(s) without a text layer","content_sha256":"fd55cfed90253a2fcc50007b14c28d4d2ae4c28ac781202e647ea52907e1720b","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":15,"source_lines":179,"assigned_lines":234,"furniture_lines":41,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99639,"provisions":22,"numbered":21,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":179,"picture_text_lines":5,"ocr_corrections":2}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"side-pivoting-visored-bascinets:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"side-pivoting-visored-bascinets:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Side-pivoting visored Bascinets are helmets with movable visors attached to the dome with pivots at the temples, in contrast to center-mounted hinges on the forehead. This type of helmet was very popular in Western Europe from 1350 to 1450. Such helmets are designed to be worn as primary head protection, and the design of the visor is made to deflect strikes.\n\nSide-pivoting visored Bascinets use a solid metal visor to protect the face, attached on the sides by pivots.\n\nSide-pivoting visored Bascinets were used from the early 14th century to 1450 across all of Western Europe. The shape of the visor will evolve throughout time.","page_from":3,"page_to":3,"stable_key":"side-pivoting-visored-bascinets:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5c8f0f19c4689dc61a50ab54bf5a83dc34e6a2bcd5f84665e83e03dfc6d5be45","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"","page_from":4,"page_to":4,"stable_key":"side-pivoting-visored-bascinets:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"04e42d373a22b64d239d42d339423dfe562a290d68219f938a8fe993f807be48","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"14th Century Sugarloaf Helmets","body":"Sugarloaf helmets are one of the earliest types of Side-pivoting visored Bascinets. It appeared at the beginning of the 14th century and includes a solid chin protection, derived from Great helms design.\n\nSugarloaf helmets are Approved for 14th century armors.\nSugarloaf helmets are Denied for Transitional and 15th century armors.\n\nBL Royal 6 E IX Address in verse to Robert of Anjou, King of Naples - 1335/1340 - Italy","page_from":4,"page_to":4,"stable_key":"side-pivoting-visored-bascinets:3.1","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dbae3af39c394d30b41704a77bf898beb4f15cbd879591be6c59fe0e04f8325b","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Transitional Style Helmets","body":"In the middle of the 14th century, Bascinets with a side-pivoting visor began to be depicted in miniatures and art. They include a longer visor with no chin plate and will represent the majority of helmets until the middle of the 15th century.\n\nTransitional style helmets are Approved for 14th century and Transitional armors.\nTransitional style helmets are Denied for 15th century armors.","page_from":5,"page_to":5,"stable_key":"side-pivoting-visored-bascinets:3.2","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6f5cdf5ee5941e9757f7160055f7488ac7018eb61c138989f5a6dc790ffdfd8a","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":2,"kind":"rule","number":"3.2.1","title":"| Romance of Alexander, Spoleto, and Other Flat-faced Bascinets","body":"These helmets are based on period art:\n\nHolkham Bible - 1327/1335 - England Romance of Alexander - 1338 - England","page_from":5,"page_to":5,"stable_key":"side-pivoting-visored-bascinets:3.2.1","parent_key":"side-pivoting-visored-bascinets:3.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b01e1347194387ab38b61a4af767359662367cc8efbe3ab5052115cd0475da57","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":2,"kind":"rule","number":"3.2.2","title":"| Houndskull/Hundsgugel Style Bascinets","body":"These helmets are very common at this time. Many originals survived and are displayed in museums.\n\nLes Grandes Chroniques de France - 1400/1425 - France","page_from":6,"page_to":6,"stable_key":"side-pivoting-visored-bascinets:3.2.2","parent_key":"side-pivoting-visored-bascinets:3.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b7bdd438d7c76729be06d67b909329601235b8c3174e9c78564558428bc72d68","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.3","title":"15th century Style Helmets","body":"At the edge of the 15th century, an evolution of previous Bascinets was developed. The great Bascinet encompasses an increased neck protection that makes it very safe. Some extant artifacts are displayed in museums.\n\nMusée de l’Armée, Paris - 1400/1420 - France Musées des Beaux Arts, Dijon - 1400/1420 - France\n\nDoges Palace, Venice - 1380/1390 - Italy","page_from":7,"page_to":7,"stable_key":"side-pivoting-visored-bascinets:3.3","parent_key":"side-pivoting-visored-bascinets:3","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d21a8868f2190f2ac1f2045b73cb31443812c2eeb7573f22060f6e19765de269","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of a Side-pivoting Bascinet source.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:4.1","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"96164506285e2d26c133c0d38e90d13586a91b8f0d7a594094a36841339d58f3","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"The visor must not be too long or too short, it must conform to the proportions of historical sources.\nThe pivots must be reproduced as per historical sources.\nIt is permitted to weld the visor down. A welded visor must resemble a functional removable visor.\n\nIt is permitted to add metal plates to protect the throat. Such a plate must be strong enough to endure full-contact fighting and must be concealed under the aventail.\n\nA leather strap can be used to secure the visor.\n\nBreath holes should be round and must not exceed a diameter of 10 mm. Breath holes must not be so numerous that they compromise the helm’s structural integrity. It is acceptable to mirror breath holes to both sides.\n\nBreath holes of other shapes must be documented by historical sources to be permitted.","page_from":8,"page_to":8,"stable_key":"side-pivoting-visored-bascinets:4.2","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"245298f728ea203b9c589975d078e9908ed764e1e7b991ecf609c64e0a3a86bd","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"4.3","title":"Eye slots","body":"Eye slots should resemble sources for the visor.\nEye slots should not exceed 25 mm tall to prevent any injury.\n\nSide-pivoting visored Bascinets with historical evidence of externally riveted Eye bars can add up to two (2) externally riveted eye bars per eye slot.\n\nHelmets that are currently documented with externally riveted Eye bars are Sugarloaf and Romance of Alexander.\n\nSide-pivoting visored Bascinets with two (2) Eye slots are permitted to add up to two (2) safety Eye bars per Eye slot.\n\nSide-pivoting visored Bascinets with a single Eye slot are permitted to add up to five (5) safety Eye bars: one (1) in the middle and two (2) on each side.\n\nExample:\n\nPicture from Medieval Extreme ©\n\nSide-pivoting visored Bascinets with historical evidence of integrated Eye bars can use some, such as the following:\n\nBL Royal 20 C VII Chroniques de France ou de St Denis - 1380/1400 - France\n\nEye bars must conform to the “Eye bars” document.","page_from":8,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:4.3","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"636ae5e36de05cc600a0eaa40341fb7d7473c21310f12b64db1d74cf02d4fda9","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"4.4","title":"Aventail","body":"Side-pivoting visored Bascinets must be worn with chainmail Aventails, fabric Aventails, or scales Aventails.\nAventails must conform to the “Aventails” document.\n\nAventails must be attached to the Bascinet by a system of leather and vervelles, or sewn to the edges of the helmet.\n\nChainmail Aventail must be fastened down to the edge of a padded pelerine, attached to the helmet liner.\n\nScales and fabric Aventails are recommended to be fastened down to the edge of a padded pelerine, attached to the helmet liner.\n\nAny additional protective plates covering the cervical spine should be hidden under the Aventail.","page_from":9,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:4.4","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8af071359807493c2854280421506e7c7a8a7fecee932c8951df0ac95215d31c","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"4.5","title":"Others","body":"Side-pivoting visored Bascinets may be decorated in the spirit of medieval styles, such as an orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers, coat of arms badges, etc.\n\nSuch decoration must be made in coherence with historical sources.\nUsing modern and/or offensive imagery and slogans is prohibited as part of decorations or heraldry.","page_from":9,"page_to":9,"stable_key":"side-pivoting-visored-bascinets:4.5","parent_key":"side-pivoting-visored-bascinets:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7db53b9307bc8129fd0ee4ea9a8db34b216e2134eff79c1d019e80899a20d5f9","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"","page_from":10,"page_to":10,"stable_key":"side-pivoting-visored-bascinets:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8e70bcb646d6ed03177c6a9f1044fed2b3062c26033fa8009a3017659d0454a8","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":1,"kind":"rule","number":"5.1","title":"Sugarloaf","body":"Picture from Age of Craft © Picture from Forge of Svan ©","page_from":10,"page_to":10,"stable_key":"side-pivoting-visored-bascinets:5.1","parent_key":"side-pivoting-visored-bascinets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9b9e867db9c142fe1a2290b123ec358a43e22b87d292986939c06bb427b68260","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":1,"kind":"rule","number":"5.2","title":"Romance of Alexander, Spoleto, and Other Flat-faced Bascinets","body":"Pictures from Master Uley ©\n\nPictures from Medieval Extreme ©\n\nPicture from Zoom en Lice ©","page_from":10,"page_to":11,"stable_key":"side-pivoting-visored-bascinets:5.2","parent_key":"side-pivoting-visored-bascinets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"148985e4582a68705f23fafdd9ba5c1d84c8841c0e7d349deb0c8424be90ab0d","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"5.3","title":"Houndskull/Hundsgugel Style Bascinets","body":"Pictures from The Medieval Things ©\n\nPicture from Medieval Extreme ©","page_from":12,"page_to":12,"stable_key":"side-pivoting-visored-bascinets:5.3","parent_key":"side-pivoting-visored-bascinets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4dfe8292858c363cff419f08baaff96e82101f02f7d396e1bd8de65faea86336","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"5.4","title":"Great Bascinets","body":"Picture from The Medieval Things ©","page_from":13,"page_to":13,"stable_key":"side-pivoting-visored-bascinets:5.4","parent_key":"side-pivoting-visored-bascinets:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f5a2c790df003bb19c13f3f10fdbafc06c9ac154f62e36504481b9ac7fea48c4","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":0,"kind":"section","number":"6","title":"Examples of Denied Reproductions","body":"Too many eye bars, not painted in black.\nEye slots are too tall, the safest option is to choose a helmet with thinner eye slots as per sources.\n\nDesign of the bottom of the visor does not Additional plate must be concealed reproduce historical sources.\n\nPictures from The Medieval Things ©","page_from":14,"page_to":14,"stable_key":"side-pivoting-visored-bascinets:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"85dccbc1076be511b09193d2fc6e3c6432ae12d41150902f1078a4d01a0d0764","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nReplace:\n\nThroughout the document “Side-hinged visored Bascinets” by “Side-pivoting visored Bascinets”\n\nAdd: “41. Implementation” (and subsequent modification of all Title numbers in the document) Suppression:\n\n- In 3.2 Transitional Style Helmets: “(such as sugarloaf)”\n\n- In 4.3 Eye slots: “internal”\n\n- In 4.4 Aventails “Supplemental hidden collar plates are permitted.”\n\n- In 4.3 Eye slots: “per eye slot”\n\n- In 4.4 Aventails: “Scales and Fabric aventails are recommended to be fastened down to the edge of a padded pelerine, attached to the helmet liner.”\n\nReplace:\n\n- In 4.4 Aventails: “The aventail must be fastened down to the outer edge of a padded pelerine attached to the helmet liner.”\n\nby “Chainmail aventail must be fastened down to the edge of a padded pelerine, attached to the helmet liner.”\n\nFebruary-2025 (V2025.03)\n- Clarification: 3.3\n- formatting: Grammar and Formatting\n\nDecember-2024: -Add Document has been created","page_from":15,"page_to":15,"stable_key":"side-pivoting-visored-bascinets:7","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":["3.2","4.3","4.4"],"content_sha256":"db429436379209db2a401dcfa3d719d32c1e4726e442976658e2a08d94fd6d43","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/tabards","synthetic":false,"version":{"version":"26.1","title":"Tabards - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\". The cover page is artwork only.","source_url":"https://drive.google.com/file/d/1mkBe8JCRfQxDuPPTMJImzV_UWaW4Mgvc/view?usp=drive_link","source_sha256":"0609e4753d13dbbaa9c6b6db9c579e130a57eb57d398491bea132b12cb1d7fda","retrieved_at":"2026-10-06T00:00:00Z","page_count":14,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 13 page(s) without a text layer","content_sha256":"89e7c7b7de91322dcf0d0bc7d311e8824687069a1402bf58ee21c6e91c77eca1","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":14,"source_lines":189,"assigned_lines":238,"furniture_lines":45,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99476,"provisions":27,"numbered":26,"needs_review":0,"verified":2,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":190,"picture_text_lines":4,"ocr_corrections":7}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"tabards:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"tabards:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"“Tabard” is a generic term used to describe the cloth worn upon the armor. It is made to show the heraldry of the wearer and prove your wealth and status on the battlefield, or in the list.\nNowadays, Tabards have the same function as a sports jersey: to indicate the team you belong to.\n\nType of Tabards:\n\n● Sleeveless Tabard Tabards without sleeves. Simple design, common in the 13th century and 14th century. Tend to be rare in the 15th century.\n\n● Short-sleeves Tabard Tabards with short sleeves that can go up to the elbow. Common design in the 14th century.\nTend to be rare in the 15th century.\n\n● Long-sleeves Tabard Tabards with long sleeves that cover the whole arms, from shoulder to hand. Common design in the 14th and the 15th century.\n\n● Eastern Tabard We do not have many historical references for eastern Tabard. It is allowed to use the same Tabard as European armors. Eastern stylization of Tabard are displayed in the document “Eastern Armors”.\n\n● Exception for full plates armors Wearing full plates armor makes the use of Tabard not practical. Therefore, it is allowed to wear only a scarf. Scarves must follow the General Requirements (see section 3 below).\n\nExample of scarf:\n\nPicture from The Medieval Things ©","page_from":3,"page_to":3,"stable_key":"tabards:2","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"8d487917e2d1c304c99d1b80e5f5453281d940a1f967a2efddc5099b9dfa5b27","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"","page_from":4,"page_to":4,"stable_key":"tabards:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8295fe2bc4208d485f0e4d62f112a839e3bfc08e2b952098f2a20793db34314","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"3.1","title":"Material Requirements","body":"All Tabards and Scarves must respect the following requirements:\n\n● Shapes, decorations and designs must be based on historical sources.\n● Tabards must conform to the “Textiles and Leather” document.\n● Tabards can be made of the following materials:\n\n○ wool, ○ linen, ○ silk,\n\n○ coton,\n\n○ any other material based on historical sources.\n\n● Tabards can be made of modern materials in the following cases:\n○ the modern material replicates the aesthetic of an approved material listed above, ○ the modern material is strong enough to endure full contact fights and to not be damaged too easily, ○ we recommend asking for approval of the Authenticity Committee regarding Tabard made of modern materials before placing an order.","page_from":4,"page_to":4,"stable_key":"tabards:3.1","parent_key":"tabards:3","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b64797425149d047f3a456f23c8481937e3569e5e366fe2cb46e765e38aaf4e8","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"3.2","title":"Fastening Systems Requirements","body":"Tabards can be tied with the following systems:\n\n● buttons made of fabric, wood, bone, or metal,\n\n● laces, made of leather, rope or fabric,\n\n● any other system based on historical sources,\n\n● any modern fastening system is denied. (Zips, snap buttons, velcro, paracord, nylon rope etc.).\n\nTabards can be open on the side, tied with laces.\nTabards can be open on the front, and tied with buttons.","page_from":4,"page_to":4,"stable_key":"tabards:3.2","parent_key":"tabards:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d439ce450658cd4df5495a9bc84e55ebe5971a4e3636a2669ef6838e8996280","has_figures":false,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"3.3","title":"Colors Requirements","body":"Colors used for Tabards must be based on historical sources. Any clearly modern color is denied. (Neon pink, fluorescent yellow, etc.)\n\nFor the Marshals’ safety, the use of yellow as a main color of a Tabard is Denied. Yellow color must represent less than 50% of the Tabard colors. The combination of black and yellow must not be inspired by Marshal’s uniforms.","page_from":4,"page_to":4,"stable_key":"tabards:3.3","parent_key":"tabards:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"707304f63f686185324e39edcfb83802a33e088f0fbeece479d349bdd87ff6e2","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"3.4","title":"Symbols and Decorations Requirements","body":"Symbols and decorations used for Tabards must be based on historical sources. Any clearly modern symbol or decoration is denied. (Warhammer logo, movies or TV show imagery, modern slogan etc.)\n\nWe recommend taking inspiration from middle ages manuscripts to create your symbols.\nSymbols and decorations used for Tabards must be made with the following techniques:\n\n● embroidery,\n\n● painting: can be by hand or by stamp,\n\n● sewing a patchwork of clothes to create a design,\n● any other techniques based on historical sources.","page_from":5,"page_to":5,"stable_key":"tabards:3.4","parent_key":"tabards:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"556cd8e84983a2d1021f4dffefe8eb2b54bb213f1389f3f4d9fc068871f78fc2","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"3.5","title":"Exception for Cuirass","body":"When wearing a Cuirass, it is allowed to wear the Tabard under it. In this case, it is also allowed to wear the pauldrons upon the Tabard.\n\nExample:\n\nPicture from Helli ©","page_from":5,"page_to":5,"stable_key":"tabards:3.5","parent_key":"tabards:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6c99053b979aa0eb08a5da4c4f62da2ebc468ca7ff47396f35eee532182ea69d","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":0,"kind":"section","number":"4","title":"Sleeveless Tabard","body":"","page_from":6,"page_to":6,"stable_key":"tabards:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b3c7a6135edea9e4dacbd3cfa5a7fb912d3e5c3f6b7f7e98a447a712d34d7bfd","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"Sleeveless Tabard is an easy way to display your heraldic. This type of Tabard has been used all along the Middle Ages, from knight templars to late 15th century armors.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nLife of Eustace and Other Saints - 1300 - France Weltchronik - 1360 - Germany Bibliothèque de Besançon - 1410 - France","page_from":6,"page_to":6,"stable_key":"tabards:4.1","parent_key":"tabards:4","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d9240ed17d5d3e267233c5430eaf2f88295a1f6717aeec57876fa36793e2e9fa","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"Sleeveless Tabard must:\n\n● follow the General Requirements (see Section 3 above),\n● not be too long, Knee is the limit.","page_from":6,"page_to":6,"stable_key":"tabards:4.2","parent_key":"tabards:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"5f1c2d2eed0e36220e927a0867b3b65a583f4e4be60c02cf43a72abb7a132df1","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Reproductions","body":"Pictures from Age of Craft ©\n\n4.4, Examples of Denied Reproductions\n\nYellow as a main color Over long Tabard","page_from":7,"page_to":7,"stable_key":"tabards:4.3","parent_key":"tabards:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"96549cbcdb7508eb889ac0e41f94cca9e4fddc0fe01e7cf8524a550cb41b426b","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":0,"kind":"section","number":"5","title":"Short-sleeves Tabard","body":"","page_from":8,"page_to":8,"stable_key":"tabards:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"435ed53d72839efcd22bfba745f3d83bf4286f08dcf06c58475ff3878f17bb22","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"Short-sleeves Tabard is the main design of the 14th century and later. Its simple shape makes it easy to craft and to wear. Many different designs can be documented by historical sources\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nBible historiale - 1360 - France Weltchronik - 1360 - Germany Office of the Feast of Corpus Christi - 1403 - Austria","page_from":8,"page_to":8,"stable_key":"tabards:5.1","parent_key":"tabards:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"023f35abe1a1a70cd0e2a912c8cd4a788afdbaeb53170173e503314ba54738a7","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"Short-sleeves Tabard must:\n● follow the General Requirements (see Section 3 above),\n● not be too long, Knee is the limit,\n● not have sleeves too long. Elbow is the limit, unless it can be documented by historical sources.\n● have open or plain (as a shirt) sleeves.\n\nExamples:\nOpen sleeve Plain sleeve","page_from":9,"page_to":9,"stable_key":"tabards:5.2","parent_key":"tabards:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"b924d29f3bdc8609de9ee366dbeb516ed880467cfffcf22cd9888dba4c97bf55","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Reproductions","body":"Pictures from Gohurt ©","page_from":9,"page_to":9,"stable_key":"tabards:5.3","parent_key":"tabards:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"58429ac36be14a4525b683b46a69e7b0d35353b8fd7db06dad38da64fa579e33","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":0,"kind":"section","number":"6","title":"Long-Sleeves Tabard","body":"","page_from":10,"page_to":10,"stable_key":"tabards:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5b361c4d5b360daef1afee70a831d2d38c2a1dd5fd0e3764ab851ed5a98d94fd","has_figures":true,"extraction":"ocr"},{"ordinal":19,"depth":1,"kind":"rule","number":"6.1","title":"Historical Sources and Datation","body":"Long-sleeves Tabard combine the role of exposing your heraldry and protecting your armor. The sleeves often cover the whole arm, up to the wrist, but can be shorter (up to mid-forearm). Many different designs can be documented by historical sources.\n\nThey are Approved for 14th century, Transitional and 15th century armors.\n\nGuiron le Courtois - Knebel von Katzenelnbogen - Bible historiale, BL Royal 15 D III - Le Livre et le vraye hystoire 1380 - France 1401 - Germany 1420 - France du bon roy Alixandre -\n\n1420 - France","page_from":10,"page_to":10,"stable_key":"tabards:6.1","parent_key":"tabards:6","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3b2ae7c4ca1827965b3f1f300672ccfa91652a18b074a7245c0de95afbb1c23c","has_figures":true,"extraction":"ocr"},{"ordinal":20,"depth":1,"kind":"rule","number":"6.2","title":"Specific Requirements","body":"Long-sleeves Tabard must:\n\n● follow the General Requirements (see Section 3 above),\n\n● not be too long, Knee is the limit,\n\n● cover the arm up to the middle of the forearm as a minimum,\n● have plain (as a shirt) sleeves.","page_from":10,"page_to":10,"stable_key":"tabards:6.2","parent_key":"tabards:6","review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly (\"not be too long\" is printed)","topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"fbc960be7127c440b5ebba2d59d837b1db7e47d8fb70831a527be1d61e38bd51","has_figures":true,"extraction":"ocr"},{"ordinal":21,"depth":1,"kind":"rule","number":"6.3","title":"Examples of Approved Reproductions","body":"","page_from":11,"page_to":11,"stable_key":"tabards:6.3","parent_key":"tabards:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"118007f1a943fe8afd0d250f62a925249c0b27c791b7701eafc21689050c61dc","has_figures":true,"extraction":"ocr"},{"ordinal":22,"depth":1,"kind":"rule","number":"6.4","title":"Examples of Denied Reproductions","body":"Yellow as the main colour\n\nPictures from The Medieval Things ©","page_from":11,"page_to":11,"stable_key":"tabards:6.4","parent_key":"tabards:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"edc16f3172a89b6e1f0a5ea53ca270657f2f0a5792a7924f59051cbf74d2372f","has_figures":true,"extraction":"ocr"},{"ordinal":23,"depth":0,"kind":"section","number":"7","title":"Examples of Approved Designs and Decorations","body":"","page_from":12,"page_to":12,"stable_key":"tabards:7","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"34484f14203f3b011ad7b8a852cb770689edc04a23e6116b204b32ab0421da8f","has_figures":true,"extraction":"ocr"},{"ordinal":24,"depth":0,"kind":"section","number":"8","title":"Fastening Systems","body":"","page_from":13,"page_to":13,"stable_key":"tabards:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c61d156e9b48248fae3972b914491161bf7b73cb089101de429aa10118c1c3aa","has_figures":true,"extraction":"ocr"},{"ordinal":25,"depth":1,"kind":"rule","number":"8.1","title":"Examples of Systems","body":"Metal buttons covered with fabric Wood buttons\n\nPicture from S.Bier © Picture from A. Labat © Picture from The Medieval Thing ©","page_from":13,"page_to":13,"stable_key":"tabards:8.1","parent_key":"tabards:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"48fadb16ae07613713fff8f398fa40f19b10cd005847bfa8eebb104e0b6625b8","has_figures":true,"extraction":"ocr"},{"ordinal":26,"depth":1,"kind":"rule","number":"8.2","title":"Examples of Denied Systems","body":"Velcro\n\nPicture from The Medieval Thing ©","page_from":13,"page_to":13,"stable_key":"tabards:8.2","parent_key":"tabards:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"331faaad13825bf403f71f461ee01d16344230d88b0c4707033d6bd06342b572","has_figures":true,"extraction":"ocr"},{"ordinal":27,"depth":0,"kind":"note","number":"9","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “41. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition and description ” and “3. General Requirements”. This split doesn’t have an impact on the content of the rules.\n\nSuppression:\n\n- Titles “1.1 Definition” and “1.2 Types of Tabards” to harmonise with other documents. Content is unchanged.\n\nDecember-2024: -Add Document has been created","page_from":14,"page_to":14,"stable_key":"tabards:9","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"d0b302ed563bebb1be2f0579d7f14eb98674ac4473126580cf6306e1f7bf97d9","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/textile-and-leather","synthetic":false,"version":{"version":"26.1","title":"Textiles and Leather - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1a7vTdkrW4ZhS-SdA22eczMmKrTUR2X38/view?usp=sharing","source_sha256":"555cc6f566137da3f8f7de1251e866b4d9eaed6806412871412147c4b1a53546","retrieved_at":"2026-10-06T00:00:00Z","page_count":9,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 9 page(s) without a text layer","content_sha256":"4a451808167e93c73e2b89634e30a993727abd4280f0f1d831b03b31daf01d92","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":9,"source_lines":136,"assigned_lines":176,"furniture_lines":30,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99595,"provisions":18,"numbered":17,"needs_review":0,"verified":2,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":136,"picture_text_lines":4,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"textile-and-leather:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season.","page_from":3,"page_to":3,"stable_key":"textile-and-leather:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e35b5946ae02907f8e065d2e3656f914639f40e08c6eb5efd4d1160c27157d4","has_figures":false,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"","page_from":3,"page_to":3,"stable_key":"textile-and-leather:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b0e430dd84d11db7bcfb85c5ebd769c0cd101fa4738a4ef4209b2146c3a2dc00","has_figures":false,"extraction":"ocr"},{"ordinal":4,"depth":1,"kind":"rule","number":"2.1","title":"Importance of Aesthetics","body":"Armors and weapons aesthetics are very important for the fighters' appearance and _ sports representation. The development of our sport will be easier with well-maintained and properly finished armor and weapons.","page_from":3,"page_to":3,"stable_key":"textile-and-leather:2.1","parent_key":"textile-and-leather:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d2afd4b3de2909504512bcf855379de921a4e74380195b2d67f7f140f7a038ea","has_figures":false,"extraction":"ocr"},{"ordinal":5,"depth":1,"kind":"rule","number":"2.2","title":"Textiles and leather","body":"Textiles and leather are part of a knightly appearance. Tabards are made of fabric (linen, wool, silk...), coats of plates are covered with fabric, leather is mainly used for armor (helmet suspension, belts, pouches, straps), etc.\n\nAll skin of a competitor must be covered.","page_from":3,"page_to":3,"stable_key":"textile-and-leather:2.2","parent_key":"textile-and-leather:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"12b46e218760e43e154bd74d97ef5c3deb5f33978df2482a9425dadd7f0fa64d","has_figures":false,"extraction":"ocr"},{"ordinal":6,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"Textiles and Leather must:\n\n● be based on historical sources,\n\n● not be of a clearly modern color (I.E neon or fluorescent),\n\n● be maintained in a good shape prior to any Buhurt International Event,\n● not be decorated with modern images, offensive logos, etc.","page_from":3,"page_to":3,"stable_key":"textile-and-leather:3","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly (\"not be decorated\" is printed)","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"22ae188139d9353dae3e6e617b35a5986b0d6fa5d87b146b369e98644898de1e","has_figures":false,"extraction":"ocr"},{"ordinal":7,"depth":0,"kind":"section","number":"4","title":"Textiles","body":"","page_from":4,"page_to":4,"stable_key":"textile-and-leather:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3b07ed6e0f855ca778f453adb41a897d0fa61efb48d64bccac70e7215fd43e51","has_figures":false,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.1","title":"Historical Sources and Datation","body":"The sources provide the following available materials during the Middle Ages:\n\n● linen,\n● wool,\n● silk,\n\n● coton.\n\nThose materials are Approved for 14th century, Transitional and 15th century armors.\n\nDepending on the area and time-period, other textiles fibers may be available. Any other material based on historical sources can be accepted.\n\nTextiles were used in many applications, such as:\n\n● tabard,\n\n● covering a coat of plates, corazzina or brigandine,\n● gambesons,\n\n● chausses,\n\n● helmet decoration (burlet, torse, orle, crest etc.).","page_from":4,"page_to":4,"stable_key":"textile-and-leather:4.1","parent_key":"textile-and-leather:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"094a1ac59681c128b198b5349d168d92a1466cf93abbb493d15c5a53589b179b","has_figures":false,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.2","title":"Specific Requirements","body":"Any material listed in 4.1 is Approved.\nAny material based on historical sources thus not listed in 4.1 is Approved.\nIt is Approved to use a modern material under the following conditions:\n\n● the modern material replicates the aesthetic of an approved material listed in 4.1,\n● the modern material is strong enough to endure full contact fights and to not be damaged too easily.\nWe recommend asking for approval of the Authenticity Committee regarding modern materials before placing an order for an item made of such material.\n\nAny clearly modern cloth element, such as underpants, sport legging, knee pad etc., must not be visible from any position.","page_from":4,"page_to":4,"stable_key":"textile-and-leather:4.2","parent_key":"textile-and-leather:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["4.1"],"content_sha256":"6a1b7b01529a215160d5add8c35609a000ace4fc91b7bcf2deee313c74e257c2","has_figures":false,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.3","title":"Examples of Approved Reproductions","body":"Pictures from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"textile-and-leather:4.3","parent_key":"textile-and-leather:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c121d617758623e26bf653356a623b8901e02dbc57435c94dfb1b2535211f138","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":1,"kind":"rule","number":"4.4","title":"Examples of Reproductions","body":"Visible modern clothes / butt protection\n\nModern legging\n\nPictures from The Medieval Things ©","page_from":5,"page_to":5,"stable_key":"textile-and-leather:4.4","parent_key":"textile-and-leather:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0b1374d64383677eba0897bddea0700fafb02a0bcde57b1c7b8ec23609c0ee60","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"section","number":"5","title":"Leather","body":"","page_from":6,"page_to":6,"stable_key":"textile-and-leather:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"714c99460c6c8ba5a2d081a60394b420247eaf4ced2d0a51bf1d2f72c1af9591","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":1,"kind":"rule","number":"5.1","title":"Historical Sources and Datation","body":"The sources provide a numerous amount of information about the use of leather. Leather can be decorated or not.\n\nThe use of leather is Approved for 14th century, Transitional and 15th century armors.\nLeather was used in many applications, such as:\n\n● covering a coat of plates, corazzina or brigandine,\n● gambesons,\n\n● helmet element (suspension system, straps etc.),\n● belts,\n\n● pouches,\n\n● shoes,\n\n● etc.\n\nReproduction of a medieval shoes - 1300/1350 - Archeologisch Museum Haarlem\n\nLeather glove - 1450/1470 - Metropolitan Museum of Art","page_from":6,"page_to":6,"stable_key":"textile-and-leather:5.1","parent_key":"textile-and-leather:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6d47ef61da434f659a5faae11bb75da8eb39df78382644050788938d4c188177","has_figures":true,"extraction":"ocr"},{"ordinal":14,"depth":1,"kind":"rule","number":"5.2","title":"Specific Requirements","body":"Any natural leather is Approved.\nIt is Approved to use a modern material under the following conditions:\n\n● the modern material replicates the aesthetic of an approved material listed in 4.1,\n● the modern material is strong enough to endure full contact fights and to not be damaged too easily.\nWe recommend asking for approval of the Authenticity Committee regarding modern materials before placing an order for an item made of such material.\n\nSpecific Requirements for boots and shoes Boots and shoes must:\n\n● be based on historical sources,\n● be fastened by leather laces, fabric laces or any historically plausible mechanism,\n● have a flat sole made of leather, or modern material.\n\nModern rubber soles must be flat or with very low texture.\nIt is Denied to use rubber sole to mimic hiking boots sole Modern soles must be black or brown, with no modern flashing color.","page_from":7,"page_to":7,"stable_key":"textile-and-leather:5.2","parent_key":"textile-and-leather:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["4.1"],"content_sha256":"2383a062872825de7d3c40bb5ea541a227aa78a6af16de0f8d6095cb8606730a","has_figures":true,"extraction":"ocr"},{"ordinal":15,"depth":1,"kind":"rule","number":"5.3","title":"Examples of Approved Reproductions","body":"Picture from Age of Craft © Picture from GoHurt ©","page_from":7,"page_to":7,"stable_key":"textile-and-leather:5.3","parent_key":"textile-and-leather:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17c3d34d0193d9060943c99903ae1691ed8c862ca04a5e22c7a7e70d56e2b3e1","has_figures":true,"extraction":"ocr"},{"ordinal":16,"depth":1,"kind":"rule","number":"5.4","title":"Examples of Approved Rubber Soles","body":"","page_from":8,"page_to":8,"stable_key":"textile-and-leather:5.4","parent_key":"textile-and-leather:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1916b18abb8b650f05a0ba30191778c539e2976c6a00f38448d06d056d4d10c6","has_figures":true,"extraction":"ocr"},{"ordinal":17,"depth":1,"kind":"rule","number":"5.5","title":"Examples of Rubber Soles","body":"","page_from":8,"page_to":8,"stable_key":"textile-and-leather:5.5","parent_key":"textile-and-leather:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"591719b00d4344615ae53c07f7455087883bf60c660709f5412930aa44e66f4e","has_figures":true,"extraction":"ocr"},{"ordinal":18,"depth":0,"kind":"note","number":"6","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document) Clarification:\n\n- Split of “1. Definition and general requirements” in “2. Definition and description” and “3. General Requirements”. This split doesn’t have an impact on the content of the rules.\n\n- In “2.2. Textiles and leather” : “All skin of a competitor must be covered.“\n\nMarch-2025 (V2025.03)\n- Add: 3.2: Boots and shoes must have a flat sole made of leather, or modern material\n- Add: 3.3: examples of Denied and Approved shoe soles\n\nDecember-2024: -Add Document has been created","page_from":9,"page_to":9,"stable_key":"textile-and-leather:6","parent_key":null,"review_status":"verified","review_note":"OCR text checked against the page image: the low-confidence words are read correctly","topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"732b075c1958b0e764da3fd21d4d0cfe411f3f4b92efc9541763e0ef591697e9","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/weapon-requirements","synthetic":false,"version":{"version":"26.4","title":"Weapons requirements 26.4","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.4\" and every page footer \"V. 26.4\"; changelog entry \"April - 2026 (V. 26.4)\".","source_url":"https://drive.google.com/file/d/1cVip6PUx62koGD1yzrygb9p0sAJ44IOj/view?usp=drive_link","source_sha256":"97bad6993ab48b619730c443d36cda331bf766d831febf74529b5563c2d232fc","retrieved_at":"2026-10-06T00:00:00Z","page_count":14,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"10d47268fdfae70ee87dee439deeebdaaeb958e14fc9dfbbff4ea6869ba1fffa","detected":{"version":"26.4","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["2 line(s) looked like a numbered heading but did not fit the sequence"],"pages":14,"source_lines":320,"assigned_lines":431,"furniture_lines":58,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99612,"provisions":43,"numbered":42,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":2,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":1,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.4\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"weapon-requirements:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"08314837801c0561e4b5da4df28df075016d78fec8597b698744a7724df00b43","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Introduction and Definitions","body":"This document will display all requirements for armors, shields, and Weapons used in any category.\nEvery competitor is solely responsible for the quality of his/her equipment. Marshals and Authenticity Officers are responsible for the correct application of this document.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a648e2555c19c78f2b099ca710e00712759875c6cb239fc39fdda93fa640663d","has_figures":true,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Equipment","body":"Armors, clothes, shields and Weapons used by a competitor.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.1","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a32d0e89b2f3ec4759f22eab33e8bc32e368336b42410c3277c657fdd3557843","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"List","body":"Place where the fights occur.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.2","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6a3b9108fce5da206e5d3123df37f9d4eee2ae2e945c9ea5d30402531a976946","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Categories","body":"● Duel 1v1 sword and shield, sword and buckler, longsword, polearm.\n● Buhurt Group fight, 5v5, 12v12, 30v30.\n● Outrance","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.3","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"279154f5accbbec2e941fee91e25b9a8322d8f2edc12ae3e00e9ea5d57ea9337","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.4","title":"Striking Edge / Non-striking Edge (of the Weapon)","body":"Striking Edge is a part of the Weapon designed to hit an opponent.\nNon-striking edge is a part of the Weapon not designed to hit an opponent.\n\nHere are some examples with the striking edge being red","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.4","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e911cf1fd0808a9f6a124d3bc98aac6fe18b7ec84748aeb723bba8b476ffbaa4","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.5","title":"Historical Sources","body":"It is the result of research to conclude the plausibility of the item had existed. Historical sources can be primary (artifacts, museum originals…) or secondary (images, paintings, statues, description, writings…).\nAny historical source must be analyzed through criticism and logic.","page_from":3,"page_to":3,"stable_key":"weapon-requirements:1.5","parent_key":"weapon-requirements:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"90dda4de36908489d497b446d3a222f721716e1aad7d150e59a14811658669a1","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"section","number":"2","title":"Historical Consistency Requirements","body":"","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d31c28382ccb21c1059e6d4305309e504fac888cd55f5f7d19f8b6c065042fda","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.1","title":"Equipment from Historical Sources","body":"Only Weapons derived from historical sources are permitted for use.\nWeapons must align with Authenticity Rules documents.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.1","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2547f2b5f93a0f77375666d0164e1dd2519a346eda97a9739ddeac1ccfa86c39","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.2","title":"Dates of Sources","body":"Weapons must align with sources dating between the 14th (1300) and 17th (1600) centuries.\nFor safety considerations, reproductions of armors predating the 13th century are prohibited, as are Weapons of the same period.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.2","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f634bb3e6d00cda61cc0389b82e80b042401795aa9036a19fe14db2b68f50d14","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.3","title":"Prohibited Features","body":"Prohibited features encompass evident indications of modern materials or manufacturing techniques including: neon colors, obvious nylon cords, plastic ties, visible welded seams, heat-induced discoloration and other visible modern equipment.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.3","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"152a00392d6f005c9e0e4dacb22396b772f573726c2bc4c2627d1d38549f951a","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.4","title":"Consistency in Equipment","body":"Armors, Shields and Weapons must consist of pieces from the same style. Distinct styles are defined in modern-day terms as:","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4","parent_key":"weapon-requirements:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ab7819040ecc8c9482a6e95f18f1efa7bed6bb694c95e2c67c0f806c10bc113f","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":2,"kind":"rule","number":"2.4.1","title":"Western Europe Style","body":"● 14th century: from 1300 to 1380\n● Transitional: from 1380 to 1420\n● 15th century: from 1420 to 1500. 15th century style armor must be approved by the Authenticity Committee. We recommended seeking approval before buying such armor.\nWestern Europe includes the following modern countries: Great Britain, Ireland, France, Portugal, Spain, Germany, Italy, Norway, Denmark, Sweden, Finland, Austria, Switzerland, Belgium, and the Netherlands","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4.1","parent_key":"weapon-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2643ae32478ba316b8395ccda4fd3a67af5df6fda578b8efa3b413b72f73bb18","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.4.2","title":"Slavic Influence","body":"● Central Europe 14th: from 1300 to 1400\n● Russian late armors: from 1500 to 1700 Slavic Influence includes the following modern countries: Czech Republic, Romania, Hungary, Poland, Slovakia, Slovenia, Croatia, Latvia, Estonia, Moldova, Serbia, Ukraine, Russia, and Belarus.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4.2","parent_key":"weapon-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8845a4bd9ab94d64bd8b444efbd8d5dc0044784fc55d9199cf3e2c8ac48a89f4","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"2.4.3","title":"Eastern Influence","body":"● Chinese style: from 1300 to 1600\n● Japanese samurai style: from 1400 to 1700\n● Middle-East style: from 1300 to 1700 Eastern influence includes the following modern countries: China, Japan, India, Korea, Iran, Iraq, Turkey, Egypt.","page_from":4,"page_to":4,"stable_key":"weapon-requirements:2.4.3","parent_key":"weapon-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a897136c756e31df00c966016acb120b39ee88b366d812f5404c7b73bacc590c","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":2,"kind":"rule","number":"2.4.4","title":"Authorized Deviations","body":"Competitors may deviate from these specified styles if they provide sources supporting their equipment choices.\n\nCompetitors who deviate from these specified styles must send an email to authenticity@buhurtinternational.com to obtain validation of their armor.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:2.4.4","parent_key":"weapon-requirements:2.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"22027dd3a2bbd5f18b1c6f280c274987188f9bcdbb075ebd0e7b099d35da600c","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":0,"kind":"section","number":"3","title":"General Requirements","body":"","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8295fe2bc4208d485f0e4d62f112a839e3bfc08e2b952098f2a20793db34314","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"3.1","title":"Competitor Responsibility","body":"Every competitor is responsible for the quality and the safety of his/her equipment.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3.1","parent_key":"weapon-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ecb1e84d661b9eff26c4d7d798592eb5051f07a5cb22c97ebf08110d719841de","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"3.2","title":"Quality Equipment","body":"All Weapon parts must be made of strong materials able to endure full contact fights.\n\nPoor quality equipment is not allowed in any category.\n\nPoor quality Weapon examples: loose guard, pommel or other element of a Weapon that may break, dented blade, cracks in metal part, etc...\n\nAll Weapons parts must not be dangerous for the other competitors. Dangerous equipment such as pointed or spiky Weapons parts, sharp edges etc... are prohibited.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3.2","parent_key":"weapon-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"69aafcaf97bb7929ace191e98aea6f30dfc4c00960497b01734695b7c71087d3","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"3.3","title":"Access to the List","body":"Marshals are allowed to deny any competitor with clearly poor quality equipment to enter the list.","page_from":5,"page_to":5,"stable_key":"weapon-requirements:3.3","parent_key":"weapon-requirements:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7f4574270a5d5d374e69d852a1994cb7a089e6d66e733bdadcf55c179c972df7","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":0,"kind":"section","number":"4","title":"Weapons Definitions","body":"","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ec6bcb8aba8b10b84d9227bd0f94dff25c7f7f49121656107054186491468263","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"4.1","title":"Types of Weapons","body":"There are 2 types of Weapons:","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.1","parent_key":"weapon-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cef2bad260bc2873df785b2c3b803431700b130d264dafd1990145c42503c120","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":2,"kind":"rule","number":"4.1.1","title":"Bladed Weapons","body":"Weapon with a long metal blade and a hilt with a hand guard.\nExamples of Bladed Weapons:\n● swords,\n● falchions,\n● longswords,\n● etc…","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.1.1","parent_key":"weapon-requirements:4.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a726f0e3342bbe88c462069ba78b641fd0c6425b0ad0d00a73a9314fbed42c37","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":2,"kind":"rule","number":"4.1.2","title":"Hafted Weapons","body":"Weapon which the main fighting part of the Weapon is fitted to the end of a long shaft Examples of Hafted Weapons:\n● axe,\n● polearm,\n● glaive,\n● maces,","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.1.2","parent_key":"weapon-requirements:4.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5c9f7bf80bb44cb4334f850d9cd582c008cbdb4b5f91b58f56e4bd01839b0047","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"4.2","title":"Subgenres of Weapons","body":"","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.2","parent_key":"weapon-requirements:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5a21f0affb335afd88ce7eac7850def25d16526532cf6851a77faf5f6b405d03","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":2,"kind":"rule","number":"4.2.1","title":"Duels","body":"● Duels Sword\n● Duels Longsword\n● Duels Polearm","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.2.1","parent_key":"weapon-requirements:4.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b225b3d4347bc9d02b4163afed50ea68302b8cf32b9b5438b314edc0067734ad","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":2,"kind":"rule","number":"4.2.2","title":"Group (3v3,5v5 etc…)","body":"● Type 1 Bladed\n● Type 2 Bladed\n● Type 3 Bladed\n● Type 1 Hafted (mace)\n● Type 2 Hafted (axe)\n● Type 3 Hafted\n● Type 4 Hafted","page_from":6,"page_to":6,"stable_key":"weapon-requirements:4.2.2","parent_key":"weapon-requirements:4.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"33521a02f664c21c62d5c2ed84bb0dbe5dae61c28099f0712d9c859e4d85febf","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":0,"kind":"section","number":"5","title":"Safety Requirements","body":"All Weapons must be able to endure full contact fights.\nAll edges of all Weapons must be rebated in compliance with this document.\nThe edge of both striking and non-striking edges must be rebated and have a thickness of 2 mm or more.\nThe radius of striking and non-striking edges must be more than 10 mm.\nWeapons constructed solely for stabbing are prohibited (spears for example) Weight permissible upward error for Weapons is 100 grams.\nAny heavier Weapon, including permissible upward error, is prohibited.\nIt is allowed to use leather thread to secure the Weapon in hand. Such leather thread must conform to the “Textiles and Leather” document .\nEvery Weapon to be used at a tournament must be first approved for safety by the Marshals and Authenticity Officers during Weapons check.","page_from":7,"page_to":7,"stable_key":"weapon-requirements:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"15e6b144e51262b6d8f345e55dedab26646b36015258f63f4b07875c4ebf5863","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":0,"kind":"section","number":"6","title":"Authenticity Requirements","body":"All Weapons must be based on historical sources and repeat the form of the original in all three dimensions.\nAll Weapons must match the style of the armor kit of the competitor.\nAll decorations on Weapons must be stylized in accordance with the style of the armor kit of the competitor.\nIt is prohibited to decorate Weapons with images that are clearly modern and/or offensive.\nAll decorations must conform to the “Armors and Weapons Aesthetics and Decorations” document .\nWeapons must conform to Authenticity Rules documents","page_from":7,"page_to":7,"stable_key":"weapon-requirements:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f1654940e0bcaab6ff205acc8f78911f502db3fa5cb0dc6d2463eaa2aee9e273","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":0,"kind":"section","number":"7","title":"Specific Requirements","body":"","page_from":8,"page_to":8,"stable_key":"weapon-requirements:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae3096ef92a3b95e91c0c022a6d0057fd5ec4311ea517ab2dc3830760d93361e","has_figures":true,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"7.1","title":"Bladed Weapons","body":"The Bladed Weapon must be made of the following elements:\n● Blade: it is the main striking edge of the Weapon,\n● Hilt: it is composed of:\n○ Pommel: it is a striking edge, ○ Handle: only place where you're allowed to hold the Weapon, ○ Guard: it is a striking edge.\nWhen holding the Bladed Weapon firmly, the guard is not allowed to extend the gauntlet of the bearer for more than 3.5 cm.","page_from":8,"page_to":8,"stable_key":"weapon-requirements:7.1","parent_key":"weapon-requirements:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cf4394957b0ed7fa6497f0fda80bba996085b32935e26737cfe4456865d6837d","has_figures":true,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"7.2","title":"Hafted Weapons","body":"","page_from":8,"page_to":8,"stable_key":"weapon-requirements:7.2","parent_key":"weapon-requirements:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"62d23038ca2f81bf286b34ea99c509f2822971b54fd33d7fd814dc46f7aff162","has_figures":true,"extraction":"text"},{"ordinal":33,"depth":2,"kind":"rule","number":"7.2.1","title":"Components","body":"Hafted Weapon must be made of the following elements:\n● Head: it is composed of:\n○ Blade: it is the main striking edge of the Weapon, ○ Back of the head: it is a striking edge but hitting an opponent with this part is prohibited,\n● Haft: the main handle,\n● Bottom: the lower part of the haft. It is a striking edge.\nNote: a mace does not have a back of the head. Each blade of a flanged mace is considered as a striking edge.\n\nThe head of any Hafted Weapon must be secured to the haft by at least 2 different methods.\nAllowed methods are:\n● wedges,\n● straps,\n● glue,\n● rivets or nails,\n● langets.\nWeapons with sharp corners (Less than 90 degrees) and corners that can be considered dangerous are prohibited.\n\nAny point on the Striking Edge of the Weapon must have an angle more than 90 degrees.\n\nA Hafted Weapon may have a rebated hook or hammerhead on the non-striking part. Any strikes with these elements are strictly prohibited.\n\nAny rebated hook or hammerhead must not present any sharp or pointed edge.","page_from":8,"page_to":9,"stable_key":"weapon-requirements:7.2.1","parent_key":"weapon-requirements:7.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8bf162a072501c8a44e67796bbef74a31ff46746075b86ab129ce67ca7180665","has_figures":true,"extraction":"text"},{"ordinal":34,"depth":2,"kind":"rule","number":"7.2.2","title":"Haft Requirements","body":"Haft must be made of strong wood or modern material that replicate the wood’s properties in terms of aspect, handling and stiffness.\n\nIt is forbidden to use soft or flexible material for haft, such as rattan.\n\nIt is forbidden to use metal haft for Hafted Weapons.\n\nIt is allowed to use a covering with the following materials:\n\n● neutral rope with glue,\n● linen thread with glue,\n● neutral color textile tape (I.E black, brown, grey).\n\nAny covering with a clearly modern appearance are prohibited\n\nIt is not allowed to enter the list with a damaged covering.\n\nThe general appearance of the covering will be examined by Authenticity Officers.\n\nIt is allowed to decorate hafts with colored tape. Such decorations can not reproduce modern patterns.\nTeam or country flags colors are allowed.\n\nAny covering must conform with the “Textile and Leather” document.\n\nExamples:\n\nPictures from The Medieval Things ©\n\nLess than 50% of the colored tape can be yellow.\nThe combination of yellow and black is allowed, but yellow must represent less than 15% of the tape. It should only be used as an accent when combined with black.\n\nThe bottom of the haft can be protected by a metal part. It must be rounded as per Striking Edge rules.\n\nHaft can be protected with metal plates. Such plates must be firmly attached to the haft and must not present any sharp edge.\n\nWeapons with poorly secured heads are prohibited.","page_from":9,"page_to":10,"stable_key":"weapon-requirements:7.2.2","parent_key":"weapon-requirements:7.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ebe3819fe87c6e806d8514527c9b9800ec300bf61fac05cb807df3a3210b0555","has_figures":true,"extraction":"text"},{"ordinal":35,"depth":0,"kind":"section","number":"8","title":"Duels Weapons","body":"Duels Weapons are built with the intent of agility and swordsmanship vs striking and punishment.\nException: all Type 3 Hafted Weapons are permitted for Polearm Category. Any Weapons not shown below must be approved by Marshal and Authenticity Committee Representatives.","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"20ccbd49d67cc01263e0c69f6b68c48262a184a2eed59a693fd6e97b9923326f","has_figures":true,"extraction":"text"},{"ordinal":36,"depth":1,"kind":"rule","number":"8.1","title":"Sword and Shield / Sword and Buckler Category","body":"Allowed Weapons: Type 1 Bladed","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8.1","parent_key":"weapon-requirements:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17aee05517ee44bcc8da3db7e6c4d875bb64ebb43a2c0a77c4e12732d4a33007","has_figures":true,"extraction":"text"},{"ordinal":37,"depth":1,"kind":"rule","number":"8.2","title":"Longsword category","body":"Allowed Weapons: Type 2 Bladed","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8.2","parent_key":"weapon-requirements:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c946cde65b374bd02cf68fd6a0404d7dc16bace25a309fa4e0fa08bec1afe4a5","has_figures":true,"extraction":"text"},{"ordinal":38,"depth":1,"kind":"rule","number":"8.3","title":"Polearm category","body":"Allowed Weapons:\n● Type 3 Hafted\n● Type 4 Hafted","page_from":11,"page_to":11,"stable_key":"weapon-requirements:8.3","parent_key":"weapon-requirements:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"70186c5b76042c599a8b8dc53341705b242fa3663f8d1357eec0266fbcaa3264","has_figures":true,"extraction":"text"},{"ordinal":39,"depth":0,"kind":"section","number":"9","title":"Outrance Weapons","body":"Outrance Weapons are any Weapon that passes the measurement requirements from Duels or Buhurt categories.\nWeapons used in outrance fights must respect their classification requirements (I.e: a sword must respect the Bladed Weapons requirements).\n\nPoint of Balance The Point of Balance of Outrance Bladed Weapons must be:\n● 15 cm from the top edge of the handle for men fights,\n● 10 cm from the top edge of the handle for women fights.\nPoint of Balance is the precise point on a blade where its weight is equally distributed to each side.","page_from":12,"page_to":12,"stable_key":"weapon-requirements:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5ce22631830f45e1c89a9e02e9dba49a880e548cc3cf8fd9d10b168cfe565880","has_figures":false,"extraction":"text"},{"ordinal":40,"depth":0,"kind":"section","number":"10","title":"Buhurt/Group Weapons","body":"Buhurt/Group Weapons may use Duels specific Weapons and any shapes that are historically documentable to the timeframe of the sport. Please reference the “Weapons/Shield Chart” document for weights and sizing.","page_from":13,"page_to":13,"stable_key":"weapon-requirements:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8e355bdfddcccfe3f5dc253f1a92b47867ac0c1f20477ad1ecfd271a255c41f8","has_figures":true,"extraction":"text"},{"ordinal":41,"depth":1,"kind":"rule","number":"10.1","title":"Type 2 & 3 Bladed","body":"These are examples for type 2 & 3:\n● longswords,\n● 2-handed falchions,\n● zweihanders,\n● etc.","page_from":13,"page_to":13,"stable_key":"weapon-requirements:10.1","parent_key":"weapon-requirements:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f455abd166aebe9f3f40dc7c679b7ea0c01547f2b87d4adf2cd05290a3f04554","has_figures":true,"extraction":"text"},{"ordinal":42,"depth":1,"kind":"rule","number":"10.2","title":"Type 2 & 3 Hafted","body":"These are examples:\n● Type 2 Hafted: Axe\n● Type 3 Hafted: Longaxe","page_from":13,"page_to":13,"stable_key":"weapon-requirements:10.2","parent_key":"weapon-requirements:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2e526fff99efc70c934fbcee5b503dd73ca865ab84ed69fe7f9af42b2ccf312d","has_figures":true,"extraction":"text"},{"ordinal":43,"depth":0,"kind":"note","number":"11","title":"Changelog","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nApril - 2026 (V. 26.4)\n\nAdd:\n- 3.2. Quality Equipment: “All Weapons parts must not be dangerous for the other competitors. Dangerous equipment such as pointed or spiky Weapons parts, sharp edges etc. are prohibited.”\n- 7.2.2. Haft Requirements: “Less than 50% of the colored tape can be yellow. The combination of yellow and black is allowed, but yellow must represent less than 15% of the tape. It should only be used as an accent when combined with black.”\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes.\nClarification:\n- Restructuration of the document to make it more easy to read,\n- Minor grammatical/formating corrections,\n- Those clarifications have no impact on the document content, except for those listed in this Changelog.\nReplace:\n- In 5.4.1 Components: An image has been changed Suppression:\n- In 5.4.2 Haft Requirements: “If a haft is not made of wood, it is mandatory to use a covering for the whole haft (from head to bottom) one end must be exposed so it can be verified what the material is” Add:\n- In 7.2.2. Haft Requirements:\n- “It is allowed to decorate hafts with colored tape. Such decorations can not reproduce modern patterns. Team or country flags colors are allowed. Any covering must conform with “Textile and Leather” document.”\n- “Haft can be protected with metal plates. Such plates must be firmly attached to the haft and must not present any sharp edge.” Clarification:\n- Addition of a subsection about polearm in “Duel Weapons”.\n\n(Version update from 2024.03 to 2024.12.13) Update date: December-2024\n- changed: Upwards weight error from 100,200,300 has been limited to 100 grams for all Weapons Added:\nThe subgenres of Weapons,Duels,Duels Sword,Duels Longsword,Duels Polearm, Group: Type 1 Bladed, Type 2 Bladed, Type 3 Bladed, Type 1 Hafted (axe), Type 1 Hafted (mace), Type 2 Hafted, Type 3 hafte, Removed: (Has been moved to document: (Weapon/Shield requirements excel) 4.4.1 Specific requirements Removed (Has been moved to document: (Weapon/Shield requirements excel) 4.4.2 Weights and measurements\n\nUpdate date: March-2024\n- format: new design format, document will be used from now on.\n- Update document based on my document (16/05/2024)\n- Update document (format)","page_from":14,"page_to":14,"stable_key":"weapon-requirements:11","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["5.4.1","5.4.2","7.2.2"],"content_sha256":"58e15e5c9c19ce6544add55eac9fbc1aee2154e2ac4e64e8a446624fd3f331f0","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"authenticity/wolfribs","synthetic":false,"version":{"version":"26.1","title":"Wolf Ribs - GoogleÂ€Docs","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.1\" and every page footer \"V. 26.1\"; changelog entry \"January - 2026 (V. 26.1)\".","source_url":"https://drive.google.com/file/d/1hd82Hg44UkAK7xa2puStRUIxoGKC_McR/view?usp=drive_link","source_sha256":"67253af516d33f96a4a81f39e6ea7f1d8f435f0cc2419b250b5ebaa53ebabb04","retrieved_at":"2026-10-06T00:00:00Z","page_count":9,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 9 page(s) without a text layer","content_sha256":"ffbe7a9099369d9a47b7747483b12b66d85f09f517dc932b4fd08224d4a9e74a","detected":{"version":"26.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":9,"source_lines":124,"assigned_lines":155,"furniture_lines":25,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.9969,"provisions":13,"numbered":12,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":124,"picture_text_lines":3,"ocr_corrections":3}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.1\n\nAuthenticity","page_from":1,"page_to":1,"stable_key":"wolfribs:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"b3cd075ee5755a5513c4f726dcdef54be200038fbb1071b0c1257f4b18b0c3f9","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Implementation","body":"The document has been created and approved by the General Assembly of 09.11.2024.\nThe document and its rules have been implemented since the 2025 season beside the part in Blue.\n\nCompetitors will have a grace period to align their equipment with the rule written in Blue. This grace period will end on 31/12/2027.","page_from":3,"page_to":3,"stable_key":"wolfribs:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"896dbdf6cec589bc65fba3eae94269dd4239fb3cc4b17b848812c05a39c100f6","has_figures":true,"extraction":"ocr"},{"ordinal":3,"depth":0,"kind":"section","number":"2","title":"Definition","body":"Wolf Ribs helmets are bascinet-based helmets topped by a central-pivot facial grill. The few available sources are paintings from the Czech Republic and Germany. The primary sources are dated from 1380 and 1450.\n\nThe helmet is very similar to other bascinets. It is constructed with a center-hinge visor (such as Klappvisor), locked with a “spoon”, and is worn with an aventail.\n\nWolf Ribs helmets are Approved for 14th century and Transitional armors.\nWolf Ribs helmets with bascinet shape are Denied for 15th century armors.","page_from":3,"page_to":3,"stable_key":"wolfribs:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9dbe36b00fbc037f571f790324f17bb874c81908ceab5354f6e78c12328d920e","has_figures":true,"extraction":"ocr"},{"ordinal":4,"depth":0,"kind":"section","number":"3","title":"Historical Sources and Datation","body":"Třeboň-altarpiece resurrection, Praha - Master of the Karlsruhe Passion - Christ 1380/1385 - Czech Republic Carrying the Cross - 1450/1474 - Germany","page_from":4,"page_to":4,"stable_key":"wolfribs:3","parent_key":null,"review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"217089e071d6d03aabd7b37c729b1ee7e0fa174200b595e9f3e0cff31a09b31f","has_figures":true,"extraction":"ocr"},{"ordinal":5,"depth":0,"kind":"section","number":"4","title":"Requirements","body":"","page_from":4,"page_to":4,"stable_key":"wolfribs:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d29162d60c0bc9bb8627f4598539b543cc6f853f7106b801fe7a3673a60cc4b","has_figures":true,"extraction":"ocr"},{"ordinal":6,"depth":1,"kind":"rule","number":"4.1","title":"General Requirements","body":"Reproductions must closely resemble the appearance and proportions of the sources.\n\nAny metal part of the helmet must conform to the “Armors and Weapons Aesthetics and Decorations” document.\n\nAny textile or leather part of the helmet must conform to the “Textiles and Leather” document.","page_from":4,"page_to":4,"stable_key":"wolfribs:4.1","parent_key":"wolfribs:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e1e092015a328ec3efba910873117f0c08f7e9245beafb85f6b06c69c84de56b","has_figures":true,"extraction":"ocr"},{"ordinal":7,"depth":1,"kind":"rule","number":"4.2","title":"Visor","body":"The visor must not be too long or too short and respect the proportions of historical sources.\n\nThe hinge must be reproduced as per historical sources.\n\nIt is permitted to weld the hinge. Welded hinges must resemble a functional hinge.\n\nIt is permitted to weld the visor down. A welded visor must resemble a functional removable visor.\n\nIt is permitted to add a metal plate to protect the throat. Such a plate must be strong enough to endure full contact fight and must be concealed under the aventail.\n\nThe visor must consist of 5 horizontal ribs.\nRibs must be round or bar-shaped.\nRibs can not be made of flat sheets.","page_from":4,"page_to":4,"stable_key":"wolfribs:4.2","parent_key":"wolfribs:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"49adfe2cd32f2dfd2987bf8d159aa8e86da0598b92f872189140ccdaa7b56a22","has_figures":true,"extraction":"ocr"},{"ordinal":8,"depth":1,"kind":"rule","number":"4.3","title":"Eye slots","body":"It is not recommended to have oversized eye slots (over 30x50 mm).\nIt is permitted to add up to four (4) vertical safety Eye bars on the visor: two (2) on each side of the visor.\nEye bars must conform to the “Eye bars” document.","page_from":4,"page_to":4,"stable_key":"wolfribs:4.3","parent_key":"wolfribs:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ec33ffe00dd8c7561c7da109512b04366fdffbfdb3eb387ed03046af99274fba","has_figures":true,"extraction":"ocr"},{"ordinal":9,"depth":1,"kind":"rule","number":"4.4","title":"Aventail","body":"Wolf Ribs helmets must be worn with chainmail Aventails, fabric Aventails, or scales Aventails.\nAventails must conform to the “Aventails” document.\nChainmail Aventail must be fastened down to the edge of a padded pelerine, attached to the helmet liner.\n\nScales and fabric Aventails are recommended to be fastened down to the edge of a padded pelerine, attached to the helmet liner.\n\nAny additional protective plates covering the cervical spine should be hidden under the Aventail.","page_from":5,"page_to":5,"stable_key":"wolfribs:4.4","parent_key":"wolfribs:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"56408e9279a76b906aafc411ad4cba4d26a5dd730f49e5954cf9a9f747e82910","has_figures":true,"extraction":"ocr"},{"ordinal":10,"depth":1,"kind":"rule","number":"4.5","title":"Others","body":"Wolf Ribs helmets may be decorated in the spirit of medieval styles, such as an orle, torse, decorated aventails (with copper/brass chainmail rings), vervelle covers, coat of arms badges, etc.\n\nSuch decoration must be made in coherence with historical sources.\nUsing modern and/or offensive imagery and slogans is prohibited.\n\nSpoon Fixation\n\n__| 5 Horizontal Ribs / Not Flat Ribs |\n\nVertical Eye Bars\n\nRecommendations for Eyes slots :\n\nEyeSlot\n\n50mm","page_from":5,"page_to":5,"stable_key":"wolfribs:4.5","parent_key":"wolfribs:4","review_status":"extracted","review_note":"includes OCR corrections checked against the page image","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f3beafccd7c573a3139d153cdfeaa0ba8401b88e8f62225c523c46b23c0e3bb0","has_figures":true,"extraction":"ocr"},{"ordinal":11,"depth":0,"kind":"section","number":"5","title":"Examples of Approved Reproductions","body":"Pictures from V. Mishurin ©","page_from":6,"page_to":6,"stable_key":"wolfribs:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6f108db9a602a366bde6093ae4213deeb3de7ea340ebc32ab6a041a6497ec45c","has_figures":true,"extraction":"ocr"},{"ordinal":12,"depth":0,"kind":"section","number":"6","title":"Examples of Reproductions","body":"More than 5 horizontal ribs Flat ribs\n\nFrame around visor Welding spot visible (not based on historical sources) Eyebars not black-painted\n\nNeck protection visible It must be concealed under the Aventail\n\nPictures from The Medieval Things ©","page_from":7,"page_to":8,"stable_key":"wolfribs:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ac1663d4650697fb11e674fb465dd77cbbd39b70a43231d38699fb25d76d6e78","has_figures":true,"extraction":"ocr"},{"ordinal":13,"depth":0,"kind":"note","number":"7","title":"Changelog","body":"Below, we will keep track of all the changes made over the lifetime of this document. This way, all our members can see how the documents are changing over time.\n\nJanuary - 2026 (V. 26.1) Formatting redone for consistency and readability. Except points listed below, no content changes\n\nAdd: “1. Implementation” (and subsequent modification of all Title numbers in the document) Format: Following sentences in Blue for Implementation schedule:\n- In 2. Definition: “Wolf Ribs helmets with bascinet shape are denied for 15th century armor.” Replace:\n- In 4.4 Aventails:\n- “The aventail must be fastened down to the outer edge of a padded pelerine attached to the helmet liner.” by “Chainmail aventail must be fastened down to the edge of a padded pelerine, attached to the helmet liner.”\n- “Wolf Ribs helmets can be worn with chainmail or fabric Aventails. Scales aventails are not permitted.” by “Wolf Ribs helmets must be worn with chainmail Aventails, fabric Aventails, or scales Aventails.”\n- “Protective plates covering the cervical spine should be hidden under the Aventail.” by “Any additional protective plates covering the cervical spine should be hidden under the Aventail.” Add:\n- In 4.4 Aventails: “Scales and Fabric aventails are recommended to be fastened down to the edge of a padded pelerine, attached to the helmet liner.”\n\nMarch - 2025 (V2025.03)\n- Clarification: Wolf Ribs helmets with bascinet shape are denied for 15th century armors\n\nFebruary - 2025 (V2025.02)\n\n- Format: formatting and grammar improvements\n\n- Replaced: 3.3 It is permitted to add up to four (4) vertical Buhurt Optimized eyebars on the visor: two\n(2) on each side of the visor. || It is permitted to add up to four (4) vertical safety eyebars on the visor: two (2) on each side of the visor.\n\nDecember - 2024 (V2024.12) Document has been created","page_from":9,"page_to":9,"stable_key":"wolfribs:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["2","4.4"],"content_sha256":"30ba9bc1edb9c24e282cc79040477d4873178fba2b2a269c91cd02d426c2cb1b","has_figures":false,"extraction":"ocr"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"executive/code-of-conduct","synthetic":false,"version":{"version":"26.1","title":"Code of Conduct Participation Requirements V26.1","published_on":null,"effective_from":null,"note":"Changelog: \"Update date: January-2026 (Version update from 2024.06 to 26.1)\". The document prints no version elsewhere.","source_url":"https://www.buhurtinternational.com/_files/ugd/735f05_eae9128857c1444290eaee38ec0fa73b.pdf","source_sha256":"a8bf8f82abb25868612a3c58f16c84553db3965a565a75182351f52798a761ef","retrieved_at":"2026-10-06T00:00:00Z","page_count":7,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"01f1ca5179281cd6995f8bf9e609245b58becef8b1bf395e185af2aaa80a87fb","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":7,"source_lines":120,"assigned_lines":143,"furniture_lines":20,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99938,"provisions":15,"numbered":13,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"code-of-conduct:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Code of Conduct and Participation Requirements This document is the Buhurt International Organization (hereinafter BI) approved policy for competitors and staff.","page_from":3,"page_to":3,"stable_key":"code-of-conduct:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"e402bd86745e24073c2b13e36de3c721b58b6e1d88b9e0e6f0de0d284e808b0a","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Participation Requirements","body":"","page_from":4,"page_to":4,"stable_key":"code-of-conduct:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"617432dbca636754b3ef5a96e297dc82a226420f78e7952561093f443ca508bf","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Requirements for all participants","body":"● Be of legal age in your home country.\n● Be a member of the National Organization of your home country\n● Be a registered and licensed (paid) member of Buhurt International.\n● Follow the Code of Conduct.\n\nNote: the home country is where you live the majority of the year (6 months at the minimum).","page_from":4,"page_to":4,"stable_key":"code-of-conduct:1.1","parent_key":"code-of-conduct:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"59cb9d19308d96436b290174e07e9e2360c6703f959fc0396728ccd732218ef9","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Requirements for all competitors","body":"● Have a sports physical or equivalent medical documentation stating they are fit for competition.","page_from":4,"page_to":4,"stable_key":"code-of-conduct:1.2","parent_key":"code-of-conduct:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"62af07ed1c6df77b32a639c6655023d5ba7d8f4c2aab03fbd0da513d867ed10a","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":0,"kind":"section","number":"2","title":"Code of Conduct","body":"","page_from":5,"page_to":5,"stable_key":"code-of-conduct:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8c022f3e413da66865f5820e641de2c41635550f0d5fadc18628280e524f5f4a","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"2.1","title":"Competitors","body":"● Treat everyone equally and sensitively regardless of their gender, ethnic origin, cultural background, sexual orientation, religion or political affiliation.\n● Know and abide by the rules of Buhurt International.\n● Must follow the WADA standards.\n● Accept the decisions of the match officials without question or complaint (let your team captain or trainer/coach make official communications and complaints).\n● Respect the event staff (marshals, officers, secretaries) at all times.\n● Exercise self-control at all times and do not use illegal or dangerous tactics.\n● Give maximum effort and strive for the best possible performance during a competition.\n● Learn to accept success and failure, victory and defeat with humility and dignity, respectively, and without excessive emotional displays.\n● Abide by the instructions of the team captain and clubs’ officials provided they do not contradict the spirit of this code.\n● Treat your teammates and opponents, trainers, club, and event officials with respect and consideration at all times-treat them as you yourself would like to be treated.\n● Do not use banned or illegal substances.\n● Do not compete while under the influence of mind-altering substances.\n● Do not use foul, sexist, or racist language at any time.\n● Be a good sport, applaud all good performance, whether by other team members or by the opponent. Remember, the aim of sport is to have fun, improve your skills and health, and feel good.","page_from":5,"page_to":5,"stable_key":"code-of-conduct:2.1","parent_key":"code-of-conduct:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9053cd210ccabe1ff51bc6f661da94d699930de489ea42ba639eb4c9332ccda7","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.2","title":"Support members","body":"● Remember the competitors are taking part for their enjoyment, not yours.\n● All spectators, on no account, must enter the field of play unless authorized otherwise.\n● Be on your best behavior. Do not use foul, sexist, or racist language or harass competitors, coaches, or event staff. Verbal abuse of participants will not be tolerated in any shape or form.\n● Show respect for opponents and event staff. Without them, there would be no sport.\n● Acknowledge good performance and fair play by opponents as well as by your own competitor or team.\n● Condemn the use of violence in all forms.\n● Do not ridicule athletes who make mistakes.\n● Do not overemphasize the importance of winning.","page_from":5,"page_to":5,"stable_key":"code-of-conduct:2.2","parent_key":"code-of-conduct:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9de26da22a3904cb10434d15f166911bce116da02ae819772c6b0b485aaaa58c","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.3","title":"Committees/Event Staff","body":"","page_from":6,"page_to":6,"stable_key":"code-of-conduct:2.3","parent_key":"code-of-conduct:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ec9cc5f7dace8531f92d7977e6d93642521ee2b8a9dc69c46634a47031edd7b9","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"2.3.1","title":null,"body":"Rights – Board Members must:\n● Respect and support the rights of every individual to take part in Buhurt International.\n● Help create an environment of enjoyment which is free of fear, discrimination or harassment.\n● Be committed to treating all people fairly and providing equality of opportunity irrespective of age, gender, ability, race, religion, ethnic origin, creed, color, social status or sexual orientation.\n● Be discreet in the handling of any information about people engaged in Buhurt International.","page_from":6,"page_to":6,"stable_key":"code-of-conduct:2.3.1","parent_key":"code-of-conduct:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cceea5086e50da64c840fb548c86418b24de7287d4b6d6d282c70007283cdda9","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":2,"kind":"rule","number":"2.3.2","title":null,"body":"Relationships – Board Members must:\n● Not engage in any behavior which constitutes any form of abuse (physical, sexual or emotional), neglect or bullying.\n● Promote the welfare of participants, take action if they have any welfare concerns by following the appropriate procedures.\n● Encourage people to take responsibility for their own development.\n● Communicate fully and as clearly as possible.","page_from":6,"page_to":6,"stable_key":"code-of-conduct:2.3.2","parent_key":"code-of-conduct:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"368905813777ef46ccd1060949bf0b1c1b5a85c4cf294581ee07e6ba793ede72","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":2,"kind":"rule","number":"2.3.3","title":null,"body":"Responsibilities (Personal Standards) – Board Members must:\n● Be fair, considerate, and honest in their dealings with everyone.\n● Promote an image of a healthy lifestyle whilst participating or volunteering in Buhurt International.\n● Display high standards of language and behavior.\n● Be a positive role model for others.\n● Promote respect for the environment.","page_from":6,"page_to":6,"stable_key":"code-of-conduct:2.3.3","parent_key":"code-of-conduct:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"676a89e6db3d5f53e789d49f99d2e9c9b5e07d0a7ce3884569d35ab0de1dfeaa","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":2,"kind":"rule","number":"2.3.4","title":null,"body":"Responsibilities (Professional Standards) – Board Members must:\n● Follow the guidelines of Buhurt International.\n● Be Registered and Licensed Members of Buhurt International and therefore become covered by these codes.","page_from":6,"page_to":6,"stable_key":"code-of-conduct:2.3.4","parent_key":"code-of-conduct:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5d798c72f5bb2ced4bd53dc465cc7198b8f2a86acdbec36e39ddca5cf1bd17c1","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.3.5","title":null,"body":"Responsibilities with respect to all forms of bribery - Board Members must:\n● Decline any ‘facilitation’ or ‘grease’ payments as these are bribes and illegal.\n● Use their best endeavors to ensure that the Buhurt International agents and other intermediaries, joint ventures and consortia, contractors and suppliers do not make facilitation payments on our behalf.\n● Decline any offer or receipt of gifts, hospitality or expenses whenever they could affect or be perceived to affect the outcome of business transactions and are not reasonable and bona fide.\n● Not make direct or indirect contributions to political parties, organizations, or individuals engaged in politics, as a way of obtaining advantage in business transactions.","page_from":6,"page_to":6,"stable_key":"code-of-conduct:2.3.5","parent_key":"code-of-conduct:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"30b62c1e5859be14f608db74102db81c6175c5199b640723a87d3bce01cfa36f","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":0,"kind":"note","number":"3","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nUpdate date: January-2026 (Version update from 2024.06 to 26.1) -clarificaton: 1.1 Update date: June-2024 (Version update from 2024.03 to 2024.06)\n- format: grammar correction 1.5 Categories in tournament\n- format: grammar correction 1.5.3 at least one (1) month\n\nUpdate date: March-2024 March 2024 (Version update from 2024.01 to 2024.03)\n- format: new design format, document will be used from now on.","page_from":7,"page_to":7,"stable_key":"code-of-conduct:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"fddd9229b32971a17e33805574524a585032236702d0ae67253a37ff74260fba","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
