":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"d107919ee6bd30ad8a2d91244f69072667d5112058a537b24b881647991cd61d","has_figures":false,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Meetings 3","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"24f7645360c0c4ac8abddeda61a167c1cdc98a0799ed3051022b33993088315c","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"General meetings 3","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.1","parent_key":"committees-decision-process:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1aeeef98b34ef48d391cb15f6172c3916f2cfa5740319b8013e38c1924094072","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":2,"kind":"rule","number":"1.1.1","title":"Definition and Organization 3","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.1.1","parent_key":"committees-decision-process:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0f8e6cf174b328f57150fbb62ff3782a1d4c7ce38a4a3d9b721872232d19d05a","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":2,"kind":"rule","number":"1.1.2","title":"Quorum 3","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.1.2","parent_key":"committees-decision-process:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2ec7d96e06bdc9890005c714d32f34261b4afc84a306996bbc6f5dcdacc79b9a","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.1.3","title":"Meeting Procedure 3","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.1.3","parent_key":"committees-decision-process:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b2642bffc43cf6d342ae6aef24a83fe7a1f2ab591bdb07df43a39ead190cb4ba","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.2","title":"Council Meetings 4","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.2","parent_key":"committees-decision-process:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"86c38f9569e7145327b791918ffd7cc588445bf90264ba7050b51d7c8127547c","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":2,"kind":"rule","number":"1.2.1","title":"Definition and Organization 4","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.2.1","parent_key":"committees-decision-process:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c979998528d8a9f79c494a768c50a59ba0ce08299e0bc3803b0c634b26870197","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":2,"kind":"rule","number":"1.2.2","title":"Quorum 4","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.2.2","parent_key":"committees-decision-process:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e8c062b89be11c53ceb2b0c0abe8f9e0f354b0e6094f64a206f324570dacec2e","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"1.2.3","title":"Meeting Procedure 4","body":"","page_from":2,"page_to":2,"stable_key":"committees-decision-process:1.2.3","parent_key":"committees-decision-process:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"de12229029d458524ed5ed5add94c161bfb6b15cbf24cd2ee25f923f2ece8d44","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"2","title":"Voting System 5","body":"1. Meetings 1.1. General meetings\n\n1.1.1. Definition and Organization\n● General Meetings are assemblies that include all members of the Committee, from Trainees to the Council members. Advisors may also be invited if the Council deems it necessary.\n● The Council organizes General Meetings whenever the situation requires it. This could be when new documents need approval, before or after a significant event, or for other important matters.\n● The Committee must hold at least one General Meeting per year, with a minimum of one month before the General Assembly of Buhurt International.\n\n1.1.2. Quorum\n\n● For a General Meeting to be valid, it must meet the quorum of 25% (1/4) of all Committee members, and a minimum of 3 Council members.\n● If this quorum is not met, the General Meeting is deemed invalid, and the Council must schedule a new one.\n\n1.1.3. Meeting Procedure\n\n● General Meetings can be conducted using any online meeting tool.\n● All members of the Committee must be notified via email at least 15 days before the scheduled date of the meeting.\n● The International Head leads the General Meetings, appointing a Secretary to take minutes.\n● The International Head also coordinates the agenda, facilitates discussions, and ensures all members have equal opportunity to participate.\n● If the International Head is unavailable, the Deputy International Head will lead the General Meeting.\n● If the Deputy International Head is unavailable, the Council will designate another Council\n\nMember to lead the General meeting and appoint a Secretary before the day of the General Meeting.\n● Meeting minutes must be shared with all Committee Members within 15 days of the Committee Meeting via Buhurt International's forum.\n\n1.2. Council Meetings 1.2.1. Definition and Organization\n● Council Meetings are gatherings of the Council members to discuss ongoing projects, evaluate or approve documents, decide on promotions to higher hierarchy ranks, issue penalties for rule violations etc.\n● The Council organizes Council meetings whenever necessary. This may occur, for example, when new documents need approval, or before or after a major tournament.\n● The Council is required to hold at least one Council Meeting per quarter.\n\n1.2.2. Quorum\n● For a Council Meeting to be valid, a minimum of 3 Committee Members must be present.\n\n1.2.3. Meeting Procedure\n● Council Meetings can be conducted using any online meeting platform.\n● All Council Members must be invited via email or other written communication at least 7 days before the scheduled date of the meeting.\n● The International Head leads the Council Meetings, appointing a Secretary to take minutes.\n● The International Head also coordinates the agenda, facilitates discussions, and ensures all members have equal opportunity to participate.\n● If the International Head is unavailable, the Deputy International Head will lead the General Meeting.\n● If the Deputy International Head is unavailable, the Council will designate another Council Member to lead the General meeting and appoint a Secretary before the day of the General Meeting.\n● Meeting minutes must be shared with all Committee Members within 15 days of the Committee Meeting via Buhurt International's forum.\n\n2. Voting System\n● The decision-making process based on voting ensures that every member within the Committee has the opportunity to express their opinion and contribute to decisions.\n● Voting enables a democratic approach where each member's input is taken into account, fostering a sense of inclusivity and shared responsibility. This approach helps ensure that all voices are heard, promoting transparency and collective ownership in the committee's operations.\n● During a vote, each Committee member is granted with 1 vote. The vote have a different weight depending on the rank of the Committee member:\n\n| Rank | Weight |\n| --- | --- |\n| International | 2 |\n| Conference | 2 |\n| National | 1 |\n| Trainees | 1 |\n\n● All decisions require a simple majority to pass (50% plus 1).\n● In the event of a tie, the \"vote of Minerva\" is applied: the member designated to lead the meeting, whether it is the International Head, Deputy International Head or a Council member, have a vote weighting +1 to sort the tie.\n● Assigning different vote weights is intended to prioritize the experience and expertise of the members in the decision-making process.\n● Each vote is personal and cannot be transferred or delegated to another Committee member.","page_from":2,"page_to":5,"stable_key":"committees-decision-process:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"472dfb30d2f9dca38f9a61e9394b8c91db85c5aa80ca65086a189c9773290f67","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"note","number":"3","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nUpdate date: December-2024 -add Document has been created","page_from":6,"page_to":6,"stable_key":"committees-decision-process:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"f12e3046e6d75c5ee5bb73a8f86906178531acb9f8fa6d8d62294cbefcf16678","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"executive/committees-internal-regulations","synthetic":false,"version":{"version":"December 2024","title":"Committees Internal Regulations","published_on":null,"effective_from":null,"note":"The document prints no version number. Its changelog has one entry, \"Update date: December-2024 / Document created\"; the label is that date.","source_url":"https://www.buhurtinternational.com/_files/ugd/d219c5_08fcf19112fc416992b0b429ba714b84.pdf","source_sha256":"07950f0881d64ef1f16c23bac5affda70931ad7b03f22a8e67cc12174c6709ab","retrieved_at":"2026-10-06T00:00:00Z","page_count":6,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"2a4053b1494fe128ce7648c7a464d44ffd3b6d6d2f2c76e9f7b2d7c18aa6a3e3","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":6,"source_lines":125,"assigned_lines":140,"furniture_lines":28,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.9958,"provisions":21,"numbered":20,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"committees-internal-regulations:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"Committees Internal Regulations","body":"This document outlines the internal regulations of Buhurt International Committees. It specifies the rules that must be followed by all members of the Committees, regardless of their rank, title, status, or other distinctions.\n\nThe document also details the disciplinary sanctions applicable in case of rule violations.\n\n1.Rules All members of the Committee must comply with the following rules:","page_from":3,"page_to":3,"stable_key":"committees-internal-regulations:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"622ebac655f117f58859e3e9e69ab08803886a4cb885d83312fcdae279c781a6","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Respect","body":"Committee members must be polite, respectful, and non-confrontational in all communications with third parties.","page_from":3,"page_to":3,"stable_key":"committees-internal-regulations:1.1","parent_key":"committees-internal-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8baac6897947856fb4616118add924338588d7147b603e956ebb8082cc05eb29","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Third parties","body":"include fighters, team captains, members of Buhurt International Committees, audience, hosts, sponsors, media etc.","page_from":3,"page_to":3,"stable_key":"committees-internal-regulations:1.2","parent_key":"committees-internal-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1b055c9a3497281916e1cb97bbb51b49eaa387ed2af2e2f1b42c6377babfa33d","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Impartiality","body":"Committee members must remain impartial and avoid bias toward any fighter or team.","page_from":3,"page_to":3,"stable_key":"committees-internal-regulations:1.3","parent_key":"committees-internal-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fa516a6743bbdd508fcc347ba63b8c7ef6e9c70053b190d3d0f0e6b4835bfce4","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.4","title":"Conflict of Interest","body":"Members of the Committee are prohibited from using their status, rank, title or other distinction within Buhurt International to benefit their business or any of their relative’s business (club, family, friends etc.)","page_from":3,"page_to":3,"stable_key":"committees-internal-regulations:1.4","parent_key":"committees-internal-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ad70085600260d4c4ce23b9d13fdc5e50ec6551946727db89168cda2ca3e5ff1","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.5","title":"Knowledge","body":"All committee members must be familiar with their rules and stay updated on any changes.\nEvery committee member involved in armors, shields and weapons inspections must adhere to the rules as written and evaluate items according to the committee's established methods.\nAll committee members must follow the general rules of Buhurt International.","page_from":3,"page_to":3,"stable_key":"committees-internal-regulations:1.5","parent_key":"committees-internal-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f13e6643c486a9cde077150c3d068a27cd11d146f86a19a4c65492dfbbe94d82","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"section","number":"2","title":"Disciplinary Sanctions","body":"The committees are responsible for enforcing discipline and ensuring compliance with the regulations.\nIf a committee member breaks a rule outlined above, the Judiciary committee will issue a sanction.\nAn official complaint has to be sent to the Board of Directors of Buhurt International. This has to be sent by email: info@buhurtinternational.com.","page_from":4,"page_to":4,"stable_key":"committees-internal-regulations:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ea4af6be4ce69cd45bba11b1e6db18b665545bd6a161537e489a67c40a89b9ba","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.1","title":"Infraction Classification","body":"","page_from":4,"page_to":4,"stable_key":"committees-internal-regulations:2.1","parent_key":"committees-internal-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"167e15c5600745d276448327b67b0594b93922cc96779df42c71720fdca67035","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"2.1.1","title":"Minor Issue","body":"A minor issue is a violation of a rule that does not cause damage to the reputation of a Committee or Buhurt International.\nIt's an issue that isn't severe enough to warrant suspension or removal. However, the Committee member must understand that it is significant enough to justify a sanction.\nExamples:\n●Disrespectful public behavior (including online). I.e: being impolite with third party, ●Inadequate knowledge of the rules during a tournament or any Buhurt International event, ●Misapplication of rules.","page_from":4,"page_to":4,"stable_key":"committees-internal-regulations:2.1.1","parent_key":"committees-internal-regulations:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f344a992838dc1deab428ef004e5b6a4580a0ffe244594b2dd22ae8954d2fef9","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":2,"kind":"rule","number":"2.1.2","title":"Serious Issue","body":"● A serious issue is a rule violation that damages the reputation of the Committee or Buhurt International. However, this does not necessarily mean that the Committee member can no longer collaborate with the organization.\n● It's an issue severe enough to erode the Council's confidence in the Authenticity Committee member. A three-month suspension is intended to indicate that this behavior is not compliant with the Authenticity Committee's rules.\nExamples of serious issues:\n●Extremely inappropriate public behavior (including online). I.e: insulting a third party, ●Showing bias during armor and weapons checks at a Buhurt International tournament or event, ●Multiple misapplications of rules during more than one event.","page_from":4,"page_to":4,"stable_key":"committees-internal-regulations:2.1.2","parent_key":"committees-internal-regulations:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7f1d4c8e4eb71440fcf6c0fba81dc6a00d377521751aeb14807133a157400107","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":2,"kind":"rule","number":"2.1.3","title":"Major Issue","body":"A major issue is a rule violation that severely damages the reputation of the Committee or Buhurt International. This level of breach indicates that it is no longer possible to continue collaborating with the Committee member.\nIt’s an issue severe enough to warrant ending the collaboration, as it signifies a compromise to the integrity of the Committee, making further cooperation impossible.\nExamples of major issues :\n●Unacceptable public behavior. I.e: aggressing a third party, ●Multiple sanctions for minor and serious issues.","page_from":4,"page_to":4,"stable_key":"committees-internal-regulations:2.1.3","parent_key":"committees-internal-regulations:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8d0a712411eb92319083356a6df1e12eaaf74f98582ab73d69edbaefffbebb71","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"2.2","title":"Sanctions","body":"","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.2","parent_key":"committees-internal-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"279618ef4a2f2a4e7bedfa900eef161bdaf4ac375305cc84306d3d849b257f0b","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.2.1","title":"Warning","body":"A warning is given by the Council to a Committee member in cases of minor issues.\nIt is not recorded nor brought to the Judiciary Committee.","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.2.1","parent_key":"committees-internal-regulations:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bc5824b9d21ad7b4fcdc7f3c23fbf16f5d81eecf54a1e88a56fab482664c6198","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"2.2.2","title":"3-Month Suspension","body":"A 3-month suspension is issued by the Judiciary Committee to a committee member in cases of multiple minor issues or a serious issue.\nThe Council shall notify the Judiciary Committee with all relevant information.","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.2.2","parent_key":"committees-internal-regulations:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e21ed0fede2013acc4c2bad989f5db535535914f88333127939f2965da1302e0","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":2,"kind":"rule","number":"2.2.3","title":"Permanent Suspension","body":"Permanent suspension is issued by the Judiciary Committee to a Committee member in cases of multiple serious issues or a major issue.\nThe Council shall notify the Judiciary Committee with all relevant information.","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.2.3","parent_key":"committees-internal-regulations:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e2613d3d243021d9235253cb598116d2363398368c46fa441d42107332642036","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":2,"kind":"rule","number":"2.2.4","title":"Other actions","body":"In addition to the previous sanction, the Council is allowed to oblige the Committee member to improve himself/herself, through mandatory online course, specific trainings etc.","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.2.4","parent_key":"committees-internal-regulations:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8989d44e57c8b49424b93c82e27d6e4a2e69b34967cf69389df2b0c148bccbda","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"2.3","title":"Sanctions Protocol","body":"","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.3","parent_key":"committees-internal-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"393f34f465ca1f4e2d30a49cfcdb4eaa5eb36d870f117c52c3887fc8842a5d59","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":2,"kind":"rule","number":"2.3.1","title":"Council evaluation","body":"The Council determines the various issues that require discussion during Council meetings.\nSanctions to be brought to the Judiciary Committee are decided through a vote in a Council meeting. The Committee member subject to the sanction will be notified via email of this decision.\nThe result of the vote, along with any relevant details, must be documented in the minutes of the Council meeting.","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.3.1","parent_key":"committees-internal-regulations:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f29f0f4008de0403ce7884b4126eb4fda3a932e3f206a8d93a756ef8263b18ba","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":2,"kind":"rule","number":"2.3.2","title":"Judiciary Committee evaluation","body":"The Judiciary committee will evaluate the sanction through its own process:\nPlease reference “ Judiciary Committee” document All sanctions given by the Judiciary Committee will be documented.","page_from":5,"page_to":5,"stable_key":"committees-internal-regulations:2.3.2","parent_key":"committees-internal-regulations:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"531fd57cf4e5378c7bb3d2bec58b1539ff9f07ff6291dc908091c8487a84db31","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":2,"kind":"rule","number":"2.3.3","title":"Appeals","body":"If a Committee member believes that a sanction is unjustified, he/she can form an appeal to the Judiciary Committee as stated in their process.\n\n2. Change log This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nUpdate date: December-2024 -add Document created","page_from":5,"page_to":6,"stable_key":"committees-internal-regulations:2.3.3","parent_key":"committees-internal-regulations:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1adc1fd89de249dd93035847803bd133f2cae85b6ed6c136858238ac44019f5a","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"executive/gender-policies","synthetic":false,"version":{"version":"2024.03","title":"Gender policies V2024.06","published_on":null,"effective_from":null,"note":"Changelog: latest entry \"March 2024 (Version update from 2024.01 to 2024.03)\". The file name used for the source drop says \"V2024.06\", which the document itself does not support.","source_url":"https://www.buhurtinternational.com/_files/ugd/d219c5_cd29c29d07894734abfd546ea3665066.pdf","source_sha256":"45b9925e034112526679516c1cba57525c48b267ab41ae2a3a7d60ef2a85b1bc","retrieved_at":"2026-10-06T00:00:00Z","page_count":4,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"ff961a2d09d3de611f132570ed8445623bd8eeb072a3d32eb1948cfed5321128","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":4,"source_lines":56,"assigned_lines":67,"furniture_lines":19,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99892,"provisions":17,"numbered":15,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"gender-policies:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Tournament Eligibility and Gender Category Policy","page_from":2,"page_to":2,"stable_key":"gender-policies:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"627cf0844349c01e2a30a637b3363484ec646c8740a4ab569e7478d08b1e35e8","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Tournament Gender Categories","body":"","page_from":3,"page_to":3,"stable_key":"gender-policies:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d28923abbc1730c3d20b367e7292d045e26bd68547d19f55f762bbf9af6f5f76","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Recognized Gender Categories","body":"Buhurt International recognizes three Gender Categories for duels, outrance (profight), and buhurt (group fight). Competitors are required to choose and compete in a single gender category for the entire event. Each category will be ranked separately.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.1","parent_key":"gender-policies:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cd10c8458e5ac30216bbaa0295eff9ea08e2af1b3a14552b3916c300d7f41fd1","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Eligibility for Men’s Tournaments","body":"","page_from":3,"page_to":3,"stable_key":"gender-policies:1.2","parent_key":"gender-policies:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a92ff48224a9dd268940d656c51b02b3d118bed820ebb37678a5c143674c4ba0","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.2.1","title":"All AMAB (assigned male at birth) competitors are eligible to compete, regardless","body":"of gender identity, including cisgender males.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.2.1","parent_key":"gender-policies:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c3f808fd582aa41818f28f70bf12bd46e2a6e2da53151be05205a8d88c14eb9d","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.2.2","title":null,"body":"FTM (female to male) competitors are also eligible to compete in this category.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.2.2","parent_key":"gender-policies:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cb421de01f5a6cb4e7fca39634d86a1ad0a61e83a93bb4800588d5e86b397d13","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"1.3","title":"Eligibility for Women’s Tournaments","body":"All AFAB (assigned female at birth) competitors are eligible to compete regardless of gender identity, including cisgender women.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.3","parent_key":"gender-policies:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17f39a8b495b192911ac2a21e15b703e16bfe57ba049fde8cb8635040dee2647","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"1.4","title":"Eligibility for Women’s Open Tournaments","body":"","page_from":3,"page_to":3,"stable_key":"gender-policies:1.4","parent_key":"gender-policies:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"23f9fd0ceef82df399054599f459d627f7eccf40fcc56fb0adac3828242d8ccf","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"1.4.1","title":"All AFAB (assigned female at birth) competitors are eligible to compete","body":"regardless of gender identity, including cisgender women.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.4.1","parent_key":"gender-policies:1.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fe0b8c3052376c5e572130022d2c1fd06342f85017b3ac455b42192f17589b53","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":2,"kind":"rule","number":"1.4.2","title":"MTF (male to female) competitors are eligible to compete if they have been living","body":"as a woman for 2 years or more.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.4.2","parent_key":"gender-policies:1.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"714dc52827765b48496470b707ac02851a088efd5ae3d16fcaaaae82a54cab68","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"1.5","title":"Categories in Tournament","body":"","page_from":3,"page_to":3,"stable_key":"gender-policies:1.5","parent_key":"gender-policies:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"59cdc61895e16c31fcd578240c03eee99639b9a1cbd7da634e2a587cb6fb54a8","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":2,"kind":"rule","number":"1.5.1","title":null,"body":"All tournaments must offer both the Men’s and Women’s categories.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.5.1","parent_key":"gender-policies:1.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d8f6501b31f4c3f70df57fc883e09a73b948576e1585ac2feca133c4ecd44432","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"1.5.2","title":"A tournament may also allow duels, pro fights, or group fights in the Women’s","body":"Open category if there are sufficient competitors willing to do so. If dividing the categories results in insufficient competitors for either the Women’s or the Women’s Open category, only the Women’s category may be held.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.5.2","parent_key":"gender-policies:1.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"00cf44d32e855d6613aa0a1554c25a0e1a12983883c797cd17fc61259398e703","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"1.5.3","title":"Event Organizers must inform competitors at least one (1) month from the start","body":"date of the event if the Women's Open category will be part of the event or not.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.5.3","parent_key":"gender-policies:1.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1729ddf2012ff0f20f7480caeda3f81fcf8c7069610727e3aa541fc64f4e8c94","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"1.6","title":"Awards","body":"To issue awards for the Regional, Conference, and International stage, there must be a minimum number of five events per category in the season.","page_from":3,"page_to":3,"stable_key":"gender-policies:1.6","parent_key":"gender-policies:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17a779a321c5d25660a3808f89dd93df3d42d28901b8443dace1c1d4a48d65ff","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":0,"kind":"note","number":"2","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nMarch 2024 (Version update from 2024.01 to 2024.03)\n\nUpdate date: March-2024\n- format: new design format, document will be used from now on.","page_from":4,"page_to":4,"stable_key":"gender-policies:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"4071e4e5401854eaf504a33b66278bc052e281b6d56d837649cf6e177cbdd8b9","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
