racted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"8518972ded9af386bdd5db37cfaf135556089d1bc47e519cd2b17f142d814a27","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Introduction","body":"","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a0954a1a5e79da65227140b58f7f993f2e41e97a99df851d4acb53d83fdc9369","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Definition","body":"Judiciary Committee is a structural unit of the organization Buhurt International.","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1.1","parent_key":"judiciary-committee:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e81ed707151936c68991784589fd2e8ee93523fe0d523d4f7299cc0c52714d9d","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Objectives","body":"","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1.2","parent_key":"judiciary-committee:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3993c218e60055c874a7f9fbc1645df4642384ec9550fdab2f3e33f8d6fc29c1","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.2.1","title":"The Judiciary Committee settles sports labor disputes, Judiciary, and other","body":"disputes arising in the field of “Buhurt International” activities by considering them, resolving and motivating for voluntary execution or forcing them to execute decisions and definitions.","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1.2.1","parent_key":"judiciary-committee:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2f488b7c3b3a1e3c6175b696364d27fc37cbf6a0027a02cb261d6cff5846958b","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.2.2","title":"The Judiciary Committee approves or revises all long-term Judiciary measures","body":"applied to athletes in accordance with the Buhurt International Regulations.","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1.2.2","parent_key":"judiciary-committee:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d2ea68dd7a2dbf2c46885e435251ef8b0863479049bdcfead4a38d6ceaa90971","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":2,"kind":"rule","number":"1.2.3","title":"The Judiciary Committee approves and revises sanctions imposed on committee","body":"members.","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1.2.3","parent_key":"judiciary-committee:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f01e3406f6d3c30ce650f254b4211c4b958d0f23fd3834600f67e36877df4f28","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"1.3","title":"No interference with other committees","body":"The Judiciary Committee cannot interfere in the activities of the Authenticity, Tournament, or Marshal Committee.","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1.3","parent_key":"judiciary-committee:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5f4ae36023968dad1dcd02b69f9e840a48da8ca722d3fd871cbe28d2f530aa65","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"1.4","title":"Used regulations","body":"Regulations used by the Judiciary committee in its activities. The Judiciary Committee is guided by the Rules and Regulations of Buhurt International and any other regulatory legal acts without restrictions.","page_from":3,"page_to":3,"stable_key":"judiciary-committee:1.4","parent_key":"judiciary-committee:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1acc4678334ce4100f5da56f19122ae4bd78523010b22495efcb6154f918a650","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"2","title":"Composition of the Committee","body":"","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6758725412b78c9e0e4d837bd9999735edf3a3f99f6f8e40134aa55d21c013dd","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.1","title":"Standard composition","body":"","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2.1","parent_key":"judiciary-committee:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4ef10e67c2ff35660448b4725d609bf46a9ea73ce9a9265bca21d2b29d6b2f76","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":2,"kind":"rule","number":"2.1.1","title":null,"body":"The Judiciary Committee consists of:\n● One (1) Chairman,\n● One (1) Vice-Chairman\n● At least three (3) members suggested by the Council and approved by the President for a period of 1 year.\n● Head Marshal and Head of Tournament are automatically included in JCas two of the three.","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2.1.1","parent_key":"judiciary-committee:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d57846ced46f8cee72877fb80cfa08ac2345312e44319ab210df7a0bcd43095e","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.1.2","title":"The members of the Judiciary Committee may be individuals who have a","body":"deserved authority, positive business reputation, and a civil position, as well as possessing the necessary knowledge for a comprehensive, objective, and independent resolution of disputes related to the competence of the Judiciary Committee.","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2.1.2","parent_key":"judiciary-committee:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4c9e331574b9ad84fa84b247a29d0cdc2d712b8b663c3978c6de933ecd87d3b3","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"2.2","title":"In case of absence of the Chairman","body":"","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2.2","parent_key":"judiciary-committee:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d324381347fe9a4bd1e5c1aa164ed185a72834c5b9ea099f66f16d5b13bc04e5","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":2,"kind":"rule","number":"2.2.1","title":"In the case of the temporary absence of the Chairman of the Judiciary","body":"Committee, his duties for this period are performed by the Vice-Chairman.","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2.2.1","parent_key":"judiciary-committee:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"46be2ebc4eb58fed526688f7b659126cb6fc84cc5ac77338ec3968978a2c547f","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":2,"kind":"rule","number":"2.2.2","title":"In case of early termination of the authority of the Chairman of the Judiciary","body":"Committee, his duties are performed by the Vice-Chairman until the appointment of a new Chairman of the Judiciary Committee in the prescribed manner.","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2.2.2","parent_key":"judiciary-committee:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b5172a7bd524ba134e3a7a42c13570c6440b7510ca1a83169d71b50a71827ea0","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"2.3","title":"Resolution of a dispute","body":"Only a member of the Judiciary Committee may resolve a dispute that is accepted by the Judiciary Committee.","page_from":4,"page_to":4,"stable_key":"judiciary-committee:2.3","parent_key":"judiciary-committee:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"91524158b3f024c610e1ae7caa57bc4d19aec99b4226325ab989789f2f263485","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":0,"kind":"section","number":"3","title":"Meetings","body":"","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be2ef3e6f8f5422bd42e26d673cc17024abae0f39b506273c281df42aeef31f6","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"3.1","title":"Reasons for a meeting","body":"The reason for opening a session of the Judiciary Committee may be:","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.1","parent_key":"judiciary-committee:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1bfc4247ff4d55a450d6cf9a3824a7dce0687a66e4bde3fbf2104cc619a61020","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":2,"kind":"rule","number":"3.1.1","title":"Making an assessment of “disqualification” – about a red card to an athlete or","body":"team, a statement, or misbehavior by an athlete, club, team, or other person who is a member of Buhurt International.","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.1.1","parent_key":"judiciary-committee:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1439c07c35b5525664206541bc52b4bdf99cf6b9cda61e02689b0f219f9148f8","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":2,"kind":"rule","number":"3.1.2","title":null,"body":"Violation of the Code of Conduct by a member.\n● 3.1.3 Review of Cards issued and determining whether additional sanctions and/or restrictions may be placed upon them:\n\n○ Reduction in points based upon number of cards earned (-1 for yellow card, -3 for red card) ○ Temp 3-6 month ban on a competitor or team\n\nImportant:\nPermanent bans will be taken to the Board and then NO for review and then voted on.","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.1.2","parent_key":"judiciary-committee:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ff0e96ad562b11bbcb8550398010da3fdfedfcc242010e5e2d59842353936daa","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"3.2","title":"Applications for reviews","body":"Applications for specific reviews are to be submitted in writing to the Buhurt International President with a request to consider the application at the next available session of the Judiciary Committee. The application must contain the full contact details of the applicant and the statement of the matter on the merits. The burden of providing evidence for the consideration of the application rests entirely with the applicant.","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.2","parent_key":"judiciary-committee:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1f095e7bb1d05e60ef4231ee626c00b7dee2f5727f5c371331cbda900ac78622","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"3.3","title":"Legitimacy","body":"","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.3","parent_key":"judiciary-committee:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9b266053bb058e72002086fd4365461a51f8ee932bbbaeb6ff842842ab1be86a","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":2,"kind":"rule","number":"3.3.1","title":"A session of the Judiciary Committee is considered to be legitimate in the","body":"presence of all members/or alternates of the Committee..","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.3.1","parent_key":"judiciary-committee:3.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"911ec3ef118f51d5fb11f91068a26d5a3ede2c3d75744720a9b21ec5b83268b3","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":2,"kind":"rule","number":"3.3.2","title":"If there is no possibility of a face-to-face meeting in a timely manner, it is possible","body":"to hold an online session of the Judiciary Committee using remote communication tools.","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.3.2","parent_key":"judiciary-committee:3.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"af1b8a03f7696c5ad11d6ba73dc2dcd48b1be4684515e006c3be7d3c96d5bf4a","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":2,"kind":"rule","number":"3.3.3","title":null,"body":"In case of emergency, a meeting of the Judiciary Committee may be incomplete.\nIn this case, special coordination with the Buhurt International President and Council is required.","page_from":5,"page_to":5,"stable_key":"judiciary-committee:3.3.3","parent_key":"judiciary-committee:3.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2e820c8f29a680e0de946900d9e35290481d4896645b14d7097923856a64abb1","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"3.4","title":"Deadlines for processing","body":"● 3.4.1 For “red cards” – no more than 14 calendar days from the date of reporting of the competition.\n● 3.4.2 For the applications – no more than 30 calendar days from the date of the application.","page_from":6,"page_to":6,"stable_key":"judiciary-committee:3.4","parent_key":"judiciary-committee:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"db5fd027624411eb003bf45347ff8252788aa580736d1de2426a03ecea34bbd7","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"3.5","title":"Proceedings","body":"● Meetings (sessions) of the Judiciary Committee are held behind closed doors.\n● At the time of the meeting, a secretary is elected from among the members of the Judiciary Committee. The secretary takes minutes of the meeting and prepares a final decision of the Judiciary Committee.\n● The Judiciary Committee makes a decision by a simple majority of votes. In the event that a simple majority of votes cannot be determined, (equal number of votes for each decision) the vote of the Chairman of the Judiciary Committee is decisive.\n● If the Judiciary Committee convenes a hearing relating to the red card or ban of a person and/or team for which a Judiciary Committee member is of the same country, the Judiciary Committee member will be consulted on their opinion of the facts of the matter, but must abstain from voting to ensure no conflict of interest on the outcome.\n● A short summary of the hearing and the outcome detailing the parties involved and the nature of the circumstances can be made public through official channels. The Committee reserves the right not to publish details in exceptional circumstances.","page_from":6,"page_to":6,"stable_key":"judiciary-committee:3.5","parent_key":"judiciary-committee:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ac0c1f3320dded37990d596f530d754a847be5327fbb0d8a4753f3c9b4908366","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":0,"kind":"section","number":"4","title":"Appeal protocol","body":"","page_from":7,"page_to":7,"stable_key":"judiciary-committee:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"65255353fa72b0dfc6299e1bbe1ade08890e1a32a24f4290464938a22b7fa6fd","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":1,"kind":"rule","number":"4.1","title":"Make sure you fully understand the nature of the sanction imposed. Review any","body":"relevant documentation such as emails or notifications that explain the reasons for the sanction and the available appeal terms. Any relevant evidence that supports your appeal must be shown, like screenshots, emails, videos, or any other documentation showing that the penalty was unfair or incorrect.","page_from":7,"page_to":7,"stable_key":"judiciary-committee:4.1","parent_key":"judiciary-committee:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d5706ffacb0791cafa1726fc5c63064eda1a71bc491e64a50ebf958c1ba6dd1a","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"4.2","title":"Write an email formally to the Judiciary Committee (J.C.) Clearly describe why you","body":"believe the sanction should be reviewed or revoked. Add the evidence with a good timeline of events, references, and a detailed explanation of your reasoning.","page_from":7,"page_to":7,"stable_key":"judiciary-committee:4.2","parent_key":"judiciary-committee:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ca2d587a0df527ec1a209fd4d30b0705e06104dd0c969ac8edc4db04a1f2f4cf","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"4.3","title":"Stay available for any additional communications You may be asked for more","body":"information or a meeting to discuss the matter in detail.","page_from":7,"page_to":7,"stable_key":"judiciary-committee:4.3","parent_key":"judiciary-committee:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7bb7a0f12d0acf73b41d34a38e09c9f50c95db3f7da556369a62f02fce978621","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"4.4","title":"The Judiciary Committee (J.C.) will take no more than a month to review your appeal","body":"and make a decision. The outcomes could be:\n\n● Keep the penalty.\n● Revoke the penalty.\n● Increase the penalty.\n● Reduce the penalty.\n\nRespect the results, even if they are not what you wanted.","page_from":7,"page_to":7,"stable_key":"judiciary-committee:4.4","parent_key":"judiciary-committee:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6b52674ee6d79f6856c99ffa4307a9a4fec7197925c2e9733bccee0e1018bb9b","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":0,"kind":"note","number":"5","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nMarch 2024 (Version update from 2024.03 to 2024.06)\n\nUpdate date: June-2024 (V2024.06)\n- add: 4. Appeal protocol Update date: March-2024\n- format: new design format, document will be used from now on.","page_from":8,"page_to":8,"stable_key":"judiciary-committee:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"fdd8adf686bb3c034078a7baa78658115ae986bd90058eebe9cd0ffe536819b1","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
