ures":false,"extraction":"text"},{"ordinal":31,"depth":2,"kind":"rule","number":"4.2.1","title":null,"body":"Non-Compliance: Failure to adhere to the outlined requirements and guidelines.","page_from":5,"page_to":5,"stable_key":"no-agreement:4.2.1","parent_key":"no-agreement:4.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"833e76a87879d7a7f059aa78ba50befb96a4a4dca9675a3308bcdc47492f83f8","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":2,"kind":"rule","number":"4.2.2","title":"Misconduct: Engagement in discriminatory practices, unfair membership","body":"rejections, or unethical behavior.","page_from":5,"page_to":5,"stable_key":"no-agreement:4.2.2","parent_key":"no-agreement:4.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"aa487aa0c44967311f5fc73a134927f32294023c06e0dfe16eb4b51338c19754","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":2,"kind":"rule","number":"4.2.3","title":"Failure to communicate: Inability or unwillingness to maintain proper","body":"communication channels with BI","page_from":5,"page_to":5,"stable_key":"no-agreement:4.2.3","parent_key":"no-agreement:4.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2772e36ad8f7494e8843a6e590f2b4c5677dbe9180c436c47a535c237e9864a6","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"4.3","title":null,"body":"Due Process:","page_from":5,"page_to":5,"stable_key":"no-agreement:4.3","parent_key":"no-agreement:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"57909b975c34461ad4b87b7f5dd0a2944d3f5b9dc322f3847c47ac962d51612b","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":2,"kind":"rule","number":"4.3.1","title":null,"body":"Prior Notification: BI will provide written notification outlining specific issues, allowing the NO an opportunity to rectify the situation.","page_from":5,"page_to":5,"stable_key":"no-agreement:4.3.1","parent_key":"no-agreement:4.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9b19daa025190844321c635fe6f6fa916cb25ab853db46b9f2879afe73c8658e","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":2,"kind":"rule","number":"4.3.2","title":"Review and Appeal: The NO will have the right to present their case before a fair","body":"and thorough review by BI.","page_from":5,"page_to":5,"stable_key":"no-agreement:4.3.2","parent_key":"no-agreement:4.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6e0b581c7b06aab57bc8a0fb167df200d37710c392206b78260c95aae3514d51","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":2,"kind":"rule","number":"4.3.3","title":"Referendum: There will be a vote amongst all other NO on the removal based","body":"upon arguments provided by BI and defence provided by the NO. An absolute majority will result in removal of the NO.","page_from":5,"page_to":5,"stable_key":"no-agreement:4.3.3","parent_key":"no-agreement:4.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1eec00a575f9ee2bd9f4b1430715c08d1e1c921acfb0f37911939bde2e0dfb26","has_figures":false,"extraction":"text"},{"ordinal":38,"depth":2,"kind":"rule","number":"4.3.4","title":"Decision: NO will be communicated in writing, along with the reasons, and will","body":"be final and effective immediately.","page_from":5,"page_to":5,"stable_key":"no-agreement:4.3.4","parent_key":"no-agreement:4.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"98dff7044b4cc5fa3f9ff752bcddc1b42786c452e35179928085cc9f43c4d671","has_figures":false,"extraction":"text"},{"ordinal":39,"depth":1,"kind":"rule","number":"4.4","title":null,"bo