_from":2,"page_to":2,"stable_key":"jobs-titles-uniforms-accreditations:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"27b9241dc9bf21a39672270a0b3c3ed6d177b6bb155e4de0736793e0fda3c96b","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Marshall Jobs","body":"","page_from":3,"page_to":3,"stable_key":"jobs-titles-uniforms-accreditations:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"599ac7a30d12205f4304cf1829afa8203901854a3fa0060f280833549c98b20a","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Knight Marshal","body":"● The knight marshal is in charge at a tournament, both inside and outside the list.\n● There may be more than one Knight Marshal for tournaments like Conference or World Cup.\n● A trainee marshal cannot be a Knight Marshal unless it is necessary.","page_from":3,"page_to":3,"stable_key":"jobs-titles-uniforms-accreditations:1.1","parent_key":"jobs-titles-uniforms-accreditations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1bdf63a344d20cc40b541929190c622cc8a4fa2c567a44fd64efde275c36ea6a","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Field Marshal","body":"● The marshal inside the list in Buhurt.\n● A trainee marshal cannot be a field marshal unless it is necessary.","page_from":3,"page_to":3,"stable_key":"jobs-titles-uniforms-accreditations:1.2","parent_key":"jobs-titles-uniforms-accreditations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"99aef28e316d66cc7d1ea874e5154288dadd4f34ba4a9424988253d92875b90b","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.3","title":"Lines Marshal","body":"● The marshal outside the list in Buhurt.\n● Acting as counters for Duels, and outrance,","page_from":3,"page_to":3,"stable_key":"jobs-titles-uniforms-accreditations:1.3","parent_key":"jobs-titles-uniforms-accreditations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e1ac6d4230e7afa5f31d467a00c8983747a7f734c5b2e38fc917c1f330955615","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"section","number":"2","title":"Accreditation Reference Accreditation","body":"document","page_from":4,"page_to":4,"stable_key":"jobs-titles-uniforms-accreditations:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"31c4bd1706248c5f8ddae3f81049391d26ba69642f7bdacee0c2f744473860af","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.1","title":"Trainee - Level 4","body":"A Trainee Marshal is the first step toward achieving international accreditation as a marshal.\nFor further details, please refer to the Marshal Accreditation document.","page_from":4,"page_to":4,"stable_key":"jobs-titles-uniforms-accreditations:2.1","parent_key":"jobs-titles-uniforms-accreditations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3e89cf830e299f0a4433e4546d21e44cf211d4509a74475de5bdc860ea4fe970","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.2","title":"Regional - Level 3","body":"A Regional Marshal is an individual who has gained experience working at multiple events, successfully passed the Trainee test, and is now qualified to marshal inside the list.","page_from":4,"page_to":4,"stable_key":"jobs-titles-uniforms-accreditations:2.2","parent_key":"jobs-titles-uniforms-accreditations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"38b8668b035a4768f6653bcf7989b6a6508f415857a9d6e3a739615beebd3831","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.3","title":"Conference - Level 2","body":"A Conference Marshal is an individual with extensive knowledge of the rules and has worked at various events. They have completed their exam, Interview and are on track for International accreditation.","page_from":4,"page_to":4,"stable_key":"jobs-titles-uniforms-accreditations:2.3","parent_key":"jobs-titles-uniforms-accreditations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a1a31851a2e3c1e2c19ab505b5e0d51f1dcab16dff8a5b2e300c7ff776c2b9e7","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.4","title":"International - Level 1","body":"An International Marshal is the final level of accreditation, achieved by individuals with extensive experience in high-level events and demonstrating exceptional skills and knowledge.","page_from":4,"page_to":4,"stable_key":"jobs-titles-uniforms-accreditations:2.4","parent_key":"jobs-titles-uniforms-accreditations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0c2728f3c3047e3816317ee19317df7d502d3d1e7b2b5f50d97311d95028254b","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":0,"kind":"section","number":"3","title":"Marshal Titles","body":"","page_from":5,"page_to":5,"stable_key":"jobs-titles-uniforms-accreditations:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0aceca73a9f9c894449aba9d5d52c95f981082074d45a2891ad76645688e3adf","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.1","title":"Buhurt International Head Marshal","body":"● Organizer Marshal for the world.\n● Will be selected from one of the Conference Head Marshals.","page_from":5,"page_to":5,"stable_key":"jobs-titles-uniforms-accreditations:3.1","parent_key":"jobs-titles-uniforms-accreditations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3c2aa0e3e64247c8951245f1ed70d1d2c096454ae4dc2d0a72a3568ae3259803","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.2","title":"Conference Head Marshal","body":"● Organizer Marshal for Conference.\n● Will be selected from one of the Regional Head Marshals in that Conference.","page_from":5,"page_to":5,"stable_key":"jobs-titles-uniforms-accreditations:3.2","parent_key":"jobs-titles-uniforms-accreditations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f028fd073ec4c2a4f03e2e50b421c8cb51c84fca315de2642bbce3dde7ffdede","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.3","title":"Buhurt International Advisor","body":"● Special nomination for Highly Experienced Marshals that do not hold another title.\n● They advise the Buhurt International Head Marshal.\n● This position will be selected by the Buhurt International Committee.","page_from":5,"page_to":5,"stable_key":"jobs-titles-uniforms-accreditations:3.3","parent_key":"jobs-titles-uniforms-accreditations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9c1daf597e4826b1b28f96b5bb2292df29b5d7e163137e5140c57d10a7198a08","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"3.4","title":"Deputy Conference Head Marshal","body":"● Deputy Organizer Marshal for Conference.\n● Will be selected from one of the Regional Head Marshals in that Conference.","page_from":5,"page_to":5,"stable_key":"jobs-titles-uniforms-accreditations:3.4","parent_key":"jobs-titles-uniforms-accreditations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"65a6b8a79da170239685dc6dd305c872fb18202d8759612999a8642a27c05c1f","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"3.5","title":"Regional Head Marshal","body":"● Organizer Marshal for Region.\nExample: UK Head Marshal. France Head Marshal.","page_from":5,"page_to":5,"stable_key":"jobs-titles-uniforms-accreditations:3.5","parent_key":"jobs-titles-uniforms-accreditations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2f401d86de3b7d4d955fe9e132c2f732ea3f6ccc439661866509b8c29fcf50a1","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"3.6","title":"Senior International Marshal","body":"● International marshals that are a very high level but are not regional heads or committee members.\n● The Buhurt International marshal committee will give this title to a marshal.","page_from":5,"page_to":5,"stable_key":"jobs-titles-uniforms-accreditations:3.6","parent_key":"jobs-titles-uniforms-accreditations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"12d37889b2173643283aca884df9196584e0072b78419637de0d616196c15a0d","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":0,"kind":"section","number":"4","title":"Buhurt International Marshall Committee","body":"The following are all a part of the Buhurt International Marshal Committee.","page_from":6,"page_to":6,"stable_key":"jobs-titles-uniforms-accreditations:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2e74e031045ee6f2b0f7890aa3231216564f3e00170c74486fd884246cfe97d4","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"4.1","title":"Buhurt International Head Marshal","body":"● Description can be found in 2.1","page_from":6,"page_to":6,"stable_key":"jobs-titles-uniforms-accreditations:4.1","parent_key":"jobs-titles-uniforms-accreditations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2.1"],"content_sha256":"8788a6b9db0853963c6d2bf9202eb0d81294371ee5a5e2ac6014c7d31f741e74","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"4.2","title":"Buhurt International Advisor","body":"● Description can be found in 2.3","page_from":6,"page_to":6,"stable_key":"jobs-titles-uniforms-accreditations:4.2","parent_key":"jobs-titles-uniforms-accreditations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2.3"],"content_sha256":"61f55a73c916dd14680a437443d62737eb363469216ffe1e7be240f9dffd3c45","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"4.3","title":"Conference Head Marshal","body":"● Description can be found in 2.2","page_from":6,"page_to":6,"stable_key":"jobs-titles-uniforms-accreditations:4.3","parent_key":"jobs-titles-uniforms-accreditations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2.2"],"content_sha256":"4f4e254e39660d06dd55220077545b0d63cf336dc8b629969a732609cada48a0","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"4.4","title":"Conference Deputy Head Marshal","body":"● Description can be found in 2.4","page_from":6,"page_to":6,"stable_key":"jobs-titles-uniforms-accreditations:4.4","parent_key":"jobs-titles-uniforms-accreditations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2.4"],"content_sha256":"68e1c19ecccc3581236137116e9e0d7bfaabb3a113d77f482ea2f13cbfc134bd","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":0,"kind":"section","number":"5","title":"Marshal uniforms","body":"This section displays all the rules and regulations about uniforms for marshals.","page_from":7,"page_to":7,"stable_key":"jobs-titles-uniforms-accreditations:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8105cd8a73bede2187e08b2438e146bb1853e6b6cfadfbe8a65e498ec38e097b","has_figures":true,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"5.1","title":"Knight marshal","body":"● Knight Marshals wear 14th to 16th century period clothes that are yellow and black striped.","page_from":7,"page_to":7,"stable_key":"jobs-titles-uniforms-accreditations:5.1","parent_key":"jobs-titles-uniforms-accreditations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"41787b48dae27b0f5543aad67fef47d559f751200d158d1f767fa44672d69d83","has_figures":true,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"5.2","title":"Field marshal and line marshal","body":"● All accredited marshals who are not Knight Marshals at a tournament wear 14th to 16th century period clothes that are yellow.","page_from":7,"page_to":7,"stable_key":"jobs-titles-uniforms-accreditations:5.2","parent_key":"jobs-titles-uniforms-accreditations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"407a9c1a6cb16f6d29a3a0f409369c2f65af1cf5967568d8ec32416b5678ea5a","has_figures":true,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"5.3","title":"Trainee marshal","body":"● Trainee Marshals wear 14th to 16th century period clothes that are not yellow, with a yellow hood.","page_from":7,"page_to":7,"stable_key":"jobs-titles-uniforms-accreditations:5.3","parent_key":"jobs-titles-uniforms-accreditations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"14c04c27fc64a2f8e72fb1cd487be439e3924c396fb4cf49495d49f367b7b217","has_figures":true,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"5.4","title":"Modern events","body":"● Marshals are allowed to wear a yellow shirt at modern events. Appropriate pants and shoes must be worn.","page_from":7,"page_to":7,"stable_key":"jobs-titles-uniforms-accreditations:5.4","parent_key":"jobs-titles-uniforms-accreditations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8d099e1852258f1c91e83eb2c2b9cde8668edbcabfb981996d8bc1a417fee35c","has_figures":true,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"5.5","title":"Suggestions","body":"Knight Marshal   Marshal   Trainee","page_from":7,"page_to":7,"stable_key":"jobs-titles-uniforms-accreditations:5.5","parent_key":"jobs-titles-uniforms-accreditations:5","review_status":"verified","review_note":"Not a table: the captions \"Knight Marshal\", \"Marshal\" and \"Trainee\" above three photos of suggested uniforms.","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2cd1aa3f125021ca55c86698a528284db19fef30e99d24422e9b15a90af2b220","has_figures":true,"extraction":"text"},{"ordinal":30,"depth":0,"kind":"section","number":"6","title":"Belt flags","body":"Buhurt International Head Marshal (COMMITTEE)\n\nConference Head Marshal and Advisor Marshal (COMMITTEE)\n\nDeputy Conference Head Marshal (COMMITTEE)\n\nRegional Head Marshal\n\nSenior International Marshal\n\nInternational Marshal - Level 1\n\nConference Marshal - Level 2\n\nRegional and Trainee - Level 3 and 4 NO FLAG","page_from":8,"page_to":8,"stable_key":"jobs-titles-uniforms-accreditations:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9fb4eb80de0a006d620f6ac1606385da7deea7ff8ce25e113a41eb09d2fc2030","has_figures":true,"extraction":"text"},{"ordinal":31,"depth":0,"kind":"note","number":"7","title":"Change log","body":"This will be the change log of this document. It will be updated regularly, displaying what has been removed, added, reworded, or formatted to maintain transparent communication and clarity about the rules.\nFebruary 2025 (Version update from 2024.12 to 2025.02)\n- Add: Levels 1,2,3,4 throughout the document.\n- format: overall grammar and formatting corrections.\nDecember 2024 (Version update from 2024.06 to 2024.12)\n- Add: Accreditation Reference Accreditation document March 2024 (Version update from 2024.01 to 2024.06)\n- format: new design format, document will be used from now on.","page_from":9,"page_to":9,"stable_key":"jobs-titles-uniforms-accreditations:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"86b80e95718028e8d418f9b4960643a3984b314b2738c0ceb1ef4d5e26952809","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"marshal/outrance-rules","synthetic":false,"version":{"version":"26.4","title":"Outrance Rules and Regulations 26.4","published_on":null,"effective_from":null,"note":"Cover \"VER. 26.4\" and every page footer \"V. 26.4\".","source_url":"https://drive.google.com/file/d/1nRkVgelFzD3Vrk4EGXIAvZaCzWYniqQz/view?usp=drive_link","source_sha256":"a55222b0f7dacc00ddced85d23ebcb85aadbd134007630ac6a1a422cfb8fff7b","retrieved_at":"2026-10-06T00:00:00Z","page_count":28,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 2 page(s) without a text layer","content_sha256":"457bd9909ba34a9a4e20e9e36d0e4cfafc696fd90bd6455818935282a7dfac6d","detected":{"version":"26.4","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":28,"source_lines":716,"assigned_lines":965,"furniture_lines":64,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99551,"provisions":139,"numbered":138,"needs_review":0,"verified":1,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":34,"picture_text_lines":18,"ocr_corrections":4}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"VER. 26.4\n\nRules and Regulations","page_from":1,"page_to":1,"stable_key":"outrance-rules:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"35a2cbb9dc8b412bfbf87cff0df9f26bd8684eb9c16f55879c0214a4bdf69212","has_figures":true,"extraction":"ocr"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"General Provisions","body":"","page_from":3,"page_to":3,"stable_key":"outrance-rules:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d3460a1bce22168eb4fc581713c7f54838f7f6aa5be599e1b9b2b4e8ddc14938","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Types of fights","body":"Outrance fights may be held in two ways:\n● Matched fights: one single fight between 2 competitors.\n● Tournament: a series of fights between multiple competitors.","page_from":3,"page_to":3,"stable_key":"outrance-rules:1.1","parent_key":"outrance-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"15f1ec634d6426f63190aad271fbf04269a1bf53a1c68b65466ac282dd262c2c","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Weight categories","body":"Outrance fights are held in different categories based on the weight of participants.","page_from":3,"page_to":3,"stable_key":"outrance-rules:1.2","parent_key":"outrance-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"faaa29fe71d03af042f4159c017440d99b0c0dd5c7053538f653b20731cb1896","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":2,"kind":"rule","number":"1.2.1","title":"For men","body":"● Lightweight: Up to a maximum of 75 kg.\n● Middleweight: Over 75 kg up to a maximum of 85 kg.\n● Light Heavyweight: Over 85 kg up to a maximum of 95 kg.\n● Heavyweight: Over 95 kg up to a maximum of 105 kg.\n● Super Heavyweight: Over 105 kg up to a maximum of 115 kg.\n● Ultra Heavyweight: Over 115 kg.","page_from":3,"page_to":3,"stable_key":"outrance-rules:1.2.1","parent_key":"outrance-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c5f764a10c7ca5d1f00613cba1cf278887e7050baff5694fba117c09142b8a50","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.2.2","title":"For women","body":"● Featherweight: Up to a maximum of 60 kg.\n● Lightweight: Over 60 kg up to a maximum of 70 kg.\n● Middleweight: Over 70 kg up to a maximum of 80 kg.\n● Light Heavyweight: over 80 kg up to a maximum of 90 kg.\n● Heavyweight: over 90 kg.\n\n|  | Men | Women |\n| --- | --- | --- |\n| Featherweight |  | < 60 kg |\n| Lightweight | < 75 kg | 60 - 70 kg |\n| Middleweight | 75 - 85 kg | 70 - 80 kg |\n| Light Heavyweight | 85 - 95 kg | 80 - 90 kg |\n| Heavyweight | 95 -105 kg | > 90 kg |\n| Super Heavyweight | 105 -115 kg |  |\n| Ultra Heavyweight | > 115 kg |  |","page_from":3,"page_to":3,"stable_key":"outrance-rules:1.2.2","parent_key":"outrance-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0d49758bcce1489231852c23b7f6c5bbcde6c9f65a18cc6d9a20ea8ddc43c76b","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.2.3","title":"Open weight category","body":"Should both participants agree, there may be a difference in the weight of competitors not based on the previously mentioned weight categories. This will not generate a Weight Modifier if agreed upon in advance.","page_from":4,"page_to":4,"stable_key":"outrance-rules:1.2.3","parent_key":"outrance-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ffb144c69ec0f6dc28bedf1c277a1eda3c1da6efb2bb9e0c19a857db71e905be","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":2,"kind":"rule","number":"1.2.4","title":"Weigh-in procedure","body":"The weigh-in may be done up to 24 before the event starts up until the day of competition to assign competitors to the proper category. If a competitor misses the weigh-in, they may have to forfeit their fight or the tournament. They may attempt a second weigh in before the competition begins.","page_from":4,"page_to":4,"stable_key":"outrance-rules:1.2.4","parent_key":"outrance-rules:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ca333911ef5662a4ab1359dfe7f8f2687bac47359426e010e7afce3044bd6ebe","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"1.3","title":"Divisions","body":"Division 1 is for more experienced competitors and will be rewarded more League points for this format (Defined as fighters with over 2 years competitive experience or fighters with demonstrable international experience).\n\nDivision 2 is for less experienced competitors, structured to be more forgiving to newcomers to the ruleset. (Defined as fighters with under 2 years competitive experience and no or minimal international competitive experience).\n\nDivision 2 fighters can elect to fight in Division 1 should they choose to.","page_from":4,"page_to":4,"stable_key":"outrance-rules:1.3","parent_key":"outrance-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2"],"content_sha256":"2a227af8349d1046b3f1bdf0364861e769c5ddbd3fcfafb64b844d5cd76806d9","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"1.4","title":"Criteria for participation","body":"","page_from":4,"page_to":4,"stable_key":"outrance-rules:1.4","parent_key":"outrance-rules:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"edd00c26c8fa62226bfbe13f60e726ef0f3a3e8a7b0ff0dda90d9b5b35edcdcc","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":2,"kind":"rule","number":"1.4.1","title":"Legal age","body":"Competitors must be of legal age according to the laws of both their country and the country in which the competition is held.","page_from":4,"page_to":4,"stable_key":"outrance-rules:1.4.1","parent_key":"outrance-rules:1.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5507f8e1e4a9801c69d3cf8c0f06f5512a804c7dcd1abb7eb76ad2705dd09475","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":2,"kind":"rule","number":"1.4.2","title":"Medical fitness","body":"Competitors must declare themselves medically fit to fight before the competition.","page_from":4,"page_to":4,"stable_key":"outrance-rules:1.4.2","parent_key":"outrance-rules:1.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"de75ce1b68b7a6e112ceef2deab16d0f98d96032c83f49aff64df00177da6bfe","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":2,"kind":"rule","number":"1.4.3","title":"Medical support","body":"Each competition should have professional medical support provided by the organizer of the event.\nIn case of an injury, members of the medical support team may decide to withdraw the injured competitor from competition.","page_from":4,"page_to":4,"stable_key":"outrance-rules:1.4.3","parent_key":"outrance-rules:1.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"07e80c2c6cb89011da06ab0170a49000008bde0aae1a72ff1bbe9f6a4765f89c","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":0,"kind":"section","number":"2","title":"Marshals Committee","body":"During an event, it is allowed to combine some of the marshals’ duties, for example the duties of the timekeeper may be combined with the secretary, and technical marshal with any other duties (knight marshal, line marshal, etc.).\nA marshals committee should consist of:","page_from":5,"page_to":5,"stable_key":"outrance-rules:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3d52902392dd5e41fb903d2744875618ad1095faece2f7cf63173ddf4c5e33f5","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"2.1","title":"One Head Marshal","body":"The head marshal:\n● is responsible for the work of the marshals committee during the competition,\n● takes the lead in the consideration by the Marshals Committee of any appeal submitted by competitors,\n● has the final say in all matters related to the consideration of said appeals, and in the interpretation of the rules,\n● Is responsible for reviewing circumstances related to competitor stoppage, cornerman stoppage and TKO stoppage,\n● Where only one knight marshal is present, they can perform the senior knight marshal duties.","page_from":5,"page_to":5,"stable_key":"outrance-rules:2.1","parent_key":"outrance-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2aec6b66d5b7ccda46e94f793c334ed15164788c2800be89f3a98519e69fff89","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"2.2","title":"One Knight Marshal","body":"The knight marshal:\n● is responsible for checking the readiness of competitors, marshals, and timekeeper before the fight,\n● gives the command to start, suspend and stop the fight,\n● controls the course of the fight by:\n○ counting time of clinches, ○ reacting to breakages of armor and weapon, losses of weapon, use of unauthorized techniques, ○ assessing knockout (KO) and technical knockout (TKO) of competitors,\n● has the right to give verbal warnings, yellow and red cards (disqualification), and to expel corner men,\n● checks the condition of the list between the rounds of a fight,\n● announces the winner according to the result of points counted by the line marshals.","page_from":5,"page_to":5,"stable_key":"outrance-rules:2.2","parent_key":"outrance-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ec1cd1b60549ff27df206b2f985492444e1d72cce15fa49c9a89202502dcf845","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"2.3","title":"Three or five Line Marshals","body":"The line marshals:\n● review objectively all the actions made by both competitors during the fight,\n● take note of loss of weapons and armor failure,\n● each keep scores independently. They are not allowed to contact other line marshals during the round and should be located on different sides of the list.","page_from":5,"page_to":5,"stable_key":"outrance-rules:2.3","parent_key":"outrance-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fe34709ca7b3ce438abb2c40766730ad129968b876d75967c2a67fee0e1ce910","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"2.4","title":"One Timekeeper","body":"The timekeeper:\n● counts down the time of each round of the fight and of each break between rounds,\n● counts down the time allotted for repairment/replacement of broken equipment,\n● announces the end of the round and the end of the break between rounds with the command ”Time” and the sound of a gong or similar device.","page_from":6,"page_to":6,"stable_key":"outrance-rules:2.4","parent_key":"outrance-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"26b6dd2b679d10d077e4587b95012b7f81eb862561ac17b56f931897d84f977d","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"2.5","title":"One Secretary","body":"The secretary:\n● records the results of each round of the fight based on points counted by the line marshals,\n● makes notes in the fight protocol. All yellow and red cards should be marked in the protocol for further calculations,\n● takes notes if any medical conditions forbids a competitor to continue fighting,\n● calls competitors to the list according to the order of the fights, in case there's no announcer/herald of the event.","page_from":6,"page_to":6,"stable_key":"outrance-rules:2.5","parent_key":"outrance-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5116564040ae7787b07ee7c20fab8127f03ab5c15c462263d554d9876da3ea78","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"2.6","title":"One Technical Marshal","body":"The technical marshal:\n● checks the safety of the offensive and defensive equipment of each competitor,\n● inspects the general appearance and historical accuracy of armor and weapon,\n● have the right to demand the replacement of a selected element of equipment if it does not meet requirements of safety, appearance, or historical accuracy,\n● checks the equipment before each fight, and after a fight if a competitor requests it.","page_from":6,"page_to":6,"stable_key":"outrance-rules:2.6","parent_key":"outrance-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9a8d72a48cf75c17dbec5ccd2787c47216bc9799d14850b77d59b587c425e57b","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"2.7","title":"One Video Supervisor","body":"The video supervisor:\n● checks and reviews all appeals given to the knight marshal,\n● discusses and makes decisions on all appeals with the knight/head marshal.","page_from":6,"page_to":6,"stable_key":"outrance-rules:2.7","parent_key":"outrance-rules:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"47c1da0c2b70e439df4ac1dca96e4924d74f70cd515832d7f34948ed54cbbefc","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":0,"kind":"section","number":"3","title":"General Commands","body":"Commands reserved for the knight marshal","page_from":7,"page_to":7,"stable_key":"outrance-rules:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5693550a80ed5c96a9c74fbc824b723828c7679886f0d4ea16bf90b0816cd275","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"3.1","title":"“Fight”","body":"Purpose: Initializes the fight at the beginning of the round or after any suspension of the fight.\nUsage: Start or resume the fight.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.1","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9e45b65ec70d9a916631eb6dccfb76a3a503ad748f0f76a61d91a2069baf09f7","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"3.2","title":"“Stop fight”","body":"Purpose: Stops the fight at the end of the round or when the fight is finished due to KO (Knockout) or TKO (Technical Knockout).\nUsage: Concludes the fight.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.2","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4a01f94ecc5ede42ef90998b0cdb723d10834e54c8969fe0f247ad152909fea4","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"3.3","title":"“Break”","body":"Purpose: Pauses the fight and separates both competitors.\nUsage: Temporarily stops the fight, creating a break between the competitors.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.3","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"924bd548f9de9c4dfaa081266e7ab56494fc6a967a647cfebf50b722a7b800ed","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"3.4","title":"“Hold”","body":"Purpose: Pauses the fight but holds competitors' positions for a re-arm of the weapon or to move both competitors to the middle of the list when needed.\nUsage: Temporarily halts the action, keeping the competitors in their current positions for specific adjustments.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.4","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"08d830c80ec51e119c6bc47a84459ef8548b23b082baf185fb40896100a81879","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"3.5","title":"“Breakdown of weapon/armor”","body":"Purpose: Announces the breakdown of part of the equipment.\nUsage: After the “Break” command has been given, indicates a specific issue with a competitor's weapon or armor that requires attention.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.5","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"41a4cfe376a7997a01b3ee393462b4407646e08d345d499030c05de71d080b6b","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"3.6","title":"“Loss of weapon”","body":"Purpose: Used when one of the competitors loses their weapon.\nUsage: After the “Hold” command has been given, indicates that a competitor has lost their weapon during the paused state.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.6","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"27798fe49e21aefc8c78c8d2e5b4660f0e63c4ef763d61056dde570c3ae88f3d","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"3.7","title":"“Knockout”","body":"Purpose: Used when one of the competitors is subject to a KO or TKO and after the “Stop fight” command has been given.\nUsage: Declares the end of the fight due to a knockout or technical knockout.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.7","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0fa9f68bd5d618e969740a3fdafe0dbf1f91d159b7998976c0de470d878df8e6","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"3.8","title":"“Time”","body":"Purpose: Announces the flow of time during the fight.\nUsage:\n● To signify the end of a round or the end of a break between rounds.\n● If there was a breakdown of equipment, and the competitor has been granted time to repair it.\n● This command keeps track of the time progression during the fight.","page_from":7,"page_to":7,"stable_key":"outrance-rules:3.8","parent_key":"outrance-rules:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ba665144d3d651cc7b513268368310c9b24a07c18a66232fc68a92c0939f92c2","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":0,"kind":"section","number":"4","title":"Fight Procedures","body":"A fight against an opponent consists of multiple rounds. The time duration of rounds and breaks and the number of rounds in a fight depends on the tournament type and Division. Below are the number of rounds and the round time durations.","page_from":8,"page_to":8,"stable_key":"outrance-rules:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ae3b4db5b69152e65d579621b6e1c720f4695ce63e9051c9ba9d080f4f69ed62","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":1,"kind":"rule","number":"4.1","title":"Matched fights","body":"Matched fights are competitive “Matches” where opponents are paired based on factors like skill, weight, experience, or age to ensure fairness and balance in the contest.\n\nDivision 1:\n● 3 rounds of 2 minutes (120 seconds)\n● 2 breaks of 1 minute (60 seconds) Division 2:\n● 3 rounds of 1 minute and 30 seconds (90 seconds)\n● 2 breaks of 1 minute (60 seconds)","page_from":8,"page_to":8,"stable_key":"outrance-rules:4.1","parent_key":"outrance-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1e1978b16670966b94b11719f42981d609435f9dd65983006402a48ef635ed88","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"4.2","title":"Tournament fights","body":"Division 1:\n● 2 rounds of 2 minutes (120 seconds)\n● 1 break of 45 seconds Division 2:\n● 2 rounds of 1 minute and 30 seconds (90 seconds)\n● 1 break of 45 seconds\n● If a tiebreaker round is needed. Use the same time as above\n\n|  | Matched fights | Tournament fights |\n| --- | --- | --- |\n| Division 1 | 3 rounds of 2 minutes (120 seconds)<br>2 breaks of 1 minute (60 seconds) | 2 rounds of 2 minutes (120 seconds)<br>1 break of 45 seconds |\n| Division 2 | 3 rounds of 1m30s (90 seconds)<br>2 breaks of 1 minute (60 seconds) | 2 rounds of 1m30s (90 seconds)<br>1 break of 45 seconds |\n\nImportant!\nFor tournament fights, if after two rounds the fight is a draw, a 3rd round will be fought.","page_from":8,"page_to":8,"stable_key":"outrance-rules:4.2","parent_key":"outrance-rules:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"73403e99c7773254e6798d995bad6f5f616e092e603cb6373d594afd388575cf","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":0,"kind":"section","number":"5","title":"Competitors","body":"","page_from":9,"page_to":9,"stable_key":"outrance-rules:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e3207a0ba88189b190d7e840fa8cd17cecedf7325a32cac518c1d7a2fa68a2f0","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":1,"kind":"rule","number":"5.1","title":"Knowledge and respect of the rules","body":"All competitors are obligated to know the rules and regulations and to strictly obey them.\nThey shall obey commands given by the knight marshal.\nThey shall defend themselves at all times unless under the direct instruction of the knight marshal to “Stop Fight”, “Break” or “Hold”.\nThey shall be polite to other participants, marshals, and spectators.\nSwearing, rudeness, and other impolite actions may be penalized by the knight marshal with a verbal warning, yellow card, or even disqualification if they are persistent.\nIn the case above, actions taken outside the list, the knight marshal may demand penalizing them by the event organizer and/or League.\nAll competitors shall use a set of armor, weapon, and clothes that fulfill all technical safety requirements.\nThey shall come to the list within one (1) minute after being called by the herald/secretary/announcer of the event.\nThey should have a set of spare weapons and elements of armor, along with the necessary repair kit that allows making urgent repairs.\nEach competitor should have at least one (1) corner man. A competitor has a maximum of two (2) corner men.","page_from":9,"page_to":9,"stable_key":"outrance-rules:5.1","parent_key":"outrance-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ad8c4bf7a39e50aedaa6647797d4f4066e18e9947f888374a69f890e6efcbe0f","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":1,"kind":"rule","number":"5.2","title":"Competitor stoppage","body":"A competitor may stop the fight to yield during a round. They signal the knight marshal by throwing their weapon to the surface of the list and/or shouting “Stop fighting”.\nA competitor may forfeit before the fight has started because of:\n● Disqualification armor/weapon failure: The competitor is unable to continue the fight because of their damaged armor/weapon.\n● Medical retirement: The competitor is unable to continue the fight for a medical reason (e.g., injury).\n\nImportant!\nA competitor that yields or forfeits will need to be assessed to verify their ability to continue. This may include medical review and senior knight marshal review.","page_from":9,"page_to":9,"stable_key":"outrance-rules:5.2","parent_key":"outrance-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dcd5032c13c23c951bdb260e77b5c7a7a4e8a2c1c37b565088f1532b65180a91","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":1,"kind":"rule","number":"5.3","title":"Appeal submission","body":"The competitor may submit an appeal to the marshals committee if, in their opinion, an action or actions taken by the opponent or any marshal contradicts the rules.","page_from":9,"page_to":9,"stable_key":"outrance-rules:5.3","parent_key":"outrance-rules:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"11c495ba9d4d8293f9c9bc8af96b803086089dd39bfe8cc545090669f045972d","has_figures":false,"extraction":"text"},{"ordinal":38,"depth":0,"kind":"section","number":"6","title":"Corner Support","body":"","page_from":10,"page_to":10,"stable_key":"outrance-rules:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b01e54061b7ed3a6518297fe71f233fed3c4c83b582c194e2d4d91a36942b4eb","has_figures":false,"extraction":"text"},{"ordinal":39,"depth":1,"kind":"rule","number":"6.1","title":"Knowledge and respect of rules","body":"All corner men are obligated to know the rules and regulations and to strictly obey them.\nThey shall obey commands given by the knight marshal.\nThey shall help their competitor to the limits of the list and aid them in preparations before the fight.\nThey shall be ready during the fight to make repairs/exchanges of damaged equipment or weapons according to the Marshal's demands.\nThey shall only enter the list in the time between rounds or at the demand of the knight marshal to aid the competitor in repairing/exchanging damaged equipment.\nThey shall be polite to other participants, marshals, and spectators.","page_from":10,"page_to":10,"stable_key":"outrance-rules:6.1","parent_key":"outrance-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f6c8e5bf4b24e3ae0ad0d9450156977d7c8ef708c2299a30e18365ca06bcc610","has_figures":false,"extraction":"text"},{"ordinal":40,"depth":1,"kind":"rule","number":"6.2","title":"Right to demand stoppage","body":"A corner man has the right to demand to stop the fight. They signal the above demand by throwing a white towel/flag onto the surface of the list.\nThey have the right to demand to stop the fight in the following cases:\n● They recognize and accept the defeat of their competitor (TKO).\n● Their competitor is unable to continue fighting caused by the breakdown or loss of the element of their equipment (TKO armor/weapons failure).\n● The competitor is unable to continue the fight due to an injury or other medical causes (Medical Retirement).\n\nImportant!\nIf one of their corner men demand to stop the fight, the competitor will need to be assessed to verify their ability to continue. This may include medical review and senior knight marshal review of corner men stoppage.","page_from":10,"page_to":10,"stable_key":"outrance-rules:6.2","parent_key":"outrance-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"30d30feae6d9fb8490015b4082055450954aa5fc62ed93d633a8628969e856fa","has_figures":false,"extraction":"text"},{"ordinal":41,"depth":1,"kind":"rule","number":"6.3","title":"Appeal submission","body":"The corner man has the right to submit an appeal in the name of their competitor (if they cannot do it by themselves) if, in their opinion, an action or actions taken by the opponent or any marshal contradicts the rules. See Section 16","page_from":10,"page_to":10,"stable_key":"outrance-rules:6.3","parent_key":"outrance-rules:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["16"],"content_sha256":"e8ebf367dfcfd33df7b92ca4f8df978f36e460aa36ed5ff4fe5037dd11909c25","has_figures":false,"extraction":"text"},{"ordinal":42,"depth":0,"kind":"section","number":"7","title":"List Requirements","body":"","page_from":11,"page_to":11,"stable_key":"outrance-rules:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f97f13e9abfd78a8b389ad60295bde73b902148202adabb3cfeb0b70ab78926","has_figures":false,"extraction":"text"},{"ordinal":43,"depth":1,"kind":"rule","number":"7.1","title":"Size","body":"The list can be made of any suitable rigid structure.\nWidth and Length:\n● Minimum: 5 meters\n● Maximum: 10 meters","page_from":11,"page_to":11,"stable_key":"outrance-rules:7.1","parent_key":"outrance-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a4bc7af027adc01dd8e362ab9daf565efbf363fe92c47b205c13ad384522bfd8","has_figures":false,"extraction":"text"},{"ordinal":44,"depth":1,"kind":"rule","number":"7.2","title":"List fence","body":"Height:\n● Minimum: between 0.9 meter\n● Maximum: 1.3 meters It should prevent competitors from coming out of the list’s limits.\nIt should be visible.","page_from":11,"page_to":11,"stable_key":"outrance-rules:7.2","parent_key":"outrance-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7f0511503efd27f6dce7d2cd502a4457bf04a9278f19d25b912861ea4aa63528","has_figures":false,"extraction":"text"},{"ordinal":45,"depth":1,"kind":"rule","number":"7.3","title":"List boundaries","body":"Boundaries of the lists should be properly seated on the ground.","page_from":11,"page_to":11,"stable_key":"outrance-rules:7.3","parent_key":"outrance-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7b390e7aed015fd92b457b0178a979765f4f0f6e0ebca4d5ef9d6fab02b203ba","has_figures":false,"extraction":"text"},{"ordinal":46,"depth":1,"kind":"rule","number":"7.4","title":"Surface quality","body":"The surface of lists should be dense and plain.\nIt should prevent competitors from slipping.","page_from":11,"page_to":11,"stable_key":"outrance-rules:7.4","parent_key":"outrance-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"20b53862e65b488b5c1b43350b188cb6185ef179c3985a6abc80b039dbdb2a51","has_figures":false,"extraction":"text"},{"ordinal":47,"depth":1,"kind":"rule","number":"7.5","title":"Lighting","body":"The light source should be located above the list.\nPositioned at a height that prevents competitors from being blinded by it.","page_from":11,"page_to":11,"stable_key":"outrance-rules:7.5","parent_key":"outrance-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"475587dcf937a30a9dad124fc0d75fe53f0f417f38142038e7c95afa5404a2ce","has_figures":false,"extraction":"text"},{"ordinal":48,"depth":1,"kind":"rule","number":"7.6","title":"Signalization tools","body":"It is recommended to place a white towel in the competitors’ corners for the corner men to use if they want to demand the stoppage of the fight.\nIt is recommended to make a clear and visible mark for the starting corner of each competitor.","page_from":11,"page_to":11,"stable_key":"outrance-rules:7.6","parent_key":"outrance-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"618d6b5de589c3a03dae7beed0958ec661eb7d9e2ce2792882fbb9b45224c320","has_figures":false,"extraction":"text"},{"ordinal":49,"depth":1,"kind":"rule","number":"7.7","title":"Safety zone","body":"The organizer must provide a 2m-wide safety zone by placing a barrier around every side of the list.\nOnly the marshals committee, the corner men, and accredited photo/videographers are permitted into the safety zone.","page_from":11,"page_to":11,"stable_key":"outrance-rules:7.7","parent_key":"outrance-rules:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"edabb1365adfec42fc8ed7444841faec2ec956ba0ac1c454c90401783243d9e3","has_figures":false,"extraction":"text"},{"ordinal":50,"depth":0,"kind":"section","number":"8","title":"Authorized Equipment","body":"","page_from":12,"page_to":12,"stable_key":"outrance-rules:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"496113a9bf833af881f77398b1f661869429b298a41f0628eb03be0b3182b7fb","has_figures":false,"extraction":"text"},{"ordinal":51,"depth":1,"kind":"rule","number":"8.1","title":"General requirements","body":"Technical and Authentic Compliance: all equipment must meet Buhurt International technical and authentic requirements.","page_from":12,"page_to":12,"stable_key":"outrance-rules:8.1","parent_key":"outrance-rules:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c2a33aa57bffd4dd2212fa3416e3f2904006d88a8867af42924d3db0b277cb7b","has_figures":false,"extraction":"text"},{"ordinal":52,"depth":1,"kind":"rule","number":"8.2","title":"Specifics on weapons and shields","body":"All Buhurt International weapons and shields are permitted.\nAny combination of these weapons is allowed.","page_from":12,"page_to":12,"stable_key":"outrance-rules:8.2","parent_key":"outrance-rules:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b5d16a12999435d5aaacdcf80f49c4f65b99af51a8e6fed84710beb965f00cc3","has_figures":false,"extraction":"text"},{"ordinal":53,"depth":1,"kind":"rule","number":"8.3","title":"Changes of equipment","body":"Participants are allowed to change elements of their equipment (armor or weapon) during intervals or due to breakage.\nThe supervision of the technical marshal is required for any change of equipment.","page_from":12,"page_to":12,"stable_key":"outrance-rules:8.3","parent_key":"outrance-rules:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9547ab66402d5b6c8277ec3c1aed95f501f5c8d34553d5ef515b3b16cd27a1a7","has_figures":false,"extraction":"text"},{"ordinal":54,"depth":1,"kind":"rule","number":"8.4","title":"Marshal authority","body":"The knight marshal and the technical marshal have the authority to demand changes to any element of armor or weapon for safety, aesthetic, or historical accuracy reasons.","page_from":12,"page_to":12,"stable_key":"outrance-rules:8.4","parent_key":"outrance-rules:8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"669e5d812acc64ba965a196e018973f027a1c33448ee85091a9548f29c4574e2","has_figures":false,"extraction":"text"},{"ordinal":55,"depth":0,"kind":"section","number":"9","title":"Authorized Fighting Techniques","body":"These rules aim to define a set of permitted and prohibited actions to ensure the safety of participants while engaging in combat. The guidelines cover striking, grabbing, and various techniques to maintain a fair and controlled environment during the event.","page_from":13,"page_to":13,"stable_key":"outrance-rules:9","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c265a10f3aed278cf5536f6cb47ba3dd548ed1318d4c409175266d80954d3b78","has_figures":false,"extraction":"text"},{"ordinal":56,"depth":1,"kind":"rule","number":"9.1","title":"Permitted strikes","body":"Strikes are permitted with any part of the weapon, the shield, and with various body parts (arms, legs and head), whether standing or on the ground.","page_from":13,"page_to":13,"stable_key":"outrance-rules:9.1","parent_key":"outrance-rules:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"463db0f2c4d6dc5f420f3e37e115cf0fdc213c676848695c010941c52f145953","has_figures":false,"extraction":"text"},{"ordinal":57,"depth":1,"kind":"rule","number":"9.2","title":"Permitted strike zones","body":"Strikes are allowed to any area not mentioned as a prohibited strike zone (See section 12 below).","page_from":13,"page_to":13,"stable_key":"outrance-rules:9.2","parent_key":"outrance-rules:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["12"],"content_sha256":"afc6275d61f3b495ee306879ae2f24a0208bf60c39f1b100a77c25d335ac68ce","has_figures":false,"extraction":"text"},{"ordinal":58,"depth":1,"kind":"rule","number":"9.3","title":"Weapon-grabbing","body":"Competitors are allowed to grab their own weapon and weapon blade with their hands.\nCompetitors are allowed to grab their opponent’s weapon (except by the blade) and shield with a free hand.","page_from":13,"page_to":13,"stable_key":"outrance-rules:9.3","parent_key":"outrance-rules:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6e569761abb23e15a2f3c8ac06ebaee7357ee44260f7fd4f1fe5187ea9b63e28","has_figures":false,"extraction":"text"},{"ordinal":59,"depth":1,"kind":"rule","number":"9.4","title":"Techniques and moves","body":"Back heels, wrestling throws, and clinches are allowed.","page_from":13,"page_to":13,"stable_key":"outrance-rules:9.4","parent_key":"outrance-rules:9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a2aaeee61085e518170add53a4f62b09ac68e73802b845bf174a1a03916c7b0","has_figures":false,"extraction":"text"},{"ordinal":60,"depth":0,"kind":"section","number":"10","title":"Prohibited Fighting Techniques","body":"These rules aim to ensure the safety, fairness, and adherence to a set of standards during the combat activities in the specified event.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e980a590ce70858e20b24c3e1178087c17067ddfa6fe24ee2c9d917c2f6b02c","has_figures":false,"extraction":"text"},{"ordinal":61,"depth":1,"kind":"rule","number":"10.1","title":"Unlisted techniques","body":"Any actions not listed in section 9 of the rules are prohibited. Only authorized techniques are permitted.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.1","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["9"],"content_sha256":"d8994506e8d786f7579b262eef87d77ad2ae6a9938f3bd29c329f8e06e782391","has_figures":false,"extraction":"text"},{"ordinal":62,"depth":1,"kind":"rule","number":"10.2","title":"Thrusting actions","body":"Any thrusting actions with a weapon are prohibited. Threats of a thrusting action are also prohibited.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.2","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b66e09919729cecf191266007dd5da0dc963a9e438f0326ccb2cd867f494bbea","has_figures":false,"extraction":"text"},{"ordinal":63,"depth":1,"kind":"rule","number":"10.3","title":"Offensive actions at prohibited strike zones","body":"Any offensive actions aimed at any prohibited strike zones (See section 12 below) are prohibited.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.3","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["12"],"content_sha256":"730568cb565ffb6ab736923a995264760a67ac6fd08df2c7e97fce2def652688","has_figures":false,"extraction":"text"},{"ordinal":64,"depth":1,"kind":"rule","number":"10.4","title":"Actions with foot or shin at the knee","body":"Actions with the foot or shin aimed at the knee are prohibited. This includes actions that may cause the knee to hyperextend, such as push kicks to the thigh.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.4","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bdd2a1a56805d323c07108ff30e7071129601f687c1135fe76bd417d614bcc05","has_figures":false,"extraction":"text"},{"ordinal":65,"depth":1,"kind":"rule","number":"10.5","title":"Grappling and holding","body":"Grappling and holding with the hand on specific armor elements (aventail, edge of pauldrons, edge of the helmet), pushes on the bottom edge of the helmet, neck cranks, and subsequent neck twists are prohibited.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.5","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ebad01195a93f387d5e46c0e36c4bcf77c629161fc186e2efafafbd15649744a","has_figures":false,"extraction":"text"},{"ordinal":66,"depth":1,"kind":"rule","number":"10.6","title":"Suffocation techniques","body":"Grips, clamps, suffocation techniques with direct pressure on the neck using any part of the body, equipment, or weapon are prohibited. A poorly fitted helmet does not count as a suffocating technique.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.6","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3af2ba155c4db337d42c3b28a45a5bde742afe0268d0d09fbb1c14d96d931ca2","has_figures":false,"extraction":"text"},{"ordinal":67,"depth":1,"kind":"rule","number":"10.7","title":"Joint locks and hyperextension","body":"Arm lock techniques, leg lock techniques and any actions that may cause a limb to hyperextend are prohibited.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.7","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2f243cce25ae6a960f48d0a4e436f841b4867f51c7c63c5cc7302b78bf37d037","has_figures":false,"extraction":"text"},{"ordinal":68,"depth":1,"kind":"rule","number":"10.8","title":"Specific strikes","body":"Strikes with the head of a one-handed axe are prohibited if the grip of the hand on the shaft is less than 30cm away from the axe’s head.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.8","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5bad418b26eee2070ef7b7cb03bbaf02324f2a792d23ed2438137d316277ef7f","has_figures":false,"extraction":"text"},{"ordinal":69,"depth":1,"kind":"rule","number":"10.9","title":"Armor tampering","body":"Deliberate attempts to remove any elements of the armor are prohibited.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.9","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6b7b4ea932304fb1d125dae460a9fc74d04c24e15a052ed844524e3bfb7dc0ca","has_figures":false,"extraction":"text"},{"ordinal":70,"depth":1,"kind":"rule","number":"10.10","title":"Strikes to a disarmed opponent","body":"Strikes to an opponent who has lost their weapon are prohibited.","page_from":14,"page_to":14,"stable_key":"outrance-rules:10.10","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"84b9084515fcabc21f3c37ddcf2dfe4e6b38f8ff6cfe6bac0bf125d0a77129a9","has_figures":false,"extraction":"text"},{"ordinal":71,"depth":1,"kind":"rule","number":"10.11","title":"Strikes to a grounded opponent","body":"Foot and shin strikes to a grounded opponent are prohibited.\nKnee strikes to a grounded opponent’s legs or head are prohibited.","page_from":15,"page_to":15,"stable_key":"outrance-rules:10.11","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"28510dc32cc2d677ab083007345ed4951f141e36aa4a3e419995cd621cfafd5d","has_figures":false,"extraction":"text"},{"ordinal":72,"depth":1,"kind":"rule","number":"10.12","title":"Dangerous take downs","body":"Any takedown that forces an opponent to land on their head/neck and suplex (arch throws) variations are prohibited.","page_from":15,"page_to":15,"stable_key":"outrance-rules:10.12","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"085ebf40e5c0bd61a4dbe650ef7e85ee52df6e2ea86e68d2f5c5868b21f64416","has_figures":false,"extraction":"text"},{"ordinal":73,"depth":1,"kind":"rule","number":"10.13","title":"Out-of-bounds actions","body":"Intentional pushing or throwing an opponent out of the designated fighting area (list) is prohibited.","page_from":15,"page_to":15,"stable_key":"outrance-rules:10.13","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e2b8a8baa47db4ddca50f5322e8801fdc13e3f4fc4b38bcc098115653025efb9","has_figures":false,"extraction":"text"},{"ordinal":74,"depth":1,"kind":"rule","number":"10.14","title":"Fence interaction","body":"Grabbing the fence and resting with hands/elbows above the fence is prohibited.","page_from":15,"page_to":15,"stable_key":"outrance-rules:10.14","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ab8a7a6166cb42684eaa12269fce4aaff1c79d3d26d4b3c80597de9346b0c5d8","has_figures":false,"extraction":"text"},{"ordinal":75,"depth":1,"kind":"rule","number":"10.15","title":"Eye protection","body":"Attacks that may penetrate the eye slits of the opponent's helmet are prohibited.","page_from":15,"page_to":15,"stable_key":"outrance-rules:10.15","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3da3ab854ee4291c286626b6694062a7dea988d41fb8b178bf983649cac847ab","has_figures":false,"extraction":"text"},{"ordinal":76,"depth":1,"kind":"rule","number":"10.16","title":"Intentional passivity","body":"Intentional passivity and stalling of the action are prohibited.","page_from":15,"page_to":15,"stable_key":"outrance-rules:10.16","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"84300c0852731b2133834b04875369a637fe4e63bca744c477fd61f932ad3c66","has_figures":false,"extraction":"text"},{"ordinal":77,"depth":1,"kind":"rule","number":"10.17","title":"Assistance after a break","body":"A competitor cannot purposefully push on their opponent to get up off the ground after a \"Break\" or \"Stop fight\" command.","page_from":15,"page_to":15,"stable_key":"outrance-rules:10.17","parent_key":"outrance-rules:10","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a8c2c2232fc5989d49bf3f959587bbde6e8e0d2816ef8a418c1d2449a0ea3e1d","has_figures":false,"extraction":"text"},{"ordinal":78,"depth":0,"kind":"section","number":"11","title":"Other Prohibited Actions","body":"These rules contribute to maintaining the integrity, safety, and orderliness of the event. They cover aspects such as participants behavior, substance use, adherence to commands, and respect for officials and other attendees. The role of the knight marshal is highlighted in several instances, emphasizing their authority and responsibility in ensuring the proper conduct of the event.","page_from":16,"page_to":16,"stable_key":"outrance-rules:11","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"126fedd1f774d965d8529bb44a6650dab3f7fd8b646e3dda2bfa7e3824c32c7d","has_figures":false,"extraction":"text"},{"ordinal":79,"depth":1,"kind":"rule","number":"11.1","title":"Leaving the list","body":"Intentional leaving of the list after the command “Start fight” and before the announcement of the results of the fight is prohibited. Permission to leave must be granted by the knight marshal.","page_from":16,"page_to":16,"stable_key":"outrance-rules:11.1","parent_key":"outrance-rules:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b427588b2dfd29cee4ee03ede09d61fb8133e0a99aa386985fa699d4676a2b4d","has_figures":false,"extraction":"text"},{"ordinal":80,"depth":1,"kind":"rule","number":"11.2","title":"Equipment and weapon approval","body":"Competitors are not allowed to use any part of the equipment or any weapon that hasn't been allowed by the technical marshal.","page_from":16,"page_to":16,"stable_key":"outrance-rules:11.2","parent_key":"outrance-rules:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"479bb988a530a3044a7e3dc1eef83e813bd4d52169f82949ef553386d11edea2","has_figures":false,"extraction":"text"},{"ordinal":81,"depth":1,"kind":"rule","number":"11.3","title":"Substance use","body":"Competitors are not allowed to be under the influence of alcohol or any psychoactive substances.","page_from":16,"page_to":16,"stable_key":"outrance-rules:11.3","parent_key":"outrance-rules:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a9c911e3f8f27bacca5d368c5d24c77d8e5408e040ad7d85cb6357bbc3f8cec5","has_figures":false,"extraction":"text"},{"ordinal":82,"depth":1,"kind":"rule","number":"11.4","title":"Stalling after commands","body":"Intentionally stalling for time after a “Break” or “Hold” command has been given is prohibited.\nThe knight marshal will issue a warning, and if the competitor is not ready after the warning, a 5-second count will be initiated. If the count reaches 5 seconds, the fight will be stopped, and a TKO win will be awarded to the opposing competitor.","page_from":16,"page_to":16,"stable_key":"outrance-rules:11.4","parent_key":"outrance-rules:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e8d4d1739c49d628cdd303381144eee6e3f12afe8c34489447d08dab17649e53","has_figures":false,"extraction":"text"},{"ordinal":83,"depth":1,"kind":"rule","number":"11.5","title":"Offensive actions against others participants","body":"Any offensive actions against marshals, corner men, spectators, or anyone else other than the current opponent are prohibited.","page_from":16,"page_to":16,"stable_key":"outrance-rules:11.5","parent_key":"outrance-rules:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2c86702d3e4dc933998828a44433aca54faa0875f760dd1bc1593ca572a4970b","has_figures":false,"extraction":"text"},{"ordinal":84,"depth":1,"kind":"rule","number":"11.6","title":"Event interference","body":"Any actions made by a competitor or their corner men that may impede the course of the event are prohibited.","page_from":16,"page_to":16,"stable_key":"outrance-rules:11.6","parent_key":"outrance-rules:11","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"844b31352bb827d5b9dc20ae011be50e76d9c05c98828c63a9e13aee59000b0f","has_figures":false,"extraction":"text"},{"ordinal":85,"depth":0,"kind":"section","number":"12","title":"Prohibited Strike Zones","body":"These rules are designed to prioritize the safety of the participants by prohibiting strikes to vulnerable and potentially dangerous areas. Their overall intention is to prevent serious injuries and ensure a fair and safe competition.","page_from":17,"page_to":17,"stable_key":"outrance-rules:12","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dcccd135e0a9d2a209e4375a99e575d5f67d8de9ba962292c170da1837bc8ecc","has_figures":false,"extraction":"text"},{"ordinal":86,"depth":1,"kind":"rule","number":"12.1","title":"Back and front of the neck","body":"Strikes to the back and front of the neck are prohibited.","page_from":17,"page_to":17,"stable_key":"outrance-rules:12.1","parent_key":"outrance-rules:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ba5b4d19d67dbc00da3a0d862ce3f42233a188c52db100966e34beed9fcc9d51","has_figures":false,"extraction":"text"},{"ordinal":87,"depth":1,"kind":"rule","number":"12.2","title":"Base of the skull","body":"Strikes to the base of the skull are prohibited.\nThe base of the skull is defined as the bottom third of the back of the helmet.","page_from":17,"page_to":17,"stable_key":"outrance-rules:12.2","parent_key":"outrance-rules:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0ac383a5ab2ee6d4111ddd671247ec3713532cbfe465348ad6d3b0c1e8e67820","has_figures":false,"extraction":"text"},{"ordinal":88,"depth":1,"kind":"rule","number":"12.3","title":"Back of the knee","body":"Strikes to the back of the knee are prohibited.\nPlacing pressure to the back of the knee is prohibited.","page_from":17,"page_to":17,"stable_key":"outrance-rules:12.3","parent_key":"outrance-rules:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fe6d30aad8e67c65b4e0d14636bd36943630ca300bb1a6af7effd36692fdc75f","has_figures":false,"extraction":"text"},{"ordinal":89,"depth":1,"kind":"rule","number":"12.4","title":"Groin and crotch","body":"Strikes to the groin and crotch are prohibited.","page_from":17,"page_to":17,"stable_key":"outrance-rules:12.4","parent_key":"outrance-rules:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b0967807713ead468ffecca5a927a47cdc2a1f0234a4d2655712796ab9d7e65f","has_figures":false,"extraction":"text"},{"ordinal":90,"depth":1,"kind":"rule","number":"12.5","title":"Foot and ankle","body":"Strikes to the feet and ankles are prohibited. However, striking the foot is not considered a prohibited strike if the competitor raises their foot while the strike is already occurring.","page_from":17,"page_to":17,"stable_key":"outrance-rules:12.5","parent_key":"outrance-rules:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8b10bd12f1d9be3f9cba59d1431feb1c364e4d7fcc5f5d2d6ae4ce0d4f40afa5","has_figures":false,"extraction":"text"},{"ordinal":91,"depth":1,"kind":"rule","number":"12.6","title":"Unprotected body parts","body":"Any part of the opponent’s body that has lost its protection is considered a prohibited strike zone.","page_from":17,"page_to":17,"stable_key":"outrance-rules:12.6","parent_key":"outrance-rules:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bbb308732796487926d50b26501bfc6a6a4ad01e5f9b8c76c44f714af30bdb1b","has_figures":false,"extraction":"text"},{"ordinal":92,"depth":1,"kind":"rule","number":"12.7","title":"Illustration of prohibited strikes zones","body":"","page_from":18,"page_to":18,"stable_key":"outrance-rules:12.7","parent_key":"outrance-rules:12","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a8e6c1314e0cdd5061f5ccbf82d33826bd9941f9dc31bf92e6822464b17289b8","has_figures":true,"extraction":"text"},{"ordinal":93,"depth":0,"kind":"section","number":"13","title":"Penalties","body":"These penalties are designed to maintain the integrity of the event, enforce the rules, and ensure a fair and safe competition. The progression from verbal warnings to yellow cards and potential disqualification emphasizes the seriousness of rule violations. Only the Knight Marshal may issue these.","page_from":19,"page_to":19,"stable_key":"outrance-rules:13","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"10c0f09bcc7c993568bcbb047187521e0e4323cdc96ecec823a30608e6760647","has_figures":false,"extraction":"text"},{"ordinal":94,"depth":1,"kind":"rule","number":"13.1","title":"Verbal warning","body":"A verbal warning is given to a competitor or a corner man for a minor rule violation that does not significantly impact the course of the fight.\nIt serves as an alert that more serious actions will be taken if the violation is repeated.\nVerbal warnings do not have to be recorded in the protocol.\n3 verbal warnings will result in escalation to a yellow card.","page_from":19,"page_to":19,"stable_key":"outrance-rules:13.1","parent_key":"outrance-rules:13","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2163118158cc9b73ea83ff01133e9db2779ba3505677d1d2cb5f1d9dd6e37717","has_figures":false,"extraction":"text"},{"ordinal":95,"depth":1,"kind":"rule","number":"13.2","title":"Yellow card","body":"Given by the knight marshal to a competitor or a corner man for systematic violations of the rules or for a violation that had a serious impact on the fight.\nYellow cards are recorded in the protocol and considered in the final score of the fight.\nThe knight marshal should point their hand in the direction of the competitor while announcing \"Yellow card”.","page_from":19,"page_to":19,"stable_key":"outrance-rules:13.2","parent_key":"outrance-rules:13","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3caec1c9c3b0976f2ddee8374597c275c561b88afeda7a6243af099d20c90f49","has_figures":false,"extraction":"text"},{"ordinal":96,"depth":1,"kind":"rule","number":"13.3","title":"Expulsion of a corner man","body":"The knight marshal has the authority to expel a corner man for systematic violations of the rules or for a violation that had a serious impact on the fight.\nThe decision is noted in the protocol but does not affect the score of the fight.\nIf a competitor had only one (1) corner man, another person should be appointed immediately to take their position.","page_from":19,"page_to":19,"stable_key":"outrance-rules:13.3","parent_key":"outrance-rules:13","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4d768c83b60dc32e6949ad34699c6e343f0f0b19572d1a2e1ae6c566c50b8f8e","has_figures":false,"extraction":"text"},{"ordinal":97,"depth":1,"kind":"rule","number":"13.4","title":"Red card (disqualification)","body":"A red card equals a disqualification and is automatically given to a competitor who receives a second yellow card.\nIt may also be given if action(s) by the competitor or their corner man disrupt the course of the fight to the extent that it cannot continue or properly start.\nRed cards are recorded in the protocol.\nThe marshal should point their hand in the direction of the competitor while announcing “Red card” or “Disqualification”.","page_from":19,"page_to":19,"stable_key":"outrance-rules:13.4","parent_key":"outrance-rules:13","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"773f40aaf3900eea21db6e1cba1166816aef78e58cb55f9484f88967a18c7fe8","has_figures":false,"extraction":"text"},{"ordinal":98,"depth":0,"kind":"section","number":"14","title":"Special Situations","body":"","page_from":20,"page_to":20,"stable_key":"outrance-rules:14","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"afd7d276d1e426c68dad942183c8d52808da597d09d1fd2d2984944cbbc69f04","has_figures":false,"extraction":"text"},{"ordinal":99,"depth":1,"kind":"rule","number":"14.1","title":"Weapon loss","body":"Procedure:\n● The knight marshal stops the fight with the “Hold” command.\n● Both competitors cease fighting, remain in position.\n● The knight marshal rearms the competitor and resets both competitors.\n● The knight marshal gives the “Fight” command.\n\nImportant note:\nWhen a fighter loses a weapon 3 or more times in a single round, this will result in a 1 point deduction to the fighter's round (see section 15.3.2. below).","page_from":20,"page_to":20,"stable_key":"outrance-rules:14.1","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["15.3.2"],"content_sha256":"cc9378ea745db195d9c754db369a3403e0bcca684e8556f3641cffe13bab082b","has_figures":false,"extraction":"text"},{"ordinal":100,"depth":1,"kind":"rule","number":"14.2","title":"Weapon breakage","body":"Procedure:\n● The knight marshal stops the fight with the “Break” command.\n● The competitor must replace the weapon with a new one that was accepted by the technical marshal during the preparation of the fight.\n● If a replacement is impossible, victory is given to the opponent by TKO armor/weapon failure.\n● If a replacement is done, the fight continues with no penalty.","page_from":20,"page_to":20,"stable_key":"outrance-rules:14.2","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"988c7976d51620eb6ac99af66c91e1c68fd5ce000a783f68635434b38967a204","has_figures":false,"extraction":"text"},{"ordinal":101,"depth":1,"kind":"rule","number":"14.3","title":"Shield Breakage","body":"In case of a shield breakage, the competitor can either:\n● Remove it, provided their armor cover their arm efficiently,\n● Replace it with a new one that was accepted by the technical marshal during the preparation of the fight.\nNo penalty is imposed.","page_from":20,"page_to":20,"stable_key":"outrance-rules:14.3","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7bb6bbafcef0a1ab4a96b3c92f27425611e242fe6a155dbf6b4d04a283377c88","has_figures":false,"extraction":"text"},{"ordinal":102,"depth":1,"kind":"rule","number":"14.4","title":"Armor failure","body":"Procedure:\n● The knight marshal stops the fight with the “Break” command.\n● If the competitor, with the help of their corner men, can fix their armor in 90 seconds or less, they are deducted 1 point off their round score (see section 15.3.2 below).\n● If they are unable to fix their armor in 90 seconds or less, they may be granted 90 additional seconds. They are deducted 1 additional point off their round score (see section 15.3.2 below).\n● If they are still unable to fix the armor within the additional 90 seconds, their opponent is awarded the victory by TKO armor/weapon failure.","page_from":20,"page_to":20,"stable_key":"outrance-rules:14.4","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["90","15.3.2"],"content_sha256":"97bce97f6956e2897e3a0e00737fded3eb63f41fb2ab16c12f255f41f0e5aae9","has_figures":false,"extraction":"text"},{"ordinal":103,"depth":1,"kind":"rule","number":"14.5","title":"Clinch","body":"A clinch is a standing position where fighters lock their upper bodies together with their arms between competitors during the fight.\nProcedure:\n● If the clinch is inactive for 10 seconds, the knight marshal stops the fight with the “Break” command.\n● Both competitors separate, and after the \"Fight\" command, they continue the fight.","page_from":21,"page_to":21,"stable_key":"outrance-rules:14.5","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"25386d5b485996b11d3ecd02705867d5c1588a645f02d50cd43e9d5a49f4af07","has_figures":false,"extraction":"text"},{"ordinal":104,"depth":1,"kind":"rule","number":"14.6","title":"Unintentional fall outside or under the list","body":"Procedure:\n● The knight marshal stops the fight with a \"Hold\" command.\n● Both competitors return to the middle of the list in the same position as when the \"Hold\" command was given.\n● \"Fight\" command is given to resume the fight.","page_from":21,"page_to":21,"stable_key":"outrance-rules:14.6","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d2dd2f352bdd24c1ed7cbb5a3bd4e69c361494d1fb159fe44475c1e612c82097","has_figures":false,"extraction":"text"},{"ordinal":105,"depth":1,"kind":"rule","number":"14.7","title":"Grounded position","body":"A grounded position is a situation when a competitor has more than just the soles of their feet touching the ground. This includes hands, knees, back or their buttocks. One or both competitors can be in a grounded position simultaneously. The action is permitted to continue for 30 seconds providing that the action is consistent.\nProcedure:\n● The knight marshal stops the fight after 10 seconds of inactivity with the \"Break\" command.\n● Both competitors take a standing position about 3 meters apart and wait for the knight marshal's command to resume the fight.\n● A fallen competitor may take any actions to protect themselves (excluding prohibited actions).","page_from":21,"page_to":21,"stable_key":"outrance-rules:14.7","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"424a5893c433776749bf98a8d096f4b6d0203895db7035e34c048026b1cd2173","has_figures":false,"extraction":"text"},{"ordinal":106,"depth":1,"kind":"rule","number":"14.8","title":"Technical knockout (TKO)","body":"Procedure:\n● Determination by the knight marshal: The knight marshal, as the official overseeing the fight, is responsible for determining if a fighter is no longer able to intelligently defend themselves.\n\n● Verbal warning: If the knight marshal observes that a fighter is unable to intelligently defend themselves, they will issue a verbal warning to the fighter.\n\n● 5-Second count: Following the verbal warning, the knight marshal will initiate a 5-second count, during which the fighter must demonstrate the ability to intelligently defend themselves.\n\n● Continuous lack of defense: If, after the 5-second count, the fighter continues to be unable to intelligently defend themselves, the knight marshal will intervene.\n\n● “Stop fight” announcement: At this point, the knight marshal will call for the fight to be stopped.\n\n● Declaration of TKO: Following the stoppage of the fight, the knight marshal will officially declare a Technical Knockout (TKO) by announcing \"Knockout.\"\n\n● TKO: If a competitor receives a TKO due to a lack of defense, they will lose the Match in Division 1 or the Round in Division 2. All TKO’s must be checked by Medic to verify they can continue to fight.","page_from":21,"page_to":22,"stable_key":"outrance-rules:14.8","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5e5f32f5a460fa6d3bf30fbcc592acdd356ef2047d6790b8608de5b96da4c13f","has_figures":false,"extraction":"text"},{"ordinal":107,"depth":1,"kind":"rule","number":"14.9","title":"Intelligent defending","body":"","page_from":22,"page_to":22,"stable_key":"outrance-rules:14.9","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1ad50265602b165c38a53a559eab6e60be884518578d1695a833f39eefc2f75e","has_figures":false,"extraction":"text"},{"ordinal":108,"depth":2,"kind":"rule","number":"14.9.1","title":"Movement and positioning","body":"● Employing footwork to maintain distance from the opponent.\n● Utilizing angles and lateral movement to create advantageous positions.\n● Controlling the center of the fighting space to dictate the pace and direction of the engagement.","page_from":22,"page_to":22,"stable_key":"outrance-rules:14.9.1","parent_key":"outrance-rules:14.9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cd05850fc3bc513e6ba0f39c4f235af93f67ac2a9045dbe23067a42f63de0562","has_figures":false,"extraction":"text"},{"ordinal":109,"depth":2,"kind":"rule","number":"14.9.2","title":"Technique","body":"● Blocking or parrying strikes with proper technique to minimize impact.\n● Executing defensive maneuvers such as slips, rolls, and evasions to avoid incoming attacks.\n● Understanding defensive principles specific to different martial arts or combat sports.","page_from":22,"page_to":22,"stable_key":"outrance-rules:14.9.2","parent_key":"outrance-rules:14.9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9c5a360dcf3a4eebe32e7e776117462bf1caece828fa0d46f9b30db1da754db6","has_figures":false,"extraction":"text"},{"ordinal":110,"depth":2,"kind":"rule","number":"14.9.3","title":"Counterattacking opportunities","body":"● Identifying openings in the opponent's defense to launch effective counterattacks.\n● Capitalizing on the opponent's mistakes or vulnerabilities to turn the tide of the fight.\n● Using feints and baiting techniques to provoke reactions and create offensive opportunities.","page_from":22,"page_to":22,"stable_key":"outrance-rules:14.9.3","parent_key":"outrance-rules:14.9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3e5a4c0c99c2c4ceee5618d2de306b6ecf856454b883b21f5fe5b3d9979fc50b","has_figures":false,"extraction":"text"},{"ordinal":111,"depth":2,"kind":"rule","number":"14.9.4","title":"Composure and adaptability","body":"● Staying calm and focused under pressure to make sound defensive decisions.\n● Analyzing the opponent's movements and adjusting defensive strategies accordingly.\n● Being adaptable to changing circumstances and adjusting tactics as the fight progresses.","page_from":22,"page_to":22,"stable_key":"outrance-rules:14.9.4","parent_key":"outrance-rules:14.9","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b3eac1f0ce77a607024fa7d2ee903c90a6df87f1f60bea3f05543657fdd2fc78","has_figures":false,"extraction":"text"},{"ordinal":112,"depth":1,"kind":"rule","number":"14.10","title":"Disqualification","body":"Disqualification occurs when a competitor is unable to continue fighting due to:\n● No available weapon or armor breakage that can not be repaired in the given time.\n● Disqualification also includes a fighter that has received a red card.\n\nImportant!\nShould a fighter be subject to a disqualification due to no available weapon or armor breakage, they will have until their next match to fix the issue or be completely disqualified from the Tournament.","page_from":22,"page_to":22,"stable_key":"outrance-rules:14.10","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"48b6ac94a2264e4ba86d744f54a776e15abaca2fdc96a89ef1ed23e4d72aa9c2","has_figures":false,"extraction":"text"},{"ordinal":113,"depth":1,"kind":"rule","number":"14.11","title":"Knockout (KO)","body":"knockout occurs when a fighter is rendered unconscious and unable to continue fighting.\nThe knight marshal will announce “Stop Fight” then “Knockout”.\n\nImportant!\nShould a fighter lose a fight by KO, they will not be allowed to participate further in the tournament.","page_from":22,"page_to":22,"stable_key":"outrance-rules:14.11","parent_key":"outrance-rules:14","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"beb75dd14724988b20c8107e92c6ad54d7cadc3ee4d0fc2bc9394b6602839d62","has_figures":false,"extraction":"text"},{"ordinal":114,"depth":0,"kind":"section","number":"15","title":"Scoring the fight","body":"","page_from":23,"page_to":23,"stable_key":"outrance-rules:15","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"264d62ce1bfa92461f3410e2c92acca94b5af9c1e5c5cecb8310366bab7cac8e","has_figures":false,"extraction":"text"},{"ordinal":115,"depth":1,"kind":"rule","number":"15.1","title":"Scoring system overview","body":"","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.1","parent_key":"outrance-rules:15","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"55266ab230144035ad1977f027524a6713f2cdd3f94d8857f38762ea4ed687d5","has_figures":false,"extraction":"text"},{"ordinal":116,"depth":2,"kind":"rule","number":"15.1.1","title":"Number of line marshals","body":"3 or 5 line marshals evaluate each bout from different locations around the list/fighting area.","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.1.1","parent_key":"outrance-rules:15.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bdaa7d7664f8f9334074f338ed756c48d6e6cad609a536b0b467c5fb8503bcd1","has_figures":false,"extraction":"text"},{"ordinal":117,"depth":2,"kind":"rule","number":"15.1.2","title":"Scoring system","body":"The “10-Point Must System” is the standard for scoring bouts.","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.1.2","parent_key":"outrance-rules:15.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"18489a91bf3080b7fe5c231d372528655a6b7710083599c41a8d7d2b3957d398","has_figures":false,"extraction":"text"},{"ordinal":118,"depth":1,"kind":"rule","number":"15.2","title":"Evaluation criteria (in order of priority)","body":"","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.2","parent_key":"outrance-rules:15","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"62a15857a695c2cd6eef1a23592d4a35568b2ad88a3b36ceed4c156460aa0dcc","has_figures":false,"extraction":"text"},{"ordinal":119,"depth":2,"kind":"rule","number":"15.2.1","title":"Effective striking","body":"Clear, strong, and well-placed legal strikes to permitted zones.\nAll legal strikes with weapons, legs, arms, and shields account for one (1) strike point per clean landed blow.\nStrikes with the head do not award any strike point.","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.2.1","parent_key":"outrance-rules:15.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bc06eebad5913383f7c15b14993776cac0dd6f268f31d1f7de4f6754d4dd04f6","has_figures":false,"extraction":"text"},{"ordinal":120,"depth":2,"kind":"rule","number":"15.2.2","title":"Effective grappling","body":"Successful legal takedowns, position reversals, and clinch control.\nConsideration for takedowns from standing position to dominant position, reversal of position, and positional clinch work.\nTakedowns with no subsequent strikes/ground action are recorded for posterity.","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.2.2","parent_key":"outrance-rules:15.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1b80fd9b1232b296ba8b5a60d2c0029b4d928a61546f6a08041a08134514368a","has_figures":false,"extraction":"text"},{"ordinal":121,"depth":2,"kind":"rule","number":"15.2.3","title":"Effective list control","body":"Dominating the opponent by dictating pace, location, and position.","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.2.3","parent_key":"outrance-rules:15.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3b595207278f3bc789e5b5f48e7f640a12b880fca7b076572e019cfa5c9bec0b","has_figures":false,"extraction":"text"},{"ordinal":122,"depth":2,"kind":"rule","number":"15.2.4","title":"Effective aggression","body":"Pushing forward with attacks, landing legal strikes, and making attempts to finish the fight.\nNo credit for chasing without effective results or impact.","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.2.4","parent_key":"outrance-rules:15.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7f8b5258fb09360086408341d2878a02ad486f846694b4306bde1b46b23cf465","has_figures":false,"extraction":"text"},{"ordinal":123,"depth":2,"kind":"rule","number":"15.2.5","title":"Effective defense","body":"Avoiding being struck, taken down, or reversed while countering with offensive attacks.","page_from":23,"page_to":23,"stable_key":"outrance-rules:15.2.5","parent_key":"outrance-rules:15.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8f95268af3001483969af76baa928073e4728625d9c100bed2e4bc9584a3bf2b","has_figures":false,"extraction":"text"},{"ordinal":124,"depth":1,"kind":"rule","number":"15.3","title":"Scoring breakdown","body":"","page_from":24,"page_to":24,"stable_key":"outrance-rules:15.3","parent_key":"outrance-rules:15","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be642ca2c8ea3d0ad0425475e72fbfe1f9346222662a68afaf7c488de8e46a71","has_figures":false,"extraction":"text"},{"ordinal":125,"depth":2,"kind":"rule","number":"15.3.1","title":"Round scores","body":"Each marshal reports the score for each round to the secretary. The secretary adds these scores together and divides the total by the number of marshals to calculate the Round Score.\n● 10-10: A round with a strike point difference of 5 or less, and a winner cannot be determined by using the other evaluation criteria (noted as “Even”).\n● 10-9: A round with a strike point difference of 5 or less, and a winner can be determined by using the other evaluation criteria (noted as “Even”).\n● 10-9: Competitor out-strikes opponent by 6 to 10 strike points (noted as 'Slight').\n● 10-8: Competitor out-strikes opponent by 11 to 15 strike points (noted as 'Moderate').\n● 10-7: Competitor out-strikes opponent by 16 or more strike points (noted as 'Dominant').KO and TKO both result in this score","page_from":24,"page_to":24,"stable_key":"outrance-rules:15.3.1","parent_key":"outrance-rules:15.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3a6eb2952ef1ed2dd135793f43c4f93bf4c4acd8193577a0da7c0bc89ff29931","has_figures":false,"extraction":"text"},{"ordinal":126,"depth":2,"kind":"rule","number":"15.3.2","title":"Point deductions","body":"Yellow cards, armor malfunction penalties and weapon loss penalties result in a single point deduction for each instance.","page_from":24,"page_to":24,"stable_key":"outrance-rules:15.3.2","parent_key":"outrance-rules:15.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"492e8380c5d11f9690910856b950332099554be995ee8f901a817e09734cfa92","has_figures":false,"extraction":"text"},{"ordinal":127,"depth":2,"kind":"rule","number":"15.3.3","title":"Example scenario","body":"If competitor A and competitor B have an evenly fought round until competitor B incurs an armor failure (fixed within the required time), competitor A would be awarded 10 points, and competitor B would be awarded 9 points due to the armor failure.","page_from":24,"page_to":24,"stable_key":"outrance-rules:15.3.3","parent_key":"outrance-rules:15.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f54249f49ce4aaad3f85318d3f4849f3605c74b986e28623015dbe5b18f09afc","has_figures":false,"extraction":"text"},{"ordinal":128,"depth":1,"kind":"rule","number":"15.4","title":"Fight outcome","body":"","page_from":24,"page_to":24,"stable_key":"outrance-rules:15.4","parent_key":"outrance-rules:15","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fa4dfe51dab5bc81185855e4d3cb07c3451e92980a905173a293982ee2fc5e12","has_figures":false,"extraction":"text"},{"ordinal":129,"depth":2,"kind":"rule","number":"15.4.1","title":"Total Fight Score","body":"The Total Fight Score is determined by adding up all the Round Scores to declare the winner of the match.\n● Tournaments: The Total Fight Score is ranging between 14 and 20.\n● Matched Fights: The Total Fight Score is ranging between 21 and 30.","page_from":24,"page_to":24,"stable_key":"outrance-rules:15.4.1","parent_key":"outrance-rules:15.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"19a1b6e9f0e6220e6aaa4ca4780ccb878b3b77f33239de4310f230482c417664","has_figures":false,"extraction":"text"},{"ordinal":130,"depth":2,"kind":"rule","number":"15.4.2","title":"Win types","body":"● Unanimous decision: All line marshals scored the win for the same competitor.\n● Unanimous draw: All line marshals score the fight as a draw.\n● Majority decision: The majority of line marshals scored the win for one competitor, and the other line marshal(s) scored the fight as a draw.\n● Majority draw: The majority of line marshals scored the fight as a draw.\n● Split decision: The majority of line marshals scored the win for one competitor, and the other line marshal(s) scored the win for the other competitor.\n● Split draw: All line marshals score the fight differently but the score totals all result in a draw.\n● Technical Knockout (TKO)\n● Knockout (KO)","page_from":24,"page_to":24,"stable_key":"outrance-rules:15.4.2","parent_key":"outrance-rules:15.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"69188f0af08312714e4e07fd916e670bced3c341109e3195dff77772a7a1a0c2","has_figures":false,"extraction":"text"},{"ordinal":131,"depth":1,"kind":"rule","number":"15.5","title":"Example scoresheet","body":"| Win Criteria | Effective strike total > Effective Grappling > Effective List Control> Effective Aggression > Effective Defence |\n| Even | Difference in Effective Strikes is 5 or less. Follow Criteria by Priority until a Winner can be determined. |\n| (10-9) | If a Winner can be determined, Round to be Scored, Winner 10, Opponent 9. |\n| (10-10) | If no Winner can be determined, Round is a Draw. A Drawn Round is Scored 10 for both Fighters. |\n| Slight (10-9) | Difference in Effective Strikes from 6 to 10. Round to be Scored, Winner 10, Opponent 9. |\n| Moderate (10-8) | Difference in Effective Strikes from 11 to 15. Round to be Scored, Winner 10, Opponent 8. |\n| Dominant (10-7) | Difference in Effective Strikes from 16 or more. Round to be Scored, Winner 10, Opponent 7. |\n| Point Deductions |  |\n| Yellow Card | Any yellow card given to a fighter will result in a 1 Point Deduction to that fighters Round. |\n| Loss of weapon | When a fighter loses a weapon 3 or more times in a single round, this will result in a 1 Point Deduction to that fighters Round. |\n| Armour Failure | For each 90 seconds granted for Armour Failure Repair, 1 Point will be Deduction to that fighters Round. |","page_from":25,"page_to":25,"stable_key":"outrance-rules:15.5","parent_key":"outrance-rules:15","review_status":"verified","review_note":"The example scoresheet is printed as a picture. Its legend (win criteria and point deductions) is transcribed as a table from the page image; the labels of the blank form are set aside as picture text.","topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cf4def353134199b810801d33a9b793e725328bea2da34e1c1fadc4fec3f45c2","has_figures":true,"extraction":"ocr"},{"ordinal":132,"depth":0,"kind":"section","number":"16","title":"Appeal","body":"","page_from":26,"page_to":26,"stable_key":"outrance-rules:16","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c86f8b577d3b6534903631a2504e11692a70b30de693f8d2a7d681f27c4d2917","has_figures":false,"extraction":"text"},{"ordinal":133,"depth":1,"kind":"rule","number":"16.1","title":"Submission of an appeal","body":"The competitor or their corner men can appeal a decision made by the marshals committee or the knight marshal.\nThe appeal is submitted in written form The number of appeals are determined by the organizers.","page_from":26,"page_to":26,"stable_key":"outrance-rules:16.1","parent_key":"outrance-rules:16","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"025f7ba3915d40a52c6999cb1a9f3fcbbaa8464320d377c9c07c9bac5235c754","has_figures":false,"extraction":"text"},{"ordinal":134,"depth":1,"kind":"rule","number":"16.2","title":"Grounds for appeal","body":"An appeal can be filed for various reasons, including:\n● False implementation of point deduction, warning, card, or disqualification.\n● Unregistered clean blows to legal strike zones affecting the fight.\n● Unregistered rule violations by the opponent warranting point deduction.\n● Unregistered rule violations warranting yellow or red cards or severe rule violations.","page_from":26,"page_to":26,"stable_key":"outrance-rules:16.2","parent_key":"outrance-rules:16","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"97f902f798266a44c4420ba5eb5e1af0261f11a09c8184970281ae9d582be023","has_figures":false,"extraction":"text"},{"ordinal":135,"depth":1,"kind":"rule","number":"16.3","title":"Submission timing","body":"The competitor can appeal directly at the end of the fight when the knight marshal requests objections, before the competitor has left the list.\nThe competitor’s corner men observing the fight must announce the intention to appeal to the knight marshal in person no later than 15 minutes after the fight.","page_from":26,"page_to":26,"stable_key":"outrance-rules:16.3","parent_key":"outrance-rules:16","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e1bc3fca2ab6546e5d3600ce80b0cc8683e2296241eaf7375d5dc9c0f1447921","has_figures":false,"extraction":"text"},{"ordinal":136,"depth":1,"kind":"rule","number":"16.4","title":"Possible results of the appeal","body":"● A general rematch of the round.\n● Imposing or withdrawal of cards.\n● Imposing or withdrawal of point deduction.","page_from":26,"page_to":26,"stable_key":"outrance-rules:16.4","parent_key":"outrance-rules:16","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d5d44a449124578738b1e1fbfcb04453643516c243a1e8683f09f0c5ea1b3fd4","has_figures":false,"extraction":"text"},{"ordinal":137,"depth":1,"kind":"rule","number":"16.5","title":"Further appeal","body":"If the competitor or their corner men are dissatisfied with the knight marshal's decision, they can appeal to the Buhurt International Control and Disciplinary Committee, or the Head of the Buhurt International Marshals’ Committee.","page_from":26,"page_to":26,"stable_key":"outrance-rules:16.5","parent_key":"outrance-rules:16","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8e16e6902df5e573d69d14e62acff7145ad8fb002d7688bd941380b2ece7ded7","has_figures":false,"extraction":"text"},{"ordinal":138,"depth":0,"kind":"section","number":"17","title":"League Ranking Scoring","body":"All competitors will be tracked via win/loss record.\n\nCompetitors will be compared via their win/loss within their active weight category.\n\nIf a competitor does not compete for 1 year their ranking will be shifted to “retired” status. If they do not compete for 2 years their ranking and record will be deleted from the standings.","page_from":27,"page_to":27,"stable_key":"outrance-rules:17","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bd5fb853b2d7334a359fe51b35b536480ed0a93314fee18df091155e694affca","has_figures":false,"extraction":"text"},{"ordinal":139,"depth":0,"kind":"note","number":"18","title":"Changelog","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules.\n\nApril - 2026 (V. 26.4) Formatting redone for consistency and readability. Except points listed below, no content changes.\nGrammatical corrections were also made.\nSuppression:\n- 14.1. Weapon loss: “If a competitor loses their weapon more than twice during a round, they are deducted one (1) point off their round score (see section 15.3.2 below).” Add:\n- New section 14.3. Shield breakage has been added for clarification.\n\nJanuary 2026 (2025.03 to 2026.1) Replaced: 1.2.4 The weigh-in may be done up to 24 before the event starts up until the day of competition to assign competitors to the proper category. If a competitor misses the weigh-in, they may have to forfeit their fight or the tournament.\nThey may attempt a second weigh in before the competition begins.\nAdd: 4.2 If a tiebreaker round is needed. Use the same time as above Add: 14.6 30 seconds Remove: 14.6 indefinitely Remove: 17 Add: 17\n\nMarch 2025 (2024.06 to 2025.03) Clarification: 2.1 Senior knight marshal Clarification: 2.2 Knight marshal Replaced: 5.2 will not be allowed to participate further in the tournament || will need to be assessed to verify their ability to continue. This may include medical review and senior knight marshal review Replaced: 6.2 will not be allowed to participate further in the tournament || will need to be assessed to verify their ability to continue. This may include medical review and senior knight marshal review Clarification: 1.3 (explaining the tier 1, 2 method) Replaced: 15.3.2 that round at the discretion of the knight marshal || each instance\n\nTo see older changelogs, please refer to the archived documents.","page_from":28,"page_to":28,"stable_key":"outrance-rules:18","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["15.3.2","14.3"],"content_sha256":"8c59df1557aeb79125b13d0334e23f505ba6a0a8ebf79f4c8923b4bf559045ba","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"marshal/weapon-shield-chart","synthetic":false,"version":{"version":"26.2.1","title":"Weapons/Shield Chart","published_on":null,"effective_from":null,"note":"Every page \"VER. 26.2.1\"; the chart's own history lists VER 26.2.1, VER 26.2 and VER 26.1.","source_url":"https://drive.google.com/file/d/1n1JTMVa9t4lgQdTEp9kU8U63flesYTqy/view?usp=drive_link","source_sha256":"392d7ecf41f75491e48341140f0718fdf9cb3d23f2f7120dc985e55cdb60edb2","retrieved_at":"2026-10-06T00:00:00Z","page_count":3,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"44b29f7e728907fd2f4005028fb2ea8004905814275f4bd3d17e93f11c19092c","detected":{"version":"26.2.1","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":[],"pages":3,"source_lines":62,"assigned_lines":86,"furniture_lines":4,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":1,"provisions":10,"numbered":0,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"section","number":null,"title":"TECHNICAL REQUIREMENTS FOR PERMITTED WEAPONS","body":"","page_from":1,"page_to":1,"stable_key":"weapon-shield-chart:technical-requirements-for-permitted-weapons","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d966b71f1fee531b6e7799f687b49483dbd6409d6d574655caf34be61216a19b","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"table","number":null,"title":"Bladed Weapons (Sword, Saber, Falchion, etc)","body":"|  | Weight | Length | Length of the Blade | Length of the Handle | Special Restrictions |\n| --- | --- | --- | --- | --- | --- |\n| Type 1 Bladed (Arming sword, Falchion, Saber) | 1.1 - 1.7 | 72 - 100 | 60 - 80 | 12 - 20 | The Hilt should not extend more then 35mm over the Bearer's hand. |\n| Type 2 Bladed (Longsword) | 1.7 - 2.3 | 100 - 140 | 70 - 100 | 20 - 50 | ^ |\n| Type 3 Bladed | 2.3 - 3.0 | 120 - 160 | 90 - 130 | 30 - 50 | ^ |","page_from":1,"page_to":1,"stable_key":"weapon-shield-chart:bladed-weapons-sword-saber-falchion-etc","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dfed9b5a242eb60d1433a679662b7c7159658da3cf224e08a09ef02f57c9c92c","has_figures":true,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"table","number":null,"title":"Hafted Weapons (Polearm, Poleaxe, 2-handed axe, etc)","body":"|  | Weight | Length | Length of Striking Edge | Special Restrictions |\n| --- | --- | --- | --- | --- |\n| Type 1 Hafted (Mace) | 0.7 -1.3 | 50-70 | >5 | Type 1 Hafted (Maces) must have 6 or more flanges or be a ball. All Hafted weapons with sharp corners (Less than 90 degrees) and corners that can be considered dangerous are not permitted. Any point on the Striking Edge of the weapon Must have an angle more than 90 degrees. |\n| Type 2 Hafted (Axe) | 0.7 - 1.3 | 50 - 90 | >7 | ^ |\n| Type 3 Hafted (Longaxe) | 1.3 - 2.5 | 90 - 130 | >9 | ^ |\n| Type 4 Hafted (Polearm) | 2.2 - 3.2 | 130 - 220 | > 12 | ^ |","page_from":1,"page_to":1,"stable_key":"weapon-shield-chart:hafted-weapons-polearm-poleaxe-2-handed-axe-etc","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8bc18ffb122e1c880e5e3235f096c934703a331ad3a1805dd48c22684bb08816","has_figures":true,"extraction":"text"},{"ordinal":4,"depth":0,"kind":"table","number":null,"title":"Outrance Bladed Weapons (Sword, Saber, Falchion, etc)","body":"|  | Calculation | Special Restrictions |\n| --- | --- | --- |\n| Men | Balance Point of 15cm or more | Outrance swords must also meet the Bladed Weapons Technical Requirements. Balance points are measured from the edge of the grip zone and includes the crossguard. |\n| Women | Balance Point of 10cm or more | ^ |","page_from":1,"page_to":1,"stable_key":"weapon-shield-chart:outrance-bladed-weapons-sword-saber-falchion-etc","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e555af8b4529170b59bd5405aed5cb3319824ffe5b8fc46a1173c8cb8674ad49","has_figures":true,"extraction":"text"},{"ordinal":5,"depth":0,"kind":"section","number":null,"title":"Other Restrictions for all Weapon Types","body":"The permissible upwards error for all weapons is 100g.\nHeavier weapons or thrust weapons are not allowed under any circumstance.\nThe edge of all blades must be rebated and have a thickness of 2mm or more. This applies to striking and non-striking edges of all weapons.\nThe Radius of all edges must be more than 10mm.\nOnly Weapons which have chronological validity of a specific historical period as confirmed by the Authenticity Committee are allowed.","page_from":1,"page_to":1,"stable_key":"weapon-shield-chart:other-restrictions-for-all-weapon-types","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8aaae0ad3580e687fa2e683375b7f0e0961b3521cf2d6529e383badc12ce6eae","has_figures":true,"extraction":"text"},{"ordinal":6,"depth":0,"kind":"section","number":null,"title":"TECHNICAL REQUIREMENTS FOR PERMITTED SHIELDS","body":"","page_from":2,"page_to":2,"stable_key":"weapon-shield-chart:technical-requirements-for-permitted-shields","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8d4a8caa6a842928caa79c39ef41de920cd1c3767dc43cd6397910b18788e8a3","has_figures":true,"extraction":"text"},{"ordinal":7,"depth":0,"kind":"table","number":null,"title":"Heather and Punch Shields","body":"|  | Lenght | Width | Weight |\n| --- | --- | --- | --- |\n| Heater Shields | 55 - 75 | 30 - 65 | ≤5 |\n| Punch Shields | 55 - 75 | 30 - 50 | ^ |","page_from":2,"page_to":2,"stable_key":"weapon-shield-chart:heather-and-punch-shields","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"888aab44940da3a487c4c31c75728b7b4d9bb750aa0d134760676e185d947c3d","has_figures":true,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"table","number":null,"title":"Round Shields and Bucklers","body":"|  | < | Diameter | Weight |\n| --- | --- | --- | --- |\n| Round Shields | Sword and Shield (Duel), Buhurt | 25 - 70 | ≤5 |\n| ^ | Sword and Buckler (Duel) | 25 - 35 | ^ |\n| Bucklers | Buhurt | 20 - 40 | ≤5 |\n| ^ | Duels | 20 - 35 | ^ |","page_from":2,"page_to":2,"stable_key":"weapon-shield-chart:round-shields-and-bucklers","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"de787d371ef54b65290153855bae775d450becdb8e6f4026a1f28a8ffd6432a0","has_figures":true,"extraction":"text"},{"ordinal":9,"depth":0,"kind":"section","number":null,"title":"Other Restrictions for all Shield and Buckler Types","body":"All shapes must be conform with the \"Shields and Bucklers\" rule document.\nThe Radius of striking edge must be more than 7 cm.\nOnly Shields which have chronological validity of a specific historical period as confirmed by the Authenticity Committee are allowed.","page_from":2,"page_to":2,"stable_key":"weapon-shield-chart:other-restrictions-for-all-shield-and-buckler-types","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"862f94e9af691aec596b119afb045596432adbec6746274a68254dcfc420183b","has_figures":true,"extraction":"text"},{"ordinal":10,"depth":0,"kind":"note","number":null,"title":"Changelog","body":"VER 26.2.1\n- change Maximum diameter changed from 35 to 70 cm for Sword and Shield.\nVER 26.2\n- change Correction of the maximum diameter of Buckler for Buhurt to match \"Shields and Bucklers\" document.\nVER 26.1\n- format Changed the layout of shields.\n- change Correction of the minimum lenght of Heather shield to match \"Shields and Bucklers\" document.\n- change Modification of the maximum diameter for Round shield and Bucklers in duels.\n- change Precision for Weight: \"≤ 5\".\n\nOlder vers.\n-add Shields sheet has been added\n- change The permissible upwards error (Has been changed to 100gram for all weapons)\n- change minium size of round shields was removed -add Round shields for Duels\n- format Changed the layout of shields","page_from":3,"page_to":3,"stable_key":"weapon-shield-chart:changelog","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"bd1a7446499c976edd8551b3d57b727abc128705e2443470cf3cc3adf7beb12e","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"tournament/buhurt-regulations","synthetic":false,"version":{"version":"26.4","title":"Buhurt Regulations 26.4","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.4\".","source_url":"https://drive.google.com/file/d/154lPdIUM8lnf4VSZmY_vlY88Waygzoq5/view?usp=drive_link","source_sha256":"24f44a49019551bb29614df604daeeced70292ac05942f85808f1c12bc281adf","retrieved_at":"2026-10-06T00:00:00Z","page_count":16,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"0242ce5db995ba296466a33b8e196e43eeeba1e245b0ec65f8a3f43a7ad63103","detected":{"version":"26.4","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":16,"source_lines":463,"assigned_lines":579,"furniture_lines":59,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99621,"provisions":71,"numbered":70,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"buhurt-regulations:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"General Regulations","body":"","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1c34870f9a45b95d70c2072f2b34fc7cf98feddc39bf0ef0064f9f14be3f722b","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Weight Limit","body":"There are no weight categories in group battles.","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1.1","parent_key":"buhurt-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7e9174cf2c0ca77c5fe747960bf5ecd6817e29242e2d6e1864dbe34dd7244ed8","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"List Requirements","body":"Fights of the Buhurt International group battles category are conducted in the list with a hard surface and a rail. Depending on the type of the tournament, the size of the list may vary, provided it was agreed with Buhurt International and documented in the tournament Regulations.","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1.2","parent_key":"buhurt-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cb519001ee279dbf1a7f44204aac91b48e609114a0ee0caef21a0c31039fb6f1","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":2,"kind":"rule","number":"1.2.1","title":"Dimensions","body":"● 3v3: Length: 7 to 20 m | Width: 5 to 15 m\n● 5v5: Length: 9 to 20 m | Width: 7 to 15 m\n● 12v12: Length: 15 to 20 m | Width: 7 to 15 m\n● 30v30: Length: 25 to 30 m | Width: 12.5 to 20 m","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1.2.1","parent_key":"buhurt-regulations:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"73cb38f40d8373e50b415eda5263b2700a96f601f09ec119089ee24060af1672","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.2.2","title":"List Height","body":"The height of the rail is 0.9 to 1.3 m.","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1.2.2","parent_key":"buhurt-regulations:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1628f5968c2cc7875b2285f9f064f56c18c6daff1b8ad4a061d314c2e8e1ea9e","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.2.3","title":"Safe Zone","body":"An organizer must provide a fenced, 2m wide safety zone around every side of the list.","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1.2.3","parent_key":"buhurt-regulations:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9faa48c22ad3e01d8ee84734b613808d21cd20b2a804434dfbee5bcb929b7fba","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":2,"kind":"rule","number":"1.2.4","title":"Table Top Size","body":"The table top width should be between 50 - 70 cm.","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1.2.4","parent_key":"buhurt-regulations:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8eb891dce5dadb4cbbdaf0c908f2f4321d03bb88e929a68c0cccb7c6a266aabd","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"1.3","title":"Roles Allowed in the Safe Zone","body":"● Marshals,\n● Team support (Handing over reserve weapons) in designated areas within the safe zone,\n● Team manager (Captain, Coach) in designated areas within the safe zone,\n● Secretaries,\n● Technical staff (List maintenance),\n● Media (Only approved media staff).\n\nAccessing the safe zone without a designated role above may result in a penalty (yellow card) for the individual or team.\nOf the above roles, only marshal teams are allowed to rest their hands on top of the list; this may result in a penalty.","page_from":3,"page_to":3,"stable_key":"buhurt-regulations:1.3","parent_key":"buhurt-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b6ad499d3b829ecde9064b0c6abaf5b752fb00b63a1cd92177ab7610fa66ca97","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":0,"kind":"section","number":"2","title":"Marshals Committee","body":"The Marshals Committee of a tournament should consist of:","page_from":4,"page_to":4,"stable_key":"buhurt-regulations:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"28ef8abb962ce80d90b3f695338b8337a3cf75b7b60d72a5968dba67a6af6fcd","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"2.1","title":"The Knight Marshal (Chief Official)","body":"● Is appointed by the Tournament Organizer.\n● Shall make the final decision in the case of any disagreement.\n● Supervises the course of the fight and assesses the team’s interactions.\n● Can return a fighter who was grounded by unauthorized technique to the fight, or withdraw the fighter who is ‘out of battle’.\n● Shall break inactive clinches with the “Break” local command and a yellow flag between the helmets of the fighters. The fighters must stop fighting immediately and take two steps apart.\n● Shall stop rounds with the “Hold” command and yellow flag between helmets of the fighters. The fighters must stop across the entire list and should not move.\n● Is the only one allowed to use the command “Start fight” and a signal with a flag that will start the round.\n● Is the only one allowed to use the command “Stop fight” and a signal with a flag that will stop the round.\n● Is the only one allowed to use the command “All rise” verbally.","page_from":4,"page_to":4,"stable_key":"buhurt-regulations:2.1","parent_key":"buhurt-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"898454192150599de6684961cf8e0ae16532a420248eecceb1ab6d396f92edab","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"2.2","title":"Field Marshals","body":"● Shall break inactive clinches with the “Break” local command and a yellow flag between the helmets of the fighters. The fighters must stop fighting immediately and take two steps apart.\nLocal command “Fight” and a signal with a flag of the same marshal who announced the break indicates the recommencement of the fight for the fighters pulled out of the clinch, and a continuation of the fight in general.\nLocal commands “Break” and “Fight” are effective only for the fighters in the clinch. After the “Fight” command, any fighter can continue the fight with the same opponent or attack another opponent.\n● Will stop a fight on the command of the Knight Marshal “Stop fight” the field marshals will stop the fight with verbal commands and a yellow flag.","page_from":4,"page_to":4,"stable_key":"buhurt-regulations:2.2","parent_key":"buhurt-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"27e15133774b0cb5ef275923434f131900e4a135eb728acf3f6e47ebf2d877c3","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"2.3","title":"Line Marshals","body":"There are between 4 and 8 Line Marshals.\n● They are the external eyes of the Knight Marshal and Field Marshals in Buhurt.\n● They look for and report rules violations, armour malfunctions and any other situation in the list to the Knight Marshal or Field Marshal during the fight.\n● Particular Line Marshals will keep watch of the allocated weapon distribution zone and inform the Knight Marshal or Field Marshals of any rule’s violation.\n\n● A line marshal may only interfere with the fight under the following circumstances:\n○ By direct order of the Knight Marshal.\n○ To prevent a direct threat to a competitor’s safety.\n○ To break an inactive clinch.\n● After the round, the Line Marshal is to report any relevant information to the Knight Marshal.","page_from":4,"page_to":5,"stable_key":"buhurt-regulations:2.3","parent_key":"buhurt-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c5d55e768472a9188389f71faea79d0a12c8551e75a532430e91a34ffcb3b3d2","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"2.4","title":"The Secretary","body":"● Shall document the course and results of fights.\n● Shall compile the tournament ladders, and determine the winner of the group stage based on registered results of the individual fights.\n● For the countries/regions with a certification system in place, a secretary must hold a certificate issued by a local/regional/international Tournament committee.","page_from":5,"page_to":5,"stable_key":"buhurt-regulations:2.4","parent_key":"buhurt-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a7b6c329253782ed49f8094a69339302b3a28955da2af91b85bba7bd76506402","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"2.5","title":"The Authenticity Committee Representative (AC rep)","body":"","page_from":5,"page_to":5,"stable_key":"buhurt-regulations:2.5","parent_key":"buhurt-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"afd19433d51866577c654dde1386682d634b2a76b2921a0302b1085bb10b39a5","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"2.6","title":"Number of Marshals","body":"The number of marshals is determined separately for each tournament, depending on its form.","page_from":5,"page_to":5,"stable_key":"buhurt-regulations:2.6","parent_key":"buhurt-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0751af86dd958a5b68bb1e42cc8ec259594385d9f7a4412deed59339f2fb7e62","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":0,"kind":"section","number":"3","title":"Team Structure","body":"","page_from":6,"page_to":6,"stable_key":"buhurt-regulations:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3bfe1ac87b62d31d55b663c79ff11514773c705940afcaaa58c714950cf519d8","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"3.1","title":"Composition","body":"Teams participating in group battles consist of the following members:\n● Team Manager (captain, coach)\n● Team Support\n● Competitors","page_from":6,"page_to":6,"stable_key":"buhurt-regulations:3.1","parent_key":"buhurt-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a8b0994012d3ea695fd161d4fcac515bbc8af90c63426bb1777309af65de7e48","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"3.2","title":"Competitors","body":"Competitors cannot be on multiple teams in a single category at a tournament.\nOnce the tournament has started, team rosters are locked in and can not be changed.\nTeams may replace competitors from their tournament roster in any frequency and number between the rounds or matches.","page_from":6,"page_to":6,"stable_key":"buhurt-regulations:3.2","parent_key":"buhurt-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b8a5b6e974986e85962446996bec66d2745a1f0c5fe39c1f100e7f8021cef7ac","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"3.3","title":"Number of Reserve Competitors and Support in the Safety Zone","body":"Competitors can have a team manager or support role.\n● 3v3 Team: 5 competitors,1 team manager, 1 support\n● 5v5 Team: 8 competitors, 1 team manager, 1 support\n● 12v12 Team: 20 competitors, 1 team manager, 2 supports\n● 30v30 Team: 50 competitors, 1 team manager, 3 supports\n\nDuring the Matches the competitors are not allowed in the safety zone (see section 1.3 above).","page_from":6,"page_to":6,"stable_key":"buhurt-regulations:3.3","parent_key":"buhurt-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["1.3"],"content_sha256":"f2a93eb7a9734e1e32edb60df792016b61865c7cc6039b9db242dda972d3e9ac","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"3.4","title":"Alternative Composition","body":"Organizers decide on the team composition for other types of group battles.","page_from":6,"page_to":6,"stable_key":"buhurt-regulations:3.4","parent_key":"buhurt-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"26241ac912d1945593e1e602268677a8ca32279f2a795137792370bc53bc3ec4","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":0,"kind":"section","number":"4","title":"Match Structure","body":"","page_from":7,"page_to":7,"stable_key":"buhurt-regulations:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5347f4727a919f7a4b2763be4db72b5788ae895725107edb7cb1fe03a8a31523","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"4.1","title":"Match and Round Win Criteria","body":"A match is won when a team secures victory in 2 rounds before the opposing team.\nA round is stopped when a team is outnumbered by a ratio of 3 to 1, with a round victory going to the outnumbering team.\nEach fighter still standing will be recorded in the scoresheet.\nExamples:\n3 vs 1 : stop fight and record “3-1” 6 vs 2 : stop fight and record “6-2” 3 vs 2 : continue the fight","page_from":7,"page_to":7,"stable_key":"buhurt-regulations:4.1","parent_key":"buhurt-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2"],"content_sha256":"c29a58547401de785c6348801c88916bb7ba12aa4b0a55bec6c5073ff1fb34db","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"4.2","title":"Group Stage","body":"Time Limit for Each Match: 10 minutes.\nTime Limit for Each Round: 5 minutes.\nIf the time limit is reached, the team with the most active (not grounded) competitors wins.\nIf the match ends in a draw (provided the number of round victories was a draw), record the match as a draw.","page_from":7,"page_to":7,"stable_key":"buhurt-regulations:4.2","parent_key":"buhurt-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d0a06b684ebee4e8804c76683fcc68f09651c7e23877aa3823ae2158f1a41262","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"4.3","title":"Round Robin, Elimination Brackets, Semi-finals, and Finals","body":"A match cannot end in a draw.\nTime Limit for Each Match: Unlimited.\nTime Limit for Each Round: 5 minutes.\nIf the time limit is reached, the team with the most active (not grounded) competitors wins.","page_from":7,"page_to":7,"stable_key":"buhurt-regulations:4.3","parent_key":"buhurt-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5cea0dbd483f2548fcbc1d755b82027b60522b0b70e0a7cc7ef405534f61cbf7","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":2,"kind":"rule","number":"4.3.1","title":"Resolving a Draw in a match","body":"● Initial Rounds ○ If no team wins two rounds after the first two rounds, a third round is fought.\n\n● Third Round ○ During the third round:\n○ If both teams have only one competitor left standing, the fight stops upon a 'Hold' command.\n○ The timer is paused.\n○ Competitors are led to the middle of the list. Then initiate the Champions Fight ○ A winner is determined according to the rules of the ‘Champion’s Fight’.\n○ If the third round ends in a draw, a fourth round is fought.\n\n● Fourth Round ○ During the fourth round:\n○ If both teams have only one competitor left standing, the fight stops upon a 'Hold' command.\n\n○ The timer is paused.\n○ Competitors are led to the middle of the list. Then initiate the Champions Fight ○ A winner is determined according to the rules of the ‘Champion’s Fight’.\n○ If the fourth round ends in a draw, a fifth round is fought.\n\n● Fifth Round ○ The rules of the 'Champion’s Fight' are applied.\n○ Teams are allowed to select a competitor to represent them in this final round.\n○ If the fifth round ends at a draw, repeat this process.","page_from":7,"page_to":8,"stable_key":"buhurt-regulations:4.3.1","parent_key":"buhurt-regulations:4.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0d0fbd91a0fa8677210764fea619a24b0cba29471a2561cf0053efbb73d293aa","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"4.4","title":"Champion's Fight Rules","body":"The Champion's Fight follows the general rules for group fights with specific adjustments and limitations.","page_from":8,"page_to":8,"stable_key":"buhurt-regulations:4.4","parent_key":"buhurt-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3b7dfb3513a8da6dc57ab10244d6a4b86515d2b763476a94500c8176533f58d9","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":2,"kind":"rule","number":"4.4.1","title":"General Setup","body":"The fight begins with both competitors positioned in the middle of the list.","page_from":8,"page_to":8,"stable_key":"buhurt-regulations:4.4.1","parent_key":"buhurt-regulations:4.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4810ebc406a1fdf105a86fbbe70b1cf84554a850dcf5bdd4a9e33acd57a73d9f","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":2,"kind":"rule","number":"4.4.2","title":"Time Limit","body":"There is no time limit for the Champion's Fight. The fight continues until a winner is determined.","page_from":8,"page_to":8,"stable_key":"buhurt-regulations:4.4.2","parent_key":"buhurt-regulations:4.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2511dae3c17ea90d3ae62b4cc987d40dbeb26649571bc6268ba7d0f8ab137003","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":2,"kind":"rule","number":"4.4.3","title":"Prohibited Actions","body":"It is strictly prohibited to touch the barrier of the list with any part of the body, including:\n● Extremities (arms, hands, legs, feet),\n● Head,\n● Shield.\n\nA competitor who touches the barrier of the list with any of these parts is immediately declared the loser of the fight.","page_from":8,"page_to":8,"stable_key":"buhurt-regulations:4.4.3","parent_key":"buhurt-regulations:4.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c0e8712552bd7058a6fa768e9b4fa01b4dace1396d31282601cc7eef75dfbc88","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":2,"kind":"rule","number":"4.4.4","title":"Permitted Actions","body":"Weapons are allowed to make contact with the barrier of the list during the fight.","page_from":8,"page_to":8,"stable_key":"buhurt-regulations:4.4.4","parent_key":"buhurt-regulations:4.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e674b0e77d085ea78be16a9d276b7042723231bff7f55ac4576a669b9783ee40","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":2,"kind":"rule","number":"4.4.5","title":"Victory Conditions","body":"A competitor loses the fight if:\n● They touch the barrier of the list as described above.\n● They are otherwise defeated according to the rules of group fights.","page_from":8,"page_to":8,"stable_key":"buhurt-regulations:4.4.5","parent_key":"buhurt-regulations:4.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7007f9f252ff58f29544e87d68cfeabfe2ffdacc7f6fa99b6dbc769ec5651a65","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":0,"kind":"section","number":"5","title":"Fight Procedure","body":"","page_from":9,"page_to":9,"stable_key":"buhurt-regulations:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9e042e10cc6c67b083eb1efac5bfba422afcbd48d28e85b713f9cc50f45053fd","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":1,"kind":"rule","number":"5.1","title":"Before the fights","body":"","page_from":9,"page_to":9,"stable_key":"buhurt-regulations:5.1","parent_key":"buhurt-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7b23f9a04faa9a5872075a492fd00e3917271ad7bec717998f08ef3782213e67","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":2,"kind":"rule","number":"5.1.1","title":"Weapon and Shields Check","body":"A weapon check is conducted by Marshals and Authenticity Rep before the fights for every tournament.\nAll weapons and shields are to be checked to ensure their safety and authenticity compliance.\nOnly weapons and shields marked as approved during this check are allowed in the list and as reserve weapons handed by teams’ supports.","page_from":9,"page_to":9,"stable_key":"buhurt-regulations:5.1.1","parent_key":"buhurt-regulations:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"200d76815c1eb38ae9d5104b7630e893e1a6bf5190429f999a21282a116aa8b4","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":2,"kind":"rule","number":"5.1.2","title":"Authenticity and Safety Check","body":"Depending on the rank of the tournament, every fighter of each team has to undergo an Authenticity check of their armor before entering the list.\nThis check will be conducted by an Authenticity Rep.\nA marshal can also be part of this check, to ensure the safety aspect of the armor (example: a check of the neck protection).","page_from":9,"page_to":9,"stable_key":"buhurt-regulations:5.1.2","parent_key":"buhurt-regulations:5.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"757e81a87a6ccb9cb57163bd0eae7b54375aedd7f6231470ae4b51751ebd7cfd","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":1,"kind":"rule","number":"5.2","title":"Entering the list","body":"","page_from":9,"page_to":9,"stable_key":"buhurt-regulations:5.2","parent_key":"buhurt-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"361b775847286dafce26a977ade9c40abd901ee267482b755ee77815f2401c18","has_figures":false,"extraction":"text"},{"ordinal":38,"depth":2,"kind":"rule","number":"5.2.1","title":"Team Invitation and Preparation","body":"The Knight Marshal (either directly or via the Secretary) invites the 2 teams to the list and announces their preparation.\n\nThe two invited teams must report to the designated area next to the list for Invited teams are expected to report to the list within 1 minute.\n\nIf a team fails to report to the list within 3 minutes, their opponent is awarded a technical win of the match or the fight starts with an uneven number of competitors (example: 5-4, 5-3…).","page_from":9,"page_to":9,"stable_key":"buhurt-regulations:5.2.1","parent_key":"buhurt-regulations:5.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6f86dceaaab01c59c34991870440d6a9fe18b512a24f4a0577ddf2c31b524626","has_figures":false,"extraction":"text"},{"ordinal":39,"depth":2,"kind":"rule","number":"5.2.2","title":"Identity Verification","body":"The Knight Marshal can request competitors to enter the list with their helmets off.\nOnce the competitors identities are verified:\n● They are given 90 seconds to put on their helmets and prepare for the fight.\n● Support outside of the list may assist competitors during this preparation phase.\nCompetitors are not allowed to leave the list before the start of the fight. This measure ensures that no unregistered competitors are fielded by the team.","page_from":9,"page_to":9,"stable_key":"buhurt-regulations:5.2.2","parent_key":"buhurt-regulations:5.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"092982914972b7fe96279147a0f6fb40035c06b62b696a43896499734d573871","has_figures":false,"extraction":"text"},{"ordinal":40,"depth":2,"kind":"rule","number":"5.2.3","title":"Line up","body":"The competitors enter the list prepared for the match and form a line for the marshal check.\n\n● 5v5: Competitors form a single line.\n● 12v12: competitors form 2 rows of 6 competitors, keeping column alignment\n● 30v30: competitors form 3 rows of 10 competitors, keeping column alignment.\n● The formations for other types of fights must be documented in the Tournament Regulations or determined by the Knight Marshal.\n\nEveryone, except for the Knight Marshal, field marshals, competitors, and a Team Manager (captain, coach), leaves the list.\nThe Team Manager (captain, coach) counts their competitors and reports readiness to the Knight Marshal.\nThe Knight Marshal checks the number of competitors on each team.","page_from":9,"page_to":10,"stable_key":"buhurt-regulations:5.2.3","parent_key":"buhurt-regulations:5.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"27f62bdd8eb51087e27faacfb73e15434f63e468da8180f0f33649e19938d8a9","has_figures":false,"extraction":"text"},{"ordinal":41,"depth":2,"kind":"rule","number":"5.2.4","title":"Marshal Check","body":"Once positioned in the line up (or at the gate entrance, depending on the tournament organization) each fighter will be submitted to a marshal check.\nWill be verified:\n● the approval mark on their weapons/shields,\n● the strap securing their helmets,\n● the protection of their neck,\n● any other safety element marshals wish to verify.","page_from":10,"page_to":10,"stable_key":"buhurt-regulations:5.2.4","parent_key":"buhurt-regulations:5.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f2cebe26967e42107e8f1bce3101a0e731cd48da7823a022b6a34c3ac2b74db0","has_figures":false,"extraction":"text"},{"ordinal":42,"depth":1,"kind":"rule","number":"5.3","title":"Starting the fight","body":"Team Managers (captains, coaches) leave the list.\nField Marshals take positions behind the teams’ formations near the gates.\nThe Knight Marshal requests field marshals to signal readiness and absence of unauthorized participants in the list.\nThe Knight Marshal commands:\n● “Team ready”: Teams can then assume their positions.\n● “Fight“, accompanied by a flag signal: fight begins.","page_from":10,"page_to":10,"stable_key":"buhurt-regulations:5.3","parent_key":"buhurt-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7f1b7451eae3e2a708543e7485b4d771a3d3f236efdd6ce186e6ce7333ab4b19","has_figures":false,"extraction":"text"},{"ordinal":43,"depth":1,"kind":"rule","number":"5.4","title":"During the fight","body":"","page_from":10,"page_to":10,"stable_key":"buhurt-regulations:5.4","parent_key":"buhurt-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"26887fdc1385a5e5bf25f1b5bf305345ec28bf1e34f4648dee8857d0d3ca85b9","has_figures":false,"extraction":"text"},{"ordinal":44,"depth":2,"kind":"rule","number":"5.4.1","title":"Grounding a Competitor","body":"Both the Knight Marshal and Field marshals can ground a competitor from the list in the following cases:\n● Multiple verbal warnings being ignored in a round.\n● Multiple Prohibited Fighting Techniques or Other Prohibited Actions.\n● Grounding your opponent by an illegal action where your opponent is unable to immediately rejoin the round.\n● Being grounded does not replace other penalties (e.g., yellow or red cards)\n\nGrounded competitors must remain on the ground until the Knight Marshal commands “All Rise.” After the “All Rise” command, teams return to their initial positions.","page_from":10,"page_to":10,"stable_key":"buhurt-regulations:5.4.1","parent_key":"buhurt-regulations:5.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f3be1de890ed6b92a4be8419ff1f40f33ecf643c49e3ef883df232bed376c1c9","has_figures":false,"extraction":"text"},{"ordinal":45,"depth":2,"kind":"rule","number":"5.4.2","title":"Removing Competitor from the list","body":"Both the Knight Marshal and field marshals must withdraw a competitor from the list in the following cases:\n\n● A competitor continues offensive actions after being grounded.\n● A competitor loses their helmet.\n● A Knight marshal can remove a competitor if they deem necessary.","page_from":11,"page_to":11,"stable_key":"buhurt-regulations:5.4.2","parent_key":"buhurt-regulations:5.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"55625a7b45e9407b253fb586cc0eb0be6e94f813ef66740a52171b6fd0425265","has_figures":false,"extraction":"text"},{"ordinal":46,"depth":1,"kind":"rule","number":"5.5","title":"End of the round or fight","body":"A round is finished only after the Knight Marshal’s command of \"Stop fight!\"\n\nMarshals report any rules violations to the Knight Marshal.\n\nThe Knight Marshal can, based on these reports and personal observations:\n\n● Decide the result.\n● Processes appeals.\n● Announce the score of the round or fight.\n● Imposes warnings, yellow cards, or red cards.\n\nAfter the end of the round or fight, the Knight Marshal can:\n\n● Declare the round finished and announce the score.\n● Announce a rematch with full or differentiated teams (e.g., 2v3, 3v4, 4v4, 4v5) if deemed necessary.","page_from":11,"page_to":11,"stable_key":"buhurt-regulations:5.5","parent_key":"buhurt-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"efb203366bdd458d1544f6c3a14bb888847905c87c1a126709bdb6162ff2f13a","has_figures":false,"extraction":"text"},{"ordinal":47,"depth":1,"kind":"rule","number":"5.6","title":"Forfeit procedure","body":"A team manager (captain, coach) can throw a white flag “forfeit\" to signal the Knight Marshal to stop the fight.\nIn such cases:\n● The opponents are awarded a technical win.\n● The number of active competitors in the list is recorded as 5-0.\n\nThe first white flag results in a round loss.\nThe second white flag results in a match loss.\nAfter the third white flag, the team is withdrawn from the tournament.","page_from":11,"page_to":11,"stable_key":"buhurt-regulations:5.6","parent_key":"buhurt-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"96f33a2cfad78ea3faa163a0746fe19c46a0ebee2a4745ab3ce02abff7909741","has_figures":false,"extraction":"text"},{"ordinal":48,"depth":1,"kind":"rule","number":"5.7","title":"Record Keeping","body":"The secretary records the results. At the end of the round, the secretary registers:\n● The round win.\n● The round score (number of active competitors of the both teams at the end of the round).\n● The time of the round.\n● The warnings, cards and appeals","page_from":11,"page_to":11,"stable_key":"buhurt-regulations:5.7","parent_key":"buhurt-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9563f450b795cec2d0e5d956ec63c474ffbf4560e9eaee24b7009dae56413a49","has_figures":false,"extraction":"text"},{"ordinal":49,"depth":0,"kind":"section","number":"6","title":"Penalties","body":"","page_from":12,"page_to":12,"stable_key":"buhurt-regulations:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fa9929f30982b06fa5897370d34355b23fffa99d5719967eb9b9893ee1839b1c","has_figures":false,"extraction":"text"},{"ordinal":50,"depth":1,"kind":"rule","number":"6.1","title":"Verbal Warning","body":"A verbal warning is imposed for insignificant rule violations and serves to indicate the violation to the competitor.\nThe verbal warning is recorded on the scoresheet with the following info:\n● belt flag number of the competitor,\n● name of the competitor,\n● description of the warning.\n\nA verbal warning can’t affect scoring.","page_from":12,"page_to":12,"stable_key":"buhurt-regulations:6.1","parent_key":"buhurt-regulations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"90e9fa6822b75b84850a919344ab109a43d5990f24f456698e110ffb85807e6b","has_figures":false,"extraction":"text"},{"ordinal":51,"depth":1,"kind":"rule","number":"6.2","title":"Warning (Yellow Card)","body":"A yellow card is recorded on the scoresheet with the following info:\n● belt flag number of the competitor,\n● name of the competitor,\n● description of the card.\n\nA yellow card can affect the scoring.","page_from":12,"page_to":12,"stable_key":"buhurt-regulations:6.2","parent_key":"buhurt-regulations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"18d19104f37f4a08696c0063771a5b531f2dc1dd8c7ad8ff271e91db5b9f0c56","has_figures":false,"extraction":"text"},{"ordinal":52,"depth":2,"kind":"rule","number":"6.2.1","title":"Reasons for Receiving a Yellow Card","body":"● The competitor delivered a prohibited action listed in the “Buhurt Rules” document.\n● The competitor performed an action not listed in the Authorized Fighting Techniques section listed in the “Buhurt Rules” document.\n● The competitor got to their feet from being grounded before the command “All Rise.”\n● The competitor started the fight before the “Fight” command.\n● The competitor conducted offensive actions after the “Stop Fight” command and while the yellow flag was hung in front of their helmet.\n● The competitor purposely ignored a marshal’s command.\n● The competitor continued to fight while aware that they had lost a significant element of their armor.","page_from":12,"page_to":12,"stable_key":"buhurt-regulations:6.2.1","parent_key":"buhurt-regulations:6.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3ee3d150f8ba3b1a482f5c1520e75053b637d77fcbe0ea3d65a55be26a7c4514","has_figures":false,"extraction":"text"},{"ordinal":53,"depth":2,"kind":"rule","number":"6.2.2","title":"Double Yellow Card","body":"Depending on the severity of the violation, the Knight Marshal may impose 1 or 2 yellow cards for these actions.\nA competitor who receives 2 yellow cards is disqualified.\nTwo yellow cards are equivalent to one red card.","page_from":12,"page_to":12,"stable_key":"buhurt-regulations:6.2.2","parent_key":"buhurt-regulations:6.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"722ad471c0f8b84f317820c0864432a40ef5dcaa313cb88644a04c77b30f78e8","has_figures":false,"extraction":"text"},{"ordinal":54,"depth":1,"kind":"rule","number":"6.3","title":"Disqualification (Red Card)","body":"A red card is imposed for severe rule violations or as a result of receiving a second yellow card.\nThe red card is recorded on the scoresheet with the following info:\n● belt flag number of the competitor,\n● name of the competitor,\n● description of the card.\n\nA red card can affect scoring.\nA competitor who receives a red card is withdrawn from the tournament.","page_from":13,"page_to":13,"stable_key":"buhurt-regulations:6.3","parent_key":"buhurt-regulations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"214695f62162b1f189ccad01bdb0945953bbc03dadaf3d7df16902889ebe72ea","has_figures":false,"extraction":"text"},{"ordinal":55,"depth":2,"kind":"rule","number":"6.3.1","title":"Reasons for Disqualification","body":"● Systematic rule violations (e.g., 2 yellow cards during the tournament).\n● Injuring an opponent with an unauthorized action, resulting in the opponent's inability to continue participating in the tournament (requires confirmation by a medic).\n● Harsh and systematic arguments with marshals, groundless challenging of decisions, or rude/derogatory behavior toward opponents or participants.","page_from":13,"page_to":13,"stable_key":"buhurt-regulations:6.3.1","parent_key":"buhurt-regulations:6.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8bebf0054c6e59f1f3f1a50750575c92cbe3cca0f8499d665104e23a9917efa2","has_figures":false,"extraction":"text"},{"ordinal":56,"depth":2,"kind":"rule","number":"6.3.2","title":"Injury Clause","body":"If an injured competitor continues competing and claims injury later in the tournament, this will not lead to a red card. If the injured competitor participates in any category, the red card will be downgraded, and the Judiciary Committee will investigate and penalties may apply.\nIf a competitor continues to fight in rounds after receiving an illegal hit but later withdraws due to an “injury” claimed to be from the illegal hit, this does not result in an upgrade to a red card.","page_from":13,"page_to":13,"stable_key":"buhurt-regulations:6.3.2","parent_key":"buhurt-regulations:6.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2cca61f7278f9bd85f266898fd847ed76af50c1efac6560ae323c331954288f5","has_figures":false,"extraction":"text"},{"ordinal":57,"depth":2,"kind":"rule","number":"6.3.3","title":"Red Card Consequences for the Team line up","body":"When a competitor is disqualified, their team fields one less competitor than their opposition (but no fewer than 3 competitors) for:\n● The match during which the disqualification was imposed.\n● The next match in the tournament.\n\nExample:\nIf the opposition cannot meet the required number of competitors (e.g., 12 in 12v12), the penalized team will be placed in a disadvantageous position. If both teams receive red cards, neither gains an advantage.","page_from":13,"page_to":13,"stable_key":"buhurt-regulations:6.3.3","parent_key":"buhurt-regulations:6.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"73f82cb17074c6393ee7fd53fa1596a62cb2127795308a9f7f39db0ee3b12a22","has_figures":false,"extraction":"text"},{"ordinal":58,"depth":1,"kind":"rule","number":"6.4","title":"Infraction in Authenticity Rules (Green Card)","body":"An official authenticity warning (green card) is a penalty imposed for an authenticity rule violation that is registered in the protocol of the tournament, and affects the competitor’s rating. A green card combined with a yellow card result in a red card, and the fighter is disqualified.\n\nThe competitor can receive one 1 green card only once they choose to enter the list with the appropriate infraction level based upon the Infraction classification document.","page_from":13,"page_to":13,"stable_key":"buhurt-regulations:6.4","parent_key":"buhurt-regulations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9522d8872513100ac8c86c063512f581ab4e0fe0348e814b1f1ccd9326c43a48","has_figures":false,"extraction":"text"},{"ordinal":59,"depth":1,"kind":"rule","number":"6.5","title":"Team Disqualification","body":"A team may be disqualified under the following circumstances:","page_from":14,"page_to":14,"stable_key":"buhurt-regulations:6.5","parent_key":"buhurt-regulations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"eefee83a50a669f9d360951ef4762b585679ddcd0720b5d070ae2070eff11ff5","has_figures":false,"extraction":"text"},{"ordinal":60,"depth":2,"kind":"rule","number":"6.5.1","title":"Exceeding the permitted number of competitors","body":"In such cases, their opposition is automatically awarded the victory.\nIf this rule violation is detected after the fact, the violating team’s results are annulled.\nIf detected during finals, trophies are withdrawn, and other competitors move up the ladder.","page_from":14,"page_to":14,"stable_key":"buhurt-regulations:6.5.1","parent_key":"buhurt-regulations:6.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"42a4260e3e220e7331ad0d3f43ed66a165270e91baf24e9c8a052b42d73f2663","has_figures":false,"extraction":"text"},{"ordinal":61,"depth":2,"kind":"rule","number":"6.5.2","title":"Card limit","body":"The team competitors, manager and/or support receive a combination of card as followed:\n● Two red cards and one yellow card.\n● Any variation totaling 5 yellow cards (red cards count as two yellow cards).\nThis applies only to the category being competed in.\nGreen cards do not count in team disqualification.","page_from":14,"page_to":14,"stable_key":"buhurt-regulations:6.5.2","parent_key":"buhurt-regulations:6.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5afa4fa096d5f571830694a19c443e2fd7ee1da0b3f345b2ec209c03e0246a5e","has_figures":false,"extraction":"text"},{"ordinal":62,"depth":2,"kind":"rule","number":"6.5.3","title":"Harassment or Systematic Arguing","body":"If a competitor, a team manager or a team support engages in:\n● Harsh and systematic arguments with marshals.\n● Groundless challenges to decisions.\n● Rude or derogatory behavior toward opponents or participants.","page_from":14,"page_to":14,"stable_key":"buhurt-regulations:6.5.3","parent_key":"buhurt-regulations:6.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"acb727e1d5b1e56f6218bfd57bf307c9e61922e019389f86b9992b12b7591cdd","has_figures":false,"extraction":"text"},{"ordinal":63,"depth":2,"kind":"rule","number":"6.5.4","title":"A competitor entered the list after the competitors were counted","body":"","page_from":14,"page_to":14,"stable_key":"buhurt-regulations:6.5.4","parent_key":"buhurt-regulations:6.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ffd7f858322f2d8a58b35ca9542495789b91d31eca4b021b93b878b7e77774f4","has_figures":false,"extraction":"text"},{"ordinal":64,"depth":1,"kind":"rule","number":"6.6","title":"Additional Notes on Cards","body":"All cards are individual warnings and are observed by the Judiciary Committee.\nYellow cards received by a team manager (captain, coach) or support staff result in disciplinary measures per general card regulations.\nCards are summed regardless of the person’s role (competitor, team manager, or support).","page_from":14,"page_to":14,"stable_key":"buhurt-regulations:6.6","parent_key":"buhurt-regulations:6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"03aa1665d5bd51ee65ca63bd03f116ff7bd9e0f597eb2cb6569f7bd0fd75bd34","has_figures":false,"extraction":"text"},{"ordinal":65,"depth":0,"kind":"section","number":"7","title":"Appeal","body":"","page_from":15,"page_to":15,"stable_key":"buhurt-regulations:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"58314bfc897db8a4d815b5af7ab8fd0eaacb86be9c976f280301518e3cd13f1d","has_figures":false,"extraction":"text"},{"ordinal":66,"depth":1,"kind":"rule","number":"7.1","title":"How to Appeal","body":"The team captain or the captain’s representative may appeal a decision made by the Marshals’ Team or the Knight Marshal.\nAppeals are submitted to the Secretary.\nThe number of appeals is determined by the Tournament Organizer.\nIt is recommended to allow 1 appeal.\nImportant: If an appeal is approved, the competitor may submit an additional appeal.","page_from":15,"page_to":15,"stable_key":"buhurt-regulations:7.1","parent_key":"buhurt-regulations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e496cb83bc200a11a48687ee55e6eb727aad751e898f44db3628e6561aa1b754","has_figures":false,"extraction":"text"},{"ordinal":67,"depth":1,"kind":"rule","number":"7.2","title":"When to Appeal","body":"The team captain or captain’s representative must announce their intention to appeal in person to the Secretary.\nAppeals must be submitted:\n● Within 15 minutes after the end of the match.\n● Before the start of the fights in the next phase of the competition.","page_from":15,"page_to":15,"stable_key":"buhurt-regulations:7.2","parent_key":"buhurt-regulations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7d4e866642665f625a4ff375680b75b85a9fa2e9e5d91e5dd4a44d51c1ea030a","has_figures":false,"extraction":"text"},{"ordinal":68,"depth":1,"kind":"rule","number":"7.3","title":"Why to Appeal","body":"An appeal can be filed for the following reasons:\n● False implementation of a penalty (reprimand, warning, or disqualification).\n● Unregistered rule violations by the opponent that should result in a penalty (reprimand, warning, or disqualification).","page_from":15,"page_to":15,"stable_key":"buhurt-regulations:7.3","parent_key":"buhurt-regulations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6012ac7a276b0b50831ff167171fde938346a45896498070cc1dd3fdcae4768b","has_figures":false,"extraction":"text"},{"ordinal":69,"depth":1,"kind":"rule","number":"7.4","title":"Result of the Appeal","body":"The possible outcomes of an appeal could include:\n● A general rematch of the round.\n● Restart from a particular point.\n● The imposition or withdrawal of yellow cards.","page_from":15,"page_to":15,"stable_key":"buhurt-regulations:7.4","parent_key":"buhurt-regulations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fbb03793cfde1555955cdc9576287c856ca63e55288487ff615fd6e01f96824c","has_figures":false,"extraction":"text"},{"ordinal":70,"depth":1,"kind":"rule","number":"7.5","title":"Appeal to the Judiciary Committee","body":"If the team captain is dissatisfied with the Knight Marshal’s decision, they may appeal to the Buhurt International Judiciary Committee.","page_from":15,"page_to":15,"stable_key":"buhurt-regulations:7.5","parent_key":"buhurt-regulations:7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6fbe39d6cde4aa628667b12192d0b6f2c4a923090a4ce78f1ce99999b9fd04f5","has_figures":false,"extraction":"text"},{"ordinal":71,"depth":0,"kind":"note","number":"8","title":"Changelog","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nApril - 2026 (V. 26.4) Formatting redone for consistency and readability. Except points listed below, no content changes.\nGrammatical corrections were also made.\nClarification:\n- Section 2. Marshal Structure removed from the Rules and added to the Regulations\n- Complete reorganisation of old “4. Preparation for the Match”, now “5. Fight Procedure”\n\nUpdate: January -2026.1 Add: 3.2 On scoresheet you will record 3-1 ratio Clarification: 3.4.1 Champions Fight Add: 5.1 Verbal Warning\n● A verbal warning is imposed for insignificant rule violations and serves to indicate the violation to the competitor. Record on the scoresheet\n● Collect belt flag number, description of warning, name of competitor\n● Cannot affect scoring Clarification: 5.2 and 5.3\n\nupdate: March-2025 (V2025.03) Clarification: 2.3: Added competitors amount per category Add: 5.4 Infraction in Authenticity Rules (Green Card) Removed: 5.2.1: The competitor used equipment in the list that had not passed technical or authenticity checks.\nRemoved: 5.2.2: A competitor is not allowed in the list if they fail to follow the Buhurt International requirements documents.\nClarification: 5.4.2 Note: green cards do not count in team disqualification\n\nupdate: December-2025 -add: Document created following BI Format and incorporated the document structures and rules","page_from":16,"page_to":16,"stable_key":"buhurt-regulations:8","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["2"],"content_sha256":"c06e9884a6ae97114762c3b50a7c8b207705f8f04bc11e1e9657ad48a19716d1","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"tournament/duel-regulations","synthetic":false,"version":{"version":"26.4","title":"Duels Regulations 26.4","published_on":null,"effective_from":null,"note":"Every page footer \"V. 26.4\"; changelog entry \"April - 2026 (V. 26.4)\".","source_url":"https://drive.google.com/file/d/1gr2EmgMvo5SprZo46vBgGKWOOg6m7bTx/view?usp=drive_link","source_sha256":"16078b6f655167ed3cf3923c8cbc004a8585e6548fbd1e477c806d83c39f1392","retrieved_at":"2026-10-06T00:00:00Z","page_count":10,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"72dd7a568051e689a20afcd4de44113be150fa366f7a5741667f8189b05e53c8","detected":{"version":"26.4","date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":10,"source_lines":262,"assigned_lines":299,"furniture_lines":38,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99732,"provisions":29,"numbered":28,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"duel-regulations:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"General Provisions","body":"","page_from":3,"page_to":3,"stable_key":"duel-regulations:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d3460a1bce22168eb4fc581713c7f54838f7f6aa5be599e1b9b2b4e8ddc14938","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"List Regulations","body":"Fights of the Buhurt International duel categories Triathlon, Sword and Buckler, Sword and Shield, Polearm are held in hard-surface lists.\nDimensions:\nLength and width: 5 to 10 m.\nHeight of the barrier: 0.9 to 1.3 m.\nThere must be a fenced, 2m-wide safety zone around every side of the list.\n\nLists that deviate from those requirements need to be approved beforehand by a representative of the Buhurt International Marshal Committee.\n\nAre permitted into the safety zone during the fights only:\n● Marshals,\n● Competitor support (1 person only),\n● Secretaries,\n● Technical staff (List maintenance),\n● Media (Only approved media staff).\n\nAccessing the safe zone without a designated role above may result in a penalty (yellow card) for the individual.","page_from":3,"page_to":3,"stable_key":"duel-regulations:1.1","parent_key":"duel-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"17704c846803e70a42457445aa1f5d9e7fa0c504491e1578fc7c1b39e1529582","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Weight categories","body":"There are no weight categories in the duel category.","page_from":3,"page_to":3,"stable_key":"duel-regulations:1.2","parent_key":"duel-regulations:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"50561c1faedb2e69e10b3ffff6ab52b4f6c60b3143169a526b33f858eac4e89d","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":0,"kind":"section","number":"2","title":"Marshals Committee","body":"The team of Marshals includes:","page_from":4,"page_to":4,"stable_key":"duel-regulations:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4be8b2ffda8ea3a9f4c559ee9ce488d01f38840e4838fdfdfda8ad7c92fbbc80","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"2.1","title":"One Knight Marshal (Chief Official/Head Referee)","body":"● Observes the general course of the fight and assesses actions of the competitors in the list.\n● In case of disagreement, the Knight Marshal makes the final decision.\n● Only the Knight Marshal can interfere with the course of the fight.","page_from":4,"page_to":4,"stable_key":"duel-regulations:2.1","parent_key":"duel-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"80659fb4ed783344e73a63b75922b2cbdb1a98e37989902995464e066cd8a181","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"2.2","title":"Four Line Marshals (Fight Officials/Referees)","body":"● Supervise the fight and score the clean blows delivered to the permitted strike zones.\n● Take note of rule violations committed during the fight.\n● Cannot interfere with the fight.","page_from":4,"page_to":4,"stable_key":"duel-regulations:2.2","parent_key":"duel-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"08f45d64db64367530c0c410787c99c564a7ef6117a409a162a125c5f48f9402","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"2.3","title":"One Timekeeper","body":"● Times the rounds of the fight.\n● If the Knight Marshal halts the fight, the Timekeeper stops timing the round and resumes timing when the fight resumes.\n● Registers the results of the round in rating protocol.","page_from":4,"page_to":4,"stable_key":"duel-regulations:2.3","parent_key":"duel-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"22bad310ce1c5a43b441d0a7c7c55b2b63ac7af9e693470905fe0e8c11a78d56","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.4","title":"One Authenticity Committee Representative (AC Rep)","body":"● Authenticity representative who will perform on location AC checks.","page_from":4,"page_to":4,"stable_key":"duel-regulations:2.4","parent_key":"duel-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7babb71b1dbcfb3a276ae782d3df09912f01f423f2f5bd9314b314e2a2aae937","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"2.5","title":"One Videos Supervisor","body":"","page_from":4,"page_to":4,"stable_key":"duel-regulations:2.5","parent_key":"duel-regulations:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c812f491fa46be2d1af4d17df3ef5d11811f6a06661c2df419dc68ecd6723f69","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":0,"kind":"section","number":"3","title":"Fight Proceedings","body":"","page_from":5,"page_to":5,"stable_key":"duel-regulations:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"176af81a5c990c7e8f3f01362a9a04513591ed7ec464da362b11ecc3c2c206c8","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"3.1","title":"Preparation for the fight","body":"The Knight Marshal invites the competitors to report to the designated area of the list to pass pre-fight, authenticity, aesthetic, and technical equipment checks. They announce the competitors preparing for the next fight.\n\nInvited competitors are granted up to 60 seconds to report to the list.\n\nThe Knight Marshal can ask the competitors to enter the list with their helmets off. When the correspondence between the competitors present in the list and competitors registered for the fight has concluded, they will then be given an additional 30 seconds to put on their helmets and prepare for the fight. Seconds (assistants) outside the list can assist the competitors in preparation. The competitors are not allowed to leave the list before the start of the fight. This measure excludes the possibility of team roster replacement.\n\nThe Knight Marshal requests marshals and competitors to confirm their readiness.\n\nThe Knight Marshal signals the beginning of the fight with the command “Fight!”.","page_from":5,"page_to":5,"stable_key":"duel-regulations:3.1","parent_key":"duel-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"140b43df7baf87e026ea34878e758e94428bb7f92731ac222526a7510bfad51f","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"3.2","title":"Characteristics of each category","body":"The organizers can alter the length of the fights/number of rounds/orders of the rounds (one category, triathlon, four fights type of competition) provided this decision is coordinated with the Head Organization and is registered in the Tournament Regulations.\n\n| Category | End of round | Break between rounds | Fight victory | Technical win |\n| --- | --- | --- | --- | --- |\n| Longsword | 60 seconds of effective time and the “Stop fight” command of the Knight Marshal | 30 seconds to rest | Total score from two (2) main rounds and an additional 30-second round in case of a tie.<br>The score must have at least a 2 point difference. | 10-0 |\n| Sword and shield | ^ | ^ | ^ | ^ |\n| Polearms | ^ | ^ | ^ | ^ |\n| Triathlon | ^ | 30 seconds to rest .<br>120 seconds to change their equipment if needed | Total score from three (3) main rounds |  |\n| Sword and buckler | 5 clean blows delivered by one competitor during the round or 60 seconds of effective time | No break | Achieve two (2) round victories<br>An additional round may be fought in case of a tie. | 5-0 |","page_from":5,"page_to":5,"stable_key":"duel-regulations:3.2","parent_key":"duel-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a9cd3c1e0d32d531810366f2dffc9f875954c6a2fbb2f437a7c568fb4910f0f","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"3.3","title":"End of the round","body":"All marshals in the list report to the Knight Marshal to announce the score and any rule violations. Based on the marshals’ reports and personal observations, the Knight Marshal makes a decision about the result of the round by:\n● Processing the appeals (if any were submitted).\n● Issuing penalties (reprimands, warnings, and disqualification) to the competitors.\nAnnouncing the result of the round.","page_from":6,"page_to":6,"stable_key":"duel-regulations:3.3","parent_key":"duel-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"55c2bff496bd41fd3fc68187055a13f6221253a0eb65b66e02208cfbc4ed87be","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":1,"kind":"rule","number":"3.4","title":"End of the fight","body":"When the conditions of fight victory are reached, the winner of the fight is announced.\nThe Secretary registers the results of the rounds in rating protocol:\n● The round victory\n● The round score\n● Match victory\n● 2-point difference for Polearm | Sword and Shield | Longsword Example: total score competitor A 10, competitor B 11 no winner additional round needed total score competitor A 15, competitor B 13, winner is competitor A\n● Yellow and red cards in the competitor’s rating The winner is documented on the scoresheet. The rest of the rating scores (victories in the rounds, number of cards) are considered only in case of a draw in points.\nProvided the competitors are informed in advance, the number of rounds and break time can be decreased under extraordinary circumstances.","page_from":6,"page_to":6,"stable_key":"duel-regulations:3.4","parent_key":"duel-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3e9686326d245d1e9762e00ff7b8ff87e634f06d2a097b7bf4eeaa153a68756b","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"3.5","title":"Technical win","body":"A technical victory is awarded to one of the competitors in the following cases:\n● If the opponent withdraws from the fight before it starts.\n● If the opponent fails to report to the list upon the Knight Marshal’s call.\n● If the opponent fails to repair the equipment within the designated time.\n● If the opponent cannot participate in the competition because of an injury or disqualification (2 Yellow cards or Red card).\nIf the opponent injures the competitor with an illegal strike, the competitor receives a penalty of double yellow cards and is disqualified.\n● If the opponent has an equipment failure (weapon and armor) that is impossible to fix in 1 minute.\nAssessment is made by the Knight Marshal.\n● If the opponent gains 3 reprimands during one fight.","page_from":6,"page_to":6,"stable_key":"duel-regulations:3.5","parent_key":"duel-regulations:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["1"],"content_sha256":"9d762e9eac6f2a63a64f7eb1065405fc8994a1a72a55385ec262d12667a87e11","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":0,"kind":"section","number":"4","title":"Penalties","body":"","page_from":7,"page_to":7,"stable_key":"duel-regulations:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bcfa77d805fe5b0fc96ec3b2f7e2d5ca1e73ea0a3a85f245c34f8e0b9e69aabd","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":1,"kind":"rule","number":"4.1","title":"Verbal warning","body":"A verbal warning is a penalty imposed for insignificant rules violation, aiming at indicating the rules violation to the competitor.\nA verbal warning is not registered in protocols.","page_from":7,"page_to":7,"stable_key":"duel-regulations:4.1","parent_key":"duel-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"45275182df5fe7ec8f864342e52d9e619102675c7bfd36d989ec0a776f2ea484","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"4.2","title":"Reprimand","body":"A reprimand to a competitor will result in 3 points added to their opponent’s score, except for buckler where only 1 point will be added.\nThe points gained because of the reprimand are registered separately in the rating.\nReprimands are not noted in the tournament protocol and personal records of the competitors.\nThe competitor receives a reprimand in case of:\n● Failing to report to the list within the designated time frame (one (1) minute) but still fighting that match.\n● A fall that was caused by offensive actions of the opponent, provided they were conducted in accordance with the ruleset.\n● Armor (not weapon or shield) failure that prevents the competitor from continuing the fight. If the issue was fixed within the one minute time limit (, the fight can continue. The decision on the severity of the Armor failure and time limit is made by the Knight Marshal.\n● Weapon loss during the fight.\n● Passive attitude. A competitor’s refusal to conduct offensive actions during the length of time (not less than 15 seconds) is considered a passive attitude.\n● Falling or stepping outside the boundaries of the list.","page_from":7,"page_to":7,"stable_key":"duel-regulations:4.2","parent_key":"duel-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["3"],"content_sha256":"99094eb07f3828e4fff8171ca777f9324bacb707fefcb0c7f4b56ae47bb67278","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":1,"kind":"rule","number":"4.3","title":"Yellow Card","body":"An official warning (yellow card) is a penalty imposed for a rule violation that is registered in the protocol of the tournament, and affects the competitor’s rating. A competitor can receive up to two (2) yellow cards within a tournament before disqualification.\nThe competitor can receive 1 or 2 yellow cards for all following actions, depending on the severity of the violation and the Knight Marshals’ decision:\n● A competitor performs any illegal action listed in the Rules for the Triathlon, Longsword, Sword and Buckler, Sword and shield, and Polearm categories.\n● A competitor performs any action not listed in the authorized techniques section of the Rules for the Triathlon, Longsword, Sword and Buckler, Sword and shield, and Polearm categories.\n● A competitor enters the list with unauthorized equipment\n● For a demonstration of poor sportsmanship, derogatory behaviour, obscene language, comments directed at marshals, opponents, or spectators.\n● A competitor enters the safety zone during fights.\n\n● A competitor starts the fight before the “Fight” command.\n● A competitor performs offensive actions after the “Stop Fight” command.\n● A competitor ignores the Knight Marshals’ orders.","page_from":7,"page_to":8,"stable_key":"duel-regulations:4.3","parent_key":"duel-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dbd358637b3efba0fa99a2fe1536f7dc9c86dd075216957bbf076eef73f30fe7","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":1,"kind":"rule","number":"4.4","title":"Red Card","body":"Disqualification (red card) is a penalty resulting from severe or regular (second yellow card) rule violations and is registered in the tournament protocol.\nThe red carded competitor will be withdrawn from the tournament.\nOnly the Knight Marshal of the tournament can apply red cards. The competitor receives a disqualification in case of:\n● Systematic rule violations (2 yellow cards during the tournament).\n● Injuring the opponent with illegal strikes. However, if marshals or medics ascertain that an injury has been simulated, the struck competitor may receive a red card as a result of serious foul play.\n● Harsh and systematic arguments with marshals, groundless challenging of Marshals’ decisions, rude and derogatory attitude to the opponents and other participants of the competition.","page_from":8,"page_to":8,"stable_key":"duel-regulations:4.4","parent_key":"duel-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2606e63d76d8c64869974d09d07dff05bdc12ab33e7e9cb5a5f7585db74f2d95","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"4.5","title":"Green Card","body":"An official authenticity warning (green card) is a penalty imposed for a rule violation that is registered in the protocol of the tournament, and affects the competitor’s rating. A competitor can only receive 1 green card and then a yellow card within a tournament before disqualification.\nThe competitor can receive one 1 green card only once they choose to enter the list with the appropriate infraction level based upon the Infraction classification and application document.","page_from":8,"page_to":8,"stable_key":"duel-regulations:4.5","parent_key":"duel-regulations:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8490140bf344b305a4b62d3abb44ae8640c5cec60c50a4e80aecd6f6abd98589","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":0,"kind":"section","number":"5","title":"Appeal","body":"","page_from":9,"page_to":9,"stable_key":"duel-regulations:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5b97781591e96230dc64f8bb2091874eeb25c23fb84afa7a290cc5a3624ee200","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"5.1","title":"How to appeal","body":"The competitor or the competitor’s representative can appeal a decision made by the Marshals’ Brigade or the Knight Marshal.\nAppeals are submitted to the Secretary.\nThe number of appeals is determined by the Tournament Organizer.\nIt is recommended to allow 1 appeal.\nImportant: If an appeal is approved, the competitor may submit an additional appeal.","page_from":9,"page_to":9,"stable_key":"duel-regulations:5.1","parent_key":"duel-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ffbd49527121a963c8fd344c1321dc8918c2ae658ed4ca6ac62a3363ca939891","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"5.2","title":"When to appeal","body":"The competitor or the competitor’s representative must announce the intention to appeal to the Secretary in person.\nAn appeal must be submitted within 15 minutes after the end of the fight, before the start of the fights of the next phase of the competition.","page_from":9,"page_to":9,"stable_key":"duel-regulations:5.2","parent_key":"duel-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1c1e83d4d94d132b2cac860e7642bea51420a0de4a1400714479ebcb01983a1a","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":1,"kind":"rule","number":"5.3","title":"Why to appeal","body":"An appeal can be filed according to the following reasons:\n● False implementation of a penalty (reprimand, warning, or disqualification).\n● Unregistered clean blows to the legal strike zones that affect the course of the fight.\n● Unregistered rule violations by the opponent that should result in a penalty (reprimand, warning, disqualification).","page_from":9,"page_to":9,"stable_key":"duel-regulations:5.3","parent_key":"duel-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"32a4ebbc05a4572032979251d23e715e052b3d24e0865aa6ae45eb1528747413","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"5.4","title":"Result of the appeal","body":"The possible results of the appeal are:\n● A general rematch of the round.\n● Imposing, or withdrawal of yellow cards","page_from":9,"page_to":9,"stable_key":"duel-regulations:5.4","parent_key":"duel-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3738639876b27c42fff1018bbfc81220994e4dc1eb4270094fafcd182eb2ae31","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"5.5","title":"Appeal to Judiciary Committee","body":"If the Team Captain is dissatisfied with the Knight Marshal's decision, they can appeal to the Buhurt International Judiciary Committee.","page_from":9,"page_to":9,"stable_key":"duel-regulations:5.5","parent_key":"duel-regulations:5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7dab29bc6bbe018872a49d832d9c32445b137afcfd845ddd26ab18476dd931d6","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":0,"kind":"note","number":"6","title":"Changelog","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nApril - 2026 (V. 26.4) Formatting redone for consistency and readability. Except points listed below, no content changes.\nGrammatical corrections were also made.\n- Add:\n- 1.1. List Regulations”: “Lists that deviate from those requirements need to be approved beforehand by a representative of the Buhurt International Marshal Committee.”\n\nJanuary 2026(2025.02 to 2026.1) -add: 4.2 except for buckler where only one (1) point will be added.\n\nFebruary 2025 (Version update from 2024.12 to 2025.02)\n- Add: Green card rules\n- Adjustment: sword buckler technical win from 2 to 5 points\n\nDecember 2024 (Version update from 2024.06 to 2024.12)\n- Add: 6.2 to the Secretary in person\n- Delete: 6.2 to the Knight Marshal in person\n- Delete: 5: Authorized equipment (moved to Duels rules document)\n- Delete: 6.2 An appeal is submitted directly after the end of the fight and is announced when the Knight Marshal requests for any objections before the competitor has left the list.\n- Delete: 6.1 The appeal is submitted to theTournament Organizer/Secretary March 2024 (Version update from 2024.01 to 2024.06)\n- format: new design format, document will be used from now on.","page_from":10,"page_to":10,"stable_key":"duel-regulations:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"703a3298ff4ac16797996ee77a880c01a831031a3f189bcf491280ad3e95fb09","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"tournament/league-structure","synthetic":false,"version":{"version":"26.1","title":"League Structure 26.1","published_on":null,"effective_from":null,"note":"Cover \"VER, 26.1\"; changelog entry \"January-26 (v2026.1)\".","source_url":"https://www.buhurtinternational.com/_files/ugd/735f05_a1ec192413a34eef82ef91f57207ab80.pdf","source_sha256":"b88d1ee4d4a0a500aea10063433b9f1fdc92374ee623a9222f3dca744746d33c","retrieved_at":"2026-10-06T00:00:00Z","page_count":14,"extractor":"pdftotext unknown -layout -enc UTF-8 + OCR (tesseract 5.3.4 psm4 300dpi) on 1 page(s) without a text layer","content_sha256":"f892b181ce824eeb8c1855d07efa5057458061e937526056f5c5d92b7a141cc4","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["16 line(s) looked like a numbered heading but did not fit the sequence"],"pages":14,"source_lines":420,"assigned_lines":579,"furniture_lines":51,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99607,"provisions":64,"numbered":63,"needs_review":0,"verified":0,"empty_pages":[],"rejected_numbers":16,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":3,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"note","number":null,"title":null,"body":"BUHURT\n\nVER, 26.1\n\nRegulations League Structure","page_from":1,"page_to":2,"stable_key":"league-structure:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"9d490ed89ea869fcb62f66acea65b77595affd4f77055b473159b43c38803aa3","has_figures":true,"extraction":"mixed"},{"ordinal":2,"depth":0,"kind":"section","number":"1","title":"General Organization","body":"","page_from":3,"page_to":3,"stable_key":"league-structure:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fae009b123ba62afbeeeb75cacc4dbbe4a528027ff5c6530968f9681cbb11cfe","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":1,"kind":"rule","number":"1.1","title":"Leagues","body":"There are three (3) leagues\n\n● Buhurt (Group Fight)\n● Duels\n● Outrance/Profights","page_from":3,"page_to":3,"stable_key":"league-structure:1.1","parent_key":"league-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"2f8802c614a954ad3f603094f43414d4e869ce45b8cf3cbfcbd6ea448b2a0f11","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.2","title":"Conferences","body":"| Conferences | North America | South America | APAC | Europe |\n| --- | --- | --- | --- | --- |\n| Regions | Canada<br>USA<br>Mexico | Argentina<br>Chile<br>Brazil | China<br>New Zealand<br>Australia | Austria<br>Belgium<br>Czech Republic<br>Denmark<br>Finland<br>France<br>Germany<br>Hungary<br>Ireland<br>Israel<br>Italy<br>Latvia<br>Monaco<br>Netherlands<br>Norway<br>Poland<br>Portugal<br>Romania<br>Serbia<br>Spain<br>Sweden<br>Switzerland<br>Turkey<br>Ukraine<br>United Kingdom |\n\nThe region list will be updated over time.","page_from":3,"page_to":3,"stable_key":"league-structure:1.2","parent_key":"league-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c37c8e5c5d8c3aa089fc7af16219ad04ec0a6799003f375be23c9a657cd6aa5c","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.3","title":"Regions","body":"Each country is its own Region. If a country has less than 15 members, it is asked that they join another nearby country or countries to form a Region. This will help smaller countries be competitive. If countries wish to make a Region, they can do so for a season at a time.\nWith approval from the BI Council. Each case will be looked at separately.","page_from":4,"page_to":4,"stable_key":"league-structure:1.3","parent_key":"league-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"beef5881d9977e0aadf958c8965647f196fade112ec9d833ea81ce987b983c87","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":1,"kind":"rule","number":"1.4","title":"Divisions","body":"Divisions will be based on National Org discretion for the 2026 season. We will use the standings to establish an appropriate standard in the future. There will be the option for Regions to divide into Divisions :\n\n● Division 1 (for each Men’s Category) : Top Tier Teams and Duellist’s will be put into Division 1. National Organisations will Promote or Demote Teams and Duelist’s with the Buhurt International Committee confirming.\n\n● Division 2 (for each Men’s Category) : Lower Tier Teams and Duelist’s will be put into Division 2. National Organisations will Promote or Demote Teams and Duelist’s with the Buhurt International Committee confirming.\n\n● Division 1 (for each Women's Category) : Until enough teams and duellist’s to make 2 Divisions.\n\nImportant : This for competitive level of tournaments, to allow for newer/lower skill teams more competitive events.","page_from":4,"page_to":4,"stable_key":"league-structure:1.4","parent_key":"league-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"08e2b09781a15f623bf051c58afe94293816a755b34a69f9b8d9370a32e8ef9b","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":1,"kind":"rule","number":"1.5","title":"Seasons time frame","body":"● Start: January 15th\n● Ends: December 1st each year.\n● Licenses: All Competitors can renew membership for the following season starting November 1st each year.","page_from":4,"page_to":4,"stable_key":"league-structure:1.5","parent_key":"league-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"428e3c8e81eb3e99967706cf7c8b1740cd93d2bafcc819b0efa7e0d6c6a2ddff","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":0,"kind":"section","number":"2","title":"Ranking and Tournaments","body":"","page_from":5,"page_to":5,"stable_key":"league-structure:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a490a88270b1b4ac9bc00cad19c68e6ad2591d59ca50f1cba0eec870ad9743bc","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"2.1","title":"Ranking System","body":"All points a team/duellist earns in a tournament, no matter what region the tournament was held, will go towards that team’s/duelist’s ranking.","page_from":5,"page_to":5,"stable_key":"league-structure:2.1","parent_key":"league-structure:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"389b3958796adbf88e432c7c0953178973bb0893b230deeecb2ec83dda8ff9c4","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"2.1.1","title":"Regional Rank","body":"Promotes Teams/competitors to get a Regional ranking.","page_from":5,"page_to":5,"stable_key":"league-structure:2.1.1","parent_key":"league-structure:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"278bd4d9cd85bdf35fd638980930e40c5c86bbfc987ea378f521b3bbbb4632bc","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":2,"kind":"rule","number":"2.1.2","title":"Conference Rank","body":"Promotes Teams/competitors to get a Conference Ranking.","page_from":5,"page_to":5,"stable_key":"league-structure:2.1.2","parent_key":"league-structure:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"174770a7003203e70748431ca308b35b150886574d43a94a8845173542e0384a","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":2,"kind":"rule","number":"2.1.3","title":"International Rank","body":"Promotes teams/competitors to get an International ranking.\n\nImportant : All registered BI teams have priority in event registration over unregistered Teams at Classic and above Tournaments.","page_from":5,"page_to":5,"stable_key":"league-structure:2.1.3","parent_key":"league-structure:2.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0a9e00a8eec7bc2d72cf2c50816f57387b176ccf89f1a1d97a27a81284b6c5d5","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"2.2","title":"Trophies for the Season","body":"","page_from":5,"page_to":5,"stable_key":"league-structure:2.2","parent_key":"league-structure:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"467b6a6b0c28d68f5a2c80a5210e99a42f45906ddb51a2e227106ef9f54bb920","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"2.2.1","title":"Regional Ranking for Season","body":"It is requested, Top 3 Teams and Duellist’s in each Category get trophies/medals paid for by the National Organisations.","page_from":5,"page_to":5,"stable_key":"league-structure:2.2.1","parent_key":"league-structure:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c0fc04b13a97c51119a4796269f42ab3eb1193794128fd8c9ab2474b7b316711","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"2.2.2","title":"Conference Ranking for Season","body":"The Top Team and Duellist in each Category get a Medal/trophy paid by Buhurt International.","page_from":5,"page_to":5,"stable_key":"league-structure:2.2.2","parent_key":"league-structure:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c21f5433ad88370b8456dfabbb0bce7fe8059ad2734f098184de5061ee9906f5","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":2,"kind":"rule","number":"2.2.3","title":"International Ranking for Invitationals","body":"Top 2 duelist(per category), top 2 groupfight teams for male and female competitors will be invited every other year to the Invitationals to be ranked as the best in World.\nInvitationals are based on a 2 year season-ranking for invitationals will be based on your top 5 tournaments in a given category","page_from":5,"page_to":5,"stable_key":"league-structure:2.2.3","parent_key":"league-structure:2.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"083b30daf8b5a60016bff13b56484dcd3317e5256dee0f71eb25df4309d91f48","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"2.3","title":"Tournament types","body":"There are 5 Tournament Types.\nNotice an Event can hold multiple types and or levels of tournaments at the same venue.\n\nExample: \"Men's 5s can be Classic, while the Women's 5s can be Source. Alternatively, you could have an Exhibition 5s and a Women's Classic Longsword tournament, all at the same event.\"","page_from":5,"page_to":5,"stable_key":"league-structure:2.3","parent_key":"league-structure:2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f69fb3dbfe94ce5fc7b4a3d9786c03bd22733a4f21443ee25ae48570eac32fc7","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":2,"kind":"rule","number":"2.3.1","title":"Exhibition (Buhurt/Duels)","body":"Tournaments that are just for Promotion. These may not even be a Tournament. It can be a small festival where just one Club attends for fun fights. No Points given.","page_from":5,"page_to":5,"stable_key":"league-structure:2.3.1","parent_key":"league-structure:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"071616a6421e1ce21a5a9e5d889d336dd10b17e0f3a8432b19b6fc1a3bbed676","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":2,"kind":"rule","number":"2.3.2","title":"Source","body":"For developing Regions that struggle to meet the Classic criteria. Regions with developing Buhurt and Duels communities may have Source Tournaments to help promote low population areas. Established Regions may not use this without special request\n\nAll Source tournaments need to be approved by the Buhurt International Committee to make sure this level of tournament is being used correctly. And must be submitted to BI 45 days in advance\n\n|  | Buhurt | Duels |\n| --- | --- | --- |\n| Points given | 50 % | < |\n| Minimal number of Marshal | 1 Regional Accredited Marshal (may be waived by National Org) | < |\n| Minimal number of participants | 3 Teams for either 3v3 or 5v5. | 3 or more Duellists for each Category ran at the tournament. |\n| Divisions | No Teams from Division 1 can compete. | It is preferred that Division 1 duelists only coach at these events, but due to low number of duelists it is accepted to compete, but will be reviewed in case of abuse |\n| Authenticity | Basic level ( Waiting to be defined by Authenticity Committee) | Basic level of Authenticity. (Defined in AC documents) |","page_from":6,"page_to":6,"stable_key":"league-structure:2.3.2","parent_key":"league-structure:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b82b707f91ec5a567bd740d2c520c86ab4d7785a8e8df8701ef260961c7fef43","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":2,"kind":"rule","number":"2.3.3","title":"Classic","body":"There are 3 Classifications for Classic Tournaments. A tournament can consist of multiple Classifications. And must be submitted to BI 45 days in advance+\n\n● Division 1 Classic: Only Division 1 Teams or Duelist’s may compete at this Tournament.\n● Division 2 Classic: Only Division 2 Teams or Duelist’s may compete at this Tournament.\n● Open Classic: All Teams or Duelist’s from both Division 1 and Division 2 may compete at this Tournament.\n\n|  | Buhurt | Duels |\n| --- | --- | --- |\n| Points given | 100 % | < |\n| Minimal number of Marshal | 1 Conference Accredited Marshal(waiver may be requested) | < |\n| Minimal number of participants | 4 Registered 5v5 Buhurt International Teams for Men.<br>3 Registered 5v5 Buhurt International Teams for Women. | 6 Duelists for Men’s and/or 3 Duellists for Women’s for each Category ran at the tournament.<br>Duellists from at least 2 clubs/teams must be competing |\n| Divisions | Depending on Classification | < |\n| Authenticity | change wording to match AC regs | < |\n| Video recording and online streaming | Only video recording (livestream recommended) | < |","page_from":7,"page_to":7,"stable_key":"league-structure:2.3.3","parent_key":"league-structure:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ab30c5209322141cf7e875f7d31a4ed76a42111f82775ab71a8f5fe0f61fd1dd","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":2,"kind":"rule","number":"2.3.4","title":"Regional","body":"1 per region if under 80 competitors registered in the region, 2 per region if over 81 competitors registered in the region. And must be submitted to BI 90 days in advance\n\n|  | Buhurt | Duels |\n| --- | --- | --- |\n| Points given | 150 % | < |\n| Minimal number of Marshal | 1 Buhurt International Accredited Marshal and 2 Regional Accredited Marshals. | < |\n| Minimal number of participants | 8 Registered 5v5 Buhurt International Teams for Men.<br>5 Registered 5v5 Buhurt International Teams for Women. | 8 Duelists for Men’s and/or 5 Duellists for Women’s for each Category ran at the tournament.<br>Duellists from at least 3 clubs must be competing |\n| Division | Any Division<br>If a region has 2 Regional Tournaments, they can be split to have 1 regional tournament for Division 1 teams/duellist’s and the other for Division 2 teams/duellist’s. | < |\n| Authenticity | change wording to match AC regs | < |\n| Video recording and online streaming | Video Recording required, Livestream Recommended | < |","page_from":8,"page_to":8,"stable_key":"league-structure:2.3.4","parent_key":"league-structure:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["80"],"content_sha256":"2a2bb415f7408a966dc5596f76fdfe6fcadb5834ef8ab1e5b3f37d3b77406349","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":2,"kind":"rule","number":"2.3.5","title":"Conference (1 per conference)","body":"Conference Level Tournaments must have a 60/40 approval from all NO’s within the Conference it is taking place in. And must be submitted to BI 120 days in advance\n\n|  | Buhurt | Duels |\n| --- | --- | --- |\n| Points given | 200 % | < |\n| Minimal number of Marshal | 3 Buhurt International Accredited Marshals | < |\n| Minimal number of participants | Representatives of 3 countries are participating. (2 with Buhurt International Council Approval).<br>10 Registered 5v5 Buhurt International Teams for Men. (8 with Buhurt International Council Approval).<br>7 Registered 5v5 Buhurt International Teams for Women. (5 with Buhurt International Council Approval). | Representatives of 3 countries are participating. (2 with Buhurt International Council Approval).<br>10 Duelists for Men’s and/or 7 Duellists for Women’s for each Category ran at the tournament.<br>Duellists from at least 5 clubs must be competing |\n| Divisions | Any Division | < |\n| Authenticity | Full Authenticity Requirements | < |\n| Video recording and online streaming | Mandatory- livestream and recording | < |","page_from":9,"page_to":9,"stable_key":"league-structure:2.3.5","parent_key":"league-structure:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"77dfea35d047295b777a29c7ed8797f3155c80aaa3caad8b1e06077fc28de39f","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":2,"kind":"rule","number":"2.3.6","title":"Clarification","body":"Regional and Conference Tournaments can be independent based on.\n\n● League Categories (Duels or Buhurt)\n● Gender Categories\n\nFor example:\n\"One could host a Women’s Duels Conference Tournament and a Men’s Duels Conference Tournament on different days and at different locations. Additionally, there could be a regional tournament for duels, held as a separate event from regional group fights.\"\n\nUnregistered Teams made up of Licensed Members are always allowed at events. But priority must be given to Registered Teams","page_from":9,"page_to":9,"stable_key":"league-structure:2.3.6","parent_key":"league-structure:2.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8f58c8781d9865fc5604e9d6b9fda0beaa460bff930baead705992362111fdaa","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":0,"kind":"section","number":"3","title":"Teams","body":"","page_from":10,"page_to":10,"stable_key":"league-structure:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0d567a02723b8d0bbbf2fb9706cadb47a2f35014408518ec2b3e0c64888d4a66","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"3.1","title":"Team Roster (5s)","body":"","page_from":10,"page_to":10,"stable_key":"league-structure:3.1","parent_key":"league-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f234925169640db9fba8aa1414c7cc2d66b49726702e1d45c27b2c43ad96420a","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":2,"kind":"rule","number":"3.1.1","title":null,"body":"A men’s team may have from 5 to 20 competitors.","page_from":10,"page_to":10,"stable_key":"league-structure:3.1.1","parent_key":"league-structure:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fd1a773a9876e7253cf55b103961a35c46144689a17a9bc86e54a7fe23f8ffd9","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":2,"kind":"rule","number":"3.1.2","title":null,"body":"A women’s team may have 3 to 20 competitors.","page_from":10,"page_to":10,"stable_key":"league-structure:3.1.2","parent_key":"league-structure:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"81e5fefd3162acb42f114137956c71bccea55455d87a0044faf0dbf8cab55e36","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":2,"kind":"rule","number":"3.1.3","title":"A men’s team may register to a tournament from 5 to 8 competitors for 5v5","body":"tournaments or 3 to 5 competitors for 3v3 tournaments.","page_from":10,"page_to":10,"stable_key":"league-structure:3.1.3","parent_key":"league-structure:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7eb564abd2082ea54e7c48784c4a3957cd5f266b3f88dc120b43f8ef4e88aba8","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":2,"kind":"rule","number":"3.1.4","title":"A women’s team may register to a tournament from 3 to 8 competitors for a 5v5","body":"tournament or 3 to 5 competitors for 3v3 tournaments","page_from":10,"page_to":10,"stable_key":"league-structure:3.1.4","parent_key":"league-structure:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ab684a3e45a54b30118cf82530abef81e9bff1a5b531cf1e574a8e3ab58af1df","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":2,"kind":"rule","number":"3.1.5","title":null,"body":"A competitor must not be on more than one team’s roster for a tournament.","page_from":10,"page_to":10,"stable_key":"league-structure:3.1.5","parent_key":"league-structure:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"90d93f60c1fd087d121982600a3022bd58710a0720b52674dea17f6de5e6423a","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":2,"kind":"rule","number":"3.1.6","title":null,"body":"A competitor must not be on more than one team’s roster for the League.","page_from":10,"page_to":10,"stable_key":"league-structure:3.1.6","parent_key":"league-structure:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"31101f7a6b701eb6e61cf56c58182431205c70ba30117fb6232853b506b5bd5e","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":2,"kind":"rule","number":"3.1.7","title":null,"body":"If a team is attending a tournament and wishes to field two squads at a single event, they must state which squad is earning points before the tournament begins.\n\nImportant: A team may field at multiple events and earn league points at each of those events.","page_from":10,"page_to":10,"stable_key":"league-structure:3.1.7","parent_key":"league-structure:3.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"061d6e7d2371c9a2ff02621dfe00a75ce6756989f057cea5f460ca5cf053274c","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":1,"kind":"rule","number":"3.2","title":"Team Roster (12s)","body":"","page_from":10,"page_to":10,"stable_key":"league-structure:3.2","parent_key":"league-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dab41e8f5f6f26292e5143832d9f0fc91f2cd596aafe111a1b7794515f8b06cf","has_figures":false,"extraction":"text"},{"ordinal":34,"depth":2,"kind":"rule","number":"3.2.1","title":null,"body":"No valid teams are required for the 12vs12 but only licensed competitors.","page_from":10,"page_to":10,"stable_key":"league-structure:3.2.1","parent_key":"league-structure:3.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"23245c9b0464eeb8fc0d5ef095e95604987758d941fcec357b7b75d9076e19f7","has_figures":false,"extraction":"text"},{"ordinal":35,"depth":2,"kind":"rule","number":"3.2.2","title":"A team may register to a tournament from 12-20 competitors for a 12v12","body":"tournament.","page_from":10,"page_to":10,"stable_key":"league-structure:3.2.2","parent_key":"league-structure:3.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e6156485808a779f3dd43471a75a19a50f4919d9389ba3ffe9327a82897da8c4","has_figures":false,"extraction":"text"},{"ordinal":36,"depth":2,"kind":"rule","number":"3.2.3","title":null,"body":"A competitor must not be on more than one team roster for a tournament.","page_from":10,"page_to":10,"stable_key":"league-structure:3.2.3","parent_key":"league-structure:3.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"00aae42b80bbb6f0a47633c460e2af05ebbf4b13aa5c6b4efa4267b64a1fe75a","has_figures":false,"extraction":"text"},{"ordinal":37,"depth":2,"kind":"rule","number":"3.2.4","title":"When a 12s is formed the competitors must decide which team will collect the points","body":"Important: Only the named team for that tournament will earn league points. All other clubs that form the singular team will not earn points for that event.","page_from":10,"page_to":10,"stable_key":"league-structure:3.2.4","parent_key":"league-structure:3.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bc7442dcdc070b9aa53ab99a01b1c61a130f4906bcf436dece9819d560a9afc7","has_figures":false,"extraction":"text"},{"ordinal":38,"depth":1,"kind":"rule","number":"3.3","title":"Ranking Process","body":"","page_from":10,"page_to":10,"stable_key":"league-structure:3.3","parent_key":"league-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fac77c6bf97bbcbe711f4e76f64b856ba4398ff4d600d13f3266ef9bd48f990f","has_figures":false,"extraction":"text"},{"ordinal":39,"depth":2,"kind":"rule","number":"3.3.1","title":"League Score are earned in the following way for Duels and Buhurt (all points are","body":"cumulative)\n\n● 1 point for every match victory in the Pools/round robin segment of the tourney.\n● 2 pts for every match victory in the brackets/elimination segment of the tourney.\n● No points earned for finals except for standings (2 pts for 3rd, 4 pts for 2nd, 6 pts for 1st).","page_from":10,"page_to":10,"stable_key":"league-structure:3.3.1","parent_key":"league-structure:3.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"55d3b38c7243c1c4896e3a5137596a741a047549bf1b040649cc94e0b532c11d","has_figures":false,"extraction":"text"},{"ordinal":40,"depth":2,"kind":"rule","number":"3.3.2","title":"The multiplier for each tier","body":"● x1 for Classic\n● x1.25 for Regional\n● x1.5 for Conference","page_from":10,"page_to":10,"stable_key":"league-structure:3.3.2","parent_key":"league-structure:3.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f90149b37a760cf7beeaa4fb485735ef536a32a9b337613bcd7f4cb97bb765e","has_figures":false,"extraction":"text"},{"ordinal":41,"depth":2,"kind":"rule","number":"3.3.3","title":"Outrance/Profight : Scoring can be found in the Outrance Regulations document","body":"","page_from":10,"page_to":10,"stable_key":"league-structure:3.3.3","parent_key":"league-structure:3.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ab0568a82fc485ebc1f481c4a32a8c108a7343a78a31b93807694b39fe0511d1","has_figures":false,"extraction":"text"},{"ordinal":42,"depth":2,"kind":"rule","number":"3.3.4","title":"At a single Event- only one of each category may be ranked. Example - a running 2","body":"longsword categories, only one of those may be ranked if containing the same competitors.","page_from":10,"page_to":10,"stable_key":"league-structure:3.3.4","parent_key":"league-structure:3.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3c3efbb23625ad27cd3158588732be4ead799b42acdd080282fd464c7c44fab4","has_figures":false,"extraction":"text"},{"ordinal":43,"depth":1,"kind":"rule","number":"3.4","title":"Season Record","body":"All conferences use the top 3 tournaments average for overall standing. Highest overall score will also be acknowledged and appropriately credited.","page_from":11,"page_to":11,"stable_key":"league-structure:3.4","parent_key":"league-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e5de5f31095316723cf021bbf50c45ded27a9e86ec9b631607e5f60958b41c26","has_figures":false,"extraction":"text"},{"ordinal":44,"depth":2,"kind":"rule","number":"3.4.1","title":null,"body":"Ranking average will use 0 for results until a team/competitor completes 3 events.","page_from":11,"page_to":11,"stable_key":"league-structure:3.4.1","parent_key":"league-structure:3.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e0ec24aabcdd57bff9986714cce32546d6a7965218d0992d694d726ff5677785","has_figures":false,"extraction":"text"},{"ordinal":45,"depth":1,"kind":"rule","number":"3.5","title":"Penalty","body":"","page_from":11,"page_to":11,"stable_key":"league-structure:3.5","parent_key":"league-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b28c775891967566950b4dc0fa0a76af0b4191644329c3d52095e218f8764a2d","has_figures":false,"extraction":"text"},{"ordinal":46,"depth":2,"kind":"rule","number":"3.5.1","title":"Dropping/no show","body":"● -5 pts for the league score for dropping from a tournament, within 72 hours of the start of the tournament.\n● The category should still happen and all other competitors/teams will still be eligible for earning points and being a ranked event, as long as the category would have had the appropriate numbers","page_from":11,"page_to":11,"stable_key":"league-structure:3.5.1","parent_key":"league-structure:3.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5f454ee674c4b180a3758495921adb0d381ea09c497685b97062241a72f73e26","has_figures":false,"extraction":"text"},{"ordinal":47,"depth":2,"kind":"rule","number":"3.5.2","title":"Mercenaries","body":"● A team that has licensed competitors on its roster at an event that are not registered on their team-profile on the official buhurt international website.\nNo points will be earned for that event and get status: invalid team\n● Unregistered teams must be made up of Licensed Members and are always allowed at events. But get status: invalid. But priority must be given to registered teams.\n● 12s may have mercenaries without penalty\n\nImportant: Women's teams must field at least 3 from their roster and can have up to 5 mercs without penalty.","page_from":11,"page_to":11,"stable_key":"league-structure:3.5.2","parent_key":"league-structure:3.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e7ee9da5b6603605fb45b14d9acdef5829d70c72a26e32d7f479cf507c3b5511","has_figures":false,"extraction":"text"},{"ordinal":48,"depth":2,"kind":"rule","number":"3.5.3","title":"Cards","body":"● Yellow/Red Cards will initiate a review from the Judiciary Committee. They may issue reductions in League Score and potential other appropriate actions.","page_from":11,"page_to":11,"stable_key":"league-structure:3.5.3","parent_key":"league-structure:3.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e5bcdb6c3fa5b4abe0c2dcd6c1f7dea1ebf4dfb012e2bc1275c5235b5cb613bc","has_figures":false,"extraction":"text"},{"ordinal":49,"depth":1,"kind":"rule","number":"3.6","title":"Buhurt transfer window and tokens","body":"","page_from":11,"page_to":11,"stable_key":"league-structure:3.6","parent_key":"league-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dc7c946f8dd541a10d2af16bc4ce10ce4e42991bcc7c868b251a5e4fb555e26e","has_figures":false,"extraction":"text"},{"ordinal":50,"depth":2,"kind":"rule","number":"3.6.1","title":"Tokens","body":"● Teams will receive 6 transfer tokens per season.\n● Each token allows the team to add an “Active” competitor from another team or the “Free market” to their roster.\n● A team can move one of their “Active” competitors to the “Free Agent Pool” at any time without cost in transfer tokens.\n● Adding an “Active” competitor to the roster will cost you 1 token.\n\nCompetitors can register at any time, regardless of transfer windowActive vs Non-active (buhurt)\n\n● Competitors who never joined a team are “Non-active” competitors\n● Once a competitor is assigned to a team the competitor becomes “Active”\n● Competitors don't lose the status “Active” after being dropped from a team, injuries or transfer window.","page_from":11,"page_to":12,"stable_key":"league-structure:3.6.1","parent_key":"league-structure:3.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"887ab2157c055455f0baf5f58219dde86e2e432f52f4588cc6b8a36ad1e08981","has_figures":false,"extraction":"text"},{"ordinal":51,"depth":2,"kind":"rule","number":"3.6.2","title":"Transfer Window","body":"Open transfer window from the 1st of December to the 14th of January. There will be no token reduced to readjust your teams during this time period","page_from":12,"page_to":12,"stable_key":"league-structure:3.6.2","parent_key":"league-structure:3.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6fc9bacf7b5b0608035936f148f57e337d86c76d4ec50cdbaf0565b2ebf05e8b","has_figures":false,"extraction":"text"},{"ordinal":52,"depth":0,"kind":"section","number":"4","title":"Appendix of words used","body":"","page_from":12,"page_to":12,"stable_key":"league-structure:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d88695d5c7d2d07f63f2c0613a60b02ae74b63d1f1119d7b6cf6b785718d4a79","has_figures":false,"extraction":"text"},{"ordinal":53,"depth":1,"kind":"rule","number":"4.1","title":"Country","body":"A spatially clearly delimited area, in which its own administration with at least partial autonomy comes to bear, which emanates from an organization exercising power.","page_from":12,"page_to":12,"stable_key":"league-structure:4.1","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e62f25610222ae15717f5816824f0c50c1adcdbbf2716b68a245697af416b5a6","has_figures":false,"extraction":"text"},{"ordinal":54,"depth":1,"kind":"rule","number":"4.2","title":"Region","body":"A country/group of countries that choose to form a region together within a close geographical area.","page_from":12,"page_to":12,"stable_key":"league-structure:4.2","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d9e22fc37db140d23650491d07c0b2711f4d0d0de1a0a9063971ff0568f224e6","has_figures":false,"extraction":"text"},{"ordinal":55,"depth":1,"kind":"rule","number":"4.3","title":null,"body":"Conference: Group of countries defined by Buhurt International in the above document.","page_from":12,"page_to":12,"stable_key":"league-structure:4.3","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"abaf2aaf394a4e9d6709bb3e190373f4cbe0718a7ef74cf42350a37b67114a5d","has_figures":false,"extraction":"text"},{"ordinal":56,"depth":1,"kind":"rule","number":"4.4","title":null,"body":"Tournament: A competition held within the guidelines listed above.","page_from":12,"page_to":12,"stable_key":"league-structure:4.4","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"41188cc01f5ea2f8bf50c879a40c26b19b4adc2efea8ba1b8426249fa4dc5a25","has_figures":false,"extraction":"text"},{"ordinal":57,"depth":1,"kind":"rule","number":"4.5","title":null,"body":"Division: A set group of teams/competitors within a predetermined specification.","page_from":12,"page_to":12,"stable_key":"league-structure:4.5","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"87644ebace72873619e107da2bf008ea7603b6c171cc7bf37593e759b0e396ca","has_figures":false,"extraction":"text"},{"ordinal":58,"depth":1,"kind":"rule","number":"4.6","title":null,"body":"Category: A format of competitions established by the various rules of Buhurt International.","page_from":12,"page_to":12,"stable_key":"league-structure:4.6","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"cefab5700509691d45385aa6662d24c870544dce89ea04a18fceec07fdf61061","has_figures":false,"extraction":"text"},{"ordinal":59,"depth":1,"kind":"rule","number":"4.7","title":"League: Organizational group for the purpose of competing beyond individual tournaments","body":"by having ranking and standards.","page_from":12,"page_to":12,"stable_key":"league-structure:4.7","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"bc4736d3847ca9257cbef3df8c5a7d70f75c1d0ca5b986372459ab27d9aa74d6","has_figures":false,"extraction":"text"},{"ordinal":60,"depth":1,"kind":"rule","number":"4.8","title":"League Score: Total points earned throughout a season to determine ranking throughout","body":"sport.","page_from":12,"page_to":12,"stable_key":"league-structure:4.8","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"e2ab429e58098df4565d9ae49359b85e7d77c89701ed41d9347e9010571a9370","has_figures":false,"extraction":"text"},{"ordinal":61,"depth":1,"kind":"rule","number":"4.9","title":null,"body":"Squad: 8 registered competitors on a team competing at an event.","page_from":12,"page_to":12,"stable_key":"league-structure:4.9","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1350a7f7bce6239b87f861f9d48ddb736c706a9ea839cff020f73ac32769238b","has_figures":false,"extraction":"text"},{"ordinal":62,"depth":1,"kind":"rule","number":"4.10","title":"BI:Buhurt International","body":"","page_from":12,"page_to":12,"stable_key":"league-structure:4.10","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"579724b7f84e133d56e366fe0f3ea42f4986f910a8b227b366eb673fb3d21035","has_figures":false,"extraction":"text"},{"ordinal":63,"depth":1,"kind":"rule","number":"4.11","title":"NO:National Organization","body":"","page_from":12,"page_to":12,"stable_key":"league-structure:4.11","parent_key":"league-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"caf44aa30d27ffe21491dd34c9ac0bab4bf94c96a101b93a163194b4eb0686b0","has_figures":false,"extraction":"text"},{"ordinal":64,"depth":0,"kind":"note","number":"5","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nJanuary-26(v2026.1)\n- add 2.2.3 -add 3.3.2 points modifier -add 3.3.4 -add 3.4.1 -add 3.5.1 -adjustment 3.6\n\nFebruary-25 (V2025.02)\n- Adjustment: 2.2 renamed: Tournament to Ranking for Season\n- Adjustment: 2.3.6: spelling correction: independents to independent\n- Removed: 2.2.3 International Ranking for Season Top 3 Teams and Duellist’s in each Category to get trophies paid by Buhurt International.\n-\n\nDecember-25\n- Adjustment: 2.Tournament: Was changed from Tournament to Ranking and Tournaments\n- Adjustment: 2.1 Tournament was changed to Ranking\n\nNov-25\n- clarification 3.4.2 Mercenaries (Team profile has to be on the official Buhurt International Website)\n- Tournament: Was changed from Tournament to Ranking and Tournaments\n- Adjusted: Wester/Easter Europe under Europe (removed the separation and united Europe)\n- clarification 3.4.2 Mercenaries( Licensed Members are always allowed at events, But get status: invalid. But priority must be given to registered teams.\n- Added: 3.1.2 Women's teams must field 5 from their own roster, has been changed to 3 from their own roster\n- Added: 3.1.1 Team Roster (5s) Has been changed from max 17 to 20 members per team\n- Added: 3.1.2 Team Roster (5) Has been added: A women’s team may have 3-20 competitors.\n- Added: 3.1.4 Team Roster (5) Has been added: A women’s team may register to a tournament from 3 to 8 competitors for a 5v5 tournament or 3 to 5 competitors for 3v3 tournaments\n- Added: 2.3.2 Source: And must be submitted to BI 45 days in advance\n- Added: 2.3.2 Source: Livestream (recommended)\n- Added: 2.3.3 Classic: And must be submitted to BI 45 days in advance\n- Added: 2.3.3 Classic: Livestream (recommended)\n- Added: 2.3.4 Regional: And must be submitted to BI 90 days in advance\n- Added: 2.3.5 Conference: Conference Level Tournaments must have a 60/40 approval from all NO’s within the Conference it is taking place in. And must be submitted to BI 120 days in advance\n- Added: 2.3 Tournament types: Example\n- Removed: 5 Temporary rules (first year start up)\n- Added: 1.5 All Competitors can renew membership for the following season starting November 1st each year.\n\nMarch 2024 (Version update from 2024.01 to 2024.03)\n\n- clarification: 3.2 Team Roster (12s) (page 11)\n- clarification: 3.6 Buhurt transfer window and tokens (page 12)\n- Added: Temporary Rules Addendum (page 14)\n- format: new design format, document will be used from now on.\n\n3.2 Club Roster (12s) 3.2 Team Roster (12s) 3.2.1 A club team may have any number of competitors registered to it. (replaced) 3.2.1 No valid teams are required for the 12vs12 but only licensed competitors.\n\n3.2.3 A competitor must not be on more than one Club’s roster for a tournament.\n3.2.3 A competitor must not be on more than one team roster for a tournament.\n\nremoved 3.2.4 A competitor MAY be on a different Club’s roster for the League. (removed)\n\n3.2.5 When a 12s is formed the competitors must decide which club they want this tournament to earn points for.\n3.2.4 When a 12s is formed the competitors must decide which team will collect the points\n\n3.6 Buhurt transfer window\n\n3.6.1 Teams will receive 10 transfer tokens per season. Each token allows the team to add an “Active” competitor from another team or the “Free Agent Pool” to their roster. A team can move one of their “Active” competitors to the “Free Agent Pool” at any time without cost in transfer tokens.(renamed to tokens | formatted | clarification )\n\n3.6.1 tokens Teams will receive 10 transfer tokens per season.\n\n● Each token allows the team to add an “Active” competitor from another team or the “Free market” to their roster.\n● A team can move one of their “Active” competitors to the “Free Agent Pool” at any time without cost in transfer tokens.\n● Adding an “Active” competitor to the roster will cost you 1 token.\n\n3.6.3 A registered competitor that has not been picked up by a team can be picked up at any time during the season..(renamed to“Active” vs “Non-active” (buhurt) | formatted | clarification ) 3.6.4 Once a competitor has been selected for a team, they are now considered “Active” and will remain so until the end of the season. Even when dropped from a team, they will keep the “Active” status.(renamed to“Active” vs “Non-active” (buhurt) | formatted | clarification )\n\n3.6.3 “Active” vs “Non-active” (buhurt) Competitors who never joined a team are “Non-active” competitors Once a competitor is assigned to a team the competitor becomes “Active” Competitors don't lose the status “Active” after being dropped from a team, injuries or transfer window.\n\n3.6.5 Open transfer window from the 16TH of December to the 14th of January. There will be no Cost to readjust your teams during this time period(clarification) 3.6.5 Open transfer window from the 16th of December to the 14th of January. There will be no token reduced to readjust your teams during this time period\n\n5. Temporary Rules Addendum (added)\n\nDocument got reformatted into the new format.","page_from":13,"page_to":14,"stable_key":"league-structure:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":["3.6"],"content_sha256":"3e60a9f38d803f981881db5abd71dd509a5b9ae10d86706f2c393b79bef6a2ad","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
select private.rules_import_version($rules${"governing_body":"Buhurt International","release":"2026-10-06","inventory_key":"tournament/secretary-accreditation","synthetic":false,"version":{"version":"2024.06","title":"Secretary Accreditation V2024.06","published_on":null,"effective_from":null,"note":"Changelog: \"(Version update from 2024.03 to 2024.06)\", latest entry \"Update date: June-2024\".","source_url":"https://www.buhurtinternational.com/_files/ugd/d219c5_bb995d5ca4d345d2a649067d7cb9d494.pdf","source_sha256":"4c99a239cd06340aa2abcab966b6f2936d2d1969852e88d3821968bd5248659a","retrieved_at":"2026-10-06T00:00:00Z","page_count":7,"extractor":"pdftotext unknown -layout -enc UTF-8","content_sha256":"a0cb7267662886b1f5cdf254624827914dc96f9b2d155bbd80418115065fb139","detected":{"version":null,"date":null},"confirmed_by":"Claude Code (Pack 22 import), read from the official PDF: cover, page footers and changelog","reconciliation":{"ok":true,"errors":[],"warnings":["page(s) without extractable text: 1"],"pages":7,"source_lines":139,"assigned_lines":202,"furniture_lines":30,"unaccounted_lines":[],"double_assigned_lines":[],"char_coverage":0.99969,"provisions":24,"numbered":22,"needs_review":0,"verified":0,"empty_pages":[1],"rejected_numbers":0,"duplicate_numbers":[],"duplicate_texts":[],"version_confirmed":true,"source_sha256_matches":true,"ocr_lines":0,"picture_text_lines":0,"ocr_corrections":0}},"provisions":[{"ordinal":1,"depth":0,"kind":"figure","number":null,"title":null,"body":"","page_from":1,"page_to":1,"stable_key":"secretary-accreditation:page-1","parent_key":null,"review_status":"extracted","review_note":"cover page: artwork only, no text","topics":["cover"],"keywords":[],"cross_refs":[],"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Secretary Accreditation Secretary Accreditation is the process that our Sport accredits its tournament secretaries from a Trainee to an International Secretaries. This process will ensure that our regions have a high standard of trained Absence of Regional Head Secretary. The process to become accredited is in eight (8) stages.","page_from":2,"page_to":2,"stable_key":"secretary-accreditation:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"bef28422d7039f85e31aa1fb29bd304d5d879eb4a9526fc59cffb47be0713fd3","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Organization","body":"","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5f6f1be36358fef2f47f42d70d0d1e17c5b1c4cd8b8a13720f3da372158f1828","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Stage 1 : Learning the role of a secretary","body":"● Before they can work as an event secretary, Trainee secretaries will need to understand the role, its requirements, and expectations.\n● This will include secretary duties, scorekeeping, score inputting and placing/points determination.\n● Ask your Regional Head Secretary Questions on items you may be unsure of.","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.1","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c9e7bea282f4985450f410aa59d3b2147c7eb7266e7458ba119f15f9fab01d54","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":1,"kind":"rule","number":"1.2","title":"Stage 2 : Work at events with Regional Head Secretary","body":"","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.2","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"0db67657fac978f7e7d62eb254c92b09660812439cba884b9d8a13d4f697ef58","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.2.1","title":"Trainee secretaries will be required to work at three events. Trainee secretaries","body":"will be paired with a Regional Accredited Secretary, Conference Accredited Secretary, or International Accredited Secretary to learn from. Trainee secretaries will be empowered to perform secretary roles under supervision but are not permitted to act as an event secretary alone until qualified.","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.2.1","parent_key":"secretary-accreditation:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5050b7c6c3b4ce0d8c7245a37600ccf2462b1a692988c04be960ace11ccf1239","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.2.2","title":"If there is no Regional Head Secretary in a Country or Region, the Conference","body":"Head Secretary for that country or region will be responsible for the training of secretaries until a Regional Head Secretary is appointed.","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.2.2","parent_key":"secretary-accreditation:1.2","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a97c3c48a406c45fdae2fe7069e4b678c77db69b2093497bdb4aeb88fc366d37","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"1.3","title":"Stage 3 : Take the Regional Secretary Accreditation Test","body":"","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.3","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4dc3775b0389db706f19344823d30e6c15ddea8589a6d7e328e2d069f2c9f537","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":2,"kind":"rule","number":"1.3.1","title":"After you have worked at the required number of events, you will be able to take","body":"the Regional Accreditation Test. The test is a ten (10) question test. The test will cover secretary duties, scorekeeping, score inputting and placing/points determination.","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.3.1","parent_key":"secretary-accreditation:1.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f0442dc6bfb5a12cfd77a0b185cbe3b7310b7d94ef1a52eb399d63166cdb8dd7","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":2,"kind":"rule","number":"1.3.2","title":"Once you have your Regional Accreditation, you will be able to perform event","body":"secretary duties at BI Source and Classic level events. You will be given a Regional Secretary Certificate.","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.3.2","parent_key":"secretary-accreditation:1.3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dbf47ac3460b8fd6f54ef105c6929b73c2bd763ea3c5b267072abe7c8eefffb1","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":1,"kind":"rule","number":"1.4","title":"Stage 4 : Work at events with Conference Head Secretary","body":"● Regional Secretaries will be required to work at an Event with the Conference Head Secretary. Regional Secretaries will work on all aspects of the Secretary role at this Event. After the event, the Conference Head Secretary will let you know if you are ready to take the Conference Accreditation Test or if you need to do another event.","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.4","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"b117cb124f063a53002f89fff86b0ebf25871101fff3511db588858d56a06ee3","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":1,"kind":"rule","number":"1.5","title":"Stage 5 : Take the Conference Secretary Accreditation Test","body":"● After you have your Regional Accreditation and have completed an event with your Conference Head Secretary, you can take the Conference Secretary Accreditation Test. The Test is a practical secretary exercise relating to a group stage to elimination stage tournament.","page_from":3,"page_to":3,"stable_key":"secretary-accreditation:1.5","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"dfadcfa7b2036048299178241e3d83cd0748a99b13b84a37ec042b464e047987","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"1.6","title":"Stage 6 : Interview with Conference Head Secretary","body":"● Once you have completed your Conference Secretary Accreditation Test, you will have an interview with your Conference Head Secretary. This interview will be to look at anything that you may have gotten wrong or that more information is required. The Conference Head Secretary may ask you further questions.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.6","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a2a46290b251ac23a11a05face836b6d86af546e65676c63faec7ca140aeb866","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":1,"kind":"rule","number":"1.7","title":"Stage 7 : Becoming accredited Conference Secretary","body":"","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.7","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3ac45e4df6cba0badd49021fbedea7496b70fe918670af04701704adc61cede9","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"1.7.1","title":"If you have failed your Test, you will continue to be a Regional Secretary. You will","body":"need to repeat stages 4, 5 and 6 again until you receive your accreditation.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.7.1","parent_key":"secretary-accreditation:1.7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"747314d0d0557cd0c1bf7f3d29a2ea5df5529864a410faade7db608179b7e3fd","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":2,"kind":"rule","number":"1.7.2","title":"If you have passed your Test and Interview, you are now a Conference","body":"Accredited Secretary. This means you are allowed to work as an event secretary at BI Source, Classic and Regional level events as a secretary. You will be given a Conference Secretary Certificate.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.7.2","parent_key":"secretary-accreditation:1.7","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d49496e32d220d64e296da8af6ca34536fd5078cd0269ceb26f9f87765ae1fd5","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":1,"kind":"rule","number":"1.8","title":"Stage 8 : International Secretary Accreditation","body":"","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.8","parent_key":"secretary-accreditation:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4976087b03425e09d80b536febb6ec0600966ad0ef40dff7e5c322588569492b","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":2,"kind":"rule","number":"1.8.1","title":"The International Secretary Accreditation is the highest level a secretary can","body":"receive. This level of Accreditation is for Buhurt International Events where the level of secretary experience is higher, such as Conference Events. This process will ensure that our Buhurt International events have a high standard of secretaries.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.8.1","parent_key":"secretary-accreditation:1.8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"9d933c5dae528d253417e180cf8bbec8e64719d052bbc11dd8c039cb0ac17165","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":2,"kind":"rule","number":"1.8.2","title":null,"body":"Before you can attempt the Buhurt International Secretary Accreditation process, you must be Conference Secretary Accredited.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.8.2","parent_key":"secretary-accreditation:1.8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"7759221c909b8d591c80eccde86dcac9b02f0ca3dfb64f7a6947e66da6f8024a","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":2,"kind":"rule","number":"1.8.3","title":"Conference secretaries will be required to work at a Buhurt International","body":"Conference level event alongside an Internationally Accredited Secretary.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.8.3","parent_key":"secretary-accreditation:1.8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c03378268a876d022ef53af7996a01514aa31dd4b656f20e378f0b9b29a8a1d9","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":2,"kind":"rule","number":"1.8.4","title":"Once the event has concluded, you will be responsible for the inputting and","body":"processing of the event information in the protocol as collected. This will then be reviewed by the International Accredited Secretary, who will also ask any further questions they may have.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.8.4","parent_key":"secretary-accreditation:1.8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f7bb95fd9290f0e9f2becba829e597a4be6ab512b4f146c0a570b9ea080ad8d8","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":2,"kind":"rule","number":"1.8.5","title":null,"body":"If you have failed this process, you will continue being a Conference Secretary.\nYou will need to repeat the Buhurt International Secretary Accreditation Process until you receive your accreditation.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.8.5","parent_key":"secretary-accreditation:1.8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f54b88b9f968c4938ba6c5e780c310407f1fa017e0ab3114ed86a212879819ed","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":2,"kind":"rule","number":"1.8.6","title":"If you have passed your review, you are now an Internationally Accredited","body":"Secretary. This means you are allowed to work at all levels of Buhurt International events (Source, Classic, Regional, and Conference) including Buhurt International World Championships. You will be given a Buhurt International Secretary Certificate.","page_from":4,"page_to":4,"stable_key":"secretary-accreditation:1.8.6","parent_key":"secretary-accreditation:1.8","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"40e70c69937afd722eeb7be05fb135a21b43ce21aef4cfc19cf01e4eb54f9ea4","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":0,"kind":"section","number":"2","title":"Secretary Accreditation Checklist","body":"STAGE 1 – LEARNING THE ROLE\n\nREGIONAL HEAD SECRETARY SIGNATURE: ____________________________________\n\nSTAGE 2 – WORK AT EVENTS WITH REGIONAL HEAD SECRETARY\n\nEVENT 1: ______________________________________________ DATE: ______________\n\nREGIONAL HEAD SECRETARY SIGNATURE: ____________________________________\n\nEVENT 2: ______________________________________________ DATE: ______________\n\nREGIONAL HEAD SECRETARY SIGNATURE: ____________________________________\n\nEVENT 3: ______________________________________________ DATE: ______________\n\nREGIONAL HEAD SECRETARY SIGNATURE: ____________________________________\n\nSTAGE 3 – TAKE THE REGIONAL SECRETARY ACCREDITATION TEST\n\nEVENT 1: ______________________________________________ DATE: ______________\n\nSCORE: _______________________________________________ FAIL/PASS: _________\n\nREGIONAL HEAD SECRETARY SIGNATURE: ____________________________________\n\nSTAGE 4 – WORK AT AN EVENT WITH CONFERENCE HEAD SECRETARY\n\nEVENT 1: ______________________________________________ DATE: ______________\n\nREGIONAL HEAD SECRETARY SIGNATURE: ____________________________________\n\nSTAGE 5 – TAKE THE CONFERENCE SECRETARY ACCREDITATION TEST\n\nEVENT 1: ______________________________________________ DATE: ______________\n\nSCORE: _______________________________________________ FAIL/PASS: _________\n\nCONFERENCE HEAD SECRETARY SIGNATURE: _________________________________\n\nSTAGE 6 – INTERVIEW WITH CONFERENCE HEAD SECRETARY\n\nEVENT: ________________________________________________ DATE: _____________\n\nCONFERENCE HEAD SECRETARY SIGNATURE: _________________________________\n\nSTAGE 7 – BECOMING ACCREDITED CONFERENCE SECRETARY\n\nEVENT: ________________________________________________ DATE: _____________\n\nSENIOR HEAD SECRETARY SIGNATURE: _______________________________________\n\nSTAGE 8 – INTERNATIONAL SECRETARY ACCREDITATION\n\nEVENT: ________________________________________________ DATE: _____________\n\nSENIOR HEAD SECRETARY SIGNATURE: _______________________________________\n\nChange log This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nMarch 2024 (Version update from 2024.03 to 2024.06)\n\nUpdate date: June-2024\n- format: Grammar corrections Update date: March-2024\n- format: new design format, document will be used from now on.","page_from":5,"page_to":7,"stable_key":"secretary-accreditation:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6f5b26bd1fdecbc4548da7dc8b7388d10a922d079d6125cb92c1c4d50256fdf2","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
