,"content_sha256":"75a11da44c802486bc6f65640aa48a730f0f684c5c07a42ba3cd1735eb3fb070","has_figures":true,"extraction":"text"},{"ordinal":2,"depth":0,"kind":"note","number":null,"title":null,"body":"Tournament Structure and Formats","page_from":2,"page_to":2,"stable_key":"tournament-structure:p0001","parent_key":null,"review_status":"extracted","review_note":null,"topics":["introduction"],"keywords":[],"cross_refs":[],"content_sha256":"7824d701ca77d46935fcd33be427df9456998e58fe1bc9135f6347373d2b243e","has_figures":false,"extraction":"text"},{"ordinal":3,"depth":0,"kind":"section","number":"1","title":"Structure","body":"","page_from":3,"page_to":3,"stable_key":"tournament-structure:1","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"674cd3827e7f811dc9db3e2da9db46ebd9268d5886a123d224c625fb4f695393","has_figures":false,"extraction":"text"},{"ordinal":4,"depth":1,"kind":"rule","number":"1.1","title":"Registration","body":"","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.1","parent_key":"tournament-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f5576f8ac1c31577bbeccf0556174bcd6165a33264332aa91abfe616d16b666f","has_figures":false,"extraction":"text"},{"ordinal":5,"depth":2,"kind":"rule","number":"1.1.1","title":"Registration should be closed at least 15 days before the event date to properly","body":"plan and prepare the event.","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.1.1","parent_key":"tournament-structure:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c2fc1e82846487f532237ee706395cb4bfa109e0f9844a9d416cf417c9df39b2","has_figures":false,"extraction":"text"},{"ordinal":6,"depth":2,"kind":"rule","number":"1.1.2","title":"A tournament may run a Double Elimination Bracket format with any number of","body":"competitors, but this must be declared before any fees are collected and competitors must be made aware of the limited number of matches they may earn.","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.1.2","parent_key":"tournament-structure:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a6adfb3bb0a9d5dfa13ebed13e7cbe575538e3f1a6bb16f2fdccebb2bfcff85d","has_figures":false,"extraction":"text"},{"ordinal":7,"depth":2,"kind":"rule","number":"1.1.3","title":null,"body":"Events must register at least six weeks before the start date of the event.","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.1.3","parent_key":"tournament-structure:1.1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"23a0b2d3ef40b29db9911a068b9c2f15c921acc5570e8eeb6f17144671287a55","has_figures":false,"extraction":"text"},{"ordinal":8,"depth":1,"kind":"rule","number":"1.2","title":"Determination of Tournament format","body":"Tournament formats will be determined based on the total number of entrants. This is for Group matches and duels.","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.2","parent_key":"tournament-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"09c331e96771ee2a2171f8dfdefd19ad35756130e704bf326897c204843cefac","has_figures":false,"extraction":"text"},{"ordinal":9,"depth":1,"kind":"rule","number":"1.3","title":"4–6 Entrants | Teams | Competitors","body":"The tournament will be conducted as a round-robin; each competitor or team will fight each other competitor or team the same number of times. The tournament results will be determined based on matches won. In the event of a tie, you will follow the regulations listed below.","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.3","parent_key":"tournament-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"c6e157ca63048d0988e5ae1e2a1f0e0eaf8433997429b4a89400b043ac065ff6","has_figures":false,"extraction":"text"},{"ordinal":10,"depth":1,"kind":"rule","number":"1.4","title":"6–12 Entrants | Teams | Competitors","body":"","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.4","parent_key":"tournament-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ad1974d12b5c8c1ccd7509095fba4fcc1e48a17fa7366bf94afc9e943209946c","has_figures":false,"extraction":"text"},{"ordinal":11,"depth":2,"kind":"rule","number":"1.4.1","title":"Option 1: The Tournament will be conducted as a round-robin; each competitor","body":"or team will fight each other competitor or team the same number of times. The tournament results will be determined based on matches won. In the event of a tie, you will follow the regulations listed below.","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.4.1","parent_key":"tournament-structure:1.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"30dd4dcfed35246288965b7fb6b14613a0827fddf282895d9c7f49f5b8c73c13","has_figures":false,"extraction":"text"},{"ordinal":12,"depth":2,"kind":"rule","number":"1.4.2","title":null,"body":"Option 2: Entrants will be split into pools, with 3-6 competitors/teams per pool.\nEach pool is run as a round-robin, with the top two competitors/teams from each pool advancing to the semi-finals.\n● Option 2A: A round-robin tournament is conducted with the remaining four competitors/teams, and the tournament results will be determined based on overall matches won. In the event of a tie, you will follow the regulations listed below.\n● Option 2B: The remaining four teams will participate in a single elimination bracket. An additional match will establish the 3rd and 4th place.","page_from":3,"page_to":3,"stable_key":"tournament-structure:1.4.2","parent_key":"tournament-structure:1.4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"be41eeea6f2df162524476d74d8381a61f37b8dd69cf48ebdf9cca34a9516613","has_figures":false,"extraction":"text"},{"ordinal":13,"depth":1,"kind":"rule","number":"1.5","title":"12–16 Entrants | Teams | Competitors","body":"","page_from":4,"page_to":4,"stable_key":"tournament-structure:1.5","parent_key":"tournament-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1f776c84b5ba818aad27302e13339a5ad450007afc89c89644f36a6eedb49f16","has_figures":false,"extraction":"text"},{"ordinal":14,"depth":2,"kind":"rule","number":"1.5.1","title":"Option 1: Entrants will be split into two pools, with 6-8 competitors/teams per","body":"pool. Each pool is run as a round-robin, with the top two entrants from each pool advancing to the semi-finals.\n● Option 1A: A round-robin tournament is conducted with the remaining four competitors/teams, and the tournament results will be determined based on overall matches won. In the event of a tie, you will follow the regulations listed below.\n● Option 1B: The remaining four teams will participate in a single elimination bracket. An additional match will establish the 3rd and 4th place.","page_from":4,"page_to":4,"stable_key":"tournament-structure:1.5.1","parent_key":"tournament-structure:1.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6c97519642377eea882fa7e6f956166676c6977c0801396040bc1cbfbafedbbe","has_figures":false,"extraction":"text"},{"ordinal":15,"depth":2,"kind":"rule","number":"1.5.2","title":"Option 2: Entrants will be split into three pools of 4-6. Each pool is run as a","body":"round-robin, with the top two entrants from each pool advancing to the semi-finals.\n● Option 2A: A round-robin tournament is conducted with the remaining six competitors/teams, and the tournament results will be determined based on overall matches won. In the event of a tie, a tiebreaker round will be fought.\n● Option 2B: (not recommended due to 6 team brackets) The remaining 6 will participate in a single elimination bracket, and then have a match to establish the 3rd/4th place","page_from":4,"page_to":4,"stable_key":"tournament-structure:1.5.2","parent_key":"tournament-structure:1.5","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"8c3cabc34dd7411368ef05b78c8fbc8f7b87cb6045c41a96a2caa0e723ab6bc5","has_figures":false,"extraction":"text"},{"ordinal":16,"depth":1,"kind":"rule","number":"1.6","title":"16–20 Entrants | Teams | Competitors","body":"","page_from":4,"page_to":4,"stable_key":"tournament-structure:1.6","parent_key":"tournament-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"6aedb41d04b593648b7b0d222dd7b78fdbc5465b98942672e490ec6d8816166f","has_figures":false,"extraction":"text"},{"ordinal":17,"depth":2,"kind":"rule","number":"1.6.1","title":"Option 1: Entrants will be split into two pools, with 8-10 competitors/teams per","body":"pool. Each pool is run as a round-robin, with the top two entrants from each pool advancing to the semi-finals.\n● Option 1A: A round-robin tournament is conducted with the remaining four competitors/teams, and the tournament results will be determined based on overall matches won. In the event of a tie, you will follow the regulations listed below.\n● Option 1B: The remaining four teams will participate in a single elimination bracket. An additional match will establish the 3rd and 4th place.","page_from":4,"page_to":4,"stable_key":"tournament-structure:1.6.1","parent_key":"tournament-structure:1.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"5ff192108705170f215d15d862624838bc2e47d4cfab658cc5039c44b0571d55","has_figures":false,"extraction":"text"},{"ordinal":18,"depth":2,"kind":"rule","number":"1.6.2","title":null,"body":"Option 2: Entrants will be split into 4 pools, with 4-5 competitors/teams per pool.\nEach pool is run as a round-robin, with the top two entrants advancing to the semi-finals.\n● Option 2A: (not recommended due to length of tournament) A round-robin tournament is conducted with the remaining eight competitors/teams, and the tournament results will be determined based on overall matches won. In the event of a tie, you will follow the regulations listed below.\n● Option 2B- The remaining Eight teams will participate in a single elimination bracket. An additional match will establish the 3rd and 4th place.","page_from":4,"page_to":4,"stable_key":"tournament-structure:1.6.2","parent_key":"tournament-structure:1.6","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d0a44357d5d6cf063111c89896fc5e278e7ca9a86258fe32346a6511c8d67cf8","has_figures":false,"extraction":"text"},{"ordinal":19,"depth":1,"kind":"rule","number":"1.7","title":"20+ Entrants | Teams | Competitors","body":"For tournaments with 20+ competitors/teams, follow the above examples and continue it exponentially.\nImportant: An event organizer may choose to run a losers bracket, but these matches will not count towards League Points.","page_from":5,"page_to":5,"stable_key":"tournament-structure:1.7","parent_key":"tournament-structure:1","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f88a58cbfa0f642cc7868729c07801fc7ef9d7811f11fef03d1a139144af7b00","has_figures":false,"extraction":"text"},{"ordinal":20,"depth":0,"kind":"section","number":"2","title":"Cards","body":"1. Yellow/Red Cards: only affect the tournament they take place in, they do not carry over into other tournaments at the event.\n2. Green Cards: Follow the competitor from tournament to tournament, but the same green card violation will not stack with itself per each tournament.","page_from":5,"page_to":5,"stable_key":"tournament-structure:2","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"3fd1d6b647ec8b9d1cb449b507fea554f7480bc6a624302b281fb84e4271749d","has_figures":false,"extraction":"text"},{"ordinal":21,"depth":0,"kind":"section","number":"3","title":"How to break ties","body":"Step one (1) Only in 2 competitor/teams tie","page_from":6,"page_to":6,"stable_key":"tournament-structure:3","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["2"],"content_sha256":"75f0a70090f9afadda31641fc3daa242ad1694ce20e852780a9173a06b6c0c59","has_figures":false,"extraction":"text"},{"ordinal":22,"depth":1,"kind":"rule","number":"3.1","title":null,"body":"Head-to-Head Results:\nThese criteria prioritize direct competition outcomes. If the teams or competitors have faced each other, the winner of that match is given precedence.\nAction: Check the results of the match between the two tied teams/competitors if such a match occurred during this segment of the tournament. The team or competitor who won this match is the winner.\n\nStep two (2) if the tie was not resolved with 2.1","page_from":6,"page_to":6,"stable_key":"tournament-structure:3.1","parent_key":"tournament-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4f5076f53c2cf0950e41ee8f96fee7867385866b9808e1676d6ba305c5585763","has_figures":false,"extraction":"text"},{"ordinal":23,"depth":1,"kind":"rule","number":"3.2","title":null,"body":"Round Victories vs. Losses or Hits Earned vs. Hits Received:\nFor Buhurt and Buckler, the focus is on the overall performance in rounds, emphasizing consistent success in matches.\nFor Other Duels, the ratio of hits emphasizes skill in both offense and defense, giving a balanced view of performance.\nAction: Use the appropriate difference or ratio based on the type of event:\nBuhurt and Buckler: Compare the difference between round victories and losses. This is found in Column G (Win-Ratio).\nOther Duels: Compare the ratio of hits earned to hits received. This is found in Column S (Hits Earned / Hits Received) on the scoresheet.\n\nStep three (3) if the tie was not resolved with 2.2","page_from":6,"page_to":6,"stable_key":"tournament-structure:3.2","parent_key":"tournament-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"d2b1de9189d148513bddf313ef029a4fa2f5b0133916bbf150eacec4b7a2c3bf","has_figures":false,"extraction":"text"},{"ordinal":24,"depth":1,"kind":"rule","number":"3.3","title":null,"body":"Active vs Downed Competitors:\nThis metric provides insight into team durability and effectiveness in maintaining active competitors throughout the tournament, highlighting strategic strength.\nAction: Evaluate the difference between active competitors at the end of each round and downed competitors at the end of each round during the tournament.\nThis is reflected in the S-G Difference (Active vs. Grounded difference) on the event result sheet.\n\nStep four (4) if the tie was not resolved with 2.3","page_from":6,"page_to":6,"stable_key":"tournament-structure:3.3","parent_key":"tournament-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"fb9ae0ee4681d6bae069a7ccd31695224942a7c12c8968b5f829d48f217e8006","has_figures":false,"extraction":"text"},{"ordinal":25,"depth":1,"kind":"rule","number":"3.4","title":null,"body":"Penalties Received:\nPenalties reflect rule adherence and sportsmanship. Fewer penalties indicate better discipline and fairness, which are valued in the competition.\nAction: Consider the number of penalties received during the tournament. The team or competitor with the fewest penalties is the winner.","page_from":6,"page_to":6,"stable_key":"tournament-structure:3.4","parent_key":"tournament-structure:3","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"4e79dd70b84b259590e1f4c4786177d9da0c330a4ba2d8fc4add533975855725","has_figures":false,"extraction":"text"},{"ordinal":26,"depth":0,"kind":"section","number":"4","title":"Point System for the Season","body":"","page_from":7,"page_to":7,"stable_key":"tournament-structure:4","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ac98a6c0662475d763a38e57a398818cf794f1be4939e630ba95a8bfa63defe8","has_figures":false,"extraction":"text"},{"ordinal":27,"depth":1,"kind":"rule","number":"4.1","title":null,"body":"Cumulative scoring based on tournament progression and pool size:\n● 1 point for each pool victory (or round-robin victory).\n● 2 points for each elimination victory.\n● 2 points for 3rd.\n● 4 points for 2nd.\n● 6 points for 1st.\nImportant:\nRound Robin format FINALS are not scored beyond placement","page_from":7,"page_to":7,"stable_key":"tournament-structure:4.1","parent_key":"tournament-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"ff65e54c3fc2693d24e8d159842d8f49c9cc5147dfb8d69810bc40f2e298861c","has_figures":false,"extraction":"text"},{"ordinal":28,"depth":1,"kind":"rule","number":"4.2","title":null,"body":"Multiplier for Tier of Event:\n● 0.5 points for source.\n● 1x points for Classic.\n● 1.25x points for Regional Tournaments.\n● 1.5x points for Conference Tournaments.","page_from":7,"page_to":7,"stable_key":"tournament-structure:4.2","parent_key":"tournament-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"df5a1e419c5bf83e012ebcc66c1bb64cf652c5402015708f663cc033e50c084d","has_figures":false,"extraction":"text"},{"ordinal":29,"depth":1,"kind":"rule","number":"4.3","title":null,"body":"All tournaments contribute to the season.","page_from":7,"page_to":7,"stable_key":"tournament-structure:4.3","parent_key":"tournament-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"a4d0c57dde2566136b32baf2d154675fa2b308e940e0906c3dad6fa2b8329c7b","has_figures":false,"extraction":"text"},{"ordinal":30,"depth":1,"kind":"rule","number":"4.4","title":null,"body":"All tournaments must submit the results via the scoresheets provided by the BI website.\nHosts will have a maximum of 2 weeks to submit scoresheets. If TC is not informed of a reason for the delay your tournament will be considered null and no points will be earned for your tournament","page_from":7,"page_to":7,"stable_key":"tournament-structure:4.4","parent_key":"tournament-structure:4","review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"1a239999a3a47535c8c17da73e2c407c345586c41f1691b30fe316701853e11b","has_figures":false,"extraction":"text"},{"ordinal":31,"depth":0,"kind":"section","number":"5","title":"Rules of Tournament","body":"1. Pools Scheduling a. If you have 2/3 Pools, you should alternate between the 2/3 pools in order to have reduction in breaks and delays b. If you have 4 or more pools, you should split the each set of 2 pools into separate segments throughout the day to reduce time in armor and have reasonable breaks In example: Pool A and B alternate in morning, Pool C and D alternate in afternoon c. If a team/competitor has to fight one match immediately after another, they may have up to a 5 minute break\n\n2. Round Robin Scheduling a. If a team/competitor has to fight one match immediately after another, they may have up to a 5 minute break b. If a team or competitor Drops from competing in a match they automatically lose all additional matches and are no longer allowed to continue competing in the tournament. (potential review from judiciary committee) 3. Elimination Stage a. If a team/competitor has to fight one match immediately after another, they may have up to a 5 minute break b. If a team or competitor Drops from competing in a match they automatically lose all additional matches and are no longer allowed to continue competing in the tournament. (potential review from judiciary committee) i. If this directly affects the finals, you will advance the next in place team/competitor to ensure competition for the medaling categories","page_from":8,"page_to":8,"stable_key":"tournament-structure:5","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":[],"content_sha256":"f53bd07296e22b6b61b0252b8e3cb6b78a2a55934a4627cbf129f1d3c2e6f412","has_figures":false,"extraction":"text"},{"ordinal":32,"depth":0,"kind":"section","number":"6","title":"Definitions","body":"1. Pools- Teams/competitors are divided into groups, where they all compete against each other, to determine which teams/competitors advance to the Elimination stage 2. Elimination Stage- also known as brackets/champions/knockout rounds. Stage of the tournament where participants are eliminated from the tournament after a\n\nsingle loss. The winners of each round advance to the next stage until only one competitor remains 3. Round Robin- the entire tournament is all in one group, where every team/competitor compete against each other 4. Tournament- a category that competitors compete in 5. Event- a tournament or multiple tournaments that happen in one location in a continuous series","page_from":8,"page_to":9,"stable_key":"tournament-structure:6","parent_key":null,"review_status":"extracted","review_note":null,"topics":[],"keywords":[],"cross_refs":["5"],"content_sha256":"7219545b6b97b3cc10f630a21495909bf0131099366719ced98c14947d12c49b","has_figures":false,"extraction":"text"},{"ordinal":33,"depth":0,"kind":"note","number":"7","title":"Change log","body":"This will be the change log of this document. It will be updated regularly and we will display what has been removed/added/reworded/formatted. This way we keep transparent communication and clarity about the rules\n\nUpdate date: January 2026 Add: 2. Cards Yellow/Red Cards: only affect the tournament they take place in, they do not carry over into other tournaments at the event.\nGreen Cards: Follow the competitor from tournament to tournament, but the same green card violation will not stack with itself per each tournament.\nChange: 4.2 Multiplier of the Event Add: 4.4 Add: 5 Add: 6\n\nUpdate date: March-2025 (V2025.03)\n- format: Grammar and formatting Update date: June-2024\n- format: Grammar and formatting Update date: March-2024\n- format: new design format, document will be used from now on.\nUpdate date: april-2024\n- Removal: Option 2B: The remaining four teams will participate in a single elimination bracket. An additional match will establish the 3rd and 4th place.\n\n- Rewording: Fights > Matches\n\n- Added 1.8.2 A difference/ratio :\n● For all other Duels: Hits-H-Diff on the scoresheet\n- Added 1.9.2 Multiplier for Tier of Event\n● 0.5 points for Source","page_from":9,"page_to":9,"stable_key":"tournament-structure:7","parent_key":null,"review_status":"extracted","review_note":null,"topics":["changelog"],"keywords":[],"cross_refs":[],"content_sha256":"a37b39174073858e1bccd5b05c612fd44c172754749eb8e2f02d7104013f9681","has_figures":false,"extraction":"text"}]}$rules$::jsonb);
